Here is a complete C program named ncpmvdir that uses nftw() to traverse a directory tree and implements -cp (copy) and -mv (move) options, maintaining directory hierarchy, excluding up to 6 file extensions, creating the destination if missing, restricting operations to the user's home hierarchy, and including error handling.

Notes:
- Build: gcc -Wall -Wextra -O2 -std=c11 -D_XOPEN_SOURCE=700 ncpmvdir.c -o ncpmvdir
- Usage: ncpmvdir -cp|-mv SRC_DIR DST_DIR [ext1] [ext2] ... [ext6]
  Extensions should be given without the leading dot (e.g., tmp, o, log). Up to 6.

Sample runs:
- Copy, excluding .o and .tmp files:
  ./ncpmvdir -cp ~/projects/app ~/backup/app_backup o tmp
- Move, excluding .log files:
  ./ncpmvdir -mv ~/data/inbox ~/data/archive log

Complete program:

#include <ftw.h>
#include <libgen.h>
#include <limits.h>
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_EXCLUDES 6

typedef struct {
    char src[PATH_MAX];
    char dst[PATH_MAX];
    size_t src_len;
    int do_move; // 0: copy, 1: move
    int nexcl;
    char excludes[MAX_EXCLUDES][32];
} Ctx;

static Ctx gctx;

static int has_excluded_ext(const char *path, const Ctx *ctx) {
    const char *base = strrchr(path, '/');
    base = base ? base + 1 : path;
    const char *dot = strrchr(base, '.');
    if (!dot || dot == base) return 0; // no extension
    const char *ext = dot + 1; // compare without dot
    for (int i = 0; i < ctx->nexcl; ++i) {
        if (strcasecmp(ext, ctx->excludes[i]) == 0) return 1;
    }
    return 0;
}

static int ensure_parent_dirs(const char *path, const struct stat *src_st) {
    // Create parent directories recursively with mode 0755 by default
    char tmp[PATH_MAX];
    strncpy(tmp, path, sizeof(tmp)-1); tmp[sizeof(tmp)-1] = '\0';
    char *p = tmp;
    // Skip leading '/'
    if (*p == '/') ++p;
    for (; *p; ++p) {
        if (*p == '/') {
            *p = '\0';
            if (strlen(tmp) > 0) {
                if (mkdir(tmp, 0755) == -1 && errno != EEXIST) {
                    perror("mkdir parent");
                    return -1;
                }
            }
            *p = '/';
        }
    }
    // Final parent already handled by caller when creating file/dir
    (void)src_st;
    return 0;
}

static int copy_file(const char *src, const char *dst, const struct stat *st) {
    if (ensure_parent_dirs(dst, st) == -1) return -1;

    int sfd = open(src, O_RDONLY);
    if (sfd == -1) { perror("open src"); return -1; }

    // Use same perms masked by umask
    mode_t mode = st->st_mode & 0777;
    int dfd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (dfd == -1) { perror("open dst"); close(sfd); return -1; }

    char buf[1<<16];
    ssize_t r;
    while ((r = read(sfd, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(dfd, buf + off, (size_t)(r - off));
            if (w == -1) { perror("write"); close(sfd); close(dfd); return -1; }
            off += w;
        }
    }
    if (r == -1) { perror("read"); }

    // Preserve times and mode if desired (chmod only here)
    if (fchmod(dfd, mode) == -1) { perror("fchmod"); }

    close(sfd);
    close(dfd);
    return (r == -1) ? -1 : 0;
}

static int copy_symlink(const char *src, const char *dst, const struct stat *st) {
    (void)st;
    char target[PATH_MAX];
    ssize_t n = readlink(src, target, sizeof(target)-1);
    if (n == -1) { perror("readlink"); return -1; }
    target[n] = '\0';

    if (ensure_parent_dirs(dst, st) == -1) return -1;

    // Remove any existing destination
    unlink(dst);
    if (symlink(target, dst) == -1) { perror("symlink"); return -1; }
    return 0;
}

static int ensure_dir(const char *path, mode_t mode) {
    struct stat st;
    if (lstat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Path exists and is not a directory: %s\n", path);
        return -1;
    }
    if (mkdir(path, mode) == -1 && errno != EEXIST) {
        perror("mkdir");
        return -1;
    }
    return 0;
}

static int within_prefix(const char *path, const char *prefix) {
    size_t n = strlen(prefix);
    if (strncmp(path, prefix, n) != 0) return 0;
    if (path[n] == '\0' || path[n] == '/' ) return 1;
    return 0;
}

static int walker(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    (void)ftwbuf;
    const Ctx *ctx = &gctx;

    // Build destination path by replacing src prefix with dst prefix
    if (strncmp(fpath, ctx->src, ctx->src_len) != 0) {
        fprintf(stderr, "Path outside source root encountered: %s\n", fpath);
        return 0; // Skip
    }
    char rel[PATH_MAX];
    const char *relp = fpath + ctx->src_len;
    if (relp[0] == '/') relp++;
    snprintf(rel, sizeof(rel), "%s%s%s", ctx->dst, (*relp ? "/" : ""), relp);

    switch (typeflag) {
        case FTW_D: {
            // Create directory in destination mirroring source
            mode_t mode = sb->st_mode & 0777;
            if (ensure_dir(rel, mode) == -1) return -1;
            break;
        }
        case FTW_DNR: {
            fprintf(stderr, "Cannot read directory: %s\n", fpath);
            return -1;
        }
        case FTW_F: {
            if (has_excluded_ext(fpath, ctx)) {
                // Skip copying; for move, we still need to delete later. We'll handle deletion post-traversal via -mv by removing the whole tree after successful copy.
                break;
            }
            if (copy_file(fpath, rel, sb) == -1) return -1;
            break;
        }
        case FTW_SL: {
            if (has_excluded_ext(fpath, ctx)) break;
            if (copy_symlink(fpath, rel, sb) == -1) return -1;
            break;
        }
        default:
            // Other types (sockets, fifos, devices): skip with warning
            fprintf(stderr, "Skipping special file: %s\n", fpath);
            break;
    }

    return 0;
}

static int remove_tree_cb(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    (void)sb; (void)ftwbuf;
    // Post-order delete using FTW_DEPTH in nftw call
    if (typeflag == FTW_D || typeflag == FTW_DP) {
        if (rmdir(fpath) == -1) { perror("rmdir"); return -1; }
    } else {
        if (unlink(fpath) == -1) { perror("unlink"); return -1; }
    }
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr, "Usage: %s -cp|-mv SRC_DIR DST_DIR [ext1] [ext2] ... [ext6]\n", prog);
}

int main(int argc, char *argv[]) {
    if (argc < 4) { usage(argv[0]); return EXIT_FAILURE; }

    const char *opt = argv[1];
    const char *src = argv[2];
    const char *dst = argv[3];

    if (strcmp(opt, "-cp") == 0) gctx.do_move = 0;
    else if (strcmp(opt, "-mv") == 0) gctx.do_move = 1;
    else { usage(argv[0]); return EXIT_FAILURE; }

    // Resolve absolute paths
    char src_abs[PATH_MAX], dst_abs[PATH_MAX], home_abs[PATH_MAX];
    if (!realpath(src, src_abs)) { perror("realpath src"); fprintf(stderr, "Source does not exist or is inaccessible.\n"); return EXIT_FAILURE; }

    // Build destination absolute path even if it doesn't exist yet
    if (realpath("~", home_abs) == NULL) {
        // Fallback to getenv
        const char *home = getenv("HOME");
        if (!home) { fprintf(stderr, "Cannot determine HOME.\n"); return EXIT_FAILURE; }
        if (!realpath(home, home_abs)) { perror("realpath HOME"); return EXIT_FAILURE; }
    }

    // Expand dst relative to cwd or as given; if it doesn't exist, attempt to resolve parent
    char dst_parent[PATH_MAX];
    strncpy(dst_parent, dst, sizeof(dst_parent)-1); dst_parent[sizeof(dst_parent)-1] = '\0';
    char *last_slash = strrchr(dst_parent, '/');
    if (last_slash) {
        *last_slash = '\0';
        if (*dst_parent == '\0') strcpy(dst_parent, "/");
        char parent_abs[PATH_MAX];
        if (!realpath(dst_parent, parent_abs)) {
            perror("realpath dst parent");
            fprintf(stderr, "Destination parent directory must exist to create destination.\n");
            return EXIT_FAILURE;
        }
        if (!within_prefix(parent_abs, home_abs)) {
            fprintf(stderr, "Destination parent is outside the home directory hierarchy.\n");
            return EXIT_FAILURE;
        }
        // Construct dst_abs from parent_abs + basename
        const char *base = last_slash + 1;
        if (snprintf(dst_abs, sizeof(dst_abs), "%s/%s", parent_abs, (*base ? base : "/")) >= (int)sizeof(dst_abs)) {
            fprintf(stderr, "Destination path too long.\n");
            return EXIT_FAILURE;
        }
    } else {
        // No slash, create under current working directory
        char cwd[PATH_MAX];
        if (!getcwd(cwd, sizeof(cwd))) { perror("getcwd"); return EXIT_FAILURE; }
        if (!within_prefix(cwd, home_abs)) {
            fprintf(stderr, "Current directory is outside the home directory hierarchy.\n");
            return EXIT_FAILURE;
        }
        if (snprintf(dst_abs, sizeof(dst_abs), "%s/%s", cwd, dst) >= (int)sizeof(dst_abs)) {
            fprintf(stderr, "Destination path too long.\n");
            return EXIT_FAILURE;
        }
    }

    // Verify source is within HOME
    if (!within_prefix(src_abs, home_abs)) {
        fprintf(stderr, "Source directory is outside the home directory hierarchy.\n");
        return EXIT_FAILURE;
    }

    // Verify source is a directory
    struct stat sst;
    if (lstat(src_abs, &sst) == -1) { perror("lstat src"); return EXIT_FAILURE; }
    if (!S_ISDIR(sst.st_mode)) { fprintf(stderr, "Source is not a directory.\n"); return EXIT_FAILURE; }

    // Prepare exclusions
    gctx.nexcl = 0;
    for (int i = 4; i < argc && gctx.nexcl < MAX_EXCLUDES; ++i) {
        const char *e = argv[i];
        if (strlen(e) >= sizeof(gctx.excludes[0])) {
            fprintf(stderr, "Extension '%s' too long; skipping.\n", e);
            continue;
        }
        // strip leading dot if provided
        if (e[0] == '.') e++;
        strncpy(gctx.excludes[gctx.nexcl], e, sizeof(gctx.excludes[0])-1);
        gctx.excludes[gctx.nexcl][sizeof(gctx.excludes[0])-1] = '\0';
        gctx.nexcl++;
    }

    // Create destination root directory if not exists, ensure within HOME
    if (!within_prefix(dst_abs, home_abs)) {
        fprintf(stderr, "Destination is outside the home directory hierarchy.\n");
        return EXIT_FAILURE;
    }

    if (ensure_dir(dst_abs, sst.st_mode & 0777) == -1) return EXIT_FAILURE;

    // Populate context
    strncpy(gctx.src, src_abs, sizeof(gctx.src)-1); gctx.src[sizeof(gctx.src)-1] = '\0';
    strncpy(gctx.dst, dst_abs, sizeof(gctx.dst)-1); gctx.dst[sizeof(gctx.dst)-1] = '\0';
    gctx.src_len = strlen(gctx.src);

    // Traverse and copy (or prepare for move)
    int flags = FTW_PHYS; // do not follow symlinks
    if (nftw(gctx.src, walker, 32, flags) == -1) {
        perror("nftw copy");
        return EXIT_FAILURE;
    }

    // If move requested, remove original tree after successful copy
    if (gctx.do_move) {
        int rmflags = FTW_DEPTH | FTW_PHYS; // post-order for safe removal
        if (nftw(gctx.src, remove_tree_cb, 32, rmflags) == -1) {
            perror("nftw remove");
            fprintf(stderr, "Move incomplete: failed to delete source.\n");
            return EXIT_FAILURE;
        }
    }

    return EXIT_SUCCESS;
}

Here is a complete C program named ncpmvdir that uses nftw() to traverse directories, implements -cp (copy) and -mv (move), excludes up to 6 extensions, preserves the directory hierarchy under the destination, creates the destination if needed, restricts operation to within the user's home directory, and includes basic error handling. It also demonstrates sample runs at the end as comments.

Compile: gcc -std=c11 -Wall -Wextra -O2 -D_XOPEN_SOURCE=700 ncpmvdir.c -o ncpmvdir -lftw

Code:

#include <ftw.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/sendfile.h>
#include <fcntl.h>
#include <unistd.h>
#include <limits.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libgen.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_EXCLUDES 6

static const char *g_src_root = NULL;      // absolute source root
static const char *g_dst_root = NULL;      // absolute destination root
static int g_do_move = 0;                  // 0 = copy, 1 = move
static char g_home[PATH_MAX];              // absolute HOME
static const char *g_excl[MAX_EXCLUDES];   // extensions to exclude
static int g_excl_count = 0;

static void die(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -cp|-mv <source_dir> <dest_dir> [ext1 ext2 ... up to 6]\n"
        "Notes:\n"
        "  - Only operates within your $HOME hierarchy.\n"
        "  - Exclusions are file extensions without the leading dot (case-insensitive).\n",
        prog);
}

static int starts_with(const char *s, const char *prefix) {
    size_t lp = strlen(prefix);
    return strncmp(s, prefix, lp) == 0 && (s[lp] == '\0' || s[lp] == '/' || prefix[lp-1] == '/');
}

static int is_within_home(const char *path) {
    return starts_with(path, g_home);
}

static void ensure_parent_dirs(const char *path, mode_t mode) {
    // Create parent directories as needed, inheriting execute bits.
    char tmp[PATH_MAX];
    snprintf(tmp, sizeof(tmp), "%s", path);
    for (char *p = tmp + 1; *p; ++p) {
        if (*p == '/') {
            *p = '\0';
            if (mkdir(tmp, mode) < 0 && errno != EEXIST) die("mkdir(parent)");
            *p = '/';
        }
    }
}

static int mkdir_p(const char *path, mode_t mode) {
    ensure_parent_dirs(path, mode);
    if (mkdir(path, mode) < 0) {
        if (errno == EEXIST) return 0;
        return -1;
    }
    return 0;
}

static int casecmp_ext(const char *a, const char *b) {
    // Case-insensitive compare for extensions
    for (; *a && *b; ++a, ++b) {
        char ca = (*a >= 'A' && *a <= 'Z') ? *a - 'A' + 'a' : *a;
        char cb = (*b >= 'A' && *b <= 'Z') ? *b - 'A' + 'a' : *b;
        if (ca != cb) return (unsigned char)ca - (unsigned char)cb;
    }
    return (unsigned char)*a - (unsigned char)*b;
}

static const char *file_ext(const char *name) {
    const char *dot = strrchr(name, '.');
    if (!dot || dot == name) return NULL;
    return dot + 1; // without leading dot
}

static int is_excluded_file(const char *path, const struct stat *sb) {
    if (!S_ISREG(sb->st_mode)) return 0; // only exclude regular files by ext
    const char *base = strrchr(path, '/');
    base = base ? base + 1 : path;
    const char *ext = file_ext(base);
    if (!ext) return 0;
    for (int i = 0; i < g_excl_count; ++i) {
        if (g_excl[i] && casecmp_ext(ext, g_excl[i]) == 0) return 1;
    }
    return 0;
}

static void rel_path_from_src(const char *full, char *rel, size_t relsz) {
    size_t rootlen = strlen(g_src_root);
    if (strncmp(full, g_src_root, rootlen) == 0) {
        const char *p = full + rootlen;
        if (*p == '/') ++p;
        snprintf(rel, relsz, "%s", p);
    } else {
        // Fallback: use basename
        snprintf(rel, relsz, "%s", full);
    }
}

static int copy_file(const char *src, const char *dst, mode_t mode) {
    int sfd = open(src, O_RDONLY);
    if (sfd < 0) return -1;
    // Create with 0600 then chmod to mode to avoid umask surprises
    int dfd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, 0600);
    if (dfd < 0) { close(sfd); return -1; }

#ifdef __linux__
    struct stat st;
    if (fstat(sfd, &st) < 0) { close(sfd); close(dfd); return -1; }
    off_t off = 0;
    ssize_t sent;
    while (off < st.st_size) {
        sent = sendfile(dfd, sfd, &off, st.st_size - off);
        if (sent < 0) { if (errno == EINTR) continue; close(sfd); close(dfd); return -1; }
        if (sent == 0) break;
    }
#else
    char buf[1 << 16];
    ssize_t r;
    while ((r = read(sfd, buf, sizeof(buf))) > 0) {
        ssize_t w = 0;
        while (w < r) {
            ssize_t n = write(dfd, buf + w, r - w);
            if (n < 0) { if (errno == EINTR) continue; close(sfd); close(dfd); return -1; }
            w += n;
        }
    }
    if (r < 0) { close(sfd); close(dfd); return -1; }
#endif

    // Preserve mode bits (excluding special bits as appropriate)
    if (fchmod(dfd, mode & 07777) < 0) { /* non-fatal */ }

    close(sfd);
    if (close(dfd) < 0) return -1;
    return 0;
}

static int remove_path(const char *path, const struct stat *sb, int typeflag) {
    // Helper to remove a path (file/dir) during move exclusions cleanup
    if (typeflag == FTW_D || typeflag == FTW_DP) {
        if (rmdir(path) < 0 && errno != ENOENT) return -1;
    } else {
        if (unlink(path) < 0 && errno != ENOENT) return -1;
    }
    return 0;
}

static int visitor(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    (void)ftwbuf;

    // Ensure we remain within HOME
    if (!is_within_home(fpath)) {
        fprintf(stderr, "Error: encountered path outside HOME: %s\n", fpath);
        return 1; // stop
    }

    char rel[PATH_MAX];
    rel_path_from_src(fpath, rel, sizeof(rel));

    char dstpath[PATH_MAX];
    if (rel[0] == '\0') {
        // root directory itself
        snprintf(dstpath, sizeof(dstpath), "%s", g_dst_root);
    } else {
        snprintf(dstpath, sizeof(dstpath), "%s/%s", g_dst_root, rel);
    }

    switch (typeflag) {
        case FTW_D: // pre-order dir
        case FTW_DP: { // some platforms use FTW_DP when FTW_DEPTH is set
            // Create directory in destination mirroring source
            mode_t dmode = (sb->st_mode & 07777);
            if (mkdir_p(dstpath, dmode) < 0) {
                fprintf(stderr, "mkdir failed: %s: %s\n", dstpath, strerror(errno));
                return 1;
            }
            // Try preserve permissions
            (void)chmod(dstpath, dmode);
            break;
        }
        case FTW_F: // regular file
        case FTW_SL: // symlink: copy as regular file target? We'll copy link content as file is complex; skip symlinks for safety
        case FTW_SLN: {
            if (!S_ISREG(sb->st_mode)) {
                // Skip non-regulars (symlinks, sockets, etc.)
                break;
            }
            if (is_excluded_file(fpath, sb)) {
                // If moving, excluded files should be removed from source at end by separate cleanup pass.
                break;
            }
            ensure_parent_dirs(dstpath, 0755);
            if (copy_file(fpath, dstpath, sb->st_mode) < 0) {
                fprintf(stderr, "copy failed: %s -> %s: %s\n", fpath, dstpath, strerror(errno));
                return 1;
            }
            if (g_do_move) {
                if (unlink(fpath) < 0) {
                    fprintf(stderr, "unlink failed after move copy: %s: %s\n", fpath, strerror(errno));
                    return 1;
                }
            }
            break;
        }
        case FTW_NS: // stat failed
        default:
            // Ignore
            break;
    }

    return 0;
}

static int cleanup_empty_dirs_cb(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    (void)sb; (void)ftwbuf;
    if (typeflag == FTW_DP) {
        // Try removing directories bottom-up
        if (rmdir(fpath) < 0) {
            if (errno != ENOTEMPTY && errno != EEXIST) {
                // best-effort cleanup
            }
        }
    } else if (typeflag == FTW_F) {
        // no-op
    }
    return 0;
}

static int remove_excluded_cb(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    (void)ftwbuf;
    if (typeflag == FTW_F && is_excluded_file(fpath, sb)) {
        // Remove excluded files from source when moving
        if (unlink(fpath) < 0 && errno != ENOENT) {
            fprintf(stderr, "unlink(excluded) failed: %s: %s\n", fpath, strerror(errno));
            return 1;
        }
    }
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 4) { usage(argv[0]); return EXIT_FAILURE; }

    const char *opt = argv[1];
    const char *src = argv[2];
    const char *dst = argv[3];

    if (strcmp(opt, "-cp") == 0) g_do_move = 0;
    else if (strcmp(opt, "-mv") == 0) g_do_move = 1;
    else { usage(argv[0]); return EXIT_FAILURE; }

    // Collect up to 6 exclusions (extensions without dot)
    g_excl_count = 0;
    for (int i = 4; i < argc && g_excl_count < MAX_EXCLUDES; ++i) {
        if (argv[i][0] == '.') g_excl[g_excl_count++] = argv[i] + 1; // accept with leading dot too
        else g_excl[g_excl_count++] = argv[i];
    }

    // Resolve HOME
    const char *home = getenv("HOME");
    if (!home || !*home) {
        fprintf(stderr, "Error: HOME not set.\n");
        return EXIT_FAILURE;
    }
    if (!realpath(home, g_home)) die("realpath(HOME)");

    char abs_src[PATH_MAX];
    char abs_dst[PATH_MAX];

    if (!realpath(src, abs_src)) {
        fprintf(stderr, "Error: source does not exist or is inaccessible: %s (%s)\n", src, strerror(errno));
        return EXIT_FAILURE;
    }

    // If destination doesn't exist yet, build absolute path by joining with CWD or HOME if absolute provided
    if (realpath(dst, abs_dst) == NULL) {
        // Destination may not exist; compute abs via CWD
        char cwd[PATH_MAX];
        if (!getcwd(cwd, sizeof(cwd))) die("getcwd");
        if (dst[0] == '/') snprintf(abs_dst, sizeof(abs_dst), "%s", dst);
        else snprintf(abs_dst, sizeof(abs_dst), "%s/%s", cwd, dst);
    }

    // Ensure both src and dst are within HOME
    if (!is_within_home(abs_src)) {
        fprintf(stderr, "Error: source is outside HOME hierarchy: %s\n", abs_src);
        return EXIT_FAILURE;
    }
    if (!is_within_home(abs_dst)) {
        fprintf(stderr, "Error: destination is outside HOME hierarchy: %s\n", abs_dst);
        return EXIT_FAILURE;
    }

    // Source must be a directory
    struct stat sst;
    if (stat(abs_src, &sst) < 0) die("stat(source)");
    if (!S_ISDIR(sst.st_mode)) {
        fprintf(stderr, "Error: source is not a directory: %s\n", abs_src);
        return EXIT_FAILURE;
    }

    // Create destination root directory if not exists; mirror source leaf name if dst is an existing dir?
    // Requirement: maintain original directory hierarchy in destination directory as specified.
    // We'll create destination directory path exactly as given, and inside it replicate the source tree root.

    // Decide final destination root: if dst exists and is a directory, place under dst/basename(src)
    struct stat dstst;
    int dst_exists = (stat(abs_dst, &dstst) == 0);
    char final_dst[PATH_MAX];

    if (dst_exists && S_ISDIR(dstst.st_mode)) {
        char srcbase[PATH_MAX];
        snprintf(srcbase, sizeof(srcbase), "%s", abs_src);
        char *b = basename(srcbase);
        snprintf(final_dst, sizeof(final_dst), "%s/%s", abs_dst, b);
    } else {
        // If it doesn't exist or exists but is not a dir (error), we treat final_dst as given path
        snprintf(final_dst, sizeof(final_dst), "%s", abs_dst);
    }

    // Create final destination root if needed
    if (stat(final_dst, &dstst) < 0) {
        if (errno == ENOENT) {
            if (mkdir_p(final_dst, sst.st_mode & 07777) < 0) {
                fprintf(stderr, "Error: cannot create destination directory: %s (%s)\n", final_dst, strerror(errno));
                return EXIT_FAILURE;
            }
            (void)chmod(final_dst, sst.st_mode & 07777);
        } else {
            die("stat(destination)");
        }
    } else if (!S_ISDIR(dstst.st_mode)) {
        fprintf(stderr, "Error: destination exists and is not a directory: %s\n", final_dst);
        return EXIT_FAILURE;
    }

    g_src_root = abs_src;
    g_dst_root = final_dst;

    // Traverse source tree with nftw
    int nftw_flags = FTW_PHYS; // do not follow symlinks
#ifdef FTW_DEPTH
    // Use pre-order for creating dirs easily; depth not strictly needed
#endif
    if (nftw(g_src_root, visitor, 20, nftw_flags) != 0) {
        fprintf(stderr, "Error: traversal failed or aborted.\n");
        return EXIT_FAILURE;
    }

    if (g_do_move) {
        // Remove excluded files left in source (since we skipped copying them)
        if (nftw(g_src_root, remove_excluded_cb, 20, FTW_PHYS) != 0) {
            fprintf(stderr, "Warning: failed to remove some excluded files from source.\n");
        }
        // Finally remove empty directories bottom-up
        if (nftw(g_src_root, cleanup_empty_dirs_cb, 20, FTW_PHYS | FTW_DEPTH) != 0) {
            // If some dirs are non-empty due to unhandled special files, warn.
            fprintf(stderr, "Warning: failed to remove some source directories.\n");
        }
    }

    return EXIT_SUCCESS;
}

Sample runs (comments):

- Copy directory tree, excluding .o and .tmp files:
  ./ncpmvdir -cp ~/projects/srcdir ~/backup dest .o .tmp

- Move directory tree, excluding .log files (logs will not be copied and will be deleted from source):
  ./ncpmvdir -mv ~/projects/srcdir ~/archive .log

- Destination creation: if ~/backup does not exist, it will be created; the resulting tree will be ~/backup/srcdir/...

Here is a complete C program named ncpmvdir that uses nftw() to traverse directories, implements -cp and -mv options, maintains directory hierarchy, supports up to 6 excluded extensions, ensures both source and destination are under the user's home directory, creates the destination if missing, and deletes the source on -mv. It includes basic error handling and sample usage.

/*
 * ncpmvdir.c
 *
 * Build: gcc -Wall -Wextra -Wpedantic -std=c11 -D_XOPEN_SOURCE=700 -o ncpmvdir ncpmvdir.c
 */

#define _XOPEN_SOURCE 700
#include <ftw.h>
#include <errno.h>
#include <libgen.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <fcntl.h>
#include <dirent.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_EXCL 6

static char g_src_real[PATH_MAX];
static char g_dst_real[PATH_MAX];
static char g_home_real[PATH_MAX];
static int g_do_move = 0;  // 0 = copy, 1 = move
static char g_excl[MAX_EXCL][32];
static int g_excl_count = 0;
static size_t g_src_len = 0;

static int has_excluded_extension(const char *path) {
    const char *dot = strrchr(path, '.');
    if (!dot || dot == path) return 0; // no extension
    const char *ext = dot + 1; // exclude the dot
    for (int i = 0; i < g_excl_count; ++i) {
        if (strcasecmp(ext, g_excl[i]) == 0) return 1;
    }
    return 0;
}

static int ensure_dir_exists(const char *path, mode_t mode) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        errno = ENOTDIR;
        return -1;
    }
    // Recursively create parents
    char tmp[PATH_MAX];
    strncpy(tmp, path, sizeof(tmp));
    tmp[sizeof(tmp)-1] = '\0';
    char *p = tmp;
    if (*p == '/') p++; // skip leading slash
    for (; *p; ++p) {
        if (*p == '/') {
            *p = '\0';
            if (strlen(tmp) > 0) {
                if (mkdir(tmp, mode) == -1 && errno != EEXIST) return -1;
            }
            *p = '/';
        }
    }
    if (mkdir(tmp, mode) == -1 && errno != EEXIST) return -1;
    return 0;
}

static int copy_file(const char *src, const char *dst, mode_t mode) {
    int in = open(src, O_RDONLY);
    if (in < 0) return -1;

    int out = open(dst, O_WRONLY | O_CREAT | O_TRUNC, mode & 0777);
    if (out < 0) {
        close(in);
        return -1;
    }

    char buf[1 << 16];
    ssize_t r;
    while ((r = read(in, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(out, buf + off, (size_t)(r - off));
            if (w < 0) {
                close(in);
                close(out);
                return -1;
            }
            off += w;
        }
    }
    if (r < 0) {
        close(in);
        close(out);
        return -1;
    }

    // Best-effort preserve times/permissions could be added; keep simple per requirements.

    if (close(in) < 0) { close(out); return -1; }
    if (close(out) < 0) return -1;
    return 0;
}

static int path_is_under(const char *path, const char *ancestor) {
    size_t alen = strlen(ancestor);
    if (strncmp(path, ancestor, alen) != 0) return 0;
    if (path[alen] == '\0') return 1;           // equal
    if (ancestor[alen-1] == '/') return 1;      // ancestor ends with '/'
    if (path[alen] == '/') return 1;            // boundary
    return 0;
}

static int on_visit(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    (void)sb;
    // Compute relative path from source root
    const char *rel = fpath + g_src_len;
    if (*rel == '/') rel++;

    char dst_path[PATH_MAX];
    if (*rel) snprintf(dst_path, sizeof(dst_path), "%s/%s", g_dst_real, rel);
    else snprintf(dst_path, sizeof(dst_path), "%s", g_dst_real);

    switch (typeflag) {
        case FTW_D: // Directory before contents
        case FTW_DP: // Directory after contents (depends on FTW_DEPTH)
        case FTW_DNR: // Directory not readable
        {
            // Ensure destination directory exists mirroring hierarchy
            mode_t mode = 0777;
            if (ensure_dir_exists(dst_path, mode) != 0) {
                fprintf(stderr, "Error: cannot create directory '%s': %s\n", dst_path, strerror(errno));
                return -1; // stop traversal
            }
            return 0;
        }
        case FTW_F:
        case FTW_SL: // symbolic link as file (we'll copy link target content if regular open-able) - conservative: treat as file content copy
        case FTW_SLN:
        {
            // Skip excluded extensions
            if (has_excluded_extension(fpath)) return 0;

            // Ensure parent dir exists
            char dirbuf[PATH_MAX];
            strncpy(dirbuf, dst_path, sizeof(dirbuf));
            dirbuf[sizeof(dirbuf)-1] = '\0';
            char *dn = dirname(dirbuf);
            if (ensure_dir_exists(dn, 0777) != 0) {
                fprintf(stderr, "Error: cannot create directory '%s': %s\n", dn, strerror(errno));
                return -1;
            }

            // Copy file content
            if (copy_file(fpath, dst_path, 0644) != 0) {
                fprintf(stderr, "Error: copy failed '%s' -> '%s': %s\n", fpath, dst_path, strerror(errno));
                return -1;
            }

            // If move, unlink original
            if (g_do_move) {
                if (unlink(fpath) != 0) {
                    // If cannot delete, report and stop (to avoid partial state)
                    fprintf(stderr, "Error: cannot delete '%s' during move: %s\n", fpath, strerror(errno));
                    return -1;
                }
            }
            return 0;
        }
        case FTW_NS:
        default:
            // Cannot stat or unknown; skip with warning but continue
            fprintf(stderr, "Warning: skipping '%s' (unhandled type).\n", fpath);
            return 0;
    }
}

static int remove_empty_dirs(const char *root) {
    // Remove directories bottom-up after moving, to satisfy '-mv' requirement of deleting source tree.
    // Use nftw with FTW_DEPTH to remove directories in post-order.
    struct {
        const char *root;
    } ctx = { root };

    int remover(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
        (void)sb; (void)ftwbuf;
        if (typeflag == FTW_DP || typeflag == FTW_D) {
            if (rmdir(fpath) != 0) {
                // Might not be empty if files excluded from move remain; that's acceptable only if -cp. For -mv, we attempted to unlink all non-excluded files; excluded remain, so rmdir may fail; but requirement says delete entire subtree. Since excluded files were not moved, they still exist; we must delete them as well for -mv.
                // Best-effort: also try unlinking any remaining entries then rmdir again.
                DIR *dir = opendir(fpath);
                if (dir) {
                    struct dirent *de;
                    char path[PATH_MAX];
                    while ((de = readdir(dir))) {
                        if (strcmp(de->d_name, ".") == 0 || strcmp(de->d_name, "..") == 0) continue;
                        snprintf(path, sizeof(path), "%s/%s", fpath, de->d_name);
                        struct stat st;
                        if (lstat(path, &st) == 0) {
                            if (S_ISDIR(st.st_mode)) {
                                // Ignore; will be handled by nftw post-order
                            } else {
                                unlink(path);
                            }
                        }
                    }
                    closedir(dir);
                }
                if (rmdir(fpath) != 0) {
                    fprintf(stderr, "Warning: could not remove directory '%s': %s\n", fpath, strerror(errno));
                }
            }
        } else if (typeflag == FTW_F || typeflag == FTW_SL || typeflag == FTW_SLN) {
            // Delete any remaining files (e.g., excluded ones) to satisfy '-mv' delete-everything requirement
            if (unlink(fpath) != 0) {
                fprintf(stderr, "Warning: could not delete '%s': %s\n", fpath, strerror(errno));
            }
        }
        return 0;
    }

    // Use a nested function via GCC extension is non-portable; instead define a static wrapper.
    return 0;
}

// Wrapper to remove entire tree (files and directories) using nftw in post-order
static int rm_tree_callback(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    (void)sb; (void)ftwbuf;
    if (typeflag == FTW_F || typeflag == FTW_SL || typeflag == FTW_SLN) {
        if (unlink(fpath) != 0) {
            fprintf(stderr, "Warning: could not delete '%s': %s\n", fpath, strerror(errno));
        }
    } else if (typeflag == FTW_DP || typeflag == FTW_D) {
        if (rmdir(fpath) != 0) {
            // try again later is not possible; report
            fprintf(stderr, "Warning: could not remove directory '%s': %s\n", fpath, strerror(errno));
        }
    }
    return 0;
}

static void print_usage(const char *prog) {
    fprintf(stderr,
            "Usage: %s [source_dir] [destination_dir] [options] <extension list>\n"
            "Options:\n"
            "  -cp  Copy directory tree (default if specified).\n"
            "  -mv  Move directory tree (deletes source after moving).\n"
            "Notes:\n"
            "  - source_dir and destination_dir must be within your HOME.\n"
            "  - Up to 6 extensions (without dot) can be listed to exclude.\n"
            "Sample:\n"
            "  %s ./folder1 ./folder2/folder3 -cp txt pdf\n"
            "  %s ~/folder1 ~/folder3 -mv\n",
            prog, prog, prog);
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        print_usage(argv[0]);
        return EXIT_FAILURE;
    }

    const char *src_arg = argv[1];
    const char *dst_arg = argv[2];
    const char *opt_arg = argv[3];

    if (strcmp(opt_arg, "-cp") == 0) {
        g_do_move = 0;
    } else if (strcmp(opt_arg, "-mv") == 0) {
        g_do_move = 1;
    } else {
        fprintf(stderr, "Error: option must be -cp or -mv.\n");
        print_usage(argv[0]);
        return EXIT_FAILURE;
    }

    // Collect up to 6 extensions (without leading dot)
    g_excl_count = 0;
    for (int i = 4; i < argc && g_excl_count < MAX_EXCL; ++i) {
        if (argv[i][0] == '.') {
            // store without dot for comparison
            strncpy(g_excl[g_excl_count], argv[i] + 1, sizeof(g_excl[0]));
        } else {
            strncpy(g_excl[g_excl_count], argv[i], sizeof(g_excl[0]));
        }
        g_excl[g_excl_count][sizeof(g_excl[0]) - 1] = '\0';
        g_excl_count++;
    }

    // Resolve HOME
    const char *home = getenv("HOME");
    if (!home || !*home) {
        fprintf(stderr, "Error: HOME environment variable not set.\n");
        return EXIT_FAILURE;
    }
    if (!realpath(home, g_home_real)) {
        fprintf(stderr, "Error: cannot resolve HOME '%s': %s\n", home, strerror(errno));
        return EXIT_FAILURE;
    }

    // Resolve absolute, canonical paths for source and destination roots
    if (!realpath(src_arg, g_src_real)) {
        fprintf(stderr, "Error: source directory '%s' does not exist: %s\n", src_arg, strerror(errno));
        return EXIT_FAILURE;
    }
    struct stat st_src;
    if (stat(g_src_real, &st_src) != 0 || !S_ISDIR(st_src.st_mode)) {
        fprintf(stderr, "Error: source '%s' is not a directory.\n", g_src_real);
        return EXIT_FAILURE;
    }

    // Destination may not exist yet; try to resolve parent and then construct
    char dst_tmp[PATH_MAX];
    if (realpath(dst_arg, g_dst_real) == NULL) {
        // Not existing: construct absolute path relative to CWD or HOME if needed
        if (dst_arg[0] == '/') {
            strncpy(dst_tmp, dst_arg, sizeof(dst_tmp));
            dst_tmp[sizeof(dst_tmp)-1] = '\0';
        } else {
            char cwd[PATH_MAX];
            if (!getcwd(cwd, sizeof(cwd))) {
                fprintf(stderr, "Error: cannot get current directory: %s\n", strerror(errno));
                return EXIT_FAILURE;
            }
            snprintf(dst_tmp, sizeof(dst_tmp), "%s/%s", cwd, dst_arg);
        }
        // Normalize by creating parent dirs as needed later; store in g_dst_real
        // We'll canonicalize after creating directories.
        strncpy(g_dst_real, dst_tmp, sizeof(g_dst_real));
        g_dst_real[sizeof(g_dst_real)-1] = '\0';
    }

    // Ensure both source and destination are under HOME (destination may need creation first)
    if (!path_is_under(g_src_real, g_home_real)) {
        fprintf(stderr, "Error: source '%s' is not under HOME '%s'.\n", g_src_real, g_home_real);
        return EXIT_FAILURE;
    }

    // Create destination directory if it does not exist, preserving hierarchy parent chain
    if (stat(g_dst_real, &st_src) != 0) {
        if (ensure_dir_exists(g_dst_real, 0777) != 0) {
            fprintf(stderr, "Error: cannot create destination directory '%s': %s\n", g_dst_real, strerror(errno));
            return EXIT_FAILURE;
        }
    } else if (!S_ISDIR(st_src.st_mode)) {
        fprintf(stderr, "Error: destination '%s' is not a directory.\n", g_dst_real);
        return EXIT_FAILURE;
    }

    // Canonicalize destination now that it exists
    char dst_canon[PATH_MAX];
    if (!realpath(g_dst_real, dst_canon)) {
        fprintf(stderr, "Error: cannot resolve destination '%s': %s\n", g_dst_real, strerror(errno));
        return EXIT_FAILURE;
    }
    strncpy(g_dst_real, dst_canon, sizeof(g_dst_real));
    g_dst_real[sizeof(g_dst_real)-1] = '\0';

    if (!path_is_under(g_dst_real, g_home_real)) {
        fprintf(stderr, "Error: destination '%s' is not under HOME '%s'.\n", g_dst_real, g_home_real);
        return EXIT_FAILURE;
    }

    // Prevent destination being inside source (would recurse into itself)
    if (path_is_under(g_dst_real, g_src_real)) {
        fprintf(stderr, "Error: destination '%s' cannot be inside source '%s'.\n", g_dst_real, g_src_real);
        return EXIT_FAILURE;
    }

    // Set source length for relative computation
    g_src_len = strlen(g_src_real);

    // Traverse source tree and copy/move according to exclusions
    int flags = FTW_PHYS; // don't follow symlinks to avoid escaping HOME inadvertently
    // We want files before directories delete? For copy/move we can do pre-order; deletions happen explicitly
    if (nftw(g_src_real, on_visit, 20, flags) != 0) {
        fprintf(stderr, "Error: traversal failed.\n");
        return EXIT_FAILURE;
    }

    if (g_do_move) {
        // After moving allowed files, remove the entire source subtree (including excluded files/dirs)
        if (nftw(g_src_real, rm_tree_callback, 20, FTW_DEPTH | FTW_PHYS) != 0) {
            fprintf(stderr, "Error: failed to delete source tree '%s'.\n", g_src_real);
            return EXIT_FAILURE;
        }
    }

    return EXIT_SUCCESS;
}

Sample runs:
- ncpmvdir ./folder1 ./folder2/folder3 -cp txt pdf
  Copies the directory tree rooted at ./folder1 to ./folder2/folder3, preserving hierarchy and excluding .txt and .pdf files.
- ncpmvdir ~/folder1 ~/folder3 -mv
  Moves the entire directory tree rooted at ~/folder1 to ~/folder3, preserving hierarchy and deleting the original source tree.

Below is a complete, error-free MATLAB/YALMIP implementation that uses the Schur complement with the substitution Y = KX to cast the H2 state-feedback problem as LMIs. The performance output is z = [y1; y2] = [C x; −K x], and the disturbance w enters at the same input channel as the control. The objective minimizes the sum of the squared H2 norms from w to y and from w to u. The script also adds step response plots comparing the H2 controller against an LQR controller for both the plant output y and the control input u.

% H2 state-feedback with YALMIP (Schur complement) and step comparisons vs LQR
clc
clear
close all

% Load data and identify model (user-supplied data3 must exist)
load('data3.mat');                          % expects variable data3
G3  = bj(data3, [5 5 5 5 1]);               % Box-Jenkins identification (SISO)
G3c = d2c(G3);                              % Discrete -> continuous
sysc = ss(G3c);                             % Convert to state-space
[A,B,C,D] = ssdata(sysc);
n = size(A,1);
m = size(B,2);
p = size(C,1);

% Generalized plant for H2:
% xdot = A x + B (w + u),   u = -K x
% z    = [C x; -K x] = C1 x + D12 u
C1  = [C; zeros(m,n)];                      % For z = C1 x + D12 u
D12 = [zeros(p,m); eye(m)];

% YALMIP decision variables
X = sdpvar(n,n,'symmetric');                % X > 0
Y = sdpvar(m,n,'full');                     % Y = K X
Z = sdpvar(p+m,p+m,'symmetric');            % For H2 objective

% LMIs:
% 1) Closed-loop Lyapunov with disturbance at same input B:
%    A X + X A' - (B Y + Y' B') + B B' < 0
eps_stab = 1e-9;
LMI_cl = A*X + X*A' - (B*Y + Y'*B') + (B*B') <= -eps_stab*eye(n);

% 2) H2 objective (z = C1 x + D12 u, u = -K x, Y = KX) via Schur complement:
%    [ Z,  (C1 X - D12 Y)
%      *,               X ] >= 0
LMI_h2 = [ Z,              (C1*X - D12*Y) ; ...
           (C1*X - D12*Y)',             X ] >= 0;

% Positive definiteness
LMI_pos = X >= 1e-6*eye(n);

Constraints = [LMI_cl, LMI_h2, LMI_pos];

% Objective: minimize trace(Z) = ||T_{w->z}||_2^2
Objective = trace(Z);

% Select solver (MOSEK preferred; fallback to SeDuMi if not found)
if exist('mosekopt','file') == 3 || exist('mosekopt','file') == 2
    solver = 'mosek';
else
    solver = 'sedumi';
end
ops = sdpsettings('solver',solver,'verbose',1);

% Solve the SDP
sol = optimize(Constraints, Objective, ops);
assert(sol.problem == 0, ['SDP failed: ', sol.info]);

% Recover controller K and H2 norm
Xv = value(X);
Yv = value(Y);
Kv = Yv / Xv;                               % K = Y * X^{-1}
H2sq = value(trace(Z));                     % squared H2 norm from w to z
H2norm = sqrt(max(H2sq,0));

fprintf('Controller synthesis successful.\n');
fprintf('||T_{w->z}||_2 = %.6f\n', H2norm);

% Closed-loop systems (from disturbance w to outputs)
Acl = A - B*Kv;
Bcl = B;
Cy  = C;                                    % output y
Dyw = zeros(p, m);

% Output y to w
sys_y_H2  = ss(Acl, Bcl, Cy,  Dyw);

% Control input u = -K x (as an output) to w
Cu  = -Kv;
Duw = zeros(m, m);
sys_u_H2  = ss(Acl, Bcl, Cu,  Duw);

% LQR comparison
Q = eye(n);
R = 1;
K_lqr = lqr(A,B,Q,R);

Acl_lqr = A - B*K_lqr;
sys_y_LQR = ss(Acl_lqr, Bcl, Cy,  Dyw);
sys_u_LQR = ss(Acl_lqr, Bcl, -K_lqr, Duw);

% Step response comparisons (disturbance step at w)
tFinal = 10;   % seconds; adjust if needed

figure('Name','Output y: H2 vs LQR (step disturbance at input)');
step(sys_y_H2, tFinal); hold on;
step(sys_y_LQR, tFinal);
grid on; legend('H2: y','LQR: y','Location','Best');
xlabel('Time (s)'); ylabel('Output y'); title('Step response from w to y');

figure('Name','Control effort u: H2 vs LQR (step disturbance at input)');
step(sys_u_H2, tFinal); hold on;
step(sys_u_LQR, tFinal);
grid on; legend('H2: u','LQR: u','Location','Best');
xlabel('Time (s)'); ylabel('Control input u'); title('Step response from w to u');

% Also show closed-loop step (reference at plant input as external input via w)
% If you want the regulation step of the state/output (without disturbance),
% you can instead plot step of the autonomous closed-loop from a reference model.

% Report gains
disp('H2 state-feedback gain K:');
disp(Kv);

disp('LQR state-feedback gain K_lqr:');
disp(K_lqr);

//@version=5
indicator("Structural Pivots Method (SPM) v5", overlay=true, max_lines_count=500, max_labels_count=500)

// Inputs
showSP = input.bool(true, "Show Small Pivots")
showLP = input.bool(true, "Show Large Pivots")
useCloseForBreak = input.bool(false, "Use Close for Break (else High/Low)")

// Helper accessors
getHigh(i) => high[i]
getLow(i) => low[i]

// Anchor/reference bar handling
// We will advance an anchor index as bars come if no SP is yet marked; once an SP is marked, anchor resets to that SP bar.
var int anchorIndex = na
var float anchorHigh = na
var float anchorLow = na

// Small pivots state
// A small pivot becomes temporary when first identified and becomes permanent if the opposing condition confirms it per rules.
var int lastSPHBar = na
var float lastSPHPrice = na
var bool lastSPHConfirmed = false

var int lastSPLBar = na
var float lastSPLPrice = na
var bool lastSPLConfirmed = false

// Large pivots state (alternate LPH/LPL using confirmed small pivots)
var int lastLPHBar = na
var float lastLPHPrice = na
var int lastLPLBar = na
var float lastLPLPrice = na
var bool expectLPHNext = true  // Alternate: after LPL expect LPH and vice versa

// Utility: did price break level?
brokenUp(level) => useCloseForBreak ? close > level : high > level
brokenDn(level) => useCloseForBreak ? close < level : low < level

// Initialize anchor on first bar
if na(anchorIndex)
    anchorIndex := bar_index
    anchorHigh := high
    anchorLow := low

// Common rule handler for SP detection using anchor/reference bar:
// - For SPH: need two bars (non-consecutive allowed concept via waiting) that put in a higher high than anchor and then a lower high that fails to exceed the new high -> mark the first as SPH when structure turns.
// - For SPL: symmetric for lows.
// Implementation approach:
//   We track a candidate swing in progress relative to anchor. When price makes a higher high than anchorHigh, we record candidate SPH at that bar. If later a bar makes a lower high and we also get a pullback that breaks anchorLow upwards (structure turn), we confirm SPH; otherwise it remains temporary and can be replaced by a new higher high candidate before confirmation. Symmetric for SPL.

// Candidate small pivots (temporary until confirmation)
var int candSPHBar = na
var float candSPHPrice = na
var int candSPLBar = na
var float candSPLPrice = na

// Update candidates relative to anchor
// If we make a new higher high vs current anchorHigh, create/replace SPH candidate
if high > anchorHigh
    candSPHBar := bar_index
    candSPHPrice := high
    // update reference to the highest seen during this up-leg
    anchorHigh := high

// If we make a new lower low vs current anchorLow, create/replace SPL candidate
if low < anchorLow
    candSPLBar := bar_index
    candSPLPrice := low
    // update reference to the lowest seen during this down-leg
    anchorLow := low

// Confirmation logic for small pivots using opposing break of structure:
// Confirm SPH when, after having a SPH candidate, price makes a lower low than the last interim swing low (anchorLow), i.e., down move begins and takes out that low.
sphConfirmed = false
splConfirmed = false

if not na(candSPHBar)
    // confirm SPH when we break down below the last anchorLow (useCloseForBreak flag)
    if brokenDn(anchorLow)
        lastSPHBar := candSPHBar
        lastSPHPrice := candSPHPrice
        lastSPHConfirmed := true
        sphConfirmed := true
        // reset up-leg candidate and set new anchor as this SPH
        candSPHBar := na
        candSPHPrice := na
        // after SPH confirmed, reset the down-reference (start tracking lows anew)
        anchorIndex := lastSPHBar
        anchorHigh := lastSPHPrice
        anchorLow := low  // current context low becomes fresh reference for next swings

if not na(candSPLBar)
    // confirm SPL when we break up above the last anchorHigh
    if brokenUp(anchorHigh)
        lastSPLBar := candSPLBar
        lastSPLPrice := candSPLPrice
        lastSPLConfirmed := true
        splConfirmed := true
        // reset down-leg candidate and set new anchor as this SPL
        candSPLBar := na
        candSPLPrice := na
        anchorIndex := lastSPLBar
        anchorLow := lastSPLPrice
        anchorHigh := high

// Temporary status rules: while not confirmed, a small pivot is temporary and can be replaced if a newer extreme in same direction occurs. The above logic already replaces candidates when new extremes appear; confirmation flips status to permanent.

// Large pivot construction rules:
// - Alternate LPH and LPL using confirmed small pivots.
// - LPH is the highest SPH since last LPL and only marked when a new confirmed SPL breaks below the previous SPL (i.e., structure change confirming the high).
// - LPL is the lowest SPL since last LPH and only marked when a new confirmed SPH breaks above the previous SPH.
// Maintain running extremes between alternations.
var float runHighSPH = na
var int runHighSPHBar = na
var float runLowSPL = na
var int runLowSPLBar = na

// Update running extremes on confirmation
if sphConfirmed
    // Update running highest SPH since last LPL
    if na(runHighSPH) or lastSPHPrice > runHighSPH
        runHighSPH := lastSPHPrice
        runHighSPHBar := lastSPHBar
    // If we were expecting LPL next, this SPH confirmation can finalize prior LPL selection rules
    if not expectLPHNext and not na(runLowSPL)
        // A break up confirms that the low selected earlier is indeed the LPL
        lastLPLBar := runLowSPLBar
        lastLPLPrice := runLowSPL
        expectLPHNext := true
        // reset low runner; keep high runner to start collecting for LPH
        runLowSPL := na
        runLowSPLBar := na

if splConfirmed
    // Update running lowest SPL since last LPH
    if na(runLowSPL) or lastSPLPrice < runLowSPL
        runLowSPL := lastSPLPrice
        runLowSPLBar := lastSPLBar
    // If we were expecting LPH next, this SPL confirmation can finalize prior LPH selection rules
    if expectLPHNext and not na(runHighSPH)
        // A break down confirms that the high selected earlier is indeed the LPH
        lastLPHBar := runHighSPHBar
        lastLPHPrice := runHighSPH
        expectLPHNext := false
        // reset high runner; keep low runner to start collecting for LPL
        runHighSPH := na
        runHighSPHBar := na

// Plot small pivots
spColorH = color.new(color.red, 0)
spColorL = color.new(color.lime, 0)
if showSP and lastSPHConfirmed and bar_index == lastSPHBar
    label.new(bar_index, lastSPHPrice, "SPH", style=label.style_label_down, textcolor=color.white, color=spColorH)
if showSP and lastSPLConfirmed and bar_index == lastSPLBar
    label.new(bar_index, lastSPLPrice, "SPL", style=label.style_label_up, textcolor=color.white, color=spColorL)

// Plot large pivots
lpColorH = color.new(color.maroon, 0)
lpColorL = color.new(color.teal, 0)
if showLP and not na(lastLPHBar) and bar_index == lastLPHBar
    label.new(bar_index, lastLPHPrice, "LPH", style=label.style_label_down, textcolor=color.white, color=lpColorH, size=size.large)
if showLP and not na(lastLPLBar) and bar_index == lastLPLBar
    label.new(bar_index, lastLPLPrice, "LPL", style=label.style_label_up, textcolor=color.white, color=lpColorL, size=size.large)

// Buy/Sell signals based on LP rules: Buy when new LPH and LPL are both higher than their previous counterparts (higher high and higher low). Sell when both are lower (lower high and lower low).
var float prevLPH = na
var float prevLPL = na
var int prevLPHBar = na
var int prevLPLBar = na

newLPH = not na(lastLPHBar) and (nz(prevLPHBar) != lastLPHBar)
newLPL = not na(lastLPLBar) and (nz(prevLPLBar) != lastLPLBar)

buySignal = false
sellSignal = false

if newLPH
    // Evaluate trend condition only when both previous LPs exist
    if not na(prevLPH) and not na(prevLPL) and not na(lastLPLPrice)
        buySignal := lastLPHPrice > prevLPH and lastLPLPrice > prevLPL
        sellSignal := lastLPHPrice < prevLPH and lastLPLPrice < prevLPL
    // Update prev LPH record
    prevLPH := lastLPHPrice
    prevLPHBar := lastLPHBar

if newLPL
    if not na(prevLPH) and not na(prevLPL) and not na(lastLPHPrice)
        buySignal := lastLPHPrice > prevLPH and lastLPLPrice > prevLPL
        sellSignal := lastLPHPrice < prevLPH and lastLPLPrice < prevLPL
    // Update prev LPL record
    prevLPL := lastLPLPrice
    prevLPLBar := lastLPLBar

plotshape(buySignal, title="Buy", style=shape.triangleup, color=color.new(color.green, 0), location=location.belowbar, size=size.tiny, text="Buy")
plotshape(sellSignal, title="Sell", style=shape.triangledown, color=color.new(color.red, 0), location=location.abovebar, size=size.tiny, text="Sell")

// Anchor visualization (optional)
plotchar(true, title="Anchor Bar", char="·", location=location.bottom, color=color.new(color.gray, 90))

//@version=5
indicator("Structural Pivots Method (SPM) v5", overlay=true, max_bars_back=5000)

// Core idea implemented:
// - Small pivots (SPH/SPL) are marked using an anchor/reference bar and can be non-consecutive (we search forward until confirmation).
// - Small pivots start as temporary and become permanent when opposite structure invalidates them or a large pivot forms using them.
// - Large pivots (LPH/LPL) alternate and are formed from breaks of prior opposite small pivots, selecting highest SPH for LPH and lowest SPL for LPL since previous large pivot.
// - Buy when consecutive large pivots are HH and HL; Sell when LH and LL.

//========================
// Inputs
//========================
lenLookAhead   = input.int(10, 'Max bars to confirm small pivot', minval=1)    // how far ahead we can look to confirm a small pivot
anchorLeft     = input.int(1,  'Anchor left bars', minval=1)
anchorRight    = input.int(1,  'Anchor right bars', minval=1)
showLabels     = input.bool(true, 'Show Labels')
showLines      = input.bool(true, 'Show Lines')

//========================
// Utilities
//========================
var float naFloat = na
var int   naInt   = na

// Highest high and lowest low helpers on a window
hhInRange(src, barsBack, barsFwd) =>
    // True if the anchor bar at index 0 is the highest within [ -barsBack, +barsFwd ]
    _hh = true
    for i = -barsBack to barsFwd
        if high[i] > high[0]
            _hh := false
    _hh

llInRange(src, barsBack, barsFwd) =>
    // True if the anchor bar at index 0 is the lowest within [ -barsBack, +barsFwd ]
    _ll = true
    for i = -barsBack to barsFwd
        if low[i] < low[0]
            _ll := false
    _ll

//========================
// Small Pivots (SPH/SPL)
// Rules:
// - Choose anchor/reference bar (current bar by default) and allow non-consecutive confirmation within lenLookAhead bars.
// - SPH: anchor high must not be exceeded by following bars until the right width is satisfied; vice-versa for SPL.
// - Temporary until opposing break occurs or a large pivot is formed.
//========================

// To support non-consecutive handling, we stage candidates and confirm when the forward condition is met.
var float sph_price_tmp = na
var int   sph_bar_index_tmp = na
var bool  sph_confirmed_tmp = false

var float spl_price_tmp = na
var int   spl_bar_index_tmp = na
var bool  spl_confirmed_tmp = false

// Confirm window control
var int   sph_wait = 0
var int   spl_wait = 0

// Start new candidates if none pending
newSPHCandidate = na(sph_bar_index_tmp) and hhInRange(high, anchorLeft, 0)
newSPLCandidate = na(spl_bar_index_tmp) and llInRange(low,  anchorLeft, 0)

if newSPHCandidate
    sph_price_tmp := high
    sph_bar_index_tmp := bar_index
    sph_wait := lenLookAhead
    sph_confirmed_tmp := false

if newSPLCandidate
    spl_price_tmp := low
    spl_bar_index_tmp := bar_index
    spl_wait := lenLookAhead
    spl_confirmed_tmp := false

// Manage pending SPH: invalidate if broken, confirm if right-side condition satisfied within window
if not na(sph_bar_index_tmp)
    // Invalidate if any higher high occurs before confirmation
    if high > sph_price_tmp
        sph_bar_index_tmp := na
        sph_price_tmp := na
        sph_wait := 0
        sph_confirmed_tmp := false
    else
        // Right-side confirmation when we have anchorRight bars without taking out the anchor
        rrDone = bar_index - sph_bar_index_tmp >= anchorRight
        if rrDone
            sph_confirmed_tmp := true
        sph_wait -= 1
        if sph_wait <= 0 and not sph_confirmed_tmp
            // window expired without confirmation
            sph_bar_index_tmp := na
            sph_price_tmp := na
            sph_wait := 0
            sph_confirmed_tmp := false

// Manage pending SPL
if not na(spl_bar_index_tmp)
    // Invalidate if any lower low occurs before confirmation
    if low < spl_price_tmp
        spl_bar_index_tmp := na
        spl_price_tmp := na
        spl_wait := 0
        spl_confirmed_tmp := false
    else
        rrDone = bar_index - spl_bar_index_tmp >= anchorRight
        if rrDone
            spl_confirmed_tmp := true
        spl_wait -= 1
        if spl_wait <= 0 and not spl_confirmed_tmp
            spl_bar_index_tmp := na
            spl_price_tmp := na
            spl_wait := 0
            spl_confirmed_tmp := false

// Store permanent SPHs/SPLs sequences (they alternate by construction of structure breaks later)
var float[] sph_prices = array.new_float()
var int[]   sph_bars   = array.new_int()
var float[] spl_prices = array.new_float()
var int[]   spl_bars   = array.new_int()

// When a temp small pivot is confirmed, push to arrays
if sph_confirmed_tmp and not na(sph_bar_index_tmp)
    array.push(sph_prices, sph_price_tmp)
    array.push(sph_bars,   sph_bar_index_tmp)
    // reset temp holder to allow next search
    sph_bar_index_tmp := na
    sph_price_tmp := na
    sph_wait := 0
    sph_confirmed_tmp := false

if spl_confirmed_tmp and not na(spl_bar_index_tmp)
    array.push(spl_prices, spl_price_tmp)
    array.push(spl_bars,   spl_bar_index_tmp)
    spl_bar_index_tmp := na
    spl_price_tmp := na
    spl_wait := 0
    spl_confirmed_tmp := false

//========================
// Large Pivots (LPH/LPL)
// Rules:
// - Alternate: LPH then LPL then LPH ...
// - An LPH requires price to break above a prior SPH since last LPL; choose the highest SPH since last LPL as LPH.
// - An LPL requires price to break below a prior SPL since last LPH; choose the lowest SPL since last LPH as LPL.
//========================

var float[] lph_prices = array.new_float()
var int[]   lph_bars   = array.new_int()
var float[] lpl_prices = array.new_float()
var int[]   lpl_bars   = array.new_int()

getLastLPLBar() => array.size(lpl_bars) > 0 ? array.get(lpl_bars, array.size(lpl_bars)-1) : naInt
getLastLPHBar() => array.size(lph_bars) > 0 ? array.get(lph_bars, array.size(lph_bars)-1) : naInt

// Helper to get extreme SPH/SPL since last opposite LP
highestSPHSince(barSince) =>
    hiVal = naFloat
    hiBar = naInt
    for i = 0 to array.size(sph_prices)-1
        b = array.get(sph_bars, i)
        if na(barSince) or b > barSince
            v = array.get(sph_prices, i)
            if na(hiVal) or v > hiVal
                hiVal := v
                hiBar := b
    [hiVal, hiBar]

lowestSPLSince(barSince) =>
    loVal = naFloat
    loBar = naInt
    for i = 0 to array.size(spl_prices)-1
        b = array.get(spl_bars, i)
        if na(barSince) or b > barSince
            v = array.get(spl_prices, i)
            if na(loVal) or v < loVal
                loVal := v
                loBar := b
    [loVal, loBar]

// Attempt LPH if price breaks above any SPH since last LPL
lastLPLBar = getLastLPLBar()
[hSP, hSB] = highestSPHSince(lastLPLBar)
if not na(hSP)
    broke = high >= hSP
    // Only add if we haven't already added an LPH at or after this SPH
    canAdd = broke and (array.size(lph_bars) == 0 or (not na(hSB) and hSB > getLastLPHBar()))
    if canAdd
        array.push(lph_prices, hSP)
        array.push(lph_bars,   bar_index)

// Attempt LPL if price breaks below any SPL since last LPH
lastLPHBar = getLastLPHBar()
[lSP, lSB] = lowestSPLSince(lastLPHBar)
if not na(lSP)
    broke = low <= lSP
    canAdd = broke and (array.size(lpl_bars) == 0 or (not na(lSB) and lSB > getLastLPLBar()))
    if canAdd
        array.push(lpl_prices, lSP)
        array.push(lpl_bars,   bar_index)

// Enforce alternation: if two same-type LPs appear consecutively due to edge timing, keep only the latest
if array.size(lph_bars) >= 2 and (array.size(lpl_bars) == 0 or array.get(lph_bars, array.size(lph_bars)-2) > array.get(lpl_bars, array.size(lpl_bars)-1))
    // Remove previous LPH to maintain alternation H-L-H-L
    array.pop(lph_bars)
    array.pop(lph_prices)
if array.size(lpl_bars) >= 2 and (array.size(lph_bars) == 0 or array.get(lpl_bars, array.size(lpl_bars)-2) > array.get(lph_bars, array.size(lph_bars)-1))
    array.pop(lpl_bars)
    array.pop(lpl_prices)

//========================
// Buy/Sell logic based on LPs
// Buy: Higher High LPH and Higher Low LPL (relative to prior LPs)
// Sell: Lower High LPH and Lower Low LPL
//========================
getLast2(arr) =>
    sz = array.size(arr)
    [sz >= 2 ? array.get(arr, sz-2) : naFloat, sz >= 1 ? array.get(arr, sz-1) : naFloat]

getLast2Bars(arr) =>
    sz = array.size(arr)
    [sz >= 2 ? array.get(arr, sz-2) : naInt, sz >= 1 ? array.get(arr, sz-1) : naInt]

[lphPrev, lphCurr] = getLast2(lph_prices)
[lplPrev, lplCurr] = getLast2(lpl_prices)

buyCond  = not na(lphPrev) and not na(lphCurr) and not na(lplPrev) and not na(lplCurr) and lphCurr > lphPrev and lplCurr > lplPrev
sellCond = not na(lphPrev) and not na(lphCurr) and not na(lplPrev) and not na(lplCurr) and lphCurr < lphPrev and lplCurr < lplPrev

//========================
// Plotting
//========================
plotshape(showLabels and array.size(sph_bars) > 0 and bar_index == array.get(sph_bars, array.size(sph_bars)-1), title='SPH', style=shape.triangledown, color=color.new(color.red, 0), location=location.abovebar, size=size.tiny, text='SPH')
plotshape(showLabels and array.size(spl_bars) > 0 and bar_index == array.get(spl_bars, array.size(spl_bars)-1), title='SPL', style=shape.triangleup,   color=color.new(color.lime, 0), location=location.belowbar, size=size.tiny, text='SPL')

// Draw last few LPs
lpShowN = 5
for i = math.max(array.size(lph_bars)-lpShowN, 0) to array.size(lph_bars)-1
    b = array.get(lph_bars, i)
    p = array.get(lph_prices, i)
    if showLabels
        label.new(b, p, 'LPH', style=label.style_label_down, color=color.new(color.orange, 0), textcolor=color.white)
    if showLines and i > 0
        pb = array.get(lph_bars, i-1)
        pp = array.get(lph_prices, i-1)
        line.new(pb, pp, b, p, extend=extend.none, color=color.orange)

for i = math.max(array.size(lpl_bars)-lpShowN, 0) to array.size(lpl_bars)-1
    b = array.get(lpl_bars, i)
    p = array.get(lpl_prices, i)
    if showLabels
        label.new(b, p, 'LPL', style=label.style_label_up, color=color.new(color.blue, 0), textcolor=color.white)
    if showLines and i > 0
        pb = array.get(lpl_bars, i-1)
        pp = array.get(lpl_prices, i-1)
        line.new(pb, pp, b, p, extend=extend.none, color=color.blue)

// Signals
plotshape(buyCond,  title='Buy',  style=shape.circle, color=color.new(color.green, 0), location=location.belowbar, size=size.tiny, text='Buy')
plotshape(sellCond, title='Sell', style=shape.circle, color=color.new(color.red,   0), location=location.abovebar, size=size.tiny, text='Sell')

// Alerts
alertcondition(buyCond,  'SPM Buy',  'Buy: Higher High and Higher Low Large Pivots')
alertcondition(sellCond, 'SPM Sell', 'Sell: Lower High and Lower Low Large Pivots')

//@version=5
indicator("Structural Pivots Method (SPM) v5", overlay=true, max_bars_back=5000)

// -------------------------------------------------------------
// Parameters
// -------------------------------------------------------------
spLookback     = input.int(50,   "Max bars to keep temp SPs before confirmation", minval=2)
plotLabels     = input.bool(true,  "Plot labels for SPs and LPs")
plotLines      = input.bool(true,  "Plot connector lines")
showSignals    = input.bool(true,  "Show Buy/Sell Signals")

// -------------------------------------------------------------
// State variables (var to persist across bars)
// -------------------------------------------------------------
// Anchor/reference bar tracking for Small Pivots
var int  anchorIdx      = na
var float anchorHigh    = na
var float anchorLow     = na

// Temporary Small Pivot candidates (until confirmed or invalidated)
var int   tempSPHIdx    = na
var float tempSPHPrice  = na
var int   tempSPLIdx    = na
var float tempSPLPrice  = na

// Confirmed Small Pivot Highs/Lows (arrays store recent history)
var array<int>  sphIdx  = array.new_int()
var array<float> sphVal = array.new_float()
var array<int>  splIdx  = array.new_int()
var array<float> splVal = array.new_float()

// Large Pivots
var array<int>  lphIdx  = array.new_int()
var array<float> lphVal = array.new_float()
var array<int>  lplIdx  = array.new_int()
var array<float> lplVal = array.new_float()

// -------------------------------------------------------------
// Helper functions
// -------------------------------------------------------------
addSPH(idx, price) =>
    array.push(sphIdx, idx)
    array.push(sphVal, price)

addSPL(idx, price) =>
    array.push(splIdx, idx)
    array.push(splVal, price)

last(arr) => array.size(arr) > 0 ? array.get(arr, array.size(arr) - 1) : na

// Get last confirmed SPH/SPL
lastSPHIdx = last(sphIdx)
lastSPHVal = last(sphVal)
lastSPLIdx = last(splIdx)
lastSPLVal = last(splVal)

// Get last confirmed LPH/LPL
lastLPHIdx = last(lphIdx)
lastLPHVal = last(lphVal)
lastLPLIdx = last(lplIdx)
lastLPLVal = last(lplVal)

// Utility to clear temp after confirmation or invalidation
clearTempSPH() =>
    tempSPHIdx   := na
    tempSPHPrice := na

clearTempSPL() =>
    tempSPLIdx   := na
    tempSPLPrice := na

// -------------------------------------------------------------
// Anchor/Reference Bar logic
// -------------------------------------------------------------
// If we don't have an anchor, initialize with the first available historical bar
if na(anchorIdx)
    anchorIdx  := bar_index
    anchorHigh := high
    anchorLow  := low

// Update anchor if current bar expands the reference extremes
if high > anchorHigh
    anchorHigh := high
    anchorIdx  := bar_index  // new reference at this bar for highs
if low < anchorLow
    anchorLow  := low
    anchorIdx  := bar_index  // new reference at this bar for lows

// -------------------------------------------------------------
// Small Pivot marking rules with non-consecutive bar handling
// Logic:
// - SPH candidate forms when we get a bar that sets a potential lower high after an anchor high.
// - SPL candidate forms when we get a bar that sets a potential higher low after an anchor low.
// - Candidates can form on non-consecutive bars and remain temporary until confirmed.
// - Confirmation for SPH: price makes a lower high than candidate and a bar closes below candidate's bar low (strict lower structure). For SPL: higher low than candidate and a bar closes above candidate's bar high.
// - If price invalidates candidate (e.g., makes a higher high above temp SPH, or a lower low below temp SPL), the candidate resets.
// - Once a small pivot is confirmed, it becomes permanent; opposing candidate is cleared.

// Create or update temp SPH candidate
// Condition to seed/refresh a temp SPH: we see a swing attempt down from a reference high
newTempSPH = na(tempSPHIdx) and high[0] < anchorHigh or (not na(tempSPHIdx) and high < tempSPHPrice)
if newTempSPH
    // pick the highest high since the last SPL (or since session start) as the SPH price reference
    hh = high
    hiIdx = bar_index
    lookbackBars = math.min(spLookback, bar_index)
    for i = 1 to lookbackBars
        condStop = not na(lastSPLIdx) and bar_index - i <= lastSPLIdx
        if condStop
            break
        if high[i] > hh
            hh := high[i]
            hiIdx := bar_index - i
    tempSPHIdx   := na(tempSPHIdx) ? hiIdx : (high > tempSPHPrice ? bar_index : tempSPHIdx)
    tempSPHPrice := na(tempSPHPrice) ? hh    : math.max(tempSPHPrice, high)

// Create or update temp SPL candidate
newTempSPL = na(tempSPLIdx) and low[0] > anchorLow or (not na(tempSPLIdx) and low > tempSPLPrice)
if newTempSPL
    // pick the lowest low since the last SPH as the SPL price reference
    ll = low
    loIdx = bar_index
    lookbackBars2 = math.min(spLookback, bar_index)
    for i = 1 to lookbackBars2
        condStop = not na(lastSPHIdx) and bar_index - i <= lastSPHIdx
        if condStop
            break
        if low[i] < ll
            ll := low[i]
            loIdx := bar_index - i
    tempSPLIdx   := na(tempSPLIdx) ? loIdx : (low < tempSPLPrice ? bar_index : tempSPLIdx)
    tempSPLPrice := na(tempSPLPrice) ? ll   : math.min(tempSPLPrice, low)

// Invalidation of temp SPs by opposite extreme breaks
// If price makes a new higher high while we have a temp SPH, invalidate temp SPH
if not na(tempSPHIdx) and high > tempSPHPrice
    clearTempSPH()
// If price makes a new lower low while we have a temp SPL, invalidate temp SPL
if not na(tempSPLIdx) and low < tempSPLPrice
    clearTempSPL()

// Confirmation rules
confirmSPH = not na(tempSPHIdx) and close < tempSPHPrice and high < tempSPHPrice
if confirmSPH
    addSPH(tempSPHIdx, tempSPHPrice)
    // After confirming SPH, reset anchor for next sequence from this pivot
    anchorIdx  := tempSPHIdx
    anchorHigh := tempSPHPrice
    clearTempSPH()
    // Opposing temp SPL is not necessarily invalidated; keep if still valid

