// Utilities that enforce proper documentation formatting.
// Must-do rules implemented here:
// 1) Single H1 derived from title.
// 2) Outline extraction (H1..H6) for a sidebar.
// 3) Normalize blank lines and ensure EOF newline.

export function enforceSingleH1(markdown: string, title: string): string {
  const lines = markdown.split(/\r?\n/);
  // Remove all leading H1s
  const filtered = lines.filter((l, i) => !(i === 0 && /^#\s+/.test(l)));
  // Remove any other H1 anywhere
  const noExtraH1 = filtered.map((l) => (/^#\s+/.test(l) ? l.replace(/^#\s+/, "## ") : l));
  // Prepend single H1 based on title
  return [`# ${title.trim()}`, "", ...noExtraH1].join("\n");
}

export function normalizeSpacing(markdown: string): string {
  // Collapse >2 blank lines to exactly 1
  let out = markdown.replace(/\n{3,}/g, "\n\n");
  // Ensure single trailing newline
  out = out.replace(/\s*$/, "\n");
  return out;
}

export type OutlineItem = { depth: number; text: string; line: number };

export function extractOutline(markdown: string): OutlineItem[] {
  const lines = markdown.split(/\r?\n/);
  const outline: OutlineItem[] = [];
  lines.forEach((l, idx) => {
    const m = /^(#{1,6})\s+(.*)$/.exec(l);
    if (m) outline.push({ depth: m[1].length, text: m[2].trim(), line: idx });
  });
  return outline;
}
