# components/DocEditor.tsx
# -------------------------------------------------------------
"use client";

import * as React from "react";
import { db, storage } from "@/lib/firebase";
import {
  doc,
  getDoc,
  onSnapshot,
  setDoc,
  updateDoc,
  deleteDoc,
  serverTimestamp,
} from "firebase/firestore";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";
import { MarkdownRXEditor, MarkdownRXPreview } from "@/components/MarkdownRX";
import Outline from "@/components/Outline";
import { enforceSingleH1, normalizeSpacing } from "@/lib/formatting";
import { useRouter } from "next/navigation";

type DocData = {
  title: string;
  content: string;
  tags?: string[];
  createdAt?: any;
  updatedAt?: any;
};

function slugify(input: string) {
  return input
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)+/g, "");
}

export default function DocEditor({ slug }: { slug: string }) {
  const [docData, setDocData] = React.useState<DocData | null>(null);
  const [title, setTitle] = React.useState<string>("");
  const [tagsText, setTagsText] = React.useState<string>("");
  const [content, setContent] = React.useState<string>("");
  const [saving, setSaving] = React.useState<boolean>(false);
  const [renaming, setRenaming] = React.useState<boolean>(false);
  const [deleting, setDeleting] = React.useState<boolean>(false);
  const [lastSavedAt, setLastSavedAt] = React.useState<Date | null>(null);

  const router = useRouter();

  // Subscribe to Firestore doc by slug
  React.useEffect(() => {
    const refDoc = doc(db, "docs", slug);
    const unsub = onSnapshot(refDoc, (snap) => {
      if (snap.exists()) {
        const d = snap.data() as DocData;
        setDocData(d);
        setTitle(d.title || "");
        setContent(d.content || "");
        setTagsText((d.tags || []).join(", "));
      } else {
        setDocData(null);
        setTitle("");
        setContent("");
        setTagsText("");
      }
    });
    return () => unsub();
  }, [slug]);

  async function onUploadImage(file: File): Promise<string> {
    const path = `docs/${slug}/images/${Date.now()}-${file.name}`;
    const r = ref(storage, path);
    await uploadBytes(r, file);
    return await getDownloadURL(r);
  }

  function applyFormattingForSave(raw: string, t: string): string {
    let out = enforceSingleH1(raw, t || "Untitled");
    out = normalizeSpacing(out);
    return out;
  }

  async function saveDoc() {
    setSaving(true);
    try {
      const formatted = applyFormattingForSave(content, title);
      const refDoc = doc(db, "docs", slug);
      await setDoc(refDoc, {
        title: title || "Untitled",
        content: formatted,
        tags: tagsText
          .split(",")
          .map((t) => t.trim())
          .filter(Boolean),
        updatedAt: serverTimestamp(),
        createdAt: (await getDoc(refDoc)).exists() ? undefined : serverTimestamp(),
      }, { merge: true });
      setLastSavedAt(new Date());
      setContent(formatted); // reflect normalization in editor
    } finally {
      setSaving(false);
    }
  }

  async function renameDoc(newTitle: string) {
    const newSlug = slugify(newTitle);
    if (!newSlug || newSlug === slug) return;
    setRenaming(true);
    try {
      const oldRef = doc(db, "docs", slug);
      const snap = await getDoc(oldRef);
      if (!snap.exists()) return;
      const data = snap.data() as DocData;
      const newRef = doc(db, "docs", newSlug);
      const formatted = applyFormattingForSave(data.content || "", newTitle);
      await setDoc(newRef, {
        ...data,
        title: newTitle,
        content: formatted,
        updatedAt: serverTimestamp(),
      });
      await deleteDoc(oldRef);
      router.replace(`/docs/${newSlug}`);
    } finally {
      setRenaming(false);
    }
  }

  async function deleteDocPermanently() {
    setDeleting(true);
    try {
      await deleteDoc(doc(db, "docs", slug));
      router.replace("/docs");
    } finally {
      setDeleting(false);
    }
  }

  if (docData === null && !title && !content) {
    return (
      <div className="space-y-4">
        <div className="text-sm text-muted-foreground">Document not found. Create it below.</div>
        <button
          className="rounded border px-3 py-2 text-sm"
          onClick={async () => {
            await setDoc(doc(db, "docs", slug), {
              title: slug.replace(/-/g, " ").replace(/\b\w/g, (m) => m.toUpperCase()),
              content: `# ${slug.replace(/-/g, " ")}\n\n`,
              createdAt: serverTimestamp(),
              updatedAt: serverTimestamp(),
            }, { merge: true });
          }}
        >
          Create document
        </button>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 gap-6 lg:grid-cols-[1fr_280px]">
      <div className="space-y-4">
        <div className="flex flex-col gap-2 md:flex-row md:items-center">
          <input
            className="w-full rounded border px-3 py-2"
            placeholder="Title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />
          <div className="flex gap-2">
            <button className="rounded border px-3 py-2 text-sm" onClick={saveDoc} disabled={saving}>
              {saving ? "Saving..." : "Save"}
            </button>
            <button className="rounded border px-3 py-2 text-sm" onClick={() => renameDoc(title)} disabled={renaming}>
              Rename to Title
            </button>
            <button className="rounded border px-3 py-2 text-sm text-red-600" onClick={deleteDocPermanently} disabled={deleting}>
              Delete
            </button>
          </div>
        </div>

        <input
          className="w-full rounded border px-3 py-2"
          placeholder="tags, comma, separated"
          value={tagsText}
          onChange={(e) => setTagsText(e.target.value)}
        />

        <MarkdownRXEditor value={content} onChange={setContent} onUploadImage={onUploadImage} />

        <div className="text-xs text-muted-foreground">
          {lastSavedAt ? `Last saved ${lastSavedAt.toLocaleTimeString()}` : ""}
        </div>

        <div className="rounded-md border p-3">
          <div className="mb-2 font-semibold">Preview</div>
          <div className="prose max-w-none">
            <MarkdownRXPreview value={applyFormattingForSave(content, title)} />
          </div>
        </div>
      </div>

      <div className="hidden lg:block">
        <Outline markdown={applyFormattingForSave(content, title)} />
      </div>
    </div>
  );
}
