Here is a JavaScript-based solution that renders a cardio-style moving dot over a tight horizontal line, within a fixed 32px-high track and 100% width. The dot travels left-to-right and performs brief pulse spikes (up and down) without drawing a triangular waveform line—only the dot changes its vertical position/scale briefly to mimic the pulse, like a medical device display.

- Height: 32px container, centered 1px line across full width.
- Width: 100% responsive canvas.
- The dot moves continuously. On a schedule (or randomness), it quickly rises then falls (and mirrors below) in a short window to emulate the pulse.

Copy-paste and open in a browser:

<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8" />
<title>Cardio Pulse Dot (JS + Canvas)</title>
<style>
  /* 32px tall area, full width */
  .pulse-wrap {
    width: 100%;
    height: 32px;            /* required 32px */
    position: relative;
  }
  canvas {
    width: 100%;            /* responsive width */
    height: 100%;           /* exact 32px CSS pixels */
    display: block;
  }
</style>
</head>
<body>
  <div class="pulse-wrap">
    <canvas id="pulseCanvas"></canvas>
  </div>

<script>
(function() {
  const canvas = document.getElementById('pulseCanvas');
  const dpr = Math.max(1, window.devicePixelRatio || 1);

  function resizeCanvas() {
    // CSS size
    const cssWidth = canvas.clientWidth;
    const cssHeight = canvas.clientHeight; // 32px from CSS
    // Backing store
    canvas.width = Math.max(1, Math.floor(cssWidth * dpr));
    canvas.height = Math.max(1, Math.floor(cssHeight * dpr));
  }

  // Initial size and on resize
  resizeCanvas();
  window.addEventListener('resize', resizeCanvas);

  const ctx = canvas.getContext('2d');

  // Visual params
  const lineColor = '#e00';
  const lineWidthPx = 1;              // tight 1px line
  const dotColor = '#0a6cff';
  const dotRadiusCss = 3.5;           // CSS px radius of the dot

  // Motion params
  const travelDuration = 2000;        // ms to go left->right once
  const pulseInterval = 900;          // ms between pulse starts (can randomize)
  const pulseDuration = 220;          // ms total pulse window
  const pulsePeakScale = 3.8;         // how tall the pulse rises at peak (relative)
  const mirrorDown = true;            // mirror below the line briefly

  // Pulse scheduling
  let nextPulseAt = performance.now() + pulseInterval;
  let lastPulseStart = -Infinity;

  // Animation state
  let lastTime = performance.now();

  function easeOutCubic(t) { return 1 - Math.pow(1 - t, 3); }
  function easeInCubic(t) { return t * t * t; }

  function pulseEnvelope(t) {
    // 0..pulseDuration -> 0..1..0 envelope controlling vertical excursion
    const half = pulseDuration / 2;
    if (t < 0 || t > pulseDuration) return 0;
    if (t <= half) {
      return easeOutCubic(t / half); // up fast
    } else {
      return easeInCubic(1 - (t - half) / half); // down slower
    }
  }

  function drawFrame(now) {
    const cssW = canvas.clientWidth;
    const cssH = canvas.clientHeight; // 32

    // Clear
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Coordinate helpers (CSS px -> device px)
    const toX = v => v * dpr;
    const toY = v => v * dpr;

    // Line Y center
    const midY = cssH / 2;

    // Draw center baseline (tight 1px across 100% width)
    ctx.strokeStyle = lineColor;
    ctx.lineWidth = Math.max(1, Math.round(lineWidthPx * dpr));
    ctx.beginPath();
    // Align to pixel grid for crisp 1px
    const yAligned = Math.round(toY(midY)) + (ctx.lineWidth % 2 === 0 ? 0 : 0.5);
    ctx.moveTo(0, yAligned);
    ctx.lineTo(toX(cssW), yAligned);
    ctx.stroke();

    // Travel progress 0..1 across width
    const travelT = ((now % travelDuration) / travelDuration);
    const xCss = travelT * cssW;

    // Schedule pulses
    if (now >= nextPulseAt) {
      lastPulseStart = now;
      // Randomize slightly like medical irregularity (optional)
      const jitter = Math.random() * 250 - 100; // +/-100ms
      nextPulseAt = now + pulseInterval + jitter;
    }

    // Active pulse envelope (0..1)
    const sincePulse = now - lastPulseStart;
    const env = pulseEnvelope(sincePulse);

    // Compute vertical displacement from center
    // Up spike first; if mirrorDown, render a brief mirrored blip after peak.
    let yCss = midY;
    if (env > 0) {
      const up = (pulsePeakScale * env) * (cssH * 0.5 - dotRadiusCss - 1);
      yCss = midY - up; // go up
    } else if (mirrorDown) {
      // brief mirrored decay just after pulse window
      const t = sincePulse - pulseDuration;
      const tail = pulseEnvelope(t); // reuse envelope for symmetry tail
      if (tail > 0) {
        const down = (pulsePeakScale * tail) * (cssH * 0.5 - dotRadiusCss - 1);
        yCss = midY + down; // go down
      }
    }

    // Draw moving dot (circle)
    ctx.fillStyle = dotColor;
    ctx.beginPath();
    ctx.arc(toX(xCss), toY(yCss), toX(dotRadiusCss), 0, Math.PI * 2);
    ctx.fill();

    requestAnimationFrame(drawFrame);
  }

  requestAnimationFrame(drawFrame);
})();
</script>
</body>
</html>

Notes:
- The 32px height and 100% width are enforced by CSS on the container and canvas; the script adapts the drawing buffer for crisp rendering on high-DPI screens.
- Only a tight 1px horizontal line is drawn; the “waveform” is visually implied by the dot’s vertical motion, not by a drawn triangular shape.
- You can tune travelDuration, pulseInterval, pulseDuration, and pulsePeakScale to achieve the exact cadence you want (steady or slightly irregular).

Below is a complete, self-contained HTML + CSS + JavaScript example that renders a cardio-like pulsing animation with a horizontal baseline, a moving dot, and periodic triangular spikes. The track is 32px tall and 100% wide, the waveform itself is not constantly drawn as a triangle; instead a dot traverses the line and briefly rises/returns to create a triangular pulse.

Why JavaScript over CSS for this task:
- Timing control: JavaScript lets you schedule non-uniform events (e.g., periodic spikes with variable durations) and precisely place the moving dot using requestAnimationFrame. CSS animations are great for repetitive, fixed keyframes, but become unwieldy when you need procedural timing, dynamic BPM, jitter, or responsive recalculation.
- Dynamic wave shape: With JS you can compute the dot’s Y position per frame (baseline, up-slope, down-slope) without having to predefine complex keyframes. This mirrors medical device behavior more closely.
- Synchronization: JS makes it straightforward to keep the moving dot, spike timing, and any auxiliary indicators in sync.

Copy-paste and open in a browser:

<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Cardio-like Pulsing Animation</title>
  <style>
    /* Container fills width, fixed height 32px as requested */
    .cardio {
      width: 100%;
      height: 32px;               /* requirement: 32px height */
      position: relative;
      background: #081018;        /* dark background like monitors */
      overflow: hidden;           /* hide dot overflow during spike */
      border-left: 2px solid #0df2;
      border-right: 2px solid #0df2;
    }

    /* Horizontal baseline centered vertically */
    .baseline {
      position: absolute;
      left: 0;
      right: 0;
      top: 50%;
      height: 2px;
      transform: translateY(-50%);
      background: linear-gradient(90deg, #0df8 0 2px, transparent 2px) repeat-x;
      background-size: 6px 2px;   /* subtle tick pattern */
    }

    /* Moving dot represents the signal; we draw only the dot, not a full triangle */
    .dot {
      position: absolute;
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: #0df;           /* cyan-ish medical feel */
      box-shadow: 0 0 6px 2px #0df7;
      will-change: transform;
    }
  </style>
</head>
<body>
  <div class="cardio" id="cardio">
    <div class="baseline"></div>
    <div class="dot" id="dot"></div>
  </div>

  <script>
    // Configuration
    const container = document.getElementById('cardio');
    const dot = document.getElementById('dot');

    // Dimensions (computed from container)
    let W = 0;                    // track width (100%)
    const H = 32;                 // required height

    // Visual placement
    const baselineY = H / 2;      // vertical center baseline
    const dotSize = 6;            // matches CSS

    // Pulse timing (can be tweaked)
    const bpm = 72;               // beats per minute
    const period = 60_000 / bpm;  // ms per beat

    // Triangular spike timing proportions (sum <= 1; rest is baseline)
    const upMs = 70;              // up-slope duration
    const downMs = 110;           // down-slope duration
    const holdMs = 30;            // brief peak hold (optional)
    const spikeDuration = upMs + holdMs + downMs; // total spike window

    // Spike amplitude (in pixels). Keep within container; 10–12px looks good in 32px track.
    const spikeAmp = 12;

    // Horizontal velocity: one full sweep per period (dot traverses left->right each beat)
    // If you prefer continuous sweep regardless of BPM, decouple vx from period.
    function computeVX() {
      return W / period; // px per ms
    }

    // State
    let vx = 0;                   // horizontal px/ms
    let x = 0;                    // current x position
    let lastT = performance.now();
    let lastBeatT = lastT;        // timestamp of last spike start

    function resize() {
      W = container.clientWidth;
      vx = computeVX();
      // Keep x within [0, W)
      x = ((x % W) + W) % W;
    }
    window.addEventListener('resize', resize);
    resize();

    // Compute vertical offset for the dot given elapsed time in current beat
    function spikeYOffset(elapsed) {
      // Triangular profile: baseline -> up -> hold -> down -> baseline
      if (elapsed < 0 || elapsed > spikeDuration) return 0; // baseline

      if (elapsed <= upMs) {
        // linear rise 0 -> spikeAmp
        return -(elapsed / upMs) * spikeAmp;
      }
      if (elapsed <= upMs + holdMs) {
        // hold at peak
        return -spikeAmp;
      }
      // descend spikeAmp -> 0
      const d = elapsed - upMs - holdMs;
      return -spikeAmp * (1 - d / downMs);
    }

    function animate(t) {
      const dt = t - lastT;
      lastT = t;

      // Start a new beat at fixed intervals
      if (t - lastBeatT >= period) {
        // carry over remainder so beats stay aligned with time, not drift
        const overshoot = (t - lastBeatT) % period;
        lastBeatT = t - overshoot;
      }

      // Advance horizontal position
      x += vx * dt;
      if (x > W) x -= W; // wrap to create continuous sweep across 100% width

      // Vertical offset based on current beat phase
      const beatElapsed = t - lastBeatT;
      const yOff = spikeYOffset(beatElapsed);

      // Position the dot: baseline + y offset; center dot around its size
      const y = baselineY + yOff - dotSize / 2;
      const drawX = x - dotSize / 2;

      dot.style.transform = `translate(${drawX}px, ${y}px)`;

      requestAnimationFrame(animate);
    }

    requestAnimationFrame(animate);
  </script>
</body>
</html>

How it matches your requirements:
- JavaScript-driven animation: Uses requestAnimationFrame for smooth motion and precise timing (moving dot plus periodic triangular spike).
- Medical cardio feel: A horizontal baseline with a glowing dot that spikes up and returns, mimicking monitor blips.
- 32px height and 100% width: The container is exactly 32px tall and expands to full width; the dot traverses the entire width and wraps.
- No constantly visible triangular waveform: Only the dot is rendered; the triangle shape is implied by the dot’s vertical excursion during each beat.
- Extensible: Adjust bpm, spike timings (upMs, holdMs, downMs), and spikeAmp to tune the look.

If you prefer the dot to move at a constant speed independent of BPM, set vx to a fixed px/ms and keep lastBeatT for spikes only.

