// Generic repository (template class) - stores unique_ptr of any type T
template <typename T>
class Repository {
private:
    std::vector<std::unique_ptr<T>> items_;
public:
    Repository() = default;

    // Perfect-forwarding add overloads
    template <typename U, typename... Args>
    U& emplace(Args&&... args) {
        auto ptr = std::make_unique<U>(std::forward<Args>(args)...);
        U& ref = *ptr;
        items_.push_back(std::move(ptr));
        return ref;
    }

    void add(std::unique_ptr<T> t) { items_.push_back(std::move(t)); }

    // Iteration support
    auto begin() { return items_.begin(); }
    auto end() { return items_.end(); }
    auto begin() const { return items_.begin(); }
    auto end() const { return items_.end(); }

    std::size_t size() const { return items_.size(); }

    // Functional utility: apply a callable to each element
    template <typename F>
    void for_each(F&& f) const {
        for (const auto& p : items_) f(*p);
    }
};

// Analyzer (template) for data analysis on ranges of Exhibits or other items
template <typename Range, typename Metric>
auto average_metric(const Range& range, Metric metric) -> std::optional<double> {
    double sum = 0.0;
    std::size_t n = 0;
    for (const auto& x : range) {
        sum += metric(x);
        ++n;
    }
    if (n == 0) return std::nullopt;
    return sum / static_cast<double>(n);
}

// Overloaded free function template: count_if on smart pointers or values
// Version 1: elements are values
template <typename Range, typename Pred,
          typename Elem = decltype(*std::begin(std::declval<const Range&>())),
          typename = std::enable_if_t<!std::is_pointer<Elem>::value>>
std::size_t count_if_any(const Range& range, Pred p) {
    return static_cast<std::size_t>(std::count_if(std::begin(range), std::end(range), p));
}

// Version 2: elements are smart pointers (unique_ptr/shared_ptr)
template <typename Range, typename Pred,
          typename ElemPtr = decltype(*std::begin(std::declval<const Range&>()))>
std::size_t count_if_any_ptr(const Range& range, Pred p) {
    std::size_t cnt = 0;
    for (const auto& ptr : range) if (p(*ptr)) ++cnt;
    return cnt;
}

// Museum class encapsulating exhibits and providing analysis
class Museum {
private:
    Repository<Exhibit> exhibits_;
public:
    Museum() = default;

    // Overloaded add APIs
    void add(std::unique_ptr<Exhibit> e) { exhibits_.add(std::move(e)); }

    template <typename E, typename... Args>
    E& addEmplace(Args&&... args) { return exhibits_.emplace<E>(std::forward<Args>(args)...); }

    // Display all exhibits (polymorphism)
    void displayAll() const {
        exhibits_.for_each([](const Exhibit& e){ e.display(); });
    }

    // Data processing: group counts by type
    std::map<std::string, int> countByType() const {
        std::map<std::string, int> counts;
        exhibits_.for_each([&](const Exhibit& e){ counts[e.type()]++; });
        return counts;
    }

    // Data analysis: average rating across all exhibits
    std::optional<double> averageRatingAll() const {
        double sum = 0.0; std::size_t n = 0;
        exhibits_.for_each([&](const Exhibit& e){
            if (auto av = e.averageRating()) { sum += *av; ++n; }
        });
        if (n == 0) return std::nullopt;
        return sum / static_cast<double>(n);
    }

    // Data analysis via template: average of a metric (e.g., by year)
    std::optional<double> averageYear() const {
        return average_metric(exhibits_, [](const std::unique_ptr<Exhibit>& p){ return static_cast<double>(p->getYear()); });
    }

    // Filter by predicate into a vector of raw pointers (non-owning)
    template <typename Pred>
    std::vector<const Exhibit*> filter(Pred p) const {
        std::vector<const Exhibit*> out;
        exhibits_.for_each([&](const Exhibit& e){ if (p(e)) out.push_back(&e); });
        return out;
    }
};

int main() {
    std::ios::sync_with_stdio(false);

    Museum museum;

    // Add exhibits using emplace (templates, inheritance, polymorphism)
    museum.addEmplace<Painting>("The Starry Night", 1889, "Vincent van Gogh", "Oil on Canvas");
    museum.addEmplace<Sculpture>("David", 1504, "Marble", Dimension(5.17, 1.99, 1.99));
    museum.addEmplace<Painting>("The Persistence of Memory", 1931, "Salvador Dali", "Oil on Canvas");
    museum.addEmplace<Photograph>("Migrant Mother", 1936, "Dorothea Lange", "Film");
    museum.addEmplace<Installation>("The Weather Project", 2003, "Olafur Eliasson", Dimension(50, 35, 20));

    // Rate a few exhibits (method overloading)
    {
        // Filter by type to get some pointers and add ratings
        auto topaintings = museum.filter([](const Exhibit& e){ return e.type() == "Painting"; });
        if (!topaintings.empty()) {
            // Demonstrate that we can interact through base-class references via RTTI if needed
            const_cast<Exhibit*>(topaintings[0])->addRating({5, 5, 4, 5});
        }
    }

    // Display all (polymorphism)
    museum.displayAll();

    // Data analysis and processing using STL and templates
    if (auto avgYear = museum.averageYear()) {
        std::cout << "Average year across exhibits: " << *avgYear << "\n";
    }

    if (auto avgRating = museum.averageRatingAll()) {
        std::cout << "Average rating across rated exhibits: " << *avgRating << "\n";
    } else {
        std::cout << "No ratings to analyze.\n";
    }

    // Count by type (processing + STL map)
    auto counts = museum.countByType();
    std::cout << "Counts by type:\n";
    for (const auto& [k, v] : counts) {
        std::cout << "  " << k << ": " << v << "\n";
    }

    // Demonstrate repository-level pointer-aware counting template
    // Build a simple vector of unique_ptr<Exhibit> to reuse count_if_any_ptr
    std::vector<std::unique_ptr<Exhibit>> temp;
    temp.push_back(std::make_unique<Painting>("Guernica", 1937, "Pablo Picasso", "Oil"));
    temp.push_back(std::make_unique<Sculpture>("The Thinker", 1904, "Bronze", Dimension(1.8, 1.0, 1.0)));
    std::size_t nPaintings = count_if_any_ptr(temp, [](const Exhibit& e){ return e.type() == "Painting"; });
    std::cout << "Temporary collection has " << nPaintings << " painting(s).\n";

    // Operator overloading demo for Dimension
    Dimension base(2,3,4), addon(1,1,1);
    Dimension combined = base + addon;
    std::cout << "Combined dimension: " << combined << ", volume=" << combined.volume() << "\n";

    return 0;
}
