# ---------- Generic Repository (Template-like via Generics) ----------

class Repository(Generic[T]):
    def __init__(self):
        self._items: List[T] = []

    def add(self, item: T) -> None:
        self._items.append(item)

    def extend(self, items: IterableABC) -> None:
        for it in items:
            self.add(it)

    def where(self, predicate: Callable[[T], bool]) -> List[T]:
        return [x for x in self._items if predicate(x)]

    def sort_by(self, key: Callable[[T], object], reverse: bool = False) -> None:
        self._items.sort(key=key, reverse=reverse)

    def map(self, fn: Callable[[T], K]) -> List[K]:
        return [fn(x) for x in self._items]

    def __iter__(self) -> Iterator[T]:
        return iter(self._items)

    def __len__(self) -> int:
        return len(self._items)

    def __getitem__(self, idx: int) -> T:
        return self._items[idx]

    def to_list(self) -> List[T]:
        return list(self._items)


# ---------- Analyzer (Generic templates for methods/classes) ----------

class Analyzer(Generic[T]):
    def __init__(self, items: Iterable[T]):
        self._items = list(items)

    def token_frequencies(self, source: Callable[[T], str], tok: Callable[[str], List[str]] = tokenize) -> Counter:
        c = Counter()
        for it in self._items:
            c.update(tok(source(it)))
        return c

    def top_n(self, score: Callable[[T], float], n: int) -> List[T]:
        return sorted(self._items, key=score, reverse=True)[:n]

    def summary(self, value: Callable[[T], float]) -> Optional[Dict[str, float]]:
        return summarize_numeric(self._items, value)

    def histogram(self, bucket: Callable[[T], K]) -> Dict[K, int]:
        h: Dict[K, int] = defaultdict(int)
        for it in self._items:
            h[bucket(it)] += 1
        return dict(h)


# ---------- Example data analysis integration for Exhibits ----------

def analyze_exhibits(exhibits: Iterable[Exhibit]) -> Dict[str, object]:
    """Integrate data processing over exhibits while preserving original functionality.
    Returns assorted analysis artifacts using generic templates and STL-like constructs.
    """
    items = list(exhibits)
    az = Analyzer(items)

    # Text analysis on descriptions and names
    token_counts = az.token_frequencies(lambda e: f"{e.name} {e.description}")

    # Numeric summaries on ratings and exhibit years
    rating_summary = az.summary(lambda e: e.average_rating() or 0.0)
    year_summary = az.summary(lambda e: float(e.year))

    # Histogram/grouping by kind and by decade buckets
    by_kind = az.histogram(lambda e: e.kind())
    by_decade = az.histogram(lambda e: (e.year // 10) * 10)

    # Top-N exhibits by average rating (polymorphic score usage)
    top_rated = az.top_n(lambda e: e.average_rating() or 0.0, n=3)

    return {
        "token_counts": token_counts,
        "rating_summary": rating_summary,
        "year_summary": year_summary,
        "by_kind": by_kind,
        "by_decade": by_decade,
        "top_rated": [str(e) for e in top_rated],
    }
