Below is a detailed, end-to-end C# example that runs inside Advance Steel and uses the Autodesk Advance Steel .NET API to place Cartesian (ordinate) dimensions for all holes of a single plate on its part drawing, measured from the plate’s bottom-left corner (0,0 of the plate outline in the view). The sample shows how to: locate the single-part drawing and its view, get the plate model object and its holes, compute the Cartesian origin, and create Advance Steel drawing dimensions with their origins set to that corner.

Notes
- Target: Part drawing (single-part) with one plate; holes will be dimensioned relative to the plate outline’s lower-left corner in the view.
- Uses Advance Steel drawing API (Autodesk.AdvanceSteel.Drawing.*) and model API (Autodesk.AdvanceSteel.Modelling.*). It creates drawing dimensions (not plain AutoCAD dimensions) so they belong to the Advance Steel drawing and follow detailing updates better than vanilla entities.
- Replace naming/selection as needed to suit your workflow.

// Required references (from Advance Steel SDK installation):
// - Autodesk.AdvanceSteel.CADAccess.dll
// - Autodesk.AdvanceSteel.DotNetRoots.dll
// - Autodesk.AdvanceSteel.DocumentManagement.dll
// - Autodesk.AdvanceSteel.Geometry.dll
// - Autodesk.AdvanceSteel.Modelling.dll
// - Autodesk.AdvanceSteel.Drawing.dll
// - AcMgd.dll, AcDbMgd.dll, AcCoreMgd.dll (AutoCAD)

using System;
using System.Collections.Generic;
using System.Linq;
using Autodesk.AutoCAD.ApplicationServices;
using Autodesk.AutoCAD.DatabaseServices;
using Autodesk.AutoCAD.EditorInput;
using Autodesk.AutoCAD.Geometry;
using Autodesk.AutoCAD.Runtime;
using Autodesk.AdvanceSteel.CADAccess;
using Autodesk.AdvanceSteel.DocumentManagement;
using Autodesk.AdvanceSteel.Geometry;
using Autodesk.AdvanceSteel.Modelling;
using Autodesk.AdvanceSteel.ConstructionTypes;
using Autodesk.AdvanceSteel.Drawing;
using Autodesk.AdvanceSteel.Drawing.Objects;
using Autodesk.AdvanceSteel.Drawing.Document;
using Autodesk.AdvanceSteel.Drawing.View;
using Autodesk.AdvanceSteel.Drawing.Dimension;

public class PlateHoleCartesianDims
{
  // Entry command to dimension holes of a selected plate in its single-part drawing
  [CommandMethod("AS_DIM_PLATE_HOLES_CARTESIAN")]
  public void DimensionPlateHolesCartesian()
  {
    var doc = Application.DocumentManager.MdiActiveDocument;
    var ed = doc.Editor;

    // Ensure Advance Steel runtime is initialized
    if (!ASDocumentManager.IsAdvanceSteelRunning)
    {
      ed.WriteMessage("\nAdvance Steel runtime not available.");
      return;
    }

    // 1) Let user select a Plate object in the model
    var peo = new PromptEntityOptions("\nSelect a plate in the model: ");
    peo.SetRejectMessage("\nOnly Advance Steel plates are supported.");
    peo.AddAllowedClass(typeof(BlockReference), false); // Advance Steel objects are BlockReferences in DWG
    var per = ed.GetEntity(peo);
    if (per.Status != PromptStatus.OK)
      return;

    using (new TransactionControl()) // Advance Steel transaction wrapper
    {
      // 2) Resolve the Advance Steel model object from selection
      // API: FilerObject.GetFilerObjectFromAcadObjectId
      var filerObj = FilerObject.GetFilerObjectFromAcadObjectId(per.ObjectId);
      if (filerObj == null || !(filerObj is Plate plate))
      {
        ed.WriteMessage("\nSelected object is not an Advance Steel Plate.");
        return;
      }

      // 3) Locate or create the single-part drawing for this plate
      // API: DrawingProcess + DocumentManager or use helper to open existing part drawing
      // For simplicity, try to find an existing single-part drawing document that contains this object
      // API: DocumentManager.GetDocuments(), Document.GetModelObjects()
      var asDocs = DocumentManager.GetDocuments();
      DrawingDocument partDoc = null;
      DrawingObject drawingObjForPlate = null;

      foreach (var d in asDocs.OfType<DrawingDocument>())
      {
        // Query drawing for representations of our plate
        var drwObjs = d.GetModelObjects(new List<FilerObject> { plate });
        drawingObjForPlate = drwObjs?.FirstOrDefault();
        if (drawingObjForPlate != null)
        {
          partDoc = d;
          break;
        }
      }

      if (partDoc == null || drawingObjForPlate == null)
      {
        ed.WriteMessage("\nNo existing single-part drawing found for the selected plate. Create the drawing first.");
        return;
      }

      // 4) Get the primary view that shows the plate (single-part main view)
      // API: DrawingObject.GetParentView(), or enumerate views in document
      var parentView = drawingObjForPlate.GetParentView() as DrawingView;
      if (parentView == null)
      {
        ed.WriteMessage("\nCould not find a drawing view for the plate.");
        return;
      }

      // 5) Compute the Cartesian origin: lower-left of the plate outline in the view
      // Approach: get the 2D view geometry extents of the plate in the view coordinate system.
      // API: DrawingView.GetObjectExtents2d(FilerObject)
      if (!parentView.GetObjectExtents2d(plate, out var min2d, out var max2d))
      {
        ed.WriteMessage("\nFailed to obtain plate extents in the drawing view.");
        return;
      }
      var origin2d = new Point2d(min2d.X, min2d.Y); // bottom-left corner (0,0 reference)

      // 6) Gather holes from the plate
      // API: Plate.GetHoles() returns a collection of Hole objects (BoltHole/CircularHole)
      var holes = plate.GetHoles();
      if (holes == null || holes.Count == 0)
      {
        ed.WriteMessage("\nNo holes detected on the selected plate.");
        return;
      }

      // 7) For each hole, get its center point projected into the drawing view 2D space
      // API: Hole.GetCenter(), DrawingView.ProjectPointToView2d
      var holeCenters2d = new List<(Hole hole, Point2d p)>();
      foreach (var h in holes)
      {
        var center3d = h.GetCenter(); // Advance Steel Point3d (AS geometry)
        if (!parentView.ProjectPointToView2d(center3d, out var p2d))
          continue;
        holeCenters2d.Add((h, p2d));
      }

      if (holeCenters2d.Count == 0)
      {
        ed.WriteMessage("\nNo projectable hole centers found in the drawing view.");
        return;
      }

      // 8) Create Cartesian (ordinate) dimensions in the drawing for X and Y from origin2d to each hole center
      // API: OrdinateDimensionX / OrdinateDimensionY in Autodesk.AdvanceSteel.Drawing.Dimension
      // Dimensions are created inside the drawing document and associated to the view.

      // Optional: open the underlying AutoCAD database of the drawing document
      var acadDb = partDoc.Database; // Database hosting the drawing content

      using (var tr = acadDb.TransactionManager.StartTransaction())
      {
        // Choose a target BlockTableRecord: paper space of the drawing document
        var bt = (BlockTable)tr.GetObject(acadDb.BlockTableId, OpenMode.ForRead);
        var btrPs = (BlockTableRecord)tr.GetObject(bt[BlockTableRecord.PaperSpace], OpenMode.ForWrite);

        foreach (var (hole, p) in holeCenters2d)
        {
          // Compute delta from origin in view 2D
          double dx = p.X - origin2d.X;
          double dy = p.Y - origin2d.Y;

          // Choose a small offset for dimension text locations (paper space units)
          // Transform from view 2D to paper space using the view helper
          // API: DrawingView.MapViewPointToPaper(Point2d)
          var dimOriginPs = parentView.MapViewPointToPaper(origin2d);
          var dimTargetPs = parentView.MapViewPointToPaper(p);

          // Place X ordinate dimension (measurement along X, leader perpendicular to X)
          // API: OrdinateDimensionX.Create(DrawingView view, Point2d origin, Point2d target, double textOffset)
          // For placement in database, use the view-aware factory methods.
          var xDim = new OrdinateDimensionX();
          xDim.View = parentView;
          xDim.Origin = origin2d;
          xDim.Target = p;
          xDim.TextOffset = 5.0; // adjust as needed
          xDim.Label = $"X={dx:0.##}"; // optional explicit label; styles may auto-format
          xDim.Color = System.Drawing.Color.Yellow; // optional styling
          xDim.Create(); // commits into the Advance Steel drawing

          // Place Y ordinate dimension
          var yDim = new OrdinateDimensionY();
          yDim.View = parentView;
          yDim.Origin = origin2d;
          yDim.Target = p;
          yDim.TextOffset = 5.0;
          yDim.Label = $"Y={dy:0.##}";
          yDim.Color = System.Drawing.Color.Yellow;
          yDim.Create();
        }

        tr.Commit();
      }

      ed.WriteMessage($"\nCreated Cartesian ordinate dimensions for {holeCenters2d.Count} hole(s).\n");
    }
  }
}

How to use
1) Detail the plate to create its single-part drawing in Advance Steel.
2) Open the model DWG containing the plate; run AS_DIM_PLATE_HOLES_CARTESIAN.
3) Select the plate when prompted. The command searches for its existing part drawing and places ordinate dimensions in the main view, from the plate’s lower-left corner to each hole center.

Key API classes/methods used
- Autodesk.AdvanceSteel.Modelling.Plate: GetHoles(), model object representing the plate.
- Autodesk.AdvanceSteel.Modelling.Hole: GetCenter() to obtain hole center in model coordinates.
- Autodesk.AdvanceSteel.Drawing.DrawingDocument: represents the Advance Steel drawing; Database provides the underlying AutoCAD database.
- Autodesk.AdvanceSteel.Drawing.Objects.DrawingObject: GetParentView() to get the view hosting the plate.
- Autodesk.AdvanceSteel.Drawing.View.DrawingView: GetObjectExtents2d(plate, out min2d, out max2d) to compute the 2D extents; ProjectPointToView2d to project model points into the view; MapViewPointToPaper to map to paper space if needed.
- Autodesk.AdvanceSteel.Drawing.Dimension.OrdinateDimensionX / OrdinateDimensionY: drawing dimensions that implement Cartesian (X/Y) ordinate dimensions in an Advance Steel drawing view.

Additional resources
- Autodesk Advance Steel .NET API Reference (installed with the SDK): see namespaces Autodesk.AdvanceSteel.Modelling and Autodesk.AdvanceSteel.Drawing.*
- Autodesk Developer Network (ADN) DevBlog – Advance Steel: articles on drawing API and dimensions
- Advance Steel SDK samples folder: look for drawing/dimension samples demonstrating dimension creation patterns

Here is a correct and complete approach that identifies whether a tree can be split into branches of exactly three vertices and lists which edges to cut for each test case, handling k=0 by printing an empty line.

Algorithm outline:
- A necessary condition: n must be divisible by 3. If n % 3 != 0, answer is -1.
- Root the tree arbitrarily (e.g., at node 1). Do a DFS. For each subtree, compute its size modulo 3. If a child subtree has size % 3 == 0, cut the edge to that child (record the edge index). Otherwise, propagate the size upward.
- At the end, if the root's accumulated size % 3 != 0, impossible; else, the recorded cuts are valid. The number of cuts must be n/3 - 1 when possible.

Implementation (reads multiple test cases, preserves input edge order, prints according to the required format):

#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t; if(!(cin >> t)) return 0;
    while(t--){
        int n; cin >> n;
        vector<vector<pair<int,int>>> g(n+1);
        vector<pair<int,int>> edges(n); // 1-indexed edges: (u,v)
        for(int i=1;i<=n-1;i++){
            int u,v; cin >> u >> v;
            edges[i] = {u,v};
            g[u].push_back({v,i});
            g[v].push_back({u,i});
        }
        if(n%3!=0){
            cout << -1 << '\n';
            continue;
        }
        vector<int> par(n+1,-1), paredge(n+1,-1);
        vector<int> order; order.reserve(n);
        // iterative DFS to avoid recursion limits
        vector<int> st; st.push_back(1); par[1]=0;
        while(!st.empty()){
            int u = st.back(); st.pop_back();
            order.push_back(u);
            for(auto [v,ei]: g[u]) if(v!=par[u]){ par[v]=u; paredge[v]=ei; st.push_back(v);}        }
        if((int)order.size()!=n){ // should not happen in a tree, but safety
            cout << -1 << '\n';
            continue;
        }
        // Post-order process using order reversed
        vector<int> sz(n+1,1);
        vector<int> cuts;
        for(int i=n-1;i>=0;i--){
            int u = order[i];
            for(auto [v,ei]: g[u]) if(v==par[u]){
                // parent edge, handled when aggregating to parent
                ;
            }
            if(par[u]!=0){
                // u has a parent (except root)
                if(sz[u]%3==0){
                    cuts.push_back(paredge[u]);
                    // Do not add to parent, as this component is separated
                }else{
                    sz[par[u]] += sz[u];
                }
            }
        }
        // After processing, root should have size % 3 == 0
        if(sz[1]%3!=0){
            cout << -1 << '\n';
            continue;
        }
        // Number of components is cuts+1; each component has size 3; total n
        // cuts must be n/3 - 1
        if((int)cuts.size() != n/3 - 1){
            // Invariant should hold, but guard just in case
            cout << -1 << '\n';
            continue;
        }
        cout << cuts.size() << '\n';
        if(!cuts.empty()){
            for(size_t i=0;i<cuts.size();i++){
                cout << cuts[i] << (i+1==cuts.size()? '\n' : ' ');
            }
        }else{
            cout << '\n';
        }
    }
    return 0;
}

Notes:
- Edge indices printed are exactly those from the input (1 ≤ ei < n).
- Handles multiple test cases independently.
- Prints -1 when impossible; otherwise prints k on one line and the k edge indices on the next line. Prints an empty line when k=0.

