<script>
(function(){
  const $ = (sel) => document.querySelector(sel);
  const on = (el, ev, fn) => el && el.addEventListener(ev, fn);

  // Elements
  const tabLogin = $('#fp-tab-login');
  const tabRegister = $('#fp-tab-register');
  const panelLogin = $('#fp-panel-login');
  const panelRegister = $('#fp-panel-register');
  const toRegister = $('#fp-to-register');
  const toLogin = $('#fp-to-login');

  const loginBtn = $('#fp-login-btn');
  const loginEmail = $('#fp-login-email');
  const loginPassword = $('#fp-login-password');
  const loginErr = $('#fp-login-error');

  const regBtn = $('#fp-register-btn');
  const regUser = $('#fp-reg-username');
  const regEmail = $('#fp-reg-email');
  const regPass = $('#fp-reg-password');
  const regErr = $('#fp-register-error');

  const pairWrap = $('#fp-pair');
  const roomId = $('#fp-room-id');
  const joinRoomBtn = $('#fp-join-room');
  const randomBtn = $('#fp-random');
  const pairMsg = $('#fp-pair-msg');

  function setTab(which){
    if(!tabLogin || !tabRegister) return;
    const loginActive = which === 'login';
    tabLogin.classList.toggle('active', loginActive);
    tabRegister.classList.toggle('active', !loginActive);
    tabLogin.setAttribute('aria-selected', String(loginActive));
    tabRegister.setAttribute('aria-selected', String(!loginActive));
    panelLogin.hidden = !loginActive;
    panelRegister.hidden = loginActive;
  }

  function saveUser(u){
    localStorage.setItem('tg_user', JSON.stringify(u));
    sessionStorage.setItem('tg_session', JSON.stringify({ email: u.email, ts: Date.now() }));
  }
  function getUserByEmail(email){
    try {
      const all = JSON.parse(localStorage.getItem('tg_users')||'[]');
      return all.find(x=>x.email===email) || null;
    } catch(e){ return null; }
  }
  function upsertUser(u){
    const all = JSON.parse(localStorage.getItem('tg_users')||'[]');
    const i = all.findIndex(x=>x.email===u.email);
    if(i>=0) all[i]=u; else all.push(u);
    localStorage.setItem('tg_users', JSON.stringify(all));
  }

  function authenticated(u){
    saveUser(u);
    document.body.classList.add('fp-authenticated');
    // show pair-up UI after auth
    if (pairWrap) pairWrap.hidden = false;
    if (panelLogin) panelLogin.hidden = true;
    if (panelRegister) panelRegister.hidden = true;
    // Notify game layer
    document.dispatchEvent(new CustomEvent('frontpage:authenticated', { detail: { user: u } }));
  }

  // Tabs
  on(tabLogin, 'click', ()=> setTab('login'));
  on(tabRegister, 'click', ()=> setTab('register'));
  on(toRegister, 'click', ()=> setTab('register'));
  on(toLogin, 'click', ()=> setTab('login'));

  // Register
  on(regBtn, 'click', ()=>{
    regErr.textContent = '';
    const username = (regUser.value||'').trim();
    const email = (regEmail.value||'').trim().toLowerCase();
    const pass = regPass.value||'';
    if(!username || !email || pass.length < 6){
      regErr.textContent = 'Please provide username, valid email, and password (min 6 chars).';
      return;
    }
    if(getUserByEmail(email)){
      regErr.textContent = 'An account with this email already exists.';
      return;
    }
    const user = { username, email, passHash: btoa(pass) };
    upsertUser(user);
    authenticated(user);
    // Optionally start game immediately after pairing; pairing UI now visible
  });

  // Login
  on(loginBtn, 'click', ()=>{
    loginErr.textContent = '';
    const email = (loginEmail.value||'').trim().toLowerCase();
    const pass = loginPassword.value||'';
    const u = getUserByEmail(email);
    if(!u || u.passHash !== btoa(pass)){
      loginErr.textContent = 'Invalid email or password.';
      return;
    }
    authenticated(u);
  });

  // Pair-up actions (stubbed front-end only)
  function goToGame(match){
    // Hide overlay and start the game
    document.body.classList.add('fp-authenticated');
    try { if (typeof startGame === 'function') startGame(match); else if (typeof initGame === 'function') initGame(match); } catch(e){}
  }

  on(joinRoomBtn, 'click', ()=>{
    const id = (roomId.value||'').trim();
    if(!id){ pairMsg.textContent = 'Please enter a Room ID to join.'; return; }
    pairMsg.textContent = 'Joining room ' + id + '...';
    setTimeout(()=>{ goToGame({ mode:'private', roomId:id }); }, 400);
  });

  on(randomBtn, 'click', ()=>{
    pairMsg.textContent = 'Searching for an opponent...';
    setTimeout(()=>{ goToGame({ mode:'random', roomId:'RAND-' + Math.random().toString(36).slice(2,7).toUpperCase() }); }, 700);
  });

  // If already logged in, skip to pair-up
  try {
    const sess = JSON.parse(sessionStorage.getItem('tg_session')||'null');
    const cur = JSON.parse(localStorage.getItem('tg_user')||'null');
    if (sess && cur) {
      document.body.classList.add('fp-authenticated');
      if (pairWrap) pairWrap.hidden = false;
      if (panelLogin) panelLogin.hidden = true;
      if (panelRegister) panelRegister.hidden = true;
    }
  } catch(e){}
})();
</script>

