4) TennisGame.html — JavaScript (append near the end of the file, after your existing front-page JS from Turn 2 and before </body>)
<script>
(function(){
  // Utility: simple ID generator for private rooms
  function makeRoomId() {
    const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    let out = '';
    for (let i=0;i<6;i++) out += alphabet[Math.floor(Math.random()*alphabet.length)];
    return out;
  }

  // Pairing state kept in sessionStorage to persist across refresh for a session
  const Pairing = {
    set(state){ sessionStorage.setItem('pairing', JSON.stringify(state)); },
    get(){ try { return JSON.parse(sessionStorage.getItem('pairing')||'null'); } catch(e){ return null; } },
    clear(){ sessionStorage.removeItem('pairing'); }
  };

  // Elements (may not exist until DOM ready if this runs earlier)
  function $(id){ return document.getElementById(id); }

  function ensureAuthed(){
    // From Turn 2 auth flow: we rely on body.fp-authenticated
    return document.body.classList.contains('fp-authenticated');
  }

  // Integrations to your game: call init/start with context if present
  function startGameWithContext(ctx){
    // Attach pairing/room info for your game
    window.__matchContext = ctx;
    const evt = new CustomEvent('frontpage:pairing', { detail: ctx });
    window.dispatchEvent(evt);
    if (typeof window.startGame === 'function') return window.startGame(ctx);
    if (typeof window.initGame === 'function') return window.initGame(ctx);
  }

  // Hook up Pairing UI
  function setupPairing(){
    const joinBtn = $('fp-join-room');
    const createBtn = $('fp-create-room');
    const randBtn = $('fp-random-mm');
    const roomInput = $('fp-room-input');
    const err = $('fp-pair-error');
    if (!joinBtn || !createBtn || !randBtn || !roomInput) return;

    function requireAuth(){
      if (!ensureAuthed()){
        err.textContent = 'Please login or register first.';
        return false;
        }
      err.textContent = '';
      return true;
    }

    joinBtn.addEventListener('click', () => {
      if (!requireAuth()) return;
      const id = (roomInput.value||'').trim().toUpperCase();
      if (!/^[A-Z0-9]{3,10}$/.test(id)){
        err.textContent = 'Enter a valid Room ID (3–10 letters/numbers).';
        return;
      }
      const ctx = { mode: 'private-join', roomId: id };
      Pairing.set(ctx);
      startGameWithContext(ctx);
      // Hide FP overlay after pairing; keep consistent with Turn 2 behavior
      document.getElementById('fp-overlay')?.setAttribute('aria-hidden','true');
      document.body.classList.add('fp-authenticated');
    });

    createBtn.addEventListener('click', () => {
      if (!requireAuth()) return;
      const id = makeRoomId();
      roomInput.value = id;
      const ctx = { mode: 'private-create', roomId: id };
      Pairing.set(ctx);
      startGameWithContext(ctx);
      document.getElementById('fp-overlay')?.setAttribute('aria-hidden','true');
      document.body.classList.add('fp-authenticated');
      err.textContent = 'Room created. Share ID: ' + id;
    });

    randBtn.addEventListener('click', () => {
      if (!requireAuth()) return;
      const ctx = { mode: 'random', ticket: Date.now().toString(36) };
      Pairing.set(ctx);
      startGameWithContext(ctx);
      document.getElementById('fp-overlay')?.setAttribute('aria-hidden','true');
      document.body.classList.add('fp-authenticated');
    });
  }

  // GAME OVER overlay API
  // Call window.showGameOver(stats) from your game when a player loses.
  // stats = {
  //   timeUsed: '3:27',
  //   players: [
  //     { name:'You', score:12, hp:0, hits:34, oppHits:18, items:5 },
  //     { name:'Rival', score:15, hp:3, hits:37, oppHits:21, items:7 }
  //   ]
  // }
  function renderGameOver(stats){
    const go = $('go-overlay');
    const time = $('go-time-used');
    const body = $('go-stats-body');
    if (!go || !time || !body) return;

    time.textContent = stats && stats.timeUsed ? stats.timeUsed : '0:00';

    // Compute ranking by score desc, then hp desc
    const rows = (stats?.players || []).slice().sort((a,b)=>{
      if (b.score !== a.score) return b.score - a.score;
      return (b.hp||0) - (a.hp||0);
    });

    body.innerHTML = '';
    rows.forEach((p, idx) => {
      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td>${idx+1}</td>
        <td>${(p.name||'Player')}</td>
        <td>${(p.score??0)}</td>
        <td>${(p.hp??0)}</td>
        <td>${(p.hits??0)}</td>
        <td>${(p.oppHits??0)}</td>
        <td>${(p.items??0)}</td>
      `;
      body.appendChild(tr);
    });

    go.classList.add('active');
    go.setAttribute('aria-hidden','false');
  }

  function hideGameOver(){
    const go = $('go-overlay');
    if (!go) return;
    go.classList.remove('active');
    go.setAttribute('aria-hidden','true');
  }

  // Expose API to game code
  window.showGameOver = renderGameOver;
  window.hideGameOver = hideGameOver;

  // Wire buttons
  window.addEventListener('DOMContentLoaded', () => {
    setupPairing();
    const playAgain = $('go-play-again');
    const logout = $('go-logout');

    playAgain?.addEventListener('click', () => {
      hideGameOver();
      // Optionally restart with previous context
      const ctx = Pairing.get();
      if (ctx) startGameWithContext(ctx);
    });

    logout?.addEventListener('click', () => {
      // Clear auth (from Turn 2 it used localStorage/sessionStorage)
      try { localStorage.removeItem('authUser'); } catch(e){}
      try { sessionStorage.removeItem('authUser'); } catch(e){}
      Pairing.clear();
      hideGameOver();
      // Show front page overlay again
      document.body.classList.remove('fp-authenticated');
      document.getElementById('fp-overlay')?.setAttribute('aria-hidden','false');
    });
  });
})();
</script>

