#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const long long INF = (1LL<<62);

struct Edge {int to; long long w;};

vector<long long> dijkstra(int n, int src, const vector<vector<Edge>>& g) {
    vector<long long> dist(n+1, INF);
    priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<pair<long long,int>>> pq;
    dist[src] = 0;
    pq.push({0, src});
    while(!pq.empty()){
        auto [d,u] = pq.top(); pq.pop();
        if(d != dist[u]) continue;
        for(const auto &e: g[u]){
            int v = e.to; long long nd = d + e.w;
            if(nd < dist[v]){
                dist[v] = nd;
                pq.push({nd, v});
            }
        }
    }
    return dist;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    if(!(cin >> n >> m >> k)) return 0;
    vector<vector<Edge>> g(n+1);
    for(int i=0;i<m;i++){
        int u,v; long long w;
        cin >> u >> v >> w;
        g[u].push_back({v,w});
        g[v].push_back({u,w});
    }

    vector<pair<long long,long long>> days(k);
    for(int i=0;i<k;i++){
        long long a,b; // speeds for Thuan (from 1) and Dong (from n)
        cin >> a >> b;
        days[i] = {a,b};
    }

    // Precompute shortest path distances in terms of road lengths
    vector<long long> d1 = dijkstra(n, 1, g);      // from node 1
    vector<long long> dn = dijkstra(n, n, g);      // from node n

    // For each day, compute minimal waiting time
    // Waiting time for meeting at node v is max(ceil(d1[v]/a), ceil(dn[v]/b)) - min(ceil(d1[v]/a), ceil(dn[v]/b))
    // which equals abs(ceil(d1[v]/a) - ceil(dn[v]/b)). But the first arriver waits until the slower arrives,
    // so the waiting time is max(time1, time2) - min(time1, time2) = |time1 - time2|.
    // We'll compute time in integers using ceiling division: (x + s - 1) / s.

    auto ceil_div = [](long long x, long long s)->long long{
        if (x >= (long long)9e18) return (long long)9e18; // guard, though INF already huge
        if (s <= 0) return (long long)9e18; // safety
        return (x + s - 1) / s;
    };

    for(int i=0;i<k;i++){
        long long a = days[i].first;
        long long b = days[i].second;
        long long best = (long long)9e18;
        for(int v=1; v<=n; v++){
            if(d1[v]==INF || dn[v]==INF) continue; // unreachable meeting point
            long long t1 = ceil_div(d1[v], a);
            long long t2 = ceil_div(dn[v], b);
            long long wait = llabs(t1 - t2);
            if(wait < best) best = wait;
        }
        if(best == (long long)9e18) best = -1; // if no common reachable point exists; define as -1
        cout << best << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (ll)4e18;

struct Edge { int to; ll w; };

vector<ll> dijkstra(int n, const vector<vector<Edge>>& g, int src){
    vector<ll> dist(n+1, INF);
    priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
    dist[src] = 0;
    pq.push({0, src});
    while(!pq.empty()){
        auto [d,u] = pq.top(); pq.pop();
        if(d != dist[u]) continue;
        for(const auto& e: g[u]){
            int v = e.to; ll nd = d + e.w;
            if(nd < dist[v]){ dist[v] = nd; pq.push({nd, v}); }
        }
    }
    return dist;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    if(!(cin >> n >> m >> k)) return 0;

    vector<vector<Edge>> g(n+1);
    for(int i=0;i<m;i++){
        int u,v; ll w; cin >> u >> v >> w;
        g[u].push_back({v,w});
        g[v].push_back({u,w});
    }

    vector<pair<ll,ll>> days(k);
    for(int i=0;i<k;i++){
        ll a,b; cin >> a >> b; // speeds for Thuan (from 1) and Dong (from n)
        days[i] = {a,b};
    }

    // Precompute shortest path distances from 1 and from n
    vector<ll> d1 = dijkstra(n, g, 1);
    vector<ll> dn = dijkstra(n, g, n);

    // For each day, compute minimal possible waiting time at optimal meeting node
    // Waiting time definition: minimize max(time1, timeN) - min(time1, timeN)
    // where time1 = d1[v] / a, timeN = dn[v] / b. We will compute in doubles but output rounded down to integer if needed.

    // Problem statement asks for integer per line: we will take floor of minimal waiting time in real numbers.

    cout.setf(std::ios::fixed); cout<<setprecision(0);

    for(int i=0;i<k;i++){
        long double a = (long double)days[i].first;
        long double b = (long double)days[i].second;
        long double best = LDBL_MAX;
        for(int v=1; v<=n; v++){
            if(d1[v] >= INF/2 || dn[v] >= INF/2) continue; // unreachable
            long double t1 = (long double)d1[v] / a;
            long double t2 = (long double)dn[v] / b;
            long double wait = fabsl(t1 - t2);
            if(wait < best) best = wait;
        }
        if(best == LDBL_MAX) {
            // If no common meeting node reachable, define as -1 (or large). Since format not specified for impossible, print -1.
            // Adjust if the original problem specifies otherwise.
            cout << -1 << (i+1==k? '\n':'\n');
        } else {
            // Output minimal waiting time as integer per specification (one integer per line)
            // Use floor to match "minimal waiting time" if integer expected.
            long double eps = 1e-12L;
            long long ans = (long long)floor(best + eps);
            cout << ans << (i+1==k? '\n':'\n');
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (1LL<<62);

struct Edge {int to; int w;};

vector<ll> dijkstra(int n, const vector<vector<Edge>>& g, int src){
    vector<ll> dist(n+1, INF);
    priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
    dist[src] = 0;
    pq.push({0, src});
    while(!pq.empty()){
        auto [d,u] = pq.top(); pq.pop();
        if(d!=dist[u]) continue;
        for(const auto &e: g[u]){
            int v = e.to; ll nd = d + e.w;
            if(nd < dist[v]){ dist[v]=nd; pq.push({nd,v}); }
        }
    }
    return dist;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    if(!(cin >> n >> m >> k)) return 0;
    vector<vector<Edge>> g(n+1);
    g.reserve(n+1);
    for(int i=0;i<m;++i){
        int u,v; int w;
        cin >> u >> v >> w;
        g[u].push_back({v,w});
        g[v].push_back({u,w});
    }

    // Precompute shortest path distances in edge-length units (km)
    vector<ll> d1 = dijkstra(n, g, 1);
    vector<ll> dn = dijkstra(n, g, n);

    // Prepare list of candidate (max_d, min_d) pairs per node to speed per-day queries
    // For each node i, time Thuan = d1[i]*aj, Dong = dn[i]*bj; waiting = max(...) - min(...)
    // We cannot pre-aggregate across speeds, so we will scan all nodes per query.
    // Complexity: O(n + m log n + k*n). With n,k up to 1e5 this is too big.
    // Optimization: Pre-sort nodes by (d1[i]-dn[i]) is not helpful since aj,bj vary.
    // However, we can reduce to checking only nodes where both distances are finite.

    vector<int> nodes;
