                    ind_events[pid] = ind_events.get(pid, 0) + 1
        team_table = [(self.teams[pid].name, pts, team_events.get(pid, 0)) for pid, pts in team_points.items() if pid in self.teams]
        ind_table = [(self.individuals[pid].name, pts, ind_events.get(pid, 0)) for pid, pts in ind_points.items() if pid in self.individuals]
        # Sort by points desc, then name asc
        team_table.sort(key=lambda x: (-x[1], x[0].lower()))
        ind_table.sort(key=lambda x: (-x[1], x[0].lower()))
        return team_table, ind_table

    def recompute_one_event_only_assignments(self) -> None:
        """Clean up chosen_event_id for one-event-only entrants that lost their event, etc."""
        valid_event_ids = set(self.events.keys())
        for t in self.teams.values():
            if t.chosen_event_id not in valid_event_ids:
                t.chosen_event_id = None
        for i in self.individuals.values():
            if i.chosen_event_id not in valid_event_ids:
                i.chosen_event_id = None

    # ---- Points helpers ----
    @staticmethod
    def parse_points_string(s: str) -> Dict[int, int]:
        """Parses "1:25,2:18,3:15" into {1:25,2:18,3:15}."""
        s = (s or "").strip()
        if not s:
            raise ValueError("Points string cannot be empty.")
        result: Dict[int, int] = {}
        for part in s.split(','):
            if ':' not in part:
                raise ValueError("Each entry must be rank:points.")
            r_str, p_str = part.split(':', 1)
            r = int(r_str.strip())
            p = int(p_str.strip())
            result[r] = p
        # Validate
        temp = TournamentData()
        temp._validate_points_map(result)
        return result

    @staticmethod
    def points_from_list(lst: List[int]) -> Dict[int, int]:
        return {i + 1: v for i, v in enumerate(lst)}

    # ---- Persistence ----
    def to_json(self) -> str:
        payload = {
            "teams": [asdict(t) for t in self.teams.values()],
            "individuals": [asdict(i) for i in self.individuals.values()],
            "events": [asdict(e) for e in self.events.values()],
            "results": {str(k): v for k, v in self.results.items()},
            "points_map": self.points_map,
            "counters": {
                "team": self.team_counter,
                "indiv": self.indiv_counter,
                "event": self.event_counter,
            },
        }
        return json.dumps(payload, indent=2)

    @staticmethod
    def from_json(s: str) -> "TournamentData":
        data = json.loads(s)
        t = TournamentData()
        # Load points first (validated lazily during use)
        t.points_map = {int(k): int(v) for k, v in data.get("points_map", {}).items()} or t.points_map
        # Load entities
        for td in data.get("teams", []):
            team = Team(**td)
            t.teams[team.id] = team
        for idd in data.get("individuals", []):
            ind = Individual(**idd)
            t.individuals[ind.id] = ind
        for ed in data.get("events", []):
            # keys might be strings; ensure ints inside points_map
            pmap = ed.get("points_map")
            if pmap is not None:
                pmap = {int(k): int(v) for k, v in pmap.items()}
                t._validate_points_map(pmap)
                ed["points_map"] = pmap
            ev = Event(**ed)
            t.events[ev.id] = ev
        # Results
        res = {}
        for k, v in data.get("results", {}).items():
            res[int(k)] = [int(x) for x in v]
        t.results = res
        # Counters
        cnt = data.get("counters", {})
        t.team_counter = int(cnt.get("team", 1))
        t.indiv_counter = int(cnt.get("indiv", 1))
        t.event_counter = int(cnt.get("event", 1))
        # Validate integrity: remove results for missing events
        for eid in list(t.results.keys()):
            if eid not in t.events:
                t.results.pop(eid, None)
        t.recompute_one_event_only_assignments()
        return t


