class TournamentApp(tk.Tk):
    """Main GUI application using a tabbed layout."""

    def __init__(self):
        super().__init__()
        self.title("E-sports Tournament Scoring")
        self.geometry("1100x720")
        self.minsize(1000, 650)

        self.data = TournamentData()
        self.current_file: Optional[str] = None

        self.create_menu()
        self.create_notebook()
        self.create_participants_tab()
        self.create_events_tab()
        self.create_results_tab()
        self.create_leaderboards_tab()
        self.create_points_tab()

    # ---- Menu ----
    def create_menu(self):
        menubar = tk.Menu(self)
        file_menu = tk.Menu(menubar, tearoff=0)
        file_menu.add_command(label="New", command=self.on_new)
        file_menu.add_command(label="Open...", command=self.on_open)
        file_menu.add_command(label="Save", command=self.on_save)
        file_menu.add_command(label="Save As...", command=self.on_save_as)
        file_menu.add_separator()
        file_menu.add_command(label="Exit", command=self.destroy)
        menubar.add_cascade(label="File", menu=file_menu)
        self.config(menu=menubar)

    def on_new(self):
        if not self.confirm_discard_changes():
            return
        self.data = TournamentData()
        self.current_file = None
        self.refresh_all()

    def on_open(self):
        if not self.confirm_discard_changes():
            return
        path = filedialog.askopenfilename(filetypes=[("JSON Files", "*.json"), ("All Files", "*.*")])
        if not path:
            return
        try:
            with open(path, "r", encoding="utf-8") as f:
                s = f.read()
            self.data = TournamentData.from_json(s)
            self.current_file = path
            self.refresh_all()
        except Exception as e:
            messagebox.showerror("Open Failed", str(e))

    def on_save(self):
        if not self.current_file:
            return self.on_save_as()
        try:
            with open(self.current_file, "w", encoding="utf-8") as f:
                f.write(self.data.to_json())
            messagebox.showinfo("Saved", f"Saved to {self.current_file}")
        except Exception as e:
            messagebox.showerror("Save Failed", str(e))

    def on_save_as(self):
        path = filedialog.asksaveasfilename(defaultextension=".json",
                                            filetypes=[("JSON Files", "*.json"), ("All Files", "*.*")])
        if not path:
            return
        self.current_file = path
        self.on_save()

    def confirm_discard_changes(self) -> bool:
        return messagebox.askyesno("Confirm", "Discard current tournament and continue?")

