        ttk.Radiobutton(presets, text="Winner-Takes-All", value="WTA", variable=self.points_preset_var, command=self.on_points_preset).grid(row=0, column=2, sticky="w", padx=6, pady=4)
        ttk.Radiobutton(presets, text="Linear (N, start->desc)", value="LIN", variable=self.points_preset_var, command=self.on_points_preset).grid(row=0, column=3, sticky="w", padx=6, pady=4)

