        ttk.Entry(lin_frame, textvariable=self.lin_n_var, width=6).grid(row=0, column=1)
        ttk.Label(lin_frame, text="Start points:").grid(row=0, column=2, padx=(10,0))
        self.lin_start_var = tk.IntVar(value=10)
        ttk.Entry(lin_frame, textvariable=self.lin_start_var, width=6).grid(row=0, column=3)
        ttk.Button(lin_frame, text="Apply Linear", command=self.apply_linear_points).grid(row=0, column=4, padx=8)

        # Custom editor
        custom = ttk.LabelFrame(frm, text="Global Points (rank:pts,...) or CSV list for top-N")
        custom.grid(row=1, column=0, columnspan=2, sticky="ew", padx=8, pady=8)
        self.global_points_var = tk.StringVar(value=",".join(str(v) for v in [25,18,15,12,10,8,6,4,2,1]))
        ttk.Entry(custom, textvariable=self.global_points_var).grid(row=0, column=0, sticky="ew", padx=6, pady=6)
        custom.columnconfigure(0, weight=1)
        ttk.Button(custom, text="Apply", command=self.apply_global_points).grid(row=0, column=1, padx=6)

    def on_points_preset(self):
        preset = self.points_preset_var.get()
        if preset == "F1":
            pts = [25,18,15,12,10,8,6,4,2,1]
        elif preset == "Top8":
            pts = [10,8,6,5,4,3,2,1]
        elif preset == "WTA":
            pts = [10,0,0,0,0]
        else:
            # Linear preset uses fields; do not change string here
            return
        self.global_points_var.set(",".join(str(x) for x in pts))

    def apply_linear_points(self):
        try:
            n = int(self.lin_n_var.get())
            start = int(self.lin_start_var.get())
            if n <= 0 or start < 0:
                raise ValueError
            pts = [max(start - i, 0) for i in range(n)]
            self.global_points_var.set(",".join(str(x) for x in pts))
        except Exception:
            messagebox.showerror("Linear Points", "Provide valid integers for N and start points.")

    def apply_global_points(self):
        s = self.global_points_var.get().strip()
        try:
            if ":" in s:
                pmap = TournamentData.parse_points_string(s)
            else:
                # CSV list => top-N mapping
                lst = [int(x.strip()) for x in s.split(',') if x.strip()]
                if not lst:
                    raise ValueError("Provide at least one number.")
                pmap = TournamentData.points_from_list(lst)
            self.data._validate_points_map(pmap)
            self.data.points_map = pmap
            messagebox.showinfo("Points", "Global points updated.")
        except Exception as e:
            messagebox.showerror("Points", str(e))

    # ---- Utilities ----
    def refresh_all(self):
        self.refresh_participants_lists()
        self.refresh_events_list()
        self.refresh_results_available_list()
        self.refresh_leaderboards()


# -------------------------
# Run app
# -------------------------

def main():
    app = TournamentApp()
    app.mainloop()


if __name__ == "__main__":
    main()
