#!/usr/bin/env pwsh

# Configuration
$Folders = @(
  'Ewl.Platform.Analytics'
)
$FeatureBranch = 'TK/14278_TM-13'
$MainRemoteBranch = 'origin/main'
$TargetLine = 'o.Select().Filter().OrderBy().Count().Expand().SetMaxTop(100);'
$InsertLine = 'o.TimeZone = TimeZoneInfo.Utc;'
$ApiPackageId = 'Ewl.Platform.Common.Api'
$StoragePackageId = 'Ewl.Platform.Common.Storage'
$TargetPackageVersion = '1.0.0'

# Utilities
function Run($cmd, $workingDir) {
  Write-Host "[RUN] $cmd (cwd=$workingDir)" -ForegroundColor Cyan
  & pwsh -NoProfile -Command $cmd 2>&1 | ForEach-Object { $_ }
  if ($LASTEXITCODE -ne 0) { throw "Command failed: $cmd" }
}

function SafeRun($cmd, $workingDir) {
  try { Run $cmd $workingDir; return $true } catch { Write-Warning $_; return $false }
}

function Update-LineWithInsert($filePath, $targetLine, $insertLine) {
  if (-not (Test-Path $filePath)) { return $false }
  $content = Get-Content -Path $filePath -Raw -ErrorAction Stop
  $newline = if ($content -match "`r`n") { "`r`n" } else { "`n" }
  $lines = $content -split "`r?`n", -1
  $modified = $false
  for ($i = 0; $i -lt $lines.Count; $i++) {
    if ($lines[$i].Trim() -eq $targetLine.Trim()) {
      $nextIsInsert = $false
      if ($i + 1 -lt $lines.Count) {
        $n = $lines[$i + 1].TrimEnd(';').Trim()
        if ($n -eq $insertLine.TrimEnd(';').Trim()) { $nextIsInsert = $true }
      }
      if (-not $nextIsInsert) {
        $indent = ($lines[$i] -replace '(\S).*$', '')
        $before = $lines[0..$i]
        $after = if ($i + 1 -lt $lines.Count) { $lines[($i + 1)..($lines.Count - 1)] } else { @() }
        $lines = @($before + "$insertLine") + $after
        $modified = $true
        $i++
      }
    }
  }
  if ($modified) {
    $out = ($lines -join $newline)
    Set-Content -Path $filePath -Value $out -Encoding UTF8
    Write-Host "[INFO] Updated $filePath" -ForegroundColor Green
  } else {
    Write-Host "[INFO] No changes needed in $filePath" -ForegroundColor Yellow
  }
  return $modified
}

function Find-MvcBuilderExtensions($root) {
  Get-ChildItem -Path $root -Filter 'MvcBuilderExtensions.cs' -Recurse -File -ErrorAction SilentlyContinue |
    Where-Object { $_.FullName -notmatch "\\(bin|obj)(\\|$)" } |
    Select-Object -ExpandProperty FullName
}

function NuGet-UpdatePackage($csproj, $packageId, $version) {
  if (Get-Command nuget -ErrorAction SilentlyContinue) {
    $cmd = "nuget update `"$csproj`" -Id $packageId -Version $version"
    SafeRun $cmd (Split-Path -Parent $csproj) | Out-Null
  } else {
    Write-Warning "nuget.exe not found on PATH; skipping update for $packageId in $csproj"
  }
}

$startDir = Get-Location
try {
  foreach ($folder in $Folders) {
    Write-Host "=== Processing $folder ===" -ForegroundColor Magenta

    # Navigate to folder containing the solution (repo root assumed to be relative path of folder name)
    $repoDir = Resolve-Path -LiteralPath $folder -ErrorAction Stop
    Set-Location $repoDir

    # Ensure git repo
    if (-not (Test-Path (Join-Path $repoDir '.git'))) { throw "Not a git repository: $repoDir" }

    # Git: checkout origin/main, fetch, reset hard
    Run "git fetch origin --prune" $repoDir
    Run "git checkout -B main $MainRemoteBranch" $repoDir
    Run "git reset --hard $MainRemoteBranch" $repoDir

    # Feature branch handling
    if (SafeRun "git rev-parse --verify $FeatureBranch" $repoDir) {
      Run "git checkout $FeatureBranch" $repoDir
      Run "git reset --hard $MainRemoteBranch" $repoDir
    } else {
      Run "git checkout -b $FeatureBranch $MainRemoteBranch" $repoDir
    }

    # Find and replace in MvcBuilderExtensions.cs
    $files = Find-MvcBuilderExtensions $repoDir
    foreach ($f in $files) {
      Update-LineWithInsert -filePath $f -targetLine $TargetLine -insertLine $InsertLine | Out-Null
    }

    # NuGet updates
    $srcDir = Join-Path $repoDir 'src'
    $mainProjectDir = Join-Path $srcDir $folder
    if (Test-Path $mainProjectDir) {
      $mainCsproj = Get-ChildItem -Path $mainProjectDir -Filter '*.csproj' -File | Select-Object -First 1
      if ($mainCsproj) { NuGet-UpdatePackage -csproj $mainCsproj.FullName -packageId $ApiPackageId -version $TargetPackageVersion }
    }

    $storageCsprojs = Get-ChildItem -Path $srcDir -Recurse -Filter '*.csproj' -File -ErrorAction SilentlyContinue |
      Where-Object { $_.Name.ToLower().EndsWith('.storage.csproj') }
    foreach ($scp in $storageCsprojs) {
      NuGet-UpdatePackage -csproj $scp.FullName -packageId $StoragePackageId -version $TargetPackageVersion
    }

    # Run tests
    Run "dotnet test" $repoDir

    # Return to start of next iteration (optional since we set absolute locations)
    Set-Location $startDir | Out-Null
  }
}
finally {
  # Ensure return to starting directory
  Set-Location $startDir | Out-Null
}

