#!/usr/bin/env python3
"""
Convert all PDFs in a folder into a single CSV that:
- Has the exact headers (in this order):
  ['Posted Date', 'Value Date', 'Description', 'Debit', 'Credit', 'Balance']
- Is sorted by date from oldest to newest (by 'Posted Date').

Robustness and performance:
- Gracefully handles: missing/non-directory input, no PDFs in the folder,
  missing/unreadable PDFs, pages with no tables.
- Normalizes column names and values, coerces dates and numerics.
- Uses an in-memory threshold; if exceeded, spills sorted chunks to disk and
  performs an external k-way merge to keep memory usage bounded.
- Optional parallel extraction workers (use with care; Java/tabula can be heavyweight).

Requirements:
- Java installed and on PATH (for tabula-py).
- Python packages: tabula-py, pandas.

Usage:
  python script.py input_folder -o output.csv
Optional flags:
  --lattice              Use lattice mode in tabula (for ruled tables)
  --stream               Use stream mode in tabula (for no ruled lines)
  --workers N            Parallel PDF extraction (default: 1)
  --chunk-size N         Rows per sorted chunk after spilling (default: 200000)
  --in-memory-rows N     If total rows <= this, sort in memory (default: 300000)
  --verbose              Print progress details
"""

import os
import sys
import csv
import argparse
import tempfile
import shutil
import heapq
from decimal import Decimal, InvalidOperation
from typing import List, Optional, Dict, Tuple, Iterable, Iterator
from concurrent.futures import ProcessPoolExecutor, as_completed

import pandas as pd
import tabula

TARGET_HEADERS = ["Posted Date", "Value Date", "Description", "Debit", "Credit", "Balance"]

# Normalize likely header variants to the required target columns
_CANON_MAP = {
    # Dates
    "posted date": "Posted Date",
    "posting date": "Posted Date",
    "post date": "Posted Date",
    "date posted": "Posted Date",
    "date": "Posted Date",
    "value date": "Value Date",
    "transaction date": "Value Date",

    # Description
    "description": "Description",
    "narration": "Description",
    "details": "Description",
    "remark": "Description",
    "particulars": "Description",

    # Debit
    "debit": "Debit",
    "withdrawal": "Debit",
    "dr": "Debit",
    "debits": "Debit",

    # Credit
    "credit": "Credit",
    "deposit": "Credit",
    "cr": "Credit",
    "credits": "Credit",

    # Balance
    "balance": "Balance",
    "running balance": "Balance",
    "closing balance": "Balance",
    "available balance": "Balance",
}


def eprint(*args, **kwargs):
    print(*args, file=sys.stderr, **kwargs)


def parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser(
        description="Convert all PDFs in a folder into a single CSV with fixed headers, sorted oldest->newest."
    )
    p.add_argument("input_folder", help="Folder containing PDF files")
    p.add_argument("-o", "--output", default="combined_statements.csv", help="Output CSV file path")
    p.add_argument("--lattice", action="store_true", help="Use lattice mode in tabula (good for ruled tables)")
    p.add_argument("--stream", action="store_true", help="Use stream mode in tabula (good for no ruled lines)")
    p.add_argument("--workers", type=int, default=1, help="Number of parallel workers for PDF extraction (default: 1)")
    p.add_argument("--chunk-size", type=int, default=200_000, help="Rows per sorted chunk after spilling")
    p.add_argument("--in-memory-rows", type=int, default=300_000, help="If total rows <= this, sort in memory")
    p.add_argument("--verbose", action="store_true", help="Print progress details")
    args = p.parse_args()

    if args.lattice and args.stream:
        eprint("Both --lattice and --stream provided; proceeding with --lattice and ignoring --stream.")
        args.stream = False

    if args.workers < 1:
        args.workers = 1

    if args.in_memory_rows < 10_000:
        # Prevent pathological tiny threshold
        args.in_memory_rows = 10_000

    if args.chunk_size < 50_000:
        # Avoid excessive tiny chunks
        args.chunk_size = 50_000

    return args


def _clean_colname(name: str) -> str:
    return str(name or "").strip().lower()


def _canon(name: str) -> str:
    key = _clean_colname(name)
    return _CANON_MAP.get(key, name if name is not None else "")


def _to_decimal_str(val) -> Optional[str]:
    """
    Convert a cell to a canonical decimal string:
    - Remove common currency symbols/spaces/commas
    - Handle parentheses as negatives
    - Return None for empty/unparseable
    """
    if val is None:
        return None
    s = str(val).strip()
    if not s or s.lower() in {"nan", "none", "-"}:
        return None
    # Remove currency symbols and spaces
    s = s.replace("\u00A0", "").replace(" ", "").replace(",", "")
    for sym in ("₦", "₵", "$", "€", "£", "¥", "₹"):
        s = s.replace(sym, "")
    # Parentheses indicate negative
    neg = s.startswith("(") and s.endswith(")")
    if neg:
        s = s[1:-1].strip()
    # Remove leading + sign
    if s.startswith("+"):
        s = s[1:]
    try:
        d = Decimal(s)
        if neg:
            d = -d
        return format(d, "f")
    except InvalidOperation:
        return None


def _parse_date_to_iso(val) -> Optional[str]:
    """
    Try to parse any reasonable date into ISO YYYY-MM-DD.
    Attempts multiple day-first/month-first formats and pandas to_datetime fallback.
    Returns None if unparseable.
    """
    if val is None:
        return None
    s = str(val).strip()
    if not s or s.lower() in {"nan", "none", "-"}:
        return None
    # Common quick patterns to try first to avoid heavy parser cost in hot loop
    fmts = [
        "%d-%m-%Y", "%d/%m/%Y", "%d.%m.%Y",
        "%Y-%m-%d", "%Y/%m/%d", "%Y.%m.%d",
        "%m-%d-%Y", "%m/%d/%Y", "%m.%d.%Y",
        "%d-%b-%Y", "%d %b %Y", "%d %B %Y",
        "%b %d, %Y", "%B %d, %Y",
    ]
    from datetime import datetime
    for f in fmts:
        try:
            dt = datetime.strptime(s, f)
            return dt.strftime("%Y-%m-%d")
        except ValueError:
            pass
    # Fall back to pandas flexible parser with dayfirst heuristics
    for dayfirst in (True, False):
        try:
            dt = pd.to_datetime(s, dayfirst=dayfirst, errors="raise")
            return dt.strftime("%Y-%m-%d")
        except Exception:
            continue
    return None


def _normalize_dataframe(df: pd.DataFrame) -> pd.DataFrame:
    # Map columns to canonical names
    rename_map: Dict[str, str] = {}
    for c in df.columns:
        canon = _canon(c)
        if canon:
            rename_map[c] = canon
    df = df.rename(columns=rename_map)

    # Keep only target columns that are present; create missing ones as empty
    for col in TARGET_HEADERS:
        if col not in df.columns:
            df[col] = None

    df = df[TARGET_HEADERS]

    # Coerce dates and numerics
    df["Posted Date"] = df["Posted Date"].map(_parse_date_to_iso)
    df["Value Date"] = df["Value Date"].map(_parse_date_to_iso)
    for col in ("Debit", "Credit", "Balance"):
        df[col] = df[col].map(_to_decimal_str)

    # Drop rows that have neither description nor any amount
    mask_any_amount = df[["Debit", "Credit", "Balance"]].notna().any(axis=1)
    mask_has_desc = df["Description"].astype(str).str.strip().ne("")
    df = df[mask_any_amount | mask_has_desc]

    return df


def _extract_one_pdf(pdf_path: str, lattice: bool, stream: bool, verbose: bool) -> pd.DataFrame:
    try:
        if verbose:
            eprint(f"Extracting: {os.path.basename(pdf_path)}")
        # Read all tables from the PDF; combine to one DataFrame
        dfs = tabula.read_pdf(
            pdf_path,
            pages="all",
            multiple_tables=True,
            lattice=lattice,
            stream=stream,
            guess=False
        )
        if not dfs:
            return pd.DataFrame(columns=TARGET_HEADERS)
        out_frames: List[pd.DataFrame] = []
        for tdf in dfs:
            if tdf is None or tdf.empty:
                continue
            norm = _normalize_dataframe(tdf)
            if not norm.empty:
                out_frames.append(norm)
        if not out_frames:
            return pd.DataFrame(columns=TARGET_HEADERS)
        return pd.concat(out_frames, ignore_index=True)
    except Exception as exc:
        eprint(f"Warning: failed to read '{pdf_path}': {exc}")
        return pd.DataFrame(columns=TARGET_HEADERS)


def _list_pdfs(folder: str) -> List[str]:
    try:
        entries = [
            os.path.join(folder, f)
            for f in os.listdir(folder)
            if f.lower().endswith(".pdf") and os.path.isfile(os.path.join(folder, f))
        ]
        return sorted(entries)
    except FileNotFoundError:
        return []


def _write_chunk(csv_path: str, df: pd.DataFrame, mode: str) -> None:
    header = (mode == "w")
    df.to_csv(csv_path, mode=mode, header=header, index=False)


def _spill_sorted_chunk(tmp_dir: str, df: pd.DataFrame, chunk_idx: int) -> str:
    # Sort by Posted Date; keep rows with valid dates; rows with None dates are excluded from sorting output
    df_valid = df[df["Posted Date"].notna()].copy()
    if df_valid.empty:
        # Still spill an empty file to keep the pipeline simple
        path = os.path.join(tmp_dir, f"chunk_{chunk_idx:06d}.csv")
        pd.DataFrame(columns=TARGET_HEADERS).to_csv(path, index=False)
        return path
    df_valid.sort_values(by=["Posted Date"], kind="mergesort", inplace=True)
    path = os.path.join(tmp_dir, f"chunk_{chunk_idx:06d}.csv")
    df_valid.to_csv(path, index=False)
    return path


def _iter_csv_rows(path: str) -> Iterator[List[str]]:
    with open(path, "r", newline="", encoding="utf-8") as f:
        r = csv.reader(f)
        header = next(r, None)  # skip header
        for row in r:
            yield row


def _kway_merge(sorted_paths: List[str], out_path: str, verbose: bool) -> None:
    # Open all readers
    files = [open(p, "r", newline="", encoding="utf-8") for p in sorted_paths]
    try:
        readers = [csv.reader(f) for f in files]
        # Read and discard headers
        for r in readers:
            next(r, None)
        # Heap of (posted_date, serial, row_values, reader_idx)
        heap: List[Tuple[str, int, List[str], int]] = []
        serial = 0
        for i, r in enumerate(readers):
            try:
                row = next(r)
                if row and row[0]:
                    heap.append((row[0], serial, row, i))
                    serial += 1
            except StopIteration:
                pass
        heapq.heapify(heap)

        with open(out_path, "w", newline="", encoding="utf-8") as out_f:
            w = csv.writer(out_f)
            w.writerow(TARGET_HEADERS)
            cnt = 0
            while heap:
                posted, _, row, idx = heapq.heappop(heap)
                w.writerow(row)
                cnt += 1
                try:
                    nxt = next(readers[idx])
                    if nxt and nxt[0]:
                        heapq.heappush(heap, (nxt[0], serial, nxt, idx))
                        serial += 1
                except StopIteration:
                    pass
        if verbose:
            eprint(f"Merged {cnt} rows from {len(sorted_paths)} chunks into {out_path}")
    finally:
        for f in files:
            try:
                f.close()
            except Exception:
                pass


def _extract_worker(args_tuple) -> Tuple[str, pd.DataFrame]:
    pdf_path, lattice, stream, verbose = args_tuple
    df = _extract_one_pdf(pdf_path, lattice=lattice, stream=stream, verbose=verbose)
    return (pdf_path, df)


def convert_folder_to_csv(
    input_folder: str,
    output_csv: str,
    lattice: bool = False,
    stream: bool = False,
    workers: int = 1,
    chunk_size: int = 200_000,
    in_memory_rows: int = 300_000,
    verbose: bool = False,
) -> None:
    # Validate input folder
    if not os.path.exists(input_folder):
        raise FileNotFoundError(f"Input folder does not exist: {input_folder}")
    if not os.path.isdir(input_folder):
        raise NotADirectoryError(f"Input path is not a directory: {input_folder}")

    pdfs = _list_pdfs(input_folder)
    if not pdfs:
        # Create an empty CSV with headers to satisfy contract
        pd.DataFrame(columns=TARGET_HEADERS).to_csv(output_csv, index=False)
        eprint("No PDF files found; wrote empty CSV with headers.")
        return

    tmp_dir = tempfile.mkdtemp(prefix="pdfmerge_chunks_")
    spilled_paths: List[str] = []
    total_rows = 0
    chunk_idx = 0

    try:
        if workers > 1:
            if verbose:
                eprint(f"Using {workers} workers")
            with ProcessPoolExecutor(max_workers=workers) as ex:
                futs = [ex.submit(_extract_worker, (p, lattice, stream, verbose)) for p in pdfs]
                inmem_frames: List[pd.DataFrame] = []
                for fut in as_completed(futs):
                    pdf_path, df = fut.result()
                    rows = len(df)
                    total_rows += rows
                    if verbose:
                        eprint(f"{os.path.basename(pdf_path)} -> {rows} rows (total {total_rows})")
                    if total_rows <= in_memory_rows:
                        if not df.empty:
                            inmem_frames.append(df)
                    else:
                        # Spill in chunks when exceeding threshold
                        if inmem_frames:
                            big = pd.concat(inmem_frames, ignore_index=True)
                            inmem_frames.clear()
                        else:
                            big = df
                        # Split big into chunked spills
                        for start in range(0, len(big), chunk_size):
                            part = big.iloc[start:start + chunk_size].copy()
                            spilled_paths.append(_spill_sorted_chunk(tmp_dir, part, chunk_idx))
                            chunk_idx += 1
                # After futures complete
                if total_rows <= in_memory_rows:
                    if inmem_frames:
                        all_df = pd.concat(inmem_frames, ignore_index=True)
                        if not all_df.empty:
                            # Final in-memory sort and write
                            all_df = all_df[all_df["Posted Date"].notna()].copy()
                            all_df.sort_values(by=["Posted Date"], kind="mergesort", inplace=True)
                            all_df.to_csv(output_csv, index=False)
                        else:
                            pd.DataFrame(columns=TARGET_HEADERS).to_csv(output_csv, index=False)
                    else:
                        pd.DataFrame(columns=TARGET_HEADERS).to_csv(output_csv, index=False)
                else:
                    # Perform k-way merge of spilled chunks
                    if spilled_paths:
                        _kway_merge(spilled_paths, output_csv, verbose=verbose)
                    else:
                        # Fallback: no spills? then write empty
                        pd.DataFrame(columns=TARGET_HEADERS).to_csv(output_csv, index=False)
        else:
            # Single-process path: iterate PDFs sequentially, spilling as needed
            inmem_frames: List[pd.DataFrame] = []
            for p in pdfs:
                df = _extract_one_pdf(p, lattice=lattice, stream=stream, verbose=verbose)
                rows = len(df)
                total_rows += rows
                if verbose:
                    eprint(f"{os.path.basename(p)} -> {rows} rows (total {total_rows})")
                if total_rows <= in_memory_rows:
                    if not df.empty:
                        inmem_frames.append(df)
                else:
                    if inmem_frames:
                        big = pd.concat(inmem_frames + ([df] if not df.empty else []), ignore_index=True)
                        inmem_frames.clear()
                    else:
                        big = df
                    for start in range(0, len(big), chunk_size):
                        part = big.iloc[start:start + chunk_size].copy()
                        spilled_paths.append(_spill_sorted_chunk(tmp_dir, part, chunk_idx))
                        chunk_idx += 1

            if total_rows <= in_memory_rows:
                if inmem_frames:
                    all_df = pd.concat(inmem_frames, ignore_index=True)
                    if not all_df.empty:
                        all_df = all_df[all_df["Posted Date"].notna()].copy()
                        all_df.sort_values(by=["Posted Date"], kind="mergesort", inplace=True)
                        all_df.to_csv(output_csv, index=False)
                    else:
                        pd.DataFrame(columns=TARGET_HEADERS).to_csv(output_csv, index=False)
                else:
                    pd.DataFrame(columns=TARGET_HEADERS).to_csv(output_csv, index=False)
            else:
                if spilled_paths:
                    _kway_merge(spilled_paths, output_csv, verbose=verbose)
                else:
                    pd.DataFrame(columns=TARGET_HEADERS).to_csv(output_csv, index=False)

        if verbose:
            eprint(f"Wrote: {output_csv}")

    finally:
        # Cleanup temp chunk files
        try:
            shutil.rmtree(tmp_dir, ignore_errors=True)
        except Exception:
            pass


def main():
    args = parse_args()
    try:
        convert_folder_to_csv(
            input_folder=args.input_folder,
            output_csv=args.output,
            lattice=args.lattice or (not args.stream),  # default to lattice if neither set
            stream=args.stream,
            workers=args.workers,
            chunk_size=args.chunk_size,
            in_memory_rows=args.in_memory_rows,
            verbose=args.verbose,
        )
    except Exception as exc:
        eprint(f"Error: {exc}")
        sys.exit(1)


if __name__ == "__main__":
