(function() {
  'use strict';

  // Zero step: ensure this script runs only in the first tab (singleton lock)
  const LOCK_KEY = 'drtorkzadeh_first_tab_lock';
  const HEARTBEAT_KEY = 'drtorkzadeh_first_tab_heartbeat';
  const LOCK_TTL_MS = 8000; // consider lock stale if no heartbeat in 8s

  function now() { return Date.now(); }

  function hasLock() {
    const lockTime = GM_getValue(LOCK_KEY, 0);
    const hb = GM_getValue(HEARTBEAT_KEY, 0);
    const fresh = (now() - Math.max(lockTime, hb)) < LOCK_TTL_MS;
    return fresh;
  }

  function tryAcquireLock() {
    if (!hasLock()) {
      GM_setValue(LOCK_KEY, now());
    }
    return hasLock();
  }

  // Heartbeat to maintain ownership of the "first tab" lock
  function startHeartbeat() {
    setInterval(() => {
      GM_setValue(HEARTBEAT_KEY, now());
    }, 2000);
  }

  if (!tryAcquireLock()) {
    // Not the first tab: exit silently
    return;
  }
  startHeartbeat();

  // First step: ensure script runs only on the main page (already enforced by @match exact root URL)
  // Additional guard in case of redirects or query strings
  if (location.origin + '/' !== 'http://www.drtorkzadeh.com/') {
    return;
  }

  // Second step: time window check between 22:30 and 03:30 (overnight window spanning midnight)
  function isWithinWindow(date = new Date()) {
    const h = date.getHours();
    const m = date.getMinutes();
    const minutes = h * 60 + m;
    const start = 22 * 60 + 30; // 22:30 -> 1350
    const end = 3 * 60 + 30;    // 03:30 -> 210
    // Window spans midnight: valid if minutes >= start OR minutes < end
    return (minutes >= start) || (minutes < end);
  }

  function msUntilWindow() {
    const d = new Date();
    if (isWithinWindow(d)) return 0;
    const minutes = d.getHours() * 60 + d.getMinutes();
    const start = 22 * 60 + 30;
    let target = new Date(d);
    if (minutes < start) {
      target.setHours(22, 30, 0, 0);
    } else {
      // after 22:30 but outside window means next day's 22:30
      target.setDate(target.getDate() + 1);
      target.setHours(22, 30, 0, 0);
    }
    return target - d;
  }

  function waitForWindowThenRun(fn) {
    const delay = msUntilWindow();
    if (delay <= 0) return fn();
    setTimeout(fn, delay);
  }

  // Third & Fourth steps: loop to check for exact text, reload if found; else go to next tab
  const TARGET_TEXT = 'رزرو فقط در ساعات 9 صبح تا 10 صبح امکان پذیر است';

  function pageContainsExactText(txt) {
    // Search whole page text content
    const bodyText = document.documentElement ? document.documentElement.innerText || '' : document.body.innerText || '';
    return bodyText.includes(txt);
  }

  function reloadAfterDelay(ms) {
    setTimeout(() => location.reload(), ms);
  }

  // Fifth step: In second tab, click the specified element. We cannot control other tabs' DOM directly.
  // Approach: If we need to move to next tab, send a notification and attempt a CTRL+TAB key event (note: browsers block synthetic tab switching).
  // We provide a best-effort: notify the user to switch, then the second tab (with its own copy of this script) will be gated by the lock and thus NOT run.
  // Therefore, we expose a one-time command hint for the user to switch manually. Once on second tab, user interaction is required to click.

  function goToNextTabBestEffort() {
    try {
      GM_notification({
        title: 'Switch to Next Tab',
        text: 'Please press Ctrl+Tab to go to the next loaded tab. The first tab automation will stop after this action.',
        timeout: 5000
      });
    } catch (e) { /* ignore */ }

    // Attempt a synthetic key combo (most browsers block tab switching; included as best effort only)
    try {
      const evt = new KeyboardEvent('keydown', { key: 'Tab', code: 'Tab', ctrlKey: true, bubbles: true });
      document.dispatchEvent(evt);
    } catch (e) { /* ignore */ }
  }

  // If this is the SECOND TAB, user wants to click a specific element and stop.
  // Because our singleton lock prevents running in other tabs, the second tab will not execute this by default.
  // To allow the second tab to perform the click when brought forward, we add a small handler that triggers on user click if lock is absent.
  function trySecondTabClickIfNotFirst() {
    if (hasLock()) return; // still first tab
    const btn = document.querySelector('form[action="http://www.drtorkzadeh.com/"] input#submit[type="submit"]');
    if (btn) {
      btn.click();
    }
  }
  // In case this script is installed in all tabs, but only the tab without lock should click when focused or interacted with
  window.addEventListener('focus', trySecondTabClickIfNotFirst, { once: true });
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') trySecondTabClickIfNotFirst();
  });

  function mainLoop() {
    // Time gate each iteration
    if (!isWithinWindow()) {
      // Wait until back in window, then re-run mainLoop
      return waitForWindowThenRun(mainLoop);
    }

    if (pageContainsExactText(TARGET_TEXT)) {
      // Found exact text: wait 5 seconds then reload and repeat endlessly
      reloadAfterDelay(5000);
    } else {
      // Not found: go to next tab that is already loaded
      goToNextTabBestEffort();
      // After attempting tab switch, stop this tab's automation
      // Optionally, release the lock so the second tab can proceed with click handler when focused
      GM_setValue(LOCK_KEY, 0);
      GM_setValue(HEARTBEAT_KEY, 0);
    }
  }

  waitForWindowThenRun(mainLoop);
})();

