  // Tampermonkey cannot know absolute browser tab index, but we enforce a single active tab by electing
  // exactly one "leader" per browser profile using a storage lock. Only the leader runs the logic.
  const LOCK_KEY = 'drtorkzadeh_first_tab_lock';
  const LOCK_TTL_MS = 5000; // refresh the lock every 5s to keep leadership
  const LOCK_REFRESH_MS = 2000;

  function nowMs() { return Date.now(); }
  function hasValidLock() {
    const v = GM_getValue(LOCK_KEY, null);
    if (!v) return false;
    try {
      const obj = JSON.parse(v);
      return (obj && typeof obj.expires === 'number' && obj.expires > nowMs());
    } catch { return false; }
  }
