    if (!hasValidLock()) return;
    GM_setValue(LOCK_KEY, JSON.stringify({ expires: nowMs() + LOCK_TTL_MS }));
  }

  const iAmLeader = tryAcquireLock();
  if (!iAmLeader) {
    // Not the first/leader tab; do nothing.
    return;
  }
