    function inAllowedWindow(d) {
        const h = d.getHours();
        const m = d.getMinutes();
        // Allowed if time >= 22:30 OR time <= 03:30
        const after2230 = (h > 22) || (h === 22 && m >= 30) || (h >= 23);
        const before0330 = (h < 3) || (h === 3 && m <= 30);
        return after2230 || before0330;
    }

    function msUntilNext2230(d) {
        const next = new Date(d);
        // if before 22:30 today, schedule today 22:30, else tomorrow 22:30
        const todayTarget = new Date(d.getFullYear(), d.getMonth(), d.getDate(), 22, 30, 0, 0);
        if (d < todayTarget) return todayTarget - d;
        const tomorrow = new Date(d.getFullYear(), d.getMonth(), d.getDate() + 1, 22, 30, 0, 0);
        return tomorrow - d;
    }

    async function waitForWindow() {
        while (true) {
            const d = new Date();
            if (inAllowedWindow(d)) return;
            const ms = Math.min(msUntilNext2230(d), 60_000); // sleep in chunks up to 60s
            await new Promise(r => setTimeout(r, ms));
