            setTimeout(() => { tryClickSubmitOnThisPage(); }, 50);
        }
    });

    // Active loop only in the leader (first tab on main page)
    (async function mainLoop() {
        try {
            await waitForWindow();
            while (true) {
                // defend main page + leadership
                if (!isMainPageHere()) break;
                // time window enforcement
                if (!inAllowedWindow(new Date())) { await waitForWindow(); continue; }

                const text = getBodyText();
                if (text.includes(TARGET_TEXT)) {
                    await new Promise(r => setTimeout(r, 5000));
                    location.reload();
                    return; // after reload, the script re-runs and leadership will be reacquired
                } else {
                    // Not found: signal second tab to click and stop.
                    signalSecondTabToClick();
                    // Best-effort focus next tab (not reliably possible via userscripts); we at least stop here.
                    clearInterval(hbTimer);
                    return;
                }
            }
        } catch (err) {
            // fail-safe: release heartbeat by stopping it
            clearInterval(hbTimer);
        }
