    // in case it loads directly after the signal has already been sent recently.
    if (!isMainPageHere()) {
        const lastSignal = GM_getValue(SIGNAL_KEY, 0);
        if (lastSignal && (nowMs() - lastSignal) < 10_000) {
            setTimeout(() => { tryClickSubmitOnThisPage(); }, 100);
        }
