      ../node_modules/@vue/compiler-sfc/dist/index.js -> @vue/compiler-sfc
    """
    m = re.search(r"node_modules/(@[^/]+/[^/]+|[^/@][^/]*)", path)
    return m.group(1) if m else ""


def _is_loader_name(name: str) -> bool:
    """
    Determine if a token looks like a loader package name.
    """
    base = name.rsplit("/", 1)[-1]
    return (
        base.endswith("-loader")
        or base == "vue-loader"
        or (base.startswith("@") and base.endswith("-loader"))
    )


def parse_required_packages_from_webpack_error(error_text: str) -> Set[str]:
    """
    Given a webpack/Vue style-loader error message, infer which npm packages are needed.
    Returns a set of package names suitable for installation with a package manager.
    """
    segments = _extract_candidate_segments(error_text)
    packages: Set[str] = set()

    for seg in segments:
        # 1) Try extracting from a node_modules path
        pkg = _pkg_from_node_modules_path(seg)

        # 2) If not from node_modules, fall back to the basename
        if not pkg:
            pkg = seg.rsplit("/", 1)[-1]

        # 3) Only keep likely loader packages (or vue-loader)
        if _is_loader_name(pkg):
            packages.add(pkg)

        # 4) Any internal vue-loader path implies vue-loader itself
        if "vue-loader" in seg:
            packages.add("vue-loader")

    # Add peer dependencies required by certain loaders (e.g., less for less-loader)
    for loader, peers in PEER_DEPENDENCIES.items():
        if loader in packages:
            packages.update(peers)

    return packages


def suggest_install_commands(
    error_text: str,
    missing_only: Optional[Set[str]] = None
) -> Dict[str, str]:
    """
    Build aggregate install commands (npm/yarn/pnpm/bun) for the inferred packages.
    If 'missing_only' is provided, it will be used as the package set instead.
    """
    if missing_only is not None:
        pkgs = sorted(missing_only)
    else:
        pkgs = sorted(parse_required_packages_from_webpack_error(error_text))

    if not pkgs:
        return {}

    joined = " ".join(pkgs)
    return {
        "npm": f"npm install -D {joined}",
        "yarn": f"yarn add -D {joined}",
        "pnpm": f"pnpm add -D {joined}",
        "bun": f"bun add -D {joined}",
    }


# -----------------------
# Per-loader specific commands
# -----------------------

def specific_loader_install_commands(loaders: Set[str], vue_major: Optional[int] = None, vue_version: Optional[str] = None) -> Dict[str, Dict[str, str]]:
    """
    Build specific npm/yarn/pnpm/bun commands per loader, including peers.
    Special-cases vue-loader to include the correct compiler dependency if vue_major is known.
    """
    commands: Dict[str, Dict[str, str]] = {}

    def peers_for(loader: str) -> List[str]:
        return PEER_DEPENDENCIES.get(loader, [])

    for loader in sorted(loaders):
        # Compute package list for this loader
        pkgs = [loader] + peers_for(loader)

        # vue-loader extras based on Vue major
        if loader == "vue-loader":
            if vue_major == 3:
                # Best-effort to align compiler-sfc with app's vue version if provided
                if vue_version:
                    pkgs.append(f"@vue/compiler-sfc@{vue_version}")
                else:
                    pkgs.append("@vue/compiler-sfc")
            elif vue_major == 2:
                # vue-template-compiler must match exact Vue 2 version
                if vue_version:
                    pkgs.append(f"vue-template-compiler@{vue_version}")
                else:
                    pkgs.append("vue-template-compiler")
            else:
                # Unknown Vue major: leave hints to compatibility section
                pass

        joined = " ".join(pkgs)
        commands[loader] = {
            "npm": f"npm install -D {joined}",
            "yarn": f"yarn add -D {joined}",
            "pnpm": f"pnpm add -D {joined}",
            "bun": f"bun add -D {joined}",
        }

    return commands


# -----------------------
# Vue/webpack compatibility checks
# -----------------------

def _parse_pkgjson_like(input_value: Any) -> Dict[str, Any]:
    """
    Accepts:
      - a dict resembling package.json
      - a JSON string of a package.json
      - a filesystem path to a package.json (best-effort)
    Returns a dict with dependencies and devDependencies merged into a single flat lookup.
    """
    data: Dict[str, Any] = {}
    if input_value is None:
        return data

    if isinstance(input_value, dict):
        data = input_value
    elif isinstance(input_value, str):
        text = input_value
        # Might be a path to package.json
        if text.endswith(".json") or "/" in text or "\\" in text:
            try:
                with open(text, "r", encoding="utf-8") as f:
                    data = json.load(f)
            except Exception:
                # Fall back: maybe it's already JSON content
                try:
                    data = json.loads(text)
                except Exception:
                    data = {}
        else:
            # Try as JSON content
            try:
                data = json.loads(text)
            except Exception:
                data = {}
    else:
        data = {}

    deps = {}
    for section in ("dependencies", "devDependencies", "peerDependencies", "optionalDependencies"):
        sect = data.get(section, {})
        if isinstance(sect, dict):
            deps.update(sect)
    return deps


def _major_from_version(ver: Optional[str]) -> Optional[int]:
    """
    Extract the major number from a semver-like string such as:
      3.2.45, ^2.6.14, ~16.0.0, >=15, 5, 5.x
    Returns None if it cannot be parsed.
    """
    if not ver:
        return None
    # Strip npm range operators and whitespace
    cleaned = re.sub(r"^[\^~<>=\s]*", "", ver)
    # Replace 'x' style with 0
    cleaned = cleaned.replace("x", "0").replace("X", "0")
    m = re.match(r"(\d+)", cleaned)
    return int(m.group(1)) if m else None


def detect_environment(package_json_like: Any) -> Dict[str, Any]:
    """
    Inspect dependencies to infer Vue major version and presence of webpack loaders.
    Returns: { vue_version, vue_major, has_webpack, loaders_present }
    """
    deps = _parse_pkgjson_like(package_json_like)
    vue_ver = deps.get("vue") or deps.get("vue-next")
    vue_major = _major_from_version(vue_ver)
    has_webpack = any(name.startswith("webpack") for name in deps.keys())

    loaders_present = {k: (k in deps) for k in COMMON_STYLE_LOADERS.union({"vue-loader"})}
    return {
        "vue_version": vue_ver,
        "vue_major": vue_major,
        "has_webpack": has_webpack,
        "loaders_present": loaders_present,
    }


def vue_compiler_hint(packages: Set[str], vue_major: Optional[int] = None) -> str:
    """
    Provide an extra hint for vue-loader users about the required Vue compiler dependency.
    """
    if "vue-loader" in packages or (vue_major is not None):
        if vue_major == 3:
            return "Vue 3 detected: install @vue/compiler-sfc (no vue-template-compiler)."
        return (
            "Detected a Vue + webpack pipeline. If your project uses:\n"
            "- Vue 2: also install vue-template-compiler (version must exactly match your Vue 2 version)\n"
            "- Vue 3: install @vue/compiler-sfc"
        )
    return ""


# -----------------------
# Loader request parsing / breakdown
# -----------------------

def _parse_loader_options(options_str: str) -> Any:
    """
    Try to parse loader inline options (query after '?').
    - If it looks like JSON, return parsed JSON.
    - Otherwise parse as querystring (e.g., type=styles&index=0) to dict.
    - If parsing fails, return the raw string.
    """
    raw = (options_str or "").strip()
    if not raw:
        return {}
    # JSON-like?
    if raw.startswith("{") or raw.startswith("["):
        try:
            return json.loads(raw)
        except Exception:
            pass
    # Fallback to querystring (k=v&k2=v2)
    try:
        pairs = parse_qsl(raw, keep_blank_values=True)
        # Convert list of pairs to dict (keep last value for duplicate keys)
        d: Dict[str, Any] = {}
        for k, v in pairs:
            d[k] = v
        return d
    except Exception:
        return raw


def _infer_segment_is_resource(seg: str) -> bool:
    """
    Heuristic: decide whether a segment is the actual resource path vs a loader.
    """
    base = seg.rsplit("/", 1)[-1]
    if _is_loader_name(base):
        return False
    # If it looks like a file path (has slash or dot with extension), treat as resource
    return ("/" in seg) or bool(re.search(r"\.[a-zA-Z0-9]+$", base))


def _extract_prefix_flags(chain: str) -> Tuple[str, Dict[str, bool], str]:
    """
    Extract webpack inline loader prefix flags from the beginning of a request:
      - '!!'  => disable pre, normal, and post loaders from config
      - '-!'  => disable pre and normal loaders from config (allow post)
      - '!'   => disable normal loaders from config (allow pre and post)
    Returns: (prefix, flags, remainder_string)
    """
    if chain.startswith("!!"):
        return "!!", {
            "disable_pre": True, "disable_normal": True, "disable_post": True
        }, chain[2:]
    if chain.startswith("-!"):
        return "-!", {
            "disable_pre": True, "disable_normal": True, "disable_post": False
        }, chain[2:]
    if chain.startswith("!"):
        return "!", {
            "disable_pre": False, "disable_normal": True, "disable_post": False
        }, chain[1:]
    return "", {"disable_pre": False, "disable_normal": False, "disable_post": False}, chain


def parse_loader_request(chain: str) -> Dict[str, Any]:
    """
    Parse an inline webpack loader chain string and break it into:
      - prefix flags (e.g., '!!')
      - list of parts: loaders with options, and (optionally) a resource at the end
    """
    prefix, flags, remainder = _extract_prefix_flags(chain.strip())

    # Split on '!' for the remainder
    raw_parts = [p for p in remainder.split("!") if p != ""]
    parts: List[Dict[str, Any]] = []

    for i, raw in enumerate(raw_parts):
        name, opts = raw, {}
        if "?" in raw:
            name, q = raw.split("?", 1)
            opts = _parse_loader_options(q)

        part: Dict[str, Any] = {
            "raw": raw,
            "name": name,
            "options": opts,
            "type": "resource" if _infer_segment_is_resource(raw) else "loader",
            "package": "",
        }

        # Best-effort package inference
        pkg = _pkg_from_node_modules_path(name)
        if not pkg:
            base = name.rsplit("/", 1)[-1]
            if _is_loader_name(base) or base == "vue-loader":
                pkg = base
        part["package"] = pkg

        parts.append(part)

    return {
        "prefix": prefix,
        "flags": flags,
        "parts": parts,
    }


def breakdown_loader_syntax_text() -> str:
    """
    Human-readable explanation of webpack inline loader syntax.
    """
    return (
        "Webpack inline loader syntax overview:\n"
        "- Loaders are chained with '!'. The chain is evaluated from right to left.\n"
        "- The last segment is usually the resource (e.g., ./App.vue or ./styles.less).\n"
        "- A segment may include inline options after '?'. Options can be JSON (e.g., ?{\"modules\":true})\n"
        "  or querystring (e.g., ?modules=true&sourceMap=false).\n"
        "- Special prefixes at the start control which configured loaders are considered:\n"
        "  • '!!'  => use only the inline loaders; disable all configured pre/normal/post loaders.\n"
        "  • '-!'  => disable configured 'pre' and 'normal' loaders; allow 'post' loaders.\n"
        "  • '!'   => disable configured 'normal' loaders; allow 'pre' and 'post' loaders.\n"
        "- Example:\n"
        "  !!vue-style-loader!css-loader?{\\\"modules\\\":true}!postcss-loader!../../node_modules/vue-loader/lib/index.js!./App.vue\n"
        "  Interpreted right-to-left: vue-loader parses .vue SFC, postcss-loader transforms CSS,\n"
        "  css-loader resolves CSS imports/modules with options, vue-style-loader injects styles into DOM.\n"
    )


# -----------------------
# User-facing helpers (commands, troubleshooting, explanations)
# -----------------------

def explain_error_and_fix(error_text: str, package_json_like: Any = None) -> Dict[str, Any]:
    """
    Produce:
      - what the error means and where it occurs
      - aggregate npm command to install missing loaders
      - per-loader commands
      - Vue compatibility guidance
      - troubleshooting steps if install doesn't work
    """
    # What the error means / where it occurs
    explanation = (
        "Webpack couldn't resolve one or more loaders referenced in an inline loader chain. "
        "This typically appears in stack traces around a line that looks like '...!loader!path/to/vue-loader!...'. "
        "It occurs during module resolution while processing your .vue file or its <style>/<template> blocks."
    )

    inferred_packages = parse_required_packages_from_webpack_error(error_text)

    env = detect_environment(package_json_like) if package_json_like is not None else {
        "vue_version": None,
        "vue_major": None,
        "has_webpack": True,
        "loaders_present": {},
    }

    aggregate = suggest_install_commands(error_text, missing_only=inferred_packages)
    per_loader = specific_loader_install_commands(inferred_packages, env.get("vue_major"), env.get("vue_version"))

    compat_notes = vue_compiler_hint(inferred_packages, env.get("vue_major"))
    if env.get("vue_major") is None:
        compat_notes = (compat_notes + "\n" if compat_notes else "") + (
            "Tip: check your Vue version with 'npm ls vue' or in package.json to choose the correct compiler."
        )

    troubleshooting = [
        "Verify your Vue major version: npm ls vue (or check package.json). For Vue 2 use vue-template-compiler@exactVueVersion; for Vue 3 use @vue/compiler-sfc.",
        "Clear and reinstall: rm -rf node_modules package-lock.json && npm install (or the equivalent for your package manager).",
        "Ensure webpack config includes rules for .vue (vue-loader) and CSS preprocessors if used.",
        "If using less/sass/stylus, confirm their CLIs are installed (they are peers of the respective *-loader).",
        "Check for conflicting global installs; prefer project-local devDependencies.",
        "If using monorepo, ensure loaders are hoisted/accessible to the package running webpack.",
        "Delete cache (node --version-dependent tools) or disable cache-loader if stale.",
    ]

    return {
        "what_it_means": explanation,
        "inline_loader_syntax_help": breakdown_loader_syntax_text(),
        "detected_packages_to_install": sorted(inferred_packages),
        "aggregate_install_commands": aggregate,  # e.g., run aggregate_install_commands["npm"]
        "per_loader_install_commands": per_loader, # specific commands per loader, including peers
        "vue_compatibility_guidance": compat_notes,
        "troubleshooting": troubleshooting,
    }
```

Below is a self-contained example you can drop in as a small plugin. It:

- Creates an “Artiste” Ultimate Member profile tab.
- Enforces one Artiste post per user (post_author ownership).
- Lets the profile owner create, edit, and delete their own Artiste from the front end.
- Displays your Meta Box custom fields in the tab (edit mode for owner, read-only for other viewers).
- Handles featured image uploads with server-side validation and nonces.

Replace the example Meta Box field IDs with your real field IDs and adjust config as needed.

```php
<?php
/**
 * Plugin Name: UM Artiste Frontend Manager (example)
 * Description: Front-end create/edit/delete for "artiste" CPT in an Ultimate Member profile tab, with Meta Box field mapping.
 * Version:     0.2.0
 * Author:      Your Name
 */

/**
 * CONFIG
 * - Adjust CPT slug, field IDs, allowed roles, statuses, messages, limits.
 * - Replace 'artiste_stage_name', 'artiste_bio', 'artiste_website' with your Meta Box field IDs.
 */
function umart_config() {
    return array(
        'cpt' => 'artiste',
        'um' => array(
            'tab_key'    => 'artiste',
            'tab_name'   => 'Artiste',
            // Which roles are allowed to manage their Artiste from the front end
            'access_roles' => array('subscriber', 'contributor', 'author', 'editor', 'administrator'),
        ),
        'one_per_user' => array(
            'enforce'          => true,
            'include_trashed'  => false, // true = counts trashed as existing
            'on_second_attempt'=> 'edit', // 'edit' or 'error'
            'delete_behavior'  => 'trash' // 'trash' or 'force'
        ),
        'status' => array(
            'create' => 'pending', // 'draft'|'pending'|'publish'
            'update' => 'pending',
        ),
        'security' => array(
            'nonce_field'  => 'um_artiste_nonce',
            'nonce_action' => 'um_artiste_form',
        ),
        'media' => array(
            'featured_image' => array(
                'enabled' => true,
                'input'   => 'artiste_featured_image', // <input type="file" name="...">
                'allowed_mime_types' => array('image/jpeg','image/png','image/gif','image/webp'),
                'max_mb'   => 5,
            ),
        ),
        'fields' => array(
            // Native title
            array(
                'key'       => 'post_title',
                'label'     => 'Title',
                'type'      => 'text',
                'required'  => true,
            ),
            // Meta Box fields (replace with your actual field IDs)
            array(
                'key'        => 'artiste_stage_name',
                'label'      => 'Stage Name',
                'type'       => 'text',
                'required'   => true,
                'sanitize_cb'=> 'sanitize_text_field'
            ),
            array(
                'key'        => 'artiste_bio',
                'label'      => 'Biography',
                'type'       => 'textarea',
                'required'   => false,
                'sanitize_cb'=> 'wp_kses_post'
            ),
            array(
                'key'        => 'artiste_website',
                'label'      => 'Website',
                'type'       => 'url',
                'required'   => false,
                'sanitize_cb'=> 'esc_url_raw'
            ),
        ),
        'messages' => array(
            'created'    => 'Artiste created successfully.',
            'updated'    => 'Artiste updated.',
            'deleted'    => 'Artiste deleted.',
            'no_perm'    => 'You do not have permission to manage this Artiste.',
            'one_only'   => 'You already have an Artiste. You can edit it below.',
            'not_found'  => 'No Artiste yet.',
            'upload_err' => 'Upload failed. Please try again.',
            'file_type'  => 'Invalid file type.',
            'file_size'  => 'File too large.',
            'invalid'    => 'Please correct the highlighted fields.',
        ),
    );
}

/**
 * OPTIONAL: Register CPT if you don't already have it registered elsewhere.
 * Remove this block if your CPT exists.
 */
add_action('init', function () {
    $slug = umart_config()['cpt'];
    if (post_type_exists($slug)) return;

    register_post_type($slug, array(
        'label' => 'Artistes',
        'labels' => array(
            'name' => 'Artistes',
            'singular_name' => 'Artiste',
        ),
        'public' => true,
        'has_archive' => false,
        'show_ui' => true,
        'show_in_menu' => true,
        'supports' => array('title', 'editor', 'thumbnail'),
        // Consider adding custom capabilities and granting them to UM roles if needed:
        // 'capability_type' => array('artiste', 'artistes'),
        // 'map_meta_cap' => true,
    ));
});

/**
 * Ultimate Member: Add "Artiste" profile tab
 */
add_filter('um_profile_tabs', function ($tabs) {
    $cfg = umart_config();
    $key = $cfg['um']['tab_key'];
    $tabs[$key] = array(
        'name'   => $cfg['um']['tab_name'],
        'icon'   => 'um-icon-ios-albums', // change if you prefer a different icon
        'custom' => true,
    );
    return $tabs;
}, 1000);

/**
 * Ultimate Member: Render tab content
 */
add_action('um_profile_content_artiste', 'umart_render_tab');
add_action('um_profile_content_artiste_default', 'umart_render_tab');

function umart_render_tab() {
    if (!function_exists('um_profile_id')) {
        echo '<p>Ultimate Member not detected.</p>';
        return;
    }

    $profile_user_id = (int) um_profile_id();
    $current_user_id = (int) get_current_user_id();
    $is_owner = ($current_user_id && $current_user_id === $profile_user_id);

    // Process create/update/delete if owner is submitting
    if ($is_owner) {
        umart_handle_submission($profile_user_id);
    }

    // Render either edit form (owner) or read-only view (viewer)
    $post = umart_get_user_artiste_post($profile_user_id, umart_config()['one_per_user']['include_trashed']);

    if ($is_owner && umart_user_can_manage($profile_user_id)) {
        echo umart_render_edit_ui($post, $profile_user_id);
    } else {
        echo umart_render_readonly_ui($post, $profile_user_id);
    }
}

function umart_user_can_manage($user_id) {
    $cfg = umart_config();
    $user  = get_user_by('id', $user_id);
    if (!$user) return false;
    // Allow if user has any of the configured roles OR higher caps
    foreach ($cfg['um']['access_roles'] as $role) {
        if (in_array($role, (array) $user->roles, true)) return true;
    }
    // Fallback: admins
    return user_can($user_id, 'edit_posts');
}

function umart_get_user_artiste_post($user_id, $include_trashed = false) {
    $args = array(
        'post_type'      => umart_config()['cpt'],
        'post_status'    => $include_trashed ? array('publish','pending','draft','trash') : array('publish','pending','draft'),
        'author'         => $user_id,
        'posts_per_page' => 1,
        'orderby'        => 'ID',
        'order'          => 'DESC',
        'fields'         => 'all',
    );
    $q = new WP_Query($args);
    return $q->have_posts() ? $q->posts[0] : null;
}

function umart_handle_submission($user_id) {
    if (empty($_POST) && empty($_GET['umart_delete'])) return;

    $cfg = umart_config();

    // Delete action (GET with nonce)
    if (isset($_GET['umart_delete']) && isset($_GET[$cfg['security']['nonce_field']]) && wp_verify_nonce($_GET[$cfg['security']['nonce_field']], $cfg['security']['nonce_action'])) {
        $post = umart_get_user_artiste_post($user_id, true);
        if ($post && (int)$post->post_author === (int)$user_id) {
            if ($cfg['one_per_user']['delete_behavior'] === 'force') {
                wp_delete_post($post->ID, true);
            } else {
                wp_trash_post($post->ID);
            }
            add_action('um_before_profile_content', function () use ($cfg) { echo '<div class="um-notice success">'.esc_html($cfg['messages']['deleted']).'</div>'; });
        }
        return;
    }

    // Create/Update action (POST)
    if (!isset($_POST[$cfg['security']['nonce_field']]) || !wp_verify_nonce($_POST[$cfg['security']['nonce_field']], $cfg['security']['nonce_action'])) {
        return; // invalid nonce
    }

    if (!umart_user_can_manage($user_id)) return;

    $existing = umart_get_user_artiste_post($user_id, $cfg['one_per_user']['include_trashed']);

    // Validate and collect fields
    $errors = array();
    $clean  = array();

    foreach ($cfg['fields'] as $field) {
        $key = $field['key'];
        $required = !empty($field['required']);
        $val = isset($_POST[$key]) ? $_POST[$key] : '';
        if ($required && $val === '') {
            $errors[$key] = 'required';
            continue;
        }
        if (!empty($field['sanitize_cb']) && is_callable($field['sanitize_cb'])) {
            $val = call_user_func($field['sanitize_cb'], $val);
        } else {
            $val = is_string($val) ? wp_unslash($val) : $val;
        }
        $clean[$key] = $val;
    }

    // Validate media
    $attachment_id = 0;
    if (!empty($cfg['media']['featured_image']['enabled']) && isset($_FILES[$cfg['media']['featured_image']['input']]) && !empty($_FILES[$cfg['media']['featured_image']['input']]['name'])) {
        $file = $_FILES[$cfg['media']['featured_image']['input']];
        $max_bytes = (int) $cfg['media']['featured_image']['max_mb'] * 1024 * 1024;
        if ($file['size'] > $max_bytes) {
            $errors['featured_image'] = 'size';
        } else {
            $filetype = wp_check_filetype($file['name']);
            if (!in_array($filetype['type'], $cfg['media']['featured_image']['allowed_mime_types'], true)) {
                $errors['featured_image'] = 'type';
            }
        }
    }

    if (!empty($errors)) {
        add_action('um_before_profile_content', function () use ($cfg) { echo '<div class="um-notice error">'.esc_html($cfg['messages']['invalid']).'</div>'; });
        return;
    }

    // Create or update post
    $postarr = array(
        'post_type'   => $cfg['cpt'],
        'post_status' => $existing ? $cfg['status']['update'] : $cfg['status']['create'],
        'post_title'  => isset($clean['post_title']) ? $clean['post_title'] : ($existing ? $existing->post_title : ''),
        'post_author' => $user_id,
    );

    if ($existing) {
        $postarr['ID'] = $existing->ID;
        $post_id = wp_update_post($postarr, true);
    } else {
        // Enforce one per user
        if ($cfg['one_per_user']['enforce'] && umart_get_user_artiste_post($user_id, $cfg['one_per_user']['include_trashed'])) {
            // Already exists; do not create another
            add_action('um_before_profile_content', function () use ($cfg) { echo '<div class="um-notice info">'.esc_html($cfg['messages']['one_only']).'</div>'; });
            return;
        }
        $post_id = wp_insert_post($postarr, true);
    }

    if (is_wp_error($post_id)) {
        add_action('um_before_profile_content', function () use ($cfg) { echo '<div class="um-notice error">Operation failed.</div>'; });
        return;
    }

    // Save Meta Box fields
    foreach ($cfg['fields'] as $field) {
        $key = $field['key'];
        if ($key === 'post_title') continue; // native
        if (array_key_exists($key, $clean)) {
            update_post_meta($post_id, $key, $clean[$key]);
        }
    }

    // Handle featured image upload
    if (!empty($cfg['media']['featured_image']['enabled']) && isset($_FILES[$cfg['media']['featured_image']['input']]) && !empty($_FILES[$cfg['media']['featured_image']['input']]['name'])) {
        require_once ABSPATH . 'wp-admin/includes/file.php';
        require_once ABSPATH . 'wp-admin/includes/media.php';
        require_once ABSPATH . 'wp-admin/includes/image.php';
        $attachment_id = media_handle_upload($cfg['media']['featured_image']['input'], $post_id);
        if (!is_wp_error($attachment_id)) {
            set_post_thumbnail($post_id, $attachment_id);
        } else {
            add_action('um_before_profile_content', function () use ($cfg) { echo '<div class="um-notice error">'.esc_html($cfg['messages']['upload_err']).'</div>'; });
        }
    }

    add_action('um_before_profile_content', function () use ($cfg, $existing) {
        $msg = $existing ? $cfg['messages']['updated'] : $cfg['messages']['created'];
        echo '<div class="um-notice success">'.esc_html($msg).'</div>';
    });
}

function umart_render_edit_ui($post, $user_id) {
    $cfg = umart_config();
    ob_start();
    $nonce = wp_create_nonce($cfg['security']['nonce_action']);

    echo '<form method="post" enctype="multipart/form-data" class="umart-form">';
    echo '<input type="hidden" name="'.$cfg['security']['nonce_field'].'" value="'.$nonce.'" />';

    foreach ($cfg['fields'] as $field) {
        $key   = $field['key'];
        $label = esc_html($field['label']);
        $type  = $field['type'];
        $required = !empty($field['required']);
        $value = '';
        if ($key === 'post_title') {
            $value = $post ? $post->post_title : '';
        } else {
            $value = $post ? get_post_meta($post->ID, $key, true) : '';
        }
        echo '<p class="um-field">';
        echo '<label>'.$label.($required ? ' *' : '').'</label>';
        if ($type === 'textarea') {
            echo '<textarea name="'.esc_attr($key).'" rows="5">'.esc_textarea($value).'</textarea>';
        } else {
            echo '<input type="'.esc_attr($type).'" name="'.esc_attr($key).'" value="'.esc_attr($value).'" />';
        }
        echo '</p>';
    }

    // Featured image input
    if (!empty($cfg['media']['featured_image']['enabled'])) {
        echo '<p class="um-field">';
        echo '<label>Featured Image</label>';
        echo '<input type="file" name="'.esc_attr($cfg['media']['featured_image']['input']).'" accept="image/*" />';
        if ($post && has_post_thumbnail($post)) {
            echo '<br/>' . get_the_post_thumbnail($post, 'thumbnail');
        }
        echo '</p>';
    }

    echo '<p class="um-actions">';
    echo '<button type="submit" class="um-button">'.esc_html($cfg['messages']['updated']).'</button>';
    echo '</p>';

    // Delete link with nonce
    if ($post) {
        $del_url = add_query_arg(array(
            'umart_delete' => $post->ID,
