        ));
        echo '<p><a class="um-link umart-delete" href="'.esc_url($del_url).'" onclick="return confirm(\'Are you sure?\');">Delete Artiste</a></p>';
    }

    echo '</form>';

    return ob_get_clean();
}

function umart_render_readonly_ui($post, $user_id) {
    $cfg = umart_config();
