%% 2-D Source Panel Method (with optional vortex for lift), file I/O, Cp and Cl
% This script:
% - Reads body surface points (x,y) from a text file.
% - Prompts for flow conditions (U_inf, alpha), fluid density, and panel counts to test.
% - Builds a closed polygon, creates panels, and solves a constant-strength source panel system.
% - Optionally enforces Kutta condition via a single vortex to obtain lift for airfoils.
% - Computes surface tangential velocity, pressure coefficient Cp, and lift coefficient Cl.
% - Compares Cp and Cl against optional analytical/experimental data if provided.
% - Sweeps multiple panel counts to report convergence (accuracy).
%
% INPUT FILE FORMAT (body points):
%   Two columns: x y  (ordered along the surface, typically from TE over upper to LE to lower TE)
%   The file may be open (first point != last point); script will close it.
%
% OPTIONAL REFERENCE FILES:
%   - Cp reference: two columns s/C  Cp_ref (arc-length fraction and Cp) OR x/C  Cp_ref (monotonic x)
%   - Cl reference: single value in a text file (e.g., "0.345")
%
% NOTES:
% - Pure source panel method yields zero lift on a closed body at small AoA.
%   To compute lift on an airfoil, enable the Kutta condition switch below to add a vortex.
% - This implementation uses constant-strength panels and the standard analytic influence integrals.
% - Robust but concise; basic error checks are included.

clear; clc;

% ------------------------ User Prompts ------------------------
try
    bodyFile = input('Enter body points file (e.g., airfoil_points.txt): ', 's');
    if ~isfile(bodyFile)
        error('FileNotFound:Body','Body points file not found: %s', bodyFile);
    end

    U_inf = input('Enter free-stream speed U_inf [m/s] (e.g., 30): ');
    alpha_deg = input('Enter angle of attack alpha [deg] (e.g., 5): ');
    rho = input('Enter fluid density rho [kg/m^3] (e.g., 1.225): ');

    panelCountsStr = input('Enter panel counts to test (e.g., "40 80 160"): ', 's');
    panelCounts = str2num(panelCountsStr); %#ok<ST2NM>
    if isempty(panelCounts)
        panelCounts = 80; % default if user presses Enter
        fprintf('Using default panel count: %d\n', panelCounts);
    end

    useKutta = input('Enforce Kutta condition with a vortex? [0/1] (1 recommended for airfoils): ');
    useKutta = logical(useKutta);

    refCpFile = input('Optional Cp reference file (Enter to skip): ', 's');
    if isempty(refCpFile) || ~isfile(refCpFile)
        refCpFile = '';
    end

    refClFile = input('Optional Cl reference file (Enter to skip): ', 's');
    if isempty(refClFile) || ~isfile(refClFile)
        refClFile = '';
    end
catch ME
    fprintf(2,'Input error: %s\n', ME.message);
    return;
end

alpha = deg2rad(alpha_deg);
Vinf = U_inf;  % shorthand

% ------------------------ Read Geometry ------------------------
try
    P = readmatrix(bodyFile);
    if size(P,2) < 2
        error('FormatError:Body','Body file must have at least two columns (x y).');
    end
    x_raw = P(:,1); y_raw = P(:,2);
catch ME
    fprintf(2,'Failed to read body file: %s\n', ME.message);
    return;
end

% Ensure closed polygon (append first point if needed)
if hypot(x_raw(end)-x_raw(1), y_raw(end)-y_raw(1)) > 1e-12
    x_raw(end+1) = x_raw(1); %#ok<SAGROW>
    y_raw(end+1) = y_raw(1); %#ok<SAGROW>
end

% Scale to unit chord (optional but standard). Use projected chord = max(x)-min(x)
chord = max(x_raw) - min(x_raw);
if chord <= 0
    fprintf(2,'Invalid geometry: non-positive chord.\n');
    return;
end
x_raw = (x_raw - min(x_raw)) / chord; % shift and scale
y_raw = y_raw / chord;

% Arc length parameterization for resampling
s_nodes = [0; cumsum(hypot(diff(x_raw), diff(y_raw)))];
L_tot = s_nodes(end);

% ------------------------ Utility: Resample to N panels ------------------------
function [xN,yN] = resamplePolygon(xin, yin, N)
    s = [0; cumsum(hypot(diff(xin), diff(yin)))];
    L = s(end);
    s_target = linspace(0, L, N+1).';
    xN = interp1(s, xin, s_target, 'linear');
    yN = interp1(s, yin, s_target, 'linear');
    % Ensure closed
    xN(end) = xN(1); yN(end) = yN(1);
end

% ------------------------ Core Solver (constant source, optional vortex) ------------------------
function result = solveSourcePanel(xv, yv, Vinf, alpha, useKutta)
    % Inputs: xv,yv are N+1 vertex arrays (closed). N = number of panels.
    % Returns fields in result: xc,yc,tau,nx,ny,phi, sigma, gamma, Vt, Cp, Cl

    N = numel(xv)-1;  % panels
    % Panel geometry
    dx = xv(2:end) - xv(1:end-1);
    dy = yv(2:end) - yv(1:end-1);
    S = hypot(dx,dy);              % panel length
    tx = dx./S; ty = dy./S;        % unit tangent
    nx =  ty;   ny = -tx;          % outward normal (right-hand rotation)

    % Collocation points (midpoints)
    xc = 0.5*(xv(1:end-1)+xv(2:end));
    yc = 0.5*(yv(1:end-1)+yv(2:end));

    % Precompute geometry for local panel coordinates
    % Influence of constant-strength source panel j on collocation i
    A = zeros(N,N); RHS = zeros(N,1);
    % If Kutta: add vortex unknown gamma (single) and Kutta equation
    if useKutta
        A = zeros(N+1,N+1); RHS = zeros(N+1,1);
    end

    for i = 1:N
        for j = 1:N
            % Transform collocation point i into local system of panel j
            xj1 = xv(j);  yj1 = yv(j);
            cs = tx(j);   sn = ty(j);
            dxij = xc(i) - xj1;
            dyij = yc(i) - yj1;
            xloc =  dxij*cs + dyij*sn;
            yloc = -dxij*sn + dyij*cs;

            Sj = S(j);
            x2 = xloc - Sj; x1 = xloc;
            r1 = hypot(x1, yloc);
            r2 = hypot(x2, yloc);
            % Avoid log of zero
            eps = 1e-14;
            r1 = max(r1, eps); r2 = max(r2, eps);

            % Normal velocity influence of unit source over panel j at point i
            % From standard 2D source panel formulas:
            % I_n = (1/(2*pi)) * (theta2 - theta1)
            % with theta = atan2(yloc, x), evaluated at x1 and x2
            theta1 = atan2(yloc, x1);
            theta2 = atan2(yloc, x2);
            In = (theta2 - theta1) / (2*pi);

            if ~useKutta
                A(i,j) = In;  % normal component due to source sigma_j
            else
                A(i,j) = In;
            end
        end
        % RHS: - Vinf dot n at collocation i
        RHS(i) = -(Vinf*cos(alpha)*nx(i) + Vinf*sin(alpha)*ny(i));
    end

    gamma = 0;  % default vortex strength
    if useKutta
        % Vortex normal influence at collocation i: zero (vortex induces tangential velocity only)
        % Add zero column for gamma in first N rows
        % Kutta condition: tangential velocity equal on TE panels =>
        % Here we enforce that total tangential velocity at the two TE collocation points are equal.
        % Identify TE as first and last panels (adjacent to point 1)
        jTE1 = 1; jTE2 = N; 

        % Build last row: Vt(TE1) - Vt(TE2) = 0
        % Compute tangential influence of unit source on Vt at TE collocation points
        Vt_src_TE1 = zeros(1,N);
        Vt_src_TE2 = zeros(1,N);
        for j = 1:N
            % TE1 collocation in local coordinates of panel j
            % Reuse helper for tangential influence
            Vt_src_TE1(j) = tangentialInfluence(xv, yv, xc(jTE1), yc(jTE1), j);
            Vt_src_TE2(j) = tangentialInfluence(xv, yv, xc(jTE2), yc(jTE2), j);
        end
        % Tangential influence of a unit vortex (circulation +1) at a point is 1/(2*pi*R) around, but
        % along the body, the induced tangential component is effectively +1 around the contour when summed.
        % For a single global gamma, its contribution to Vt at any surface point = +0.5 (per Kutta-Joukowski discretization)
        % To keep it simple, use standard panel method formulation: Vt_gamma = 1 at each collocation (scaled by gamma/(2*pi))
        % We approximate with coefficient Cg = 1 (absorbed into gamma unknown), and determine by Kutta.
        Cg_TE1 = 1; Cg_TE2 = 1;

        A(N+1,1:N) = Vt_src_TE1 - Vt_src_TE2;
        A(N+1,N+1) = Cg_TE1 - Cg_TE2; % typically zero; Kutta reduces to equality of source-induced + freestream terms

        % RHS Kutta: -(Vinf*t at TE1 - Vinf*t at TE2)
        t1x = (xv(2)-xv(1))/S(1); t1y = (yv(2)-yv(1))/S(1);
        t2x = (xv(end)-xv(end-1))/S(end); t2y = (yv(end)-yv(end-1))/S(end);
        RHS(N+1) = -(Vinf*(cos(alpha)*t1x + sin(alpha)*t1y) - Vinf*(cos(alpha)*t2x + sin(alpha)*t2y));

        % Add gamma column (first N rows: gamma has zero normal velocity influence)
        % Already zero-initialized.

        % Solve
        sol = A\RHS;
        sigma = sol(1:N);
        gamma = sol(N+1);
    else
        sigma = A\RHS;
    end

    % Tangential velocity along surface
    Vt = zeros(N,1);
    for i = 1:N
        % Freestream tangential component
        Vt(i) = Vinf*(cos(alpha)*tx(i) + sin(alpha)*ty(i));
        % Add contribution from all sources
        for j = 1:N
            Vt(i) = Vt(i) + sigma(j) * tangentialInfluence(xv, yv, xc(i), yc(i), j);
        end
        % Add gamma contribution (approx model): Vt += Cg*gamma
        if useKutta
            Vt(i) = Vt(i) + gamma; % Cg=1 scaling
        end
    end

    Cp = 1 - (Vt./Vinf).^2;

    % Lift coefficient via Kutta–Joukowski: Cl = 2*Gamma/(Vinf*c) with c=1 after scaling
    % Discrete gamma here is already per-unit-length circulation effect in our simple model.
    if useKutta
        Cl = 2*gamma / Vinf; % chord = 1 after scaling
    else
        Cl = 0; % no lift for pure source method on closed body
    end

    result = struct('N',N,'xv',xv,'yv',yv,'xc',xc,'yc',yc,'tx',tx,'ty',ty,'nx',nx,'ny',ny, ...
                    'S',S,'sigma',sigma,'gamma',gamma,'Vt',Vt,'Cp',Cp,'Cl',Cl);
end

% ------------------------ Helper: Tangential influence of unit source panel ------------------------
function It = tangentialInfluence(xv, yv, xci, yci, j)
    % Influence on tangential velocity at point (xci,yci) from unit source on panel j.
    xj1 = xv(j);  yj1 = yv(j);
    xj2 = xv(j+1); yj2 = yv(j+1);
    dx = xj2 - xj1; dy = yj2 - yj1;
    Sj = hypot(dx,dy); cs = dx/Sj; sn = dy/Sj;

    dxp = xci - xj1; dyp = yci - yj1;
    xloc =  dxp*cs + dyp*sn;
    yloc = -dxp*sn + dyp*cs;

    x2 = xloc - Sj; x1 = xloc;
    eps = 1e-14;
    r1 = max(hypot(x1, yloc), eps);
    r2 = max(hypot(x2, yloc), eps);

    % Tangential velocity influence for constant source (standard formula):
    % I_t = (1/(2*pi)) * ln(r2/r1)
    It = (1/(2*pi)) * log(r2/r1);
end

% ------------------------ Convergence sweep and reporting ------------------------
results = struct([]);
report = struct('N',[],'Cl',[],'Cl_ref',[],'Cl_err',[]);

Cp_ref = [];
Cp_ref_xs = [];
% Load optional references
if ~isempty(refCpFile)
    try
        R = readmatrix(refCpFile);
        if size(R,2) >= 2
            Cp_ref_xs = R(:,1); Cp_ref = R(:,2);
        end
    catch ME
        fprintf(2,'Warning: failed to read Cp reference: %s\n', ME.message);
    end
end
Cl_ref = NaN;
if ~isempty(refClFile)
    try
        Cl_ref = load(refClFile);
        if isstruct(Cl_ref), Cl_ref = struct2array(Cl_ref); end
        Cl_ref = Cl_ref(1);
    catch ME
        fprintf(2,'Warning: failed to read Cl reference: %s\n', ME.message);
        Cl_ref = NaN;
    end
end

fprintf('\nRunning panel counts: %s\n', mat2str(panelCounts));
for k = 1:numel(panelCounts)
    N = panelCounts(k);
    % Resample to N panels (N+1 vertices)
    [xv, yv] = resamplePolygon(x_raw, y_raw, N);

    % Solve
    res = solveSourcePanel(xv, yv, Vinf, alpha, useKutta);
    results(k) = res; %#ok<SAGROW>

    % Compare Cp if reference provided (interpolate by arc-length fraction)
    Cp_err_rms = NaN;
    if ~isempty(Cp_ref)
        % Build arc-length fraction s/C along collocation points
        s_pan = [0; cumsum(res.S)];
        s_coll = 0.5*(s_pan(1:end-1) + s_pan(2:end));
        sbar = s_coll / s_pan(end);

        % If reference x is monotonic and within [0,1], attempt to map sbar->x via collocation x
        xbar = (res.xc - min(res.xv)) / (max(res.xv)-min(res.xv) + eps);
        xs_ref = Cp_ref_xs;

        % Heuristic: if reference abscissa appears like s/C (0..1), use sbar, else use xbar
        if all(xs_ref>=-0.05 & xs_ref<=1.05)
            Cp_model = interp1(sbar, res.Cp, min(max(xs_ref,0),1), 'linear','extrap');
        else
            Cp_model = interp1(xbar, res.Cp, min(max(xs_ref,0),1), 'linear','extrap');
        end
        Cp_err_rms = sqrt(mean((Cp_model - Cp_ref).^2,'omitnan'));
    end

    % Lift comparison
    Cl = res.Cl;
    Cl_err = NaN;
    if ~isnan(Cl_ref)
        Cl_err = Cl - Cl_ref;
    end

    report.N(end+1,1) = N; %#ok<SAGROW>
    report.Cl(end+1,1) = Cl; %#ok<SAGROW>
    report.Cl_ref(end+1,1) = Cl_ref; %#ok<SAGROW>
    report.Cl_err(end+1,1) = Cl_err; %#ok<SAGROW>

    % Print per-N summary
    fprintf('N=%4d | Cl= %.5f', N, Cl);
    if ~isnan(Cl_ref), fprintf(' | Cl_ref= %.5f | dCl= %.5f', Cl_ref, Cl_err); end
    if ~isempty(Cp_ref), fprintf(' | Cp RMS err= %.5f', Cp_err_rms); end
    fprintf('\n');
end

% ------------------------ Final reporting ------------------------
fprintf('\nSummary (by panel count):\n');
for i = 1:numel(report.N)
    fprintf('  N=%4d : Cl=%.6f', report.N(i), report.Cl(i));
    if ~isnan(report.Cl_ref(i)), fprintf(' (ref=%.6f, dCl=%.6f)', report.Cl_ref(i), report.Cl_err(i)); end
    fprintf('\n');
end

% Plot last case Cp if desired
if ~isempty(results)
    res = results(end);
    figure; 
    % Plot Cp vs x/c (common convention, note Cp positive down in aero plots; here we show standard sign)
    plot(res.xc, res.Cp, 'o-', 'DisplayName', sprintf('Model N=%d', res.N)); hold on; grid on;
    xlabel('x/c'); ylabel('C_p'); title('Pressure Coefficient Distribution');
    if ~isempty(Cp_ref)
        plot(Cp_ref_xs, Cp_ref, 'k--', 'DisplayName', 'Reference');
    end
    set(gca,'YDir','reverse'); legend('Location','best');
end

fprintf('\nDone. Notes:\n');
fprintf('- For non-lifting bodies (cylinders), set useKutta=0; Cl should be ~0.\n');
fprintf('- For airfoils, set useKutta=1 to obtain non-zero lift via Kutta condition.\n');

