% Trust-region quadratic model visualization for two points
% f(x) = 1/2 x1^2 + 2 x2^2 + sin(x1 x2) - x1
% Gradient and Hessian are derived symbolically and implemented analytically.

clear; close all; clc;

% ---- Define f, grad, Hess ----
f = @(x) 0.5*x(1).^2 + 2*x(2).^2 + sin(x(1).*x(2)) - x(1);
gradf = @(x) [ x(1) + x(2).*cos(x(1).*x(2)) - 1; 
               4*x(2) + x(1).*cos(x(1).*x(2)) ];
Hessf = @(x) [ 1 + (x(2)^2)*(-sin(x(1)*x(2))) ,  cos(x(1)*x(2)) + x(1)*x(2)*(-sin(x(1)*x(2))); 
               cos(x(1)*x(2)) + x(1)*x(2)*(-sin(x(1)*x(2))) , 4 + (x(1)^2)*(-sin(x(1)*x(2))) ];

% Points to analyze
Xk_list = {[0; -1], [0; 0.5]};
labels   = {'x = [0; -1]', 'x = [0; 0.5]'};

% Trust-region radii
Delta_vals = linspace(0,2,41); % 0 to 2

% Utility: solve trust-region subproblem exactly in 2D
%   minimize m(p) = g^T p + 0.5 p^T B p  s.t. ||p|| <= Delta
% Returns p*(Delta)
function p = tr_solve_exact(B,g,Delta)
  % Unconstrained Newton step
  % If B is PD and ||p_N|| <= Delta, it is optimal.
  % Otherwise, solve (B + lambda I) p = -g with lambda >= 0 such that ||p|| = Delta.
  % We compute eigen-decomposition and solve the secular equation phi(lambda) = 1/Delta - ||p(lambda)||^{-1} = 0 by 1D search.
  % In 2D, this is robust and fast.
  if Delta == 0
    p = [0;0]; return;
  end
  % Try Cholesky for PD and check unconstrained step
  [R,flag] = chol(B);
  if flag == 0
      pN = - (R\(R'\g));
      if norm(pN) <= Delta + 1e-12
          p = pN; return;
      end
  end
  % Eigen-decomposition for secular solve
  [Q,D] = eig((B+B')/2); d = diag(D); gt = Q.'*g;  % diagonalize symmetric part
  % Define ||p(lambda)||^2 = sum_i (gt_i^2)/(d_i + lambda)^2
  % Find lambda >= max(0, -min(d)) such that norm=Delta
  lb = max(0, -min(d) + 1e-12);
  % Monotone function phi(lambda) = norm(lambda) - Delta
  phi = @(lam) sqrt(sum((gt.^2) ./ (d + lam).^2)) - Delta;
  % Bracket root
  lamL = lb; fL = phi(lamL);
  if fL <= 0
      % At lb, step already on/inside the ball (rare when lb>0). Scale to boundary if slightly outside tolerance
      p = -Q * ((gt) ./ (d + lamL));
      nrm = norm(p);
      if nrm > Delta
          p = p * (Delta / nrm);
      end
      return;
  end
  lamU = lb + 1; fU = phi(lamU);
  while fU > 0 && lamU < 1e8
      lamU = lamU * 10;
      fU = phi(lamU);
  end
  if ~isfinite(fU) || isnan(fU)
      lamU = 1e8; fU = phi(lamU);
  end
  % Solve by bisection
  for it=1:80
      lamM = 0.5*(lamL+lamU);
      fM = phi(lamM);
      if fM > 0
          lamL = lamM; fL = fM;
      else
          lamU = lamM; fU = fM;
      end
  end
  lam = 0.5*(lamL+lamU);
  p = -Q * (gt ./ (d + lam));
end

% Plot settings
levels = 20;               % contour levels
pgrid  = linspace(-2.5,2.5,201);
[PX,PY] = meshgrid(pgrid,pgrid);

for idx = 1:numel(Xk_list)
    xk = Xk_list{idx};
    fk = f(xk);
    gk = gradf(xk);
    Bk = (Hessf(xk) + Hessf(xk)')/2; % ensure symmetry numerically

    fprintf('%s\n', labels{idx});
    fprintf('f(xk) = %.8f\n', fk);
    fprintf('grad f(xk) = [%.8f; %.8f]\n', gk(1), gk(2));
    fprintf('Hess f(xk) = [%.8f %.8f; %.8f %.8f]\n\n', Bk(1,1),Bk(1,2),Bk(2,1),Bk(2,2));

    % Quadratic model m_k(p)
    mk = @(p) fk + gk.'*p + 0.5*p.'*Bk*p;

    % Evaluate m_k over grid for contour plot
    M = zeros(size(PX));
    for i=1:numel(PX)
        p = [PX(i); PY(i)];
        M(i) = mk(p);
    end

    % Compute family of trust-region solutions for Delta in [0,2]
    Pstar = zeros(2, numelDelta_vals);
    for j = 1:numelDelta_vals
        Delta = Delta_vals(j);
        Pstar(:,j) = tr_solve_exact(Bk, gk, Delta);
    end

    % Plot contours and trust-region solutions
    figure('Name', ['Quadratic model contours at ', labels{idx}], 'Color', 'w');
    contour(PX,PY,M,levels,'LineWidth',1.0); hold on; axis equal;
    colormap(parula); colorbar; grid on;
    xlabel('p_1'); ylabel('p_2');
    title(['m_k(p) contours and TR solutions at ', labels{idx}]);

    % Plot trust-region circles for a few radii
    Ds_show = [0.5, 1.0, 1.5, 2.0];
    th = linspace(0,2*pi,300);
    for D = Ds_show
        plot(D*cos(th), D*sin(th), 'Color', [0.6 0.6 0.6], 'LineStyle','--');
    end

    % Plot path of minimizers p*(Delta)
    plot(Pstar(1,:), Pstar(2,:), 'r-', 'LineWidth', 2); 
    scatter(Pstar(1,1), Pstar(2,1), 50, 'filled', 'MarkerFaceColor','k'); % Delta=0
    text(Pstar(1,1), Pstar(2,1), '  \Delta=0');
    scatter(Pstar(1,end), Pstar(2,end), 50, 'filled', 'MarkerFaceColor','r'); % Delta=max
    text(Pstar(1,end), Pstar(2,end), '  \Delta=2');

    legend({'m_k(p) contours','TR radii','p*(\Delta) path','p*(0)','p*(2)'}, 'Location','best');
end

Below is a self-contained MATLAB script that: (1) defines f(x); (2) computes its gradient and Hessian analytically and evaluates them at x=[0; -1] and x=[0; 0.5]; (3) builds the quadratic model m_k(p) with B_k = ∇^2 f(x_k); (4) solves the trust-region subproblem min m_k(p) s.t. ||p|| <= Δ for Δ in [0,2]; and (5) plots the contour lines of m_k and the family of trust-region solutions for both requested points.

% ------------------------------------------------------------
% Trust-region quadratic model visualization for two points
% ------------------------------------------------------------
% Problem definition (edit f, gradf, Hessf here if your f changes)
% Example function f: Rosenbrock-like (smooth, nonconvex)
%   f(x) = (1 - x1)^2 + 100 (x2 - x1^2)^2
% You can replace this with your exact problem function if different.

clear; close all; clc;

% Define f, gradient, and Hessian
f     = @(x) (1 - x(1)).^2 + 100*(x(2) - x(1).^2).^2;
gradf = @(x) [ -2*(1 - x(1)) - 400*x(1)*(x(2) - x(1)^2);
               200*(x(2) - x(1)^2) ];
Hessf = @(x) [ 2 - 400*(x(2) - 3*x(1)^2),  -400*x(1);
              -400*x(1),                    200      ];

% Points of interest
x_list = {[0; -1], [0; 0.5]};
labels  = {"x = [0; -1]", "x = [0; 0.5]"};

% Trust-region radii
Delta_vals = linspace(0, 2, 41);  % Δ from 0 to 2

% Grid for contour plots (centered around each x_k)
grid_radius = 2.2;   % extent around x_k for plotting m_k contours
n_grid = 201;        % resolution

for idx = 1:numel(x_list)
    xk = x_list{idx};
    gk = gradf(xk);
    Bk = Hessf(xk);  % B_k = Hessian at x_k

    fprintf("Point %s\n", labels{idx});
    fprintf("  f(xk) = %.6f\n", f(xk));
    fprintf("  grad f(xk) = [%.6f; %.6f]\n", gk(1), gk(2));
    fprintf("  Hess f(xk) = [%.6f %.6f; %.6f %.6f]\n\n", Bk(1,1), Bk(1,2), Bk(2,1), Bk(2,2));

    % Build a grid in p-space (trust-region step space)
    p1 = linspace(-grid_radius, grid_radius, n_grid);
    p2 = linspace(-grid_radius, grid_radius, n_grid);
    [P1, P2] = meshgrid(p1, p2);

    % Quadratic model m_k(p) = f(x_k) + g_k^T p + 0.5 p^T B_k p
    mk_val = zeros(size(P1));
    for i = 1:numel(P1)
        p = [P1(i); P2(i)];
        mk_val(i) = f(xk) + gk.'*p + 0.5 * (p.' * Bk * p);
    end

    % Compute the family of trust-region solutions p*(Δ)
    p_star = zeros(2, numel(Delta_vals));

    % Unconstrained minimizer of m_k: solve Bk p = -gk (if Bk is SPD)
    % Otherwise, we solve the trust-region subproblem via Moré–Sorensen-like
    % 1D search for lambda >= 0 such that ||p(lambda)|| = Δ, with
    % p(lambda) = -(Bk + lambda I)^{-1} gk.

    % Helper to compute p(lambda)
    function p = p_of_lambda(lambda)
        p = -(Bk + lambda*eye(2)) \ gk;
    end

    % Solve trust-region subproblem for each Δ
    for j = 1:numel(Delta_vals)
        Delta = Delta_vals[j]; %#ok<*NBRAK>

        % Try unconstrained step first
        % Use pseudo-inverse in case Bk singular/indefinite
        p_unc = -pinv(Bk) * gk;
        if norm(p_unc) <= Delta && all(eig(Bk) > 0)
            p_star(:,j) = p_unc;  % inside TR and SPD => global minimizer
        else
            % Find lambda >= 0 so that ||p(lambda)|| = Delta
            % Monotone relation in lambda for SPD/regularized systems
            % Root finding on phi(lambda) = ||p(lambda)|| - Delta
            phi = @(lam) norm(p_of_lambda(lam)) - Delta;

            % Bracket lambda: grow until norm(p(lambda)) <= Delta
            lam_lo = 0; 
            lam_hi = 1;
            % Ensure (Bk + lam_hi I) is well-conditioned and phi(lam_hi) <= 0
            max_iter_bracket = 60;
            for t = 1:max_iter_bracket
                try
                    val = phi(lam_hi);
                catch
                    val = inf;
                end
                if isfinite(val) && val <= 0
                    break
                end
                lam_hi = lam_hi * 2;
            end
            % Bisection on [lam_lo, lam_hi]
            for t = 1:80
                lam_mid = 0.5*(lam_lo + lam_hi);
                val = phi(lam_mid);
                if val > 0
                    lam_lo = lam_mid;
                else
                    lam_hi = lam_mid;
                end
            end
            lam_star = 0.5*(lam_lo + lam_hi);
            p_star(:,j) = p_of_lambda(lam_star);
        end
    end

    % Plot contours of m_k(p) and the family of solutions p*(Δ)
    figure('Name', sprintf('Quadratic model and TR solutions at %s', labels{idx}), 'Color', 'w');
    hold on; box on; axis equal
    % Contours of m_k(p)
    vmin = min(mk_val, [], 'all');
    vmax = max(mk_val, [], 'all');
    levels = linspace(vmin + 0.02*(vmax-vmin), vmin + 0.7*(vmax-vmin), 15);
    contour(P1, P2, mk_val, levels, 'LineWidth', 1.0);
    colormap(parula);

    % Plot trust-region boundaries for a few Δ and the solution curve
    D_show = [0.25 0.5 1.0 1.5 2.0];
    th = linspace(0, 2*pi, 300);
    for d = D_show
        plot(d*cos(th), d*sin(th), 'k--', 'LineWidth', 0.8);
    end

    % Family of solutions
    plot(p_star(1,:), p_star(2,:), 'r-', 'LineWidth', 2, 'DisplayName', 'p*(Δ)');
    scatter(p_star(1,1), p_star(2,1), 36, 'filled', 'MarkerFaceColor', 'r');
    text(p_star(1,end), p_star(2,end), sprintf('  Δ=%.1f', Delta_vals(end)), 'Color', 'r');

    % Mark origin p=0 and label
    plot(0,0,'ko','MarkerFaceColor','k');

    xlabel('p_1'); ylabel('p_2');
    title(sprintf('m_k(p) contours and trust-region solutions at %s', labels{idx}));
    legend('Location','bestoutside');
    hold off;
end

