% TRUST REGION DEMO FOR A GIVEN f(x)
% ------------------------------------------------------------
% Problem definition (edit f, grad_f, hess_f here if needed)
clear; close all; clc;

% Define f(x) (column vector x = [x1; x2])
f     = @(x) (x(1)-1)^2 + 2*(x(2)+2)^2 + 0.5*x(1)*x(2) + 3;   % example convex quadratic with coupling

% Gradient and Hessian
grad_f = @(x) [ 2*(x(1)-1) + 0.5*x(2);
                4*(x(2)+2) + 0.5*x(1) ];

hess_f = @(x) [ 2     0.5;
                0.5   4   ];   % constant Hessian for this quadratic

% Points of interest
x_list = {[0; -1], [0; 0.5]};
labels = {"x = [0; -1]", "x = [0; 0.5]"};

% Trust-region radii
Deltas = linspace(0,2,41);  % from 0 to 2

% Helper: solve trust-region subproblem for quadratic model
% min 0.5 p^T B p + g^T p  s.t. ||p|| <= Delta
% Using Moré–Sorensen style via secular equation on lambda >= 0
function p = solve_tr(g,B,Delta)
    % If unconstrained minimizer is inside the ball, return it
    p_unc = -B\g;  % works if B is SPD; for indefinite, we regularize below
    if all(eig((B+B')/2) > 0) && norm(p_unc) <= Delta
        p = p_unc; return;
    end
    % Otherwise solve (B + lambda I) p = -g with ||p|| = Delta
    % Use 1D root-find on phi(lambda) = 1/||p(lambda)|| - 1/Delta
    I = eye(size(B));
    phi = @(lam) 1/norm((B + lam*I)\(-g)) - 1/Delta;
    % Bracket lambda
    lamL = 0; 
    lamU = 1; 
    % Increase lamU until phi(lamU) >= 0 (i.e., ||p(lamU)|| <= Delta)
    for k = 1:50
        try
            if phi(lamU) >= 0, break; end
        catch
            % In case (B+lamI) is singular; push lamU up
        end
        lamU = lamU*2;
    end
    % Bisection
    for k = 1:80
        lam = 0.5*(lamL+lamU);
        try
            val = phi(lam);
        catch
            val = -Inf; % force increase of lambda
        end
        if val >= 0
            lamU = lam;
        else
            lamL = lam;
        end
        if abs(lamU-lamL) <= 1e-10, break; end
    end
    lam = lamU;
    p = (-(B + lam*I)\g);
    % Project numerically in case of tiny overshoot
    if norm(p) > Delta*(1+1e-10)
        p = p * (Delta / norm(p));
    end
end

% Visualization grid for contours of m_k
xx = linspace(-3,3,301); yy = linspace(-3,3,301);
[X1,X2] = meshgrid(xx,yy);

for i = 1:numel(x_list)
    xk = x_list{i};
    gk = grad_f(xk);
    Bk = hess_f(xk);

    % Report gradient and Hessian values
    fprintf("Point %s\n", labels{i});
    fprintf("  f(xk) = %.6f\n", f(xk));
    fprintf("  grad f(xk) = [%.6f; %.6f]\n", gk(1), gk(2));
    fprintf("  Hess f(xk) = [%.6f %.6f; %.6f %.6f]\n\n", Bk(1,1),Bk(1,2),Bk(2,1),Bk(2,2));

    % Quadratic model m_k(p) = f(xk) + gk^T p + 0.5 p^T Bk p
    % Build m_k over grid in p-space for contouring
    Mk = zeros(size(X1));
    for r = 1:numel(X1)
        p = [X1(r); X2(r)];
        Mk(r) = f(xk) + gk.'*p + 0.5*p.'*Bk*p;
    end

    % Compute family of TR solutions for Delta in [0,2]
    Psol = zeros(2,numel(Deltas));
    for j = 1:numel(Deltas)
        Psol(:,j) = solve_tr(gk,Bk,Deltas(j));
    end

    % Plot contours of m_k(p) and solution path
    figure('Name',sprintf('Quadratic model and TR path at %s', labels{i}));
    hold on; box on; axis equal
    % Contours
    levels = linspace(min(Mk,[],'all'), min(Mk,[],'all') + 20, 30);
    contour(X1,X2,Mk,levels,'LineWidth',0.8);
    colormap(parula);
    colorbar; 

    % Trust-region circles for a subset of radii
    showIdx = round(linspace(1,numel(Deltas),6));
    theta = linspace(0,2*pi,200);
    for j = showIdx
        Delta = Deltas[j];
        plot(Delta*cos(theta), Delta*sin(theta), 'k--', 'LineWidth', 0.8);
    end

