    scatter(Psol(1,showIdx), Psol(2,showIdx), 36, 'r', 'filled');

    title(sprintf('m_k(p) contours and TR minimizers at %s', labels{i}));
    xlabel('p_1'); ylabel('p_2');
    legend('Location','best');
    hold off;
end

