clear; close all; clc;

% Define f(x), grad f(x), Hess f(x)
% Example function (modify here if your problem statement specifies a different f):
% f(x) = (x1 - 1)^4 + (x1 - x2)^2 + 0.5*x2^2
f  = @(x) (x(1)-1).^4 + (x(1)-x(2)).^2 + 0.5*x(2).^2;

% Gradient
% df/dx1 = 4(x1-1)^3 + 2(x1 - x2)
% df/dx2 = -2(x1 - x2) + x2
gradf = @(x) [ 4*(x(1)-1).^3 + 2*(x(1)-x(2));
              -2*(x(1)-x(2)) + x(2) ];

% Hessian
% d2f/dx1^2 = 12(x1-1)^2 + 2
% d2f/dx1dx2 = d2f/dx2dx1 = -2
