% Careful derivation:
% (x1-x2)^2 contributes: [2  -2; -2  2]
% 0.5*x2^2 contributes:   [0   0;  0  1]
% (x1-1)^4 contributes:   [12(x1-1)^2   0; 0  0]
% Sum => H = [12(x1-1)^2 + 2,  -2;  -2,  3]
Hessf = @(x) [ 12*(x(1)-1).^2 + 2,  -2; 
               -2,                      3 ];

% Points to analyze
