    % Quadratic model m_k(p) = f(xk) + gk^T p + 1/2 p^T Bk p
    mk = @(p) f(xk) + gk.'*p + 0.5*p.'*Bk*p;

    % Contour plot of m_k(p)
    figure('Name', ['Quadratic model contours at ', labels{k}], 'Color', 'w');
    hold on; axis equal; grid on;
    % Create grid in p-space
    pr = 2.2;  % span for visualization
    nx = 201; ny = 201;
    p1 = linspace(-pr, pr, nx);
    p2 = linspace(-pr, pr, ny);
    [P1, P2] = meshgrid(p1, p2);
    M = zeros(size(P1));
    for i=1:numel(P1)
        p = [P1(i); P2(i)];
        M(i) = mk(p);
    end
    % Draw contours
    contour(P1, P2, M, 30, 'LineWidth', 1.0);
    xlabel('p_1'); ylabel('p_2');
    title(['Contours of m_k(p) with B_k = \nabla^2 f(x_k) at ', labels{k}]);

    % Solve trust-region subproblems for a family of Deltas and plot solutions
    p_solutions = zeros(2, numelDelta(Delta_vals));
    for j = 1:numel(Delta_vals)
        Delta = Delta_vals(j);
        p_star = solve_trust_region(gk, Bk, Delta);
