        plot(p_star(1), p_star(2), 'ro', 'MarkerSize', 5, 'MarkerFaceColor', 'r');
    end

    % Connect the solutions to show the family as Delta grows
    plot(p_solutions(1, :), p_solutions(2, :), 'r-', 'LineWidth', 1.5);
    legend({'m_k contours', 'TR boundaries (family)', 'TR solutions', 'Solution path'}, 'Location', 'best');
    hold off;
end

% ----------------- helper: exact 2D trust-region solver -----------------
function p = solve_trust_region(g, B, Delta)
% Solve: min 0.5 p^T B p + g^T p  s.t. ||p|| <= Delta
% Uses the Moré–Sorensen approach simplified for 2D via safeguarded scalar lambda search.

% If unconstrained minimizer is feasible, return it
p_unc = -B\g;  % works even if B is indefinite (gives stationary point)
if norm(p_unc) <= Delta
    p = p_unc;
    return;
end

% Otherwise solve (B + lambda I) p = -g with lambda >= 0, ||p|| = Delta
% We search lambda by monotone function phi(lambda) = 1/||p(lambda)|| - 1/Delta
lam_low = 0; 
lam_high = 1; 
I = eye(2);

% Increase lam_high until ||p(lam_high)|| <= Delta and B+lam_high*I is PD
for iter = 1:40
    try
        p_try = -(B + lam_high*I)\g;
    catch
        p_try = [Inf; Inf];
    end
    if all(isfinite(p_try)) && norm(p_try) <= Delta && isPD(B + lam_high*I)
        break;
    end
    lam_high = lam_high * 2;
end

% Bisection on lambda
for iter = 1:60
    lam = 0.5*(lam_low + lam_high);
    A = B + lam*I;
    % Ensure numerical stability
    if ~isPD(A)
        lam_low = lam; %#ok<AGROW>
        continue;
    end
    p_lam = -A\g;
    if norm(p_lam) > Delta
        lam_low = lam;
    else
        lam_high = lam;
    end
end
p = -((B + lam_high*I)\g);
% Project to the boundary if minor numerical deviation
if norm(p) > Delta
    p = p * (Delta / norm(p));
end
end

function tf = isPD(A)
% Cholesky test for positive definiteness
[~,p] = chol((A + A.')/2);
tf = (p == 0);
end
