// Bulk upsert implementation for PostgreSQL
async function bulkUpsertCustomers(client, rows) {
  if (!rows.length) return { inserted: 0, updated: 0 };
  // Build parameterized INSERT ... ON CONFLICT ... DO UPDATE
  const cols = ['email', 'first_name', 'last_name', 'phone', 'address', 'city', 'state', 'zip'];
  const values = [];
  const params = [];
  rows.forEach((r, i) => {
    const rowVals = cols.map(c => r[c] ?? null);
    values.push(`(${rowVals.map((_, j) => `$${i * cols.length + j + 1}`).join(',')})`);
    params.push(...rowVals);
  });
  const setClause = cols.filter(c => c !== 'email').map(c => `${c}=EXCLUDED.${c}`).join(',');
  const sql = `
    INSERT INTO customers (${cols.join(',')})
    VALUES ${values.join(',')}
    ON CONFLICT (email)
    DO UPDATE SET ${setClause}
  `;
  try {
    await client.query('BEGIN');
    await client.query(sql, params);
    await client.query('COMMIT');
    return { inserted: rows.length, updated: 0 }; // For simplicity; refine by using RETURNING if needed
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  }
}

function sanitizeRowSync(row) {
  // Basic normalization; expand as needed
  const out = { ...row };
  if (out.email) out.email = String(out.email).trim().toLowerCase();
  ['first_name', 'last_name', 'phone', 'address', 'city', 'state', 'zip'].forEach(k => {
    if (out[k] != null) out[k] = String(out[k]).trim();
  });
  return out;
}

function spawnSanitizerWorker(rows) {
  return new Promise((resolve, reject) => {
    const worker = new Worker(__filename, { workerData: { rows } });
    worker.once('message', (sanitized) => resolve(sanitized));
    worker.once('error', reject);
    worker.once('exit', (code) => {
      if (code !== 0) reject(new Error(`Sanitizer worker exited with code ${code}`));
    });
  });
}

// Worker thread code to sanitize rows in parallel
if (!isMainThread) {
  const sanitized = workerData.rows.map(sanitizeRowSync);
  parentPort.postMessage(sanitized);
}

// Core function: process a CSV file path in background-like fashion
// Returns quickly (caller can respond) while processing continues via eventing
async function processCustomersCsvFile({ csvPath, onProgress }) {
  return new Promise((resolve, reject) => {
    const readStream = fs.createReadStream(csvPath);

    let headers = null;
    let buffer = [];
    let total = 0;
    let failed = 0;
    let activeBatches = 0;
    let ended = false;
    let streamErrored = false;

    const queue = [];
    const pushBatch = async (rows) => {
      if (!rows.length) return;
      const doWork = async () => {
        activeBatches++;
        const client = await pool.connect();
        try {
          // optional parallel sanitation
          const mapped = rows.map(mapCsvToModel);
          const sanitized = CONFIG.import.useWorkerThreads
            ? await spawnSanitizerWorker(mapped)
            : mapped.map(sanitizeRowSync);
          await bulkUpsertCustomers(client, sanitized);
        } finally {
          client.release();
          activeBatches--;
          onProgress && onProgress({ total, failed, activeBatches });
          drainIfDone();
        }
      };
      queue.push(doWork());
      // Enforce concurrency cap
      if (queue.length >= CONFIG.import.concurrentBatches) {
        await Promise.race(queue).catch(() => {});
        // Remove settled promises
        for (let i = queue.length - 1; i >= 0; i--) {
          if (queue[i].settled) queue.splice(i, 1);
        }
      }
    };

    function drainIfDone() {
      if (ended && activeBatches === 0 && !streamErrored) {
        resolve({ total, failed });
      }
    }

    function mapCsvToModel(r) {
      return {
        email: r[CONFIG.import.mapping.email],
        first_name: r[CONFIG.import.mapping.first_name],
        last_name: r[CONFIG.import.mapping.last_name],
        phone: r[CONFIG.import.mapping.phone],
        address: r[CONFIG.import.mapping.address],
        city: r[CONFIG.import.mapping.city],
        state: r[CONFIG.import.mapping.state],
        zip: r[CONFIG.import.mapping.zip]
      };
    }

    function validateHeaders(cols) {
      const missing = CONFIG.import.requiredColumns.filter(c => !cols.includes(c));
      if (missing.length) {
        throw new Error(`Missing required CSV columns: ${missing.join(', ')}`);
      }
    }

    // Robust error handling hooks
    readStream.on('error', (err) => {
      streamErrored = true;
      reject(new Error(`File read error: ${err.message}`));
    });

    Papa.parse(readStream, {
      header: true,
      skipEmptyLines: true,
      worker: false, // Papa's own workers handle text, but we're streaming a Node stream
      step: async (results, parser) => {
        try {
          const row = results.data;
          if (!headers) {
            headers = Object.keys(row);
            validateHeaders(headers);
          }
          // Basic row validation
          if (!row[CONFIG.import.mapping.email]) {
            failed++;
            return; // skip invalid row without throwing
          }
          buffer.push(row);
          total++;
          if (buffer.length >= CONFIG.import.batchSize) {
            const batch = buffer;
            buffer = [];
            parser.pause();
            await pushBatch(batch).catch((err) => {
              streamErrored = true;
              parser.abort();
              reject(new Error(`Batch processing error: ${err.message}`));
            });
            parser.resume();
          }
        } catch (err) {
          streamErrored = true;
          // Abort on unrecoverable parse/validation error
          parser.abort();
          reject(new Error(`Parsing/validation error: ${err.message}`));
        }
      },
      complete: async () => {
        try {
          // Flush remaining rows
          if (buffer.length) {
            await pushBatch(buffer);
            buffer = [];
          }
          ended = true;
          // Wait for all outstanding batches
          await Promise.allSettled(queue);
          drainIfDone();
        } catch (err) {
          streamErrored = true;
          reject(new Error(`Completion error: ${err.message}`));
        }
      },
      error: (err) => {
        streamErrored = true;
        reject(new Error(`Papa parse error: ${err.message}`));
      }
    });
  });
}

// Express.js handler example: returns 202 immediately, continues processing
