from __future__ import annotations
from dataclasses import dataclass
from typing import Dict, List, Optional, Set, Union

# ---------- Exceptions: explicit, precise messages ----------

class TranslationError(Exception):
    pass

class EmptyFromError(TranslationError):
    pass

class EmptySelectListError(TranslationError):
    pass

class DuplicateAliasError(TranslationError):
    pass

class UnknownTableError(TranslationError):
    pass

class UnknownColumnError(TranslationError):
    pass

class AmbiguousColumnError(TranslationError):
    pass

class UnsupportedFeatureError(TranslationError):
    pass


# ---------- SQL AST (minimal) ----------

class SQLExpr:
    pass

@dataclass
class Column(SQLExpr):
    name: str
    table: Optional[str] = None  # qualified as table.column if given

@dataclass
class Literal(SQLExpr):
    value: object

@dataclass
class Comparison(SQLExpr):
    op: str  # e.g., '=', '<', '>'
    left: SQLExpr
    right: SQLExpr

@dataclass
class BooleanOp(SQLExpr):
    op: str  # 'AND' or 'OR'
    left: SQLExpr
    right: SQLExpr

@dataclass
class Not(SQLExpr):
    expr: SQLExpr

@dataclass
class SelectItem:
    expr: SQLExpr
    alias: Optional[str] = None

@dataclass
class AllColumns(SQLExpr):
    # Represents SELECT *
    pass

@dataclass
class TableRef:
    name: str
    alias: Optional[str] = None

@dataclass
class SelectStmt:
    select_list: List[SelectItem]  # or items including AllColumns()
    from_tables: List[TableRef]
    where: Optional[SQLExpr] = None


# ---------- Relational Algebra AST (minimal) ----------

class RAExpr:
    pass

@dataclass
class RATable(RAExpr):
    name: str
    alias: Optional[str] = None

@dataclass
class RAProduct(RAExpr):
    left: RAExpr
    right: RAExpr

@dataclass
class RASelection(RAExpr):
    predicate: SQLExpr
    child: RAExpr

@dataclass
class RAProjection(RAExpr):
    items: List[SelectItem]  # project expressions (and aliases) from SQL AST
    child: RAExpr


# ---------- Pretty printing helpers ----------

def expr_to_str(e: SQLExpr) -> str:
    if isinstance(e, Column):
        return f"{e.table}.{e.name}" if e.table else e.name
    if isinstance(e, Literal):
        return repr(e.value)
    if isinstance(e, Comparison):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, BooleanOp):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, Not):
        return f"(NOT {expr_to_str(e.expr)})"
    if isinstance(e, AllColumns):
        return "*"
    return f"<expr:{e.__class__.__name__}>"

def ra_to_str(ra: RAExpr, indent: int = 0) -> str:
    pad = "  " * indent
    if isinstance(ra, RATable):
        alias = f" AS {ra.alias}" if ra.alias else ""
        return f"{pad}Table({ra.name}{alias})"
    if isinstance(ra, RAProduct):
        return f"{pad}Product\n{ra_to_str(ra.left, indent+1)}\n{ra_to_str(ra.right, indent+1)}"
    if isinstance(ra, RASelection):
        return f"{pad}Select[{expr_to_str(ra.predicate)}]\n{ra_to_str(ra.child, indent+1)}"
    if isinstance(ra, RAProjection):
        items = ", ".join(
            f"{expr_to_str(i.expr)}" + (f" AS {i.alias}" if i.alias else "")
            for i in ra.items
        )
        return f"{pad}Project[{items}]\n{ra_to_str(ra.child, indent+1)}"
    return f"{pad}<RA:{ra.__class__.__name__}>"


# ---------- Helpers: expression traversal and name resolution ----------

def map_expr(e: SQLExpr, f) -> SQLExpr:
    """Post-order map over SQLExpr; applies f to each node, returns possibly transformed node."""
    if isinstance(e, Comparison):
        left = map_expr(e.left, f)
        right = map_expr(e.right, f)
        e = Comparison(e.op, left, right)
    elif isinstance(e, BooleanOp):
        left = map_expr(e.left, f)
        right = map_expr(e.right, f)
        e = BooleanOp(e.op, left, right)
    elif isinstance(e, Not):
        child = map_expr(e.expr, f)
        e = Not(child)
    elif isinstance(e, (Column, Literal, AllColumns)):
        pass
    else:
        raise UnsupportedFeatureError(f"Unsupported SQL expression node: {type(e).__name__}")
    return f(e)

class NameResolver:
    """
    Resolves unqualified columns to a unique table alias, validates existence of tables/columns,
    and catches ambiguity. If a catalog is provided, it enables strong column validation.
    """
    def __init__(self, from_tables: List[TableRef], catalog: Optional[Dict[str, Set[str]]] = None, strict: bool = True):
        self.from_tables = from_tables
        self.catalog = catalog
        self.strict = strict
        # alias_key -> table_name
        self.alias_to_table: Dict[str, str] = {}
        self._init_aliases()

    def _init_aliases(self) -> None:
        seen: Set[str] = set()
        for t in self.from_tables:
            alias_key = t.alias if t.alias else t.name
            if alias_key in seen:
                raise DuplicateAliasError(f"Duplicate table alias/name in FROM: '{alias_key}'")
            seen.add(alias_key)
            self.alias_to_table[alias_key] = t.name

    def check_tables_exist(self) -> None:
        if not self.catalog:
            return
        for tr in self.from_tables:
            if tr.name not in self.catalog:
                raise UnknownTableError(f"Unknown table '{tr.name}'")

    def _table_aliases(self) -> List[str]:
        # Return alias keys in input order (alias if present, else name)
        return [t.alias if t.alias else t.name for t in self.from_tables]

    def resolve_expr(self, e: SQLExpr) -> SQLExpr:
        def resolve(node: SQLExpr) -> SQLExpr:
            if not isinstance(node, Column):
                return node

            col = node
            # If qualified (t.c)
            if col.table is not None:
                # validate table alias
                if col.table not in self.alias_to_table:
                    raise UnknownTableError(f"Unknown table or alias '{col.table}' for column '{col.name}'")
                # validate column using catalog if provided
                if self.catalog and self.strict:
                    table_name = self.alias_to_table[col.table]
                    if table_name not in self.catalog or col.name not in self.catalog[table_name]:
                        raise UnknownColumnError(f"Unknown column '{col.table}.{col.name}'")
                return col

            # Unqualified column: try to resolve uniquely among FROM tables
            candidates: List[str] = []  # list of alias keys where column exists
            alias_keys = self._table_aliases()
            if self.catalog and self.strict:
                # Only consider tables where column is known
                for ak in alias_keys:
                    tname = self.alias_to_table[ak]
                    if tname in self.catalog and col.name in self.catalog[tname]:
                        candidates.append(ak)
                if len(candidates) == 0:
                    # In non-strict mode we could accept and leave it unqualified, but strict: error
                    raise UnknownColumnError(f"Unknown column '{col.name}' in any FROM table")
            else:
                # Without catalog, we cannot know: assume ambiguity only if multiple tables present
                candidates = alias_keys

            # If multiple candidates and more than one table involved, this is ambiguous
            if len(self.from_tables) > 1 and len(candidates) != 1:
                raise AmbiguousColumnError(f"Ambiguous unqualified column '{col.name}' — qualify with table alias")

            # Resolve to the only available alias (single-table or uniquely known)
            resolved_alias = candidates[0]
            return Column(name=col.name, table=resolved_alias)

        return map_expr(e, resolve)


# ---------- Translators ----------

def translate_select_single_table(stmt: SelectStmt, catalog: Optional[Dict[str, Set[str]]] = None) -> RAExpr:
    # Validate FROM
    if stmt.from_tables is None or len(stmt.from_tables) == 0:
        raise EmptyFromError("SELECT must have at least one table in FROM")
    if len(stmt.from_tables) != 1:
        raise TranslationError("Single-table translator supports exactly one table in FROM")
    # Validate SELECT list
    if stmt.select_list is None or len(stmt.select_list) == 0:
        raise EmptySelectListError("SELECT list cannot be empty")

    resolver = NameResolver(stmt.from_tables, catalog=catalog, strict=True)
    resolver.check_tables_exist()

    base_table = stmt.from_tables[0]
    ra_tree: RAExpr = RATable(name=base_table.name, alias=base_table.alias)

    # Resolve WHERE and SELECT items for qualified names
    where_expr = resolver.resolve_expr(stmt.where) if stmt.where is not None else None
    select_items = [SelectItem(resolver.resolve_expr(it.expr), alias=it.alias) for it in stmt.select_list]

    if where_expr is not None:
        ra_tree = RASelection(predicate=where_expr, child=ra_tree)

    # If SELECT * alone, we can omit projection
    if len(select_items) == 1 and isinstance(select_items[0].expr, AllColumns):
        return ra_tree
    return RAProjection(items=select_items, child=ra_tree)


def translate_select_multiple_tables(stmt: SelectStmt, catalog: Optional[Dict[str, Set[str]]] = None) -> RAExpr:
    # Validate FROM
    if stmt.from_tables is None or len(stmt.from_tables) == 0:
        raise EmptyFromError("SELECT must have at least one table in FROM")
    if len(stmt.select_list) == 0:
        raise EmptySelectListError("SELECT list cannot be empty")

    resolver = NameResolver(stmt.from_tables, catalog=catalog, strict=True)
    resolver.check_tables_exist()

    # Build RA base as left-deep product of all tables
    def product_of_tables(tables: List[TableRef]) -> RAExpr:
        acc: RAExpr = RATable(name=tables[0].name, alias=tables[0].alias)
        for tr in tables[1:]:
            acc = RAProduct(left=acc, right=RATable(name=tr.name, alias=tr.alias))
        return acc

    ra_tree: RAExpr = product_of_tables(stmt.from_tables)

    # Resolve WHERE and SELECT
    where_expr = resolver.resolve_expr(stmt.where) if stmt.where is not None else None
    select_items = [SelectItem(resolver.resolve_expr(it.expr), alias=it.alias) for it in stmt.select_list]

    if where_expr is not None:
        ra_tree = RASelection(predicate=where_expr, child=ra_tree)

    # Omit projection if SELECT * alone
    if len(select_items) == 1 and isinstance(select_items[0].expr, AllColumns):
        return ra_tree
    return RAProjection(items=select_items, child=ra_tree)


# Optional: explicit JOIN representation in SQL AST could be added; for now,
# treat explicit JOIN ... ON ... as syntactic sugar that becomes a product + selection
# when already lowered into SelectStmt(from_tables=[...], where=BooleanOp/Comparison).

# ---------- Examples, pitfalls, and expected RA output ----------
if __name__ == "__main__":
    # A tiny catalog to enable validation
    catalog = {
        "users": {"id", "name", "age", "dept_id"},
        "depts": {"id", "name"},
    }

    def show(title: str, ra_or_exc):
        print(f"\n== {title} ==")
        if isinstance(ra_or_exc, Exception):
            print(f"ERROR: {type(ra_or_exc).__name__}: {ra_or_exc}")
        else:
            print(ra_to_str(ra_or_exc))

    # 1) Single-table, qualified by resolver
    sql1 = "SELECT id, name FROM users WHERE age > 18"
    stmt1 = SelectStmt(
        select_list=[SelectItem(Column("id")), SelectItem(Column("name"))],
        from_tables=[TableRef("users")],
        where=Comparison(">", Column("age"), Literal(18)),
    )
    try:
        ra1 = translate_select_single_table(stmt1, catalog=catalog)
        show(sql1, ra1)
        # Expected RA (pretty-printed):
        # Project[id, name]
        #   Select[(users.age > 18)]
        #     Table(users)
    except Exception as e:
        show(sql1, e)

    # 2) SELECT * short-circuit (no projection node)
    sql2 = "SELECT * FROM users"
    stmt2 = SelectStmt(
        select_list=[SelectItem(AllColumns())],
        from_tables=[TableRef("users", alias="u")],
        where=None,
    )
    try:
        ra2 = translate_select_single_table(stmt2, catalog=catalog)
        show(sql2, ra2)
        # Expected RA:
        # Table(users AS u)
    except Exception as e:
        show(sql2, e)

    # 3) Multiple tables with unqualified join predicate (implicit join)
    sql3 = "SELECT u.name, d.name FROM users u, depts d WHERE u.dept_id = d.id"
    stmt3 = SelectStmt(
        select_list=[SelectItem(Column("name", table="u")), SelectItem(Column("name", table="d"))],
        from_tables=[TableRef("users", alias="u"), TableRef("depts", alias="d")],
        where=Comparison("=", Column("dept_id", table="u"), Column("id", table="d")),
    )
    try:
        ra3 = translate_select_multiple_tables(stmt3, catalog=catalog)
        show(sql3, ra3)
        # Expected RA:
        # Project[u.name, d.name]
        #   Select[(u.dept_id = d.id)]
        #     Product
        #       Table(users AS u)
        #       Table(depts AS d)
    except Exception as e:
        show(sql3, e)

    # 4) Ambiguous unqualified column with multiple tables
    sql4 = "SELECT id FROM users u, depts d"
    stmt4 = SelectStmt(
        select_list=[SelectItem(Column("id"))],  # unqualified 'id' is ambiguous (users.id vs depts.id)
        from_tables=[TableRef("users", alias="u"), TableRef("depts", alias="d")],
        where=None,
    )
    try:
        ra4 = translate_select_multiple_tables(stmt4, catalog=catalog)
        show(sql4, ra4)
        # Expected: AmbiguousColumnError
    except Exception as e:
        show(sql4, e)

    # 5) Unknown column (caught via catalog)
    sql5 = "SELECT nickname FROM users"
    stmt5 = SelectStmt(
        select_list=[SelectItem(Column("nickname"))],
        from_tables=[TableRef("users")],
        where=None,
    )
    try:
        ra5 = translate_select_single_table(stmt5, catalog=catalog)
        show(sql5, ra5)
        # Expected: UnknownColumnError
    except Exception as e:
        show(sql5, e)

    # 6) Duplicate alias in FROM
    sql6 = "SELECT * FROM users u, depts u"
    stmt6 = SelectStmt(
        select_list=[SelectItem(AllColumns())],
        from_tables=[TableRef("users", alias="u"), TableRef("depts", alias="u")],
        where=None,
    )
    try:
        ra6 = translate_select_multiple_tables(stmt6, catalog=catalog)
        show(sql6, ra6)
        # Expected: DuplicateAliasError
    except Exception as e:
        show(sql6, e)

    # 7) Missing FROM tables
    sql7 = "SELECT 1"
    stmt7 = SelectStmt(
        select_list=[SelectItem(Literal(1))],
        from_tables=[],
        where=None,
    )
    try:
        ra7 = translate_select_single_table(stmt7, catalog=catalog)
        show(sql7, ra7)
        # Expected: EmptyFromError
    except Exception as e:
        show(sql7, e)
```

Common pitfalls and how this code handles them:
- Ambiguous unqualified columns when multiple tables are in scope: force qualification or raise AmbiguousColumnError.
- Unknown tables or columns: with a catalog, raise UnknownTableError/UnknownColumnError early; without a catalog, ambiguity checks still help but validation is weaker.
- Duplicate aliases: disallow reusing the same alias/name in FROM.
- Empty SELECT list or FROM: explicitly checked and rejected.
- SELECT * handling: omit the projection node to keep the RA tree minimal.
- Expression traversal: map_expr ensures we uniformly resolve names inside WHERE, AND/OR, NOT, and comparisons; add more expression node kinds as needed and raise UnsupportedFeatureError for unhandled nodes so failures are explicit.
- Joins: an explicit SQL JOIN ... ON ... can be represented as multiple tables plus a WHERE predicate during this translation stage (product + selection). If you model SQL joins as separate AST nodes, add a dedicated RAJoin node or lower them into product+selection before translation.

This step-by-step path starts with single-table SELECT, then extends to multiple tables (implicit joins), provides clear formation of RA trees from the SQL AST, and adds targeted error handling to catch common parser/translator issues early. The examples show exactly what RA shape to expect for each input.

Here’s a concise, hands-on introduction to a toy query parser that converts a pre-parsed SQL AST (Abstract Syntax Tree) into a relational algebra (RA) expression tree, plus concrete examples showing input SQL and the resulting RA expressions.

Key ideas:
- We do not parse SQL text; we start from Python objects that already model the SQL query (the SQL AST).
- We translate that SQL AST into a relational algebra AST using operators: Table (base relation), Selection (WHERE), Projection (SELECT), and Product (cross-product for multiple tables/joins via predicates).
- We include examples: the human-readable SQL, the Python AST you would construct, and the printed RA tree.

Python code (definitions, translator, and examples):

```python
from __future__ import annotations
from dataclasses import dataclass
from typing import List, Optional

# ---------- SQL AST (minimal) ----------

class SQLExpr:
    pass

@dataclass
class Column(SQLExpr):
    name: str
    table: Optional[str] = None  # e.g., Column(name="id", table="users")

@dataclass
class Literal(SQLExpr):
    value: object

@dataclass
class Comparison(SQLExpr):
    op: str  # e.g., '=', '<', '>', '<=', '>='
    left: SQLExpr
    right: SQLExpr

@dataclass
class BooleanOp(SQLExpr):
    op: str  # 'AND' or 'OR'
    left: SQLExpr
    right: SQLExpr

@dataclass
class Not(SQLExpr):
    expr: SQLExpr

@dataclass
class SelectItem:
    expr: SQLExpr
    alias: Optional[str] = None

@dataclass
class AllColumns(SQLExpr):
    # Represents SELECT *
    pass

@dataclass
class TableRef:
    name: str
    alias: Optional[str] = None

@dataclass
class SelectStmt:
    select_list: List[SelectItem]
    from_tables: List[TableRef]
    where: Optional[SQLExpr] = None


# ---------- Relational Algebra AST (minimal) ----------

class RAExpr:
    pass

@dataclass
class RATable(RAExpr):
    name: str
    alias: Optional[str] = None

@dataclass
class RAProduct(RAExpr):
    left: RAExpr
    right: RAExpr

@dataclass
class RASelection(RAExpr):
    predicate: SQLExpr
    child: RAExpr

@dataclass
class RAProjection(RAExpr):
    items: List[SelectItem]
    child: RAExpr


# ---------- Pretty printing helpers ----------

def expr_to_str(e: SQLExpr) -> str:
    if isinstance(e, Column):
        return f"{e.table}.{e.name}" if e.table else e.name
    if isinstance(e, Literal):
        return repr(e.value)
    if isinstance(e, Comparison):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, BooleanOp):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, Not):
        return f"(NOT {expr_to_str(e.expr)})"
    if isinstance(e, AllColumns):
        return "*"
    return f"<expr:{e.__class__.__name__}>"

def ra_to_str(ra: RAExpr, indent: int = 0) -> str:
    pad = "  " * indent
    if isinstance(ra, RATable):
        alias = f" AS {ra.alias}" if ra.alias else ""
        return f"{pad}Table({ra.name}{alias})"
    if isinstance(ra, RAProduct):
        return f"{pad}Product\n{ra_to_str(ra.left, indent+1)}\n{ra_to_str(ra.right, indent+1)}"
    if isinstance(ra, RASelection):
        return f"{pad}Select[{expr_to_str(ra.predicate)}]\n{ra_to_str(ra.child, indent+1)}"
    if isinstance(ra, RAProjection):
        items = ", ".join(
            f"{expr_to_str(i.expr)}" + (f" AS {i.alias}" if i.alias else "")
            for i in ra.items
        )
        return f"{pad}Project[{items}]\n{ra_to_str(ra.child, indent+1)}"
    return f"{pad}<RA:{ra.__class__.__name__}>"


# ---------- Translator: SQL AST -> RA AST ----------

class TranslationError(Exception):
    pass

def fold_product(tables: List[TableRef]) -> RAExpr:
    assert len(tables) >= 1
    ra: RAExpr = RATable(tables[0].name, alias=tables[0].alias)
    for tr in tables[1:]:
        ra = RAProduct(left=ra, right=RATable(tr.name, alias=tr.alias))
    return ra

def translate_select(stmt: SelectStmt) -> RAExpr:
    # Validation and common pitfalls to catch early
    if not stmt.from_tables:
        raise TranslationError("Missing FROM clause.")
    if not stmt.select_list:
        raise TranslationError("Empty SELECT list is not allowed.")

    # 1) FROM -> base subtree (single table or left-deep Product)
    if len(stmt.from_tables) == 1:
        ra: RAExpr = RATable(name=stmt.from_tables[0].name, alias=stmt.from_tables[0].alias)
    else:
        ra = fold_product(stmt.from_tables)

    # 2) WHERE -> Selection
    if stmt.where is not None:
        ra = RASelection(predicate=stmt.where, child=ra)

    # 3) SELECT -> Projection (omit if SELECT *)
    only_star = len(stmt.select_list) == 1 and isinstance(stmt.select_list[0].expr, AllColumns)
    if only_star:
        return ra
    else:
        return RAProjection(items=stmt.select_list, child=ra)


# ---------- Examples: SQL -> SQL AST -> RA AST ----------
if __name__ == "__main__":
    # Example 1 (single table)
    # SQL: SELECT id, name FROM users WHERE age > 18;
    stmt1 = SelectStmt(
        select_list=[SelectItem(Column("id")), SelectItem(Column("name"))],
        from_tables=[TableRef("users")],
        where=Comparison(">", Column("age"), Literal(18)),
    )
    ra1 = translate_select(stmt1)
    print("Example 1 SQL: SELECT id, name FROM users WHERE age > 18;")
    print(ra_to_str(ra1), end="\n\n")

    # Example 2 (SELECT *)
    # SQL: SELECT * FROM users;
    stmt2 = SelectStmt(
        select_list=[SelectItem(AllColumns())],
        from_tables=[TableRef("users")],
        where=None,
    )
    ra2 = translate_select(stmt2)
    print("Example 2 SQL: SELECT * FROM users;")
    print(ra_to_str(ra2), end="\n\n")

    # Example 3 (multi-table with join predicate in WHERE)
    # SQL: SELECT u.id, o.total FROM users AS u, orders AS o
    #      WHERE u.id = o.user_id AND o.total > 100;
    stmt3 = SelectStmt(
        select_list=[SelectItem(Column("id", table="u")), SelectItem(Column("total", table="o"))],
        from_tables=[TableRef("users", alias="u"), TableRef("orders", alias="o")],
        where=BooleanOp(
            "AND",
            left=Comparison("=", Column("id", "u"), Column("user_id", "o")),
            right=Comparison(">", Column("total", "o"), Literal(100)),
        ),
    )
    ra3 = translate_select(stmt3)
    print("Example 3 SQL: SELECT u.id, o.total FROM users AS u, orders AS o WHERE u.id = o.user_id AND o.total > 100;")
    print(ra_to_str(ra3), end="\n\n")
```

How the conversion works, step by step:
- FROM builds the base RA subtree: a single RATable for one table, or a left-deep RAProduct chain for multiple tables.
- WHERE wraps that subtree in an RASelection with the original predicate AST (you can later normalize/transform predicates if needed).
- SELECT adds an RAProjection unless the list is exactly SELECT * (where the projection can be elided).

Common pitfalls and error handling:
- Missing FROM or empty SELECT list should raise a clear TranslationError.
- Unqualified columns can be ambiguous in multi-table queries; add name resolution later to detect/resolve ambiguity.
- JOIN ... ON syntax can be modeled either as Product + Selection (as above) or a dedicated RAJoin node; start simple, then extend.

Indicative outputs:
- Example 1
  Project[id, name]
    Select[(age > 18)]
      Table(users)
- Example 2
  Table(users)
- Example 3
  Project[u.id, o.total]
    Select[((u.id = o.user_id) AND (o.total > 100))]
      Product
        Table(users AS u)
        Table(orders AS o)

