import backtrader as bt
from datetime import datetime, timezone
from typing import Iterable, Tuple, Union, Optional, Dict

DateLike = Union[datetime, float, int, str]


class EntryLine(bt.Indicator):
    """
    Draw an 'entryprice' line by passing the K-line timestamp and the price.

    - set_entryprice(when, price, extend='none'): accepts a datetime (or compatible) and a close price
      and updates the entryprice line for the corresponding datetime index, handling reverse iteration
      over already-loaded data. If the target bar is not yet loaded, it will be drawn when that bar arrives.
    """

    lines = ('entryprice',)
    plotinfo = dict(subplot=False)
    plotlines = dict(entryprice=dict(ls='-', lw=1, color='red'))

    def __init__(self):
        self.addminperiod(1)
        # key: int(round(bt_dtnum * 86400)) -> float(price)
        self._marks: Dict[int, float] = {}

    def prenext(self):
        self.lines.entryprice[0] = float('nan')

    def next(self):
        # Default NaN
        self.lines.entryprice[0] = float('nan')

        # Current bar's datetime key
        dtnum = float(self.data.datetime[0])
        key = self._to_key(dtnum)

        price = self._marks.get(key)
        if price is not None:
            self.lines.entryprice[0] = float(price)

    def set_entryprice(self, when: DateLike, price: float, extend: str = 'none') -> bool:
        """
        Update the entryprice line for the bar matching 'when' (datetime or bt date number)
        with the provided 'price' (e.g., K-line close price).

        - Reverse-iterates over already-loaded data to find the matching bar immediately.
        - If not found, stores it to be drawn when that datetime arrives in next().
        - extend controls propagation across loaded bars: {'none','left','right','both','full'}

        Returns True if updated immediately in loaded data, False if deferred.
        """
        key = self._to_key(when)
        price = float(price)

        found, neg_index = self._locate_index_by_key(key)
        if found and neg_index is not None:
            self._apply_extend(neg_index, price, extend)
            return True

        # Defer until the target datetime bar arrives
        self._marks[key] = price
        return False

    def set_many(self, when_price_pairs: Iterable[Tuple[DateLike, float]], extend: str = 'none'):
        for when, price in when_price_pairs:
            self.set_entryprice(when, price, extend=extend)

    # ---------------------------
    # Internal helpers
    # ---------------------------

    def _apply_extend(self, neg_index: int, price: float, extend: str):
        extend = (extend or 'none').lower()
        if extend not in {'none', 'left', 'right', 'both', 'full'}:
            raise ValueError("extend must be one of {'none','left','right','both','full'}")

        n = len(self.data)
        if n == 0:
            return

        if extend in ('both', 'full'):
            for j in range(-1, -n - 1, -1):
                self.lines.entryprice[j] = price
            return

        if extend == 'none':
            self.lines.entryprice[neg_index] = price
            return

        if extend == 'left':
            for j in range(neg_index, -n - 1, -1):
                self.lines.entryprice[j] = price
            return

        if extend == 'right':
            for j in range(-1, neg_index - 1, -1):
                self.lines.entryprice[j] = price
            return

    def _locate_index_by_key(self, key: int) -> Tuple[bool, Optional[int]]:
        """
        Reverse-iterate over already-loaded data to find the bar whose datetime matches 'key'.
        Returns (found, negative_index).
        """
        n = len(self.data)
        if n == 0:
            return False, None

        # Reverse iterate: -1 (current) to -n (oldest loaded)
        for idx in range(-1, -n - 1, -1):
            dtnum = float(self.data.datetime[idx])
            if self._to_key(dtnum) == key:
                return True, idx
        return False, None

    def _to_key(self, dt_or_num: DateLike) -> int:
        dtnum = self._coerce_to_bt_dtnum(dt_or_num)
        return int(round(dtnum * 86400))

    @staticmethod
    def _coerce_to_bt_dtnum(dt_or_num: DateLike) -> float:
        # Already a bt float day number
        if isinstance(dt_or_num, float):
            return dt_or_num
        if isinstance(dt_or_num, int):
            return float(dt_or_num)
        if isinstance(dt_or_num, str):
            try:
                dt = datetime.fromisoformat(dt_or_num)
            except Exception as e:
                raise ValueError(f"Unable to parse datetime string: {dt_or_num}") from e
            # Normalize to UTC if tz-aware
            if dt.tzinfo is not None:
                dt = dt.astimezone(timezone.utc).replace(tzinfo=None)
            return bt.date2num(dt)
        if isinstance(dt_or_num, datetime):
            dt = dt_or_num
            if dt.tzinfo is not None:
                dt = dt.astimezone(timezone.utc).replace(tzinfo=None)
            return bt.date2num(dt)
        # Fallback for pandas.Timestamp, etc.
        return bt.date2num(dt_or_num)

Below is a focused, end-to-end plan to move a .NET/SQL lookup service to a Nest.js (Express) microservice with an optional MongoDB backend. It starts with an in-memory XML ingest (fastest path, no DB) and cleanly upgrades to Mongo when needed—without changing the API. It also includes containerization and a reference deployment pipeline.

High-level migration plan
- Phase 0: Discovery and contract
  - Inventory current endpoints, response shapes, error semantics, clients, SLAs.
  - Extract canonical data shape from SQL/XML; list lookup fields and primary key.
  - Decide normalization rules (trim, lowercase, Unicode, “00123” kept as string).
  - Define acceptance: API parity on golden set, latency targets, readiness/health.

- Phase 1: In-memory Nest.js service (no DB)
  - Build a Nest service that:
    - Parses XML at startup and builds in-memory indexes by primary and lookup fields.
    - Exposes: GET /lookup, GET /lookup/fields, GET /lookup/count, GET /health.
    - Supports POST /lookup/reload with admin token; atomic index swap to avoid downtime.
  - Add normalization to match legacy lookup semantics.
  - Optional: file watch with debounced auto-reload.

- Phase 2: MongoDB option and ETL
  - Add USE_MONGO toggle; when true, use Mongo with indexes on same fields.
  - Implement XML→Mongo ETL (and optional SQL→Mongo) to seed data.
  - Keep identical HTTP contract in both modes.

- Phase 3: Hardening
  - Input validation (allowlist of fields), rate limiting (if external), structured logs.
  - Metrics (RPS, latency, reload duration, heap), tracing IDs in logs.
  - Readiness gate: only ready after in-memory index is loaded or Mongo connected.
  - Security: gate admin reload with token; optional API key/JWT guard.

- Phase 4: Containerization and CI/CD
  - Multi-stage Dockerfile; set Node heap below container memory limit.
  - docker-compose for local; Kubernetes manifests for prod (Deployment, Service).
  - CI pipeline: build, test, scan, push image, deploy to non-prod and prod.

- Phase 5: Rollout
  - Shadow compare against .NET; capture diffs on a golden sample.
  - Canary 5–10% traffic; monitor latency/errors/heap.
  - Full cutover; keep feature flag to roll back quickly.

- Phase 6: Decommission and tidy-up
  - Remove shadow, finalize runbooks/dashboards/alerts, decommission legacy infra.

Key risks and mitigations
- Data model mismatch: Normalize and keep strict: false in Mongo initially; tighten later.
- Normalization parity: Lock rules early; enforce at both index and query.
- Memory growth: Start in-memory; move to Mongo or partial indexing as data grows.
- Reload safety: Parse+validate to temp store; swap only if valid.

