strategy(
    title="Dynamic Allocation Buy (inline sizing)",
    overlay=true,
    initial_capital=100000,
    commission_type=strategy.commission.percent,  // set broker commission model here if desired
    commission_value=0.0,
    default_qty_type=strategy.fixed,              // we'll compute dynamic contracts ourselves
    default_qty_value=0
)

// Inputs
brokerCommissionFrac = input.float(0.001, "Broker commission (fraction, e.g., 0.001 = 0.1%)", step=0.0001)

// Demo Fibonacci-like levels (replace with your own fibLevelX/Y/Z series)
len = input.int(100, "Range length for demo fibs", minval=2)
hi  = ta.highest(high, len)
lo  = ta.lowest(low, len)
rng = math.max(hi - lo, syminfo.mintick)
fibLevelX = lo + rng * 0.618
fibLevelY = lo + rng * 0.786
fibLevelZ = lo + rng * 1.000

// Entry condition: close > any of the previous bar's fib levels
enterLong = (close > fibLevelX[1]) or (close > fibLevelY[1]) or (close > fibLevelZ[1])

// Compute inline sizing components
var float precloseprice = na
precloseprice := close[1]
intStopLoss     = math.round(math.abs(precloseprice - fibLevelX))
intSLPercentage = intStopLoss * 100.0 / strategy.equity
allocPercent    = math.max(intSLPercentage, brokerCommissionFrac * 100.0)

// Convert percent-of-equity allocation to contracts (units)
qtyContracts = (allocPercent / 100.0) * strategy.equity / close

// Proper strategy.entry call with inline allocation and market order
strategy.entry(
    id="Buy",
    direction=strategy.long,
    qty=enterLong ? qtyContracts : na,
    limit=na
)

// Explanation:
// - strategy.entry creates an entry order for the strategy. Here, it issues a long order with id "Buy".
//   The qty argument embeds the allocation logic inline: when the entry condition (enterLong) is true,
//   we size the order by converting the larger of (stop-loss distance as % of equity) and (broker commission %)
//   into a fraction of equity, then into contracts using current close price. When the condition is false,
//   qty is na so no order is placed.
// - The conditional logic (enterLong) checks whether the current close is greater than any of the prior bar's
//   fib levels X, Y, or Z. If true, the order is eligible; otherwise, it is skipped (qty=na).
// - The math: intStopLoss = round(|precloseprice - fibLevelX|) gives a price-distance; dividing by strategy.equity
//   and multiplying by 100 yields a percent-of-equity risk proxy. We then take max(...) with brokerCommissionFrac*100
//   so the allocation is never below the commission percentage.
// - limit=na makes this a market order in Pine Script (no price limit is specified). The order will be filled at the
//   market price on the bar where the condition is evaluated. If a limit price were provided, the order would only
//   execute at or better than that price; using na ensures immediate market-style execution when eligible.

