#define THROW_IF(cond, msg) do { if (cond) throw std::runtime_error(msg); } while(0)

static void OpenSSL_Init()
{
    OPENSSL_init_ssl(0, nullptr);
    OPENSSL_init_crypto(OPENSSL_INIT_LOAD_CONFIG, nullptr);
}

static std::string GetOpenSSLError()
{
    BIO* bio = BIO_new(BIO_s_mem());
    if (!bio) return "";
    ERR_print_errors(bio);
    char* data = nullptr;
    long len = BIO_get_mem_data(bio, &data);
    std::string s = (len > 0 && data) ? std::string(data, (size_t)len) : std::string();
    BIO_free(bio);
    return s;
}

struct HttpResponse {
    DWORD status = 0;
    std::string headers;
    std::vector<uint8_t> body;
};

class WinHttpClient {
public:
    WinHttpClient() {
        hSession = WinHttpOpen(L"TorExample/1.0",
                               WINHTTP_ACCESS_TYPE_AUTOMATIC_PROXY,
                               WINHTTP_NO_PROXY_NAME,
                               WINHTTP_NO_PROXY_BYPASS, 0);
        if (!hSession) throw std::runtime_error("WinHttpOpen failed");
        DWORD secureProtocols = WINHTTP_FLAG_SECURE_PROTOCOL_TLS1 | WINHTTP_FLAG_SECURE_PROTOCOL_TLS1_1 | WINHTTP_FLAG_SECURE_PROTOCOL_TLS1_2;
        WinHttpSetOption(hSession, WINHTTP_OPTION_SECURE_PROTOCOLS, &secureProtocols, sizeof(secureProtocols));
    }
    ~WinHttpClient(){ if (hSession) WinHttpCloseHandle(hSession); }

    HttpResponse Get(const std::wstring& host, INTERNET_PORT port, const std::wstring& path, bool tls=true) {
        return Request(L"GET", host, port, path, {}, tls);
    }

    HttpResponse Post(const std::wstring& host, INTERNET_PORT port, const std::wstring& path, const std::vector<uint8_t>& data, const std::wstring& contentType=L"application/octet-stream", bool tls=true) {
        std::wstring headers = L"Content-Type: " + contentType + L"\r\n";
        return Request(L"POST", host, port, path, data, tls, headers);
    }

private:
    HINTERNET hSession = nullptr;

    HttpResponse Request(const std::wstring& method, const std::wstring& host, INTERNET_PORT port, const std::wstring& path,
                         const std::vector<uint8_t>& body, bool tls, const std::wstring& extraHeaders=L"")
    {
        HttpResponse result;
        HINTERNET hConnect = nullptr, hRequest = nullptr;
        BOOL bRes;
        try {
            hConnect = WinHttpConnect(hSession, host.c_str(), port, 0);
            THROW_IF(!hConnect, "WinHttpConnect failed");

            DWORD flags = WINHTTP_FLAG_REFRESH;
            if (tls) flags |= WINHTTP_FLAG_SECURE;

            hRequest = WinHttpOpenRequest(hConnect, method.c_str(), path.c_str(), NULL,
                                          WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, flags);
            THROW_IF(!hRequest, "WinHttpOpenRequest failed");

            if (tls) {
                DWORD secFlags = SECURITY_FLAG_IGNORE_CERT_CN_INVALID | SECURITY_FLAG_IGNORE_CERT_DATE_INVALID | SECURITY_FLAG_IGNORE_UNKNOWN_CA;
                // For directory authorities you should validate CA; relaxed here to avoid sample failures behind MITM/enterprise proxies.
                WinHttpSetOption(hRequest, WINHTTP_OPTION_SECURITY_FLAGS, &secFlags, sizeof(secFlags));
            }

            if (!extraHeaders.empty()) {
                bRes = WinHttpAddRequestHeaders(hRequest, extraHeaders.c_str(), (DWORD)-1L, WINHTTP_ADDREQ_FLAG_ADD);
                THROW_IF(!bRes, "WinHttpAddRequestHeaders failed");
            }

            if (method == L"POST") {
                bRes = WinHttpSendRequest(hRequest,
                                          WINHTTP_NO_ADDITIONAL_HEADERS, 0,
                                          (LPVOID)(body.empty() ? nullptr : body.data()), (DWORD)body.size(), (DWORD)body.size(), 0);
            } else {
                bRes = WinHttpSendRequest(hRequest, WINHTTP_NO_ADDITIONAL_HEADERS, 0, NULL, 0, 0, 0);
            }
            THROW_IF(!bRes, "WinHttpSendRequest failed");

            bRes = WinHttpReceiveResponse(hRequest, NULL);
            THROW_IF(!bRes, "WinHttpReceiveResponse failed");

            DWORD statusCode = 0; DWORD len = sizeof(statusCode);
            bRes = WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER, WINHTTP_HEADER_NAME_BY_INDEX, &statusCode, &len, WINHTTP_NO_HEADER_INDEX);
            THROW_IF(!bRes, "WinHttpQueryHeaders status failed");
            result.status = statusCode;

            // Get all headers
            DWORD dwSize = 0;
            WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_RAW_HEADERS_CRLF, WINHTTP_HEADER_NAME_BY_INDEX, NULL, &dwSize, WINHTTP_NO_HEADER_INDEX);
            if (GetLastError() == ERROR_INSUFFICIENT_BUFFER) {
                std::wstring hdrs; hdrs.resize(dwSize/sizeof(wchar_t));
                bRes = WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_RAW_HEADERS_CRLF, WINHTTP_HEADER_NAME_BY_INDEX, hdrs.data(), &dwSize, WINHTTP_NO_HEADER_INDEX);
                if (bRes) {
                    // convert to UTF-8
                    int need = WideCharToMultiByte(CP_UTF8, 0, hdrs.c_str(), -1, NULL, 0, NULL, NULL);
                    std::string utf8; utf8.resize(need ? need-1 : 0);
                    if (need > 0)
                        WideCharToMultiByte(CP_UTF8, 0, hdrs.c_str(), -1, utf8.data(), need-1, NULL, NULL);
                    result.headers = utf8;
                }
            }

            // Read body
            for(;;) {
                DWORD avail = 0;
                if (!WinHttpQueryDataAvailable(hRequest, &avail)) break;
                if (avail == 0) break;
                size_t pos = result.body.size();
                result.body.resize(pos + avail);
                DWORD read = 0;
                if (!WinHttpReadData(hRequest, result.body.data() + pos, avail, &read)) break;
                result.body.resize(pos + read);
                if (read == 0) break;
            }
        } catch (...) {
            if (hRequest) WinHttpCloseHandle(hRequest);
            if (hConnect) WinHttpCloseHandle(hConnect);
            throw;
        }
        if (hRequest) WinHttpCloseHandle(hRequest);
        if (hConnect) WinHttpCloseHandle(hConnect);
        return result;
    }
};

// Utility: simple Base64 and Base32 (Crockford-like/Base32 variant used by Tor is base32 with lowercase, no padding).
// For brevity, implement minimal base32 decode for onion address (z-base32/tor base32 = RFC4648 without padding, lowercase).

static int from_b32_char(char c) {
    if (c >= 'a' && c <= 'z') return (c - 'a');
    if (c >= '2' && c <= '7') return 26 + (c - '2');
    return -1;
}

static std::vector<uint8_t> base32_rfc4648_nopad_decode(const std::string& s)
{
    std::vector<uint8_t> out;
    int buffer = 0; int bitsLeft = 0;
    for (char ch : s) {
        if (ch == '=') break;
        int v = from_b32_char(ch);
        if (v < 0) continue; // skip invalid
        buffer = (buffer << 5) | v; bitsLeft += 5;
        if (bitsLeft >= 8) {
            bitsLeft -= 8;
            out.push_back((uint8_t)((buffer >> bitsLeft) & 0xFF));
        }
    }
    return out;
}

// Tor v3 onion address = base32(pubkey || checksum || version), length 56 chars; pubkey ed25519 (32 bytes)
// Here we parse to extract the 32-byte ed25519 pubkey.

struct OnionV3Address {
    std::array<uint8_t,32> ed25519_pubkey{};
};

static OnionV3Address ParseOnionV3Address(const std::string& onion)
{
    // Expect something like: 56-chars base32 + ".onion"
    std::string name = onion;
    if (name.size() > 6 && name.substr(name.size()-6) == ".onion") name = name.substr(0, name.size()-6);
    std::string lower;
    lower.reserve(name.size());
    for (char c: name) lower.push_back((char)tolower((unsigned char)c));
    THROW_IF(lower.size() != 56, "Invalid v3 onion length");
    auto decoded = base32_rfc4648_nopad_decode(lower);
    // decoded = 35 bytes: 32 pubkey + 2 checksum + 1 version
    THROW_IF(decoded.size() != 35, "Invalid v3 onion decode size");
    THROW_IF(decoded.back() != 0x03, "Invalid v3 version byte");
    OnionV3Address addr;
    std::copy(decoded.begin(), decoded.begin()+32, addr.ed25519_pubkey.begin());
    return addr;
}

// Minimal Tor consensus parsing: we fetch consensus text and collect relays with HSDir flag and Dir address.
struct RelayInfo {
    std::string nickname;
    std::string address; // IPv4 textual
    uint16_t dirPort = 0; // DirPort for directory fetches (HTTPS on 443 or 80). In practice, DirPort may be 0; use ORPort + DirPort flags.
    bool hsdir = false;
};

static std::vector<RelayInfo> ParseConsensus(const std::string& consensus)
{
    std::vector<RelayInfo> relays;
    std::istringstream iss(consensus);
    std::string line;
    RelayInfo current;
    bool inRouter = false;
    while (std::getline(iss, line)) {
        if (line.size() && line.back()=='\r') line.pop_back();
        if (line.rfind("r ", 0) == 0) {
            // r Name address ORPort DirPort ...
            std::istringstream rl(line);
            std::string tag; rl >> tag;
            current = RelayInfo{}; inRouter = true;
            rl >> current.nickname >> current.address; // ignore others
            uint16_t orPort=0, dirPort=0; rl >> orPort >> dirPort; current.dirPort = dirPort;
        } else if (line.rfind("s ", 0) == 0 && inRouter) {
            // flags
            if (line.find(" HSDir") != std::string::npos || line.find(" HSDir ") != std::string::npos)
                current.hsdir = true;
            // finalize current relay when we see flags line
            relays.push_back(current);
            inRouter = false;
        }
    }
    // Filter HSDir with a plausible DirPort
    std::vector<RelayInfo> hsdirs;
    for (auto& r : relays) {
        if (r.hsdir && r.dirPort != 0) hsdirs.push_back(r);
    }
    return hsdirs;
}

// Fetch Tor consensus from a directory authority mirror (use torproject CDN). Real Tor uses multiple authorities and verifies signatures.
static std::string DownloadConsensus(WinHttpClient& http)
{
    // Use Tor Project consensus via CDN
    auto resp = http.Get(L"collector.torproject.org", INTERNET_DEFAULT_HTTPS_PORT, L"/recent/relay-descriptors/consensuses/", true);
    THROW_IF(resp.status != 200, "Failed to list consensuses");

    // Very simple: find latest consensus file name ending with .consensus
    std::string listing(resp.body.begin(), resp.body.end());
    // Naive parse: find first href to consensus file
    size_t pos = listing.find(".consensus");
    THROW_IF(pos == std::string::npos, "No consensus file found");
    // Find start of filename (previous quote)
    size_t start = listing.rfind("\"", pos);
    size_t end = pos + std::string(".consensus").size();
    THROW_IF(start == std::string::npos, "Parsing listing failed");
    std::string fname = listing.substr(start+1, end - (start+1));

    std::wstring wpath = L"/recent/relay-descriptors/consensuses/";
    wpath += std::wstring(fname.begin(), fname.end());
    auto resp2 = http.Get(L"collector.torproject.org", INTERNET_DEFAULT_HTTPS_PORT, wpath, true);
    THROW_IF(resp2.status != 200, "Consensus download failed");

    return std::string(resp2.body.begin(), resp2.body.end());
}

// Select an HSDir from consensus (very naive random pick)
static RelayInfo SelectHSDir(const std::vector<RelayInfo>& hsdirs)
{
    THROW_IF(hsdirs.empty(), "No HSDir relays available");
    // Non-cryptographic selection for demo
    size_t idx = (size_t)(GetTickCount64() % hsdirs.size());
    return hsdirs[idx];
}

// Download v3 hidden service descriptor from HSDir. Real Tor uses a hash ring and blinded keys.
static std::string DownloadHSDescriptor(WinHttpClient& http, const RelayInfo& hsdir, const std::string& onion)
{
    // Tor directory protocol v3: descriptor endpoint roughly: /tor/hs/3/<blinded-id>
    // For demo, we try common DirPort over HTTPS. In reality, many relays serve directory over ORPort; here we assume HTTPS on 443.
    std::wstring host = std::wstring(hsdir.address.begin(), hsdir.address.end());
    INTERNET_PORT port = hsdir.dirPort == 0 ? INTERNET_DEFAULT_HTTPS_PORT : hsdir.dirPort;

    // Compute blinded id from onion pubkey and current time period (prop224). Here we skip full blinding and fetch by onion directly if mirror supports; otherwise, this will 404.
    // This placeholder demonstrates request mechanics.
    std::string pathAscii = "/tor/hs/3/" + onion; // Placeholder path; real path requires blinded pubkey and period
    std::wstring path = std::wstring(pathAscii.begin(), pathAscii.end());

    auto resp = http.Get(host, port, path, true);
    THROW_IF(resp.status != 200, "HS descriptor fetch failed");
    return std::string(resp.body.begin(), resp.body.end());
}

// Parse minimal fields from v3 descriptor: introduction points and keys
struct IntroPoint {
    std::string ip_addr;
    uint16_t or_port = 0;
    std::vector<uint8_t> onion_key_raw; // ed25519
};

struct HSDescriptorV3 {
    std::vector<IntroPoint> intro_points;
    std::vector<uint8_t> blinded_pubkey; // ed25519
};

static HSDescriptorV3 ParseHSDescriptorV3(const std::string& desc)
{
    HSDescriptorV3 d;
    // Very naive parsing to demonstrate extracting intro points from text descriptor. Real descriptors are in Tor-specific format; newer use binary/CBOR-ish for some fields.
    std::istringstream ss(desc);
    std::string line;
    IntroPoint cur{}; bool inIntro = false;
    while (std::getline(ss, line)) {
        if (line.size() && line.back()=='\r') line.pop_back();
        if (line.find("blinded-public-key ") == 0) {
            // e.g., blinded-public-key: base64
            std::string b64 = line.substr(strlen("blinded-public-key "));
            // Minimal base64 decode using OpenSSL
            BIO* b64bio = BIO_new(BIO_f_base64());
            BIO_set_flags(b64bio, BIO_FLAGS_BASE64_NO_NL);
            BIO* mem = BIO_new_mem_buf(b64.data(), (int)b64.size());
            mem = BIO_push(b64bio, mem);
            std::vector<uint8_t> tmp(64);
            int n = BIO_read(mem, tmp.data(), (int)tmp.size());
            if (n > 0) tmp.resize((size_t)n); else tmp.clear();
            BIO_free_all(mem);
            d.blinded_pubkey = std::move(tmp);
        } else if (line == "introduction-point") {
            inIntro = true; cur = IntroPoint{};
        } else if (inIntro && line.find("ip ") == 0) {
            cur.ip_addr = line.substr(3);
        } else if (inIntro && line.find("or-port ") == 0) {
            cur.or_port = (uint16_t)atoi(line.substr(8).c_str());
        } else if (inIntro && line.find("onion-key ") == 0) {
            // Assume base64 key on same line for demo
            std::string b64 = line.substr(10);
            BIO* b64bio = BIO_new(BIO_f_base64());
            BIO_set_flags(b64bio, BIO_FLAGS_BASE64_NO_NL);
            BIO* mem = BIO_new_mem_buf(b64.data(), (int)b64.size());
            mem = BIO_push(b64bio, mem);
            std::vector<uint8_t> tmp(64);
            int n = BIO_read(mem, tmp.data(), (int)tmp.size());
            if (n > 0) tmp.resize((size_t)n); else tmp.clear();
            BIO_free_all(mem);
            cur.onion_key_raw = std::move(tmp);
        } else if (inIntro && line == "introduction-end") {
            d.intro_points.push_back(cur);
            inIntro = false;
        }
    }
    return d;
}

// Demonstrate crypto for v3 onion handshake material: derive ephemeral x25519 key, perform ntor-like KDF placeholders
struct RendezvousMaterial {
    std::array<uint8_t,32> eph_priv{};
    std::array<uint8_t,32> eph_pub{};
};

static RendezvousMaterial BuildRendezvous(OPENSSL_CTX* /*ctx*/, const HSDescriptorV3& desc)
{
    RendezvousMaterial mat{};
    // Generate ephemeral X25519 keypair
    EVP_PKEY_CTX* pctx = EVP_PKEY_CTX_new_id(EVP_PKEY_X25519, NULL);
    THROW_IF(!pctx, ("EVP_PKEY_CTX_new_id failed: "+GetOpenSSLError()).c_str());
    EVP_PKEY* pkey = NULL;
    THROW_IF(EVP_PKEY_keygen_init(pctx) <= 0, ("X25519 keygen_init failed: "+GetOpenSSLError()).c_str());
    THROW_IF(EVP_PKEY_keygen(pctx, &pkey) <= 0, ("X25519 keygen failed: "+GetOpenSSLError()).c_str());

    // Extract raw private/public
    size_t len = 0;
    THROW_IF(EVP_PKEY_get_raw_private_key(pkey, NULL, &len) <= 0 || len != 32, "raw priv len");
    THROW_IF(EVP_PKEY_get_raw_private_key(pkey, mat.eph_priv.data(), &len) <= 0, "get raw priv");
    THROW_IF(EVP_PKEY_get_raw_public_key(pkey, NULL, &len) <= 0 || len != 32, "raw pub len");
    THROW_IF(EVP_PKEY_get_raw_public_key(pkey, mat.eph_pub.data(), &len) <= 0, "get raw pub");

    EVP_PKEY_free(pkey);
    EVP_PKEY_CTX_free(pctx);

    // In real Tor: Perform ntor on intro point's curve25519 key, derive keys via KDF (HKDF-SHA3/Blake2 variants per spec), construct INTRODUCE1 and RENDEZVOUS cells.
    (void)desc; // suppress unused warning

    return mat;
}

// Placeholder Tor over WinHTTP transport: In real usage, you send cells over a circuit. Here we just demonstrate request formation.
static HttpResponse TorGET_viaWinHTTP_Scaffold(WinHttpClient& http, const std::string& onionHost, const std::string& path)
{
    // WinHTTP cannot resolve .onion in clearnet. This scaffold shows how a request would look once tunneled.
    // We simulate by sending to a dummy endpoint to illustrate GET/POST code paths.
    std::wstring wHost = L"example.com"; // placeholder
    std::wstring wPath = std::wstring(L"/get?via=tor&onion=") + std::wstring(onionHost.begin(), onionHost.end()) + L"&path=" + std::wstring(path.begin(), path.end());
    return http.Get(wHost, INTERNET_DEFAULT_HTTPS_PORT, wPath, true);
}

static HttpResponse TorPOST_viaWinHTTP_Scaffold(WinHttpClient& http, const std::string& onionHost, const std::string& path, const std::vector<uint8_t>& data, const std::wstring& contentType)
{
    std::wstring wHost = L"example.com"; // placeholder
    std::wstring wPath = std::wstring(L"/post?via=tor&onion=") + std::wstring(onionHost.begin(), onionHost.end()) + L"&path=" + std::wstring(path.begin(), path.end());
    return http.Post(wHost, INTERNET_DEFAULT_HTTPS_PORT, wPath, data, contentType, true);
}

int main()
{
    try {
        OpenSSL_Init();
        WinHttpClient http;

        const std::string ONION_ADDRESS = "exampleexampleexampleexampleexampleexampleexampleex.onion"; // replace with real v3 address

        // 1) Parse onion v3 address
        OnionV3Address onion = ParseOnionV3Address(ONION_ADDRESS);

        // 2) Download Tor consensus
        std::string consensus = DownloadConsensus(http);
        if (consensus.empty()) throw std::runtime_error("Consensus empty");

        // 3) Parse consensus and select HSDir
        auto hsdirs = ParseConsensus(consensus);
        THROW_IF(hsdirs.empty(), "No HSDir relays parsed from consensus");
        RelayInfo hsdir = SelectHSDir(hsdirs);

        // 4) Download hidden service descriptor (placeholder endpoint)
        std::string hsdesc = DownloadHSDescriptor(http, hsdir, ONION_ADDRESS.substr(0, ONION_ADDRESS.size()-6));

        // 5) Parse descriptor
        HSDescriptorV3 desc = ParseHSDescriptorV3(hsdesc);
        if (desc.intro_points.empty()) {
            fprintf(stderr, "Warning: No intro points parsed; proceeding with demo crypto only.\n");
        }

        // 6) Build rendezvous/intro crypto material using OpenSSL
        RendezvousMaterial mat = BuildRendezvous(nullptr, desc);
        (void)mat;

        // 7) Demonstrate GET over Tor transport scaffold using WinHTTP
        auto getResp = TorGET_viaWinHTTP_Scaffold(http, ONION_ADDRESS, "/");
        printf("GET status: %lu\n", (unsigned long)getResp.status);
        printf("GET body size: %zu\n", getResp.body.size());

        // 8) Demonstrate POST over Tor transport scaffold using WinHTTP
        std::vector<uint8_t> postData = {'h','e','l','l','o'};
        auto postResp = TorPOST_viaWinHTTP_Scaffold(http, ONION_ADDRESS, "/submit", postData, L"application/octet-stream");
        printf("POST status: %lu\n", (unsigned long)postResp.status);
        printf("POST body size: %zu\n", postResp.body.size());

        return 0;
    } catch (const std::exception& ex) {
        std::string oss = GetOpenSSLError();
        fprintf(stderr, "Error: %s\n", ex.what());
        if (!oss.empty()) fprintf(stderr, "OpenSSL: %s\n", oss.c_str());
        return 1;
    }
}

