// Utility: RAII for HINTERNET
struct WinHttpHandle {
    HINTERNET h{nullptr};
    WinHttpHandle() = default;
    explicit WinHttpHandle(HINTERNET x) : h(x) {}
    ~WinHttpHandle(){ if(h) WinHttpCloseHandle(h); }
    operator HINTERNET() const { return h; }
};

static std::string LastErrorMessage(const char* ctx){
    DWORD e = GetLastError();
    LPVOID lpMsgBuf = nullptr;
    FormatMessageA(FORMAT_MESSAGE_ALLOCATE_BUFFER|FORMAT_MESSAGE_FROM_SYSTEM|FORMAT_MESSAGE_IGNORE_INSERTS,
                   NULL, e, MAKELANGID(LANG_NEUTRAL, SUBLANG_DEFAULT), (LPSTR)&lpMsgBuf, 0, NULL);
    std::string msg = ctx;
    msg += ": ";
    if(lpMsgBuf){ msg += (char*)lpMsgBuf; LocalFree(lpMsgBuf);} else { msg += "Unknown error"; }
    return msg;
}

// OpenSSL init
struct OpenSSLGlobalInit {
    OpenSSLGlobalInit(){
        OPENSSL_init_crypto(0, nullptr);
        OPENSSL_init_ssl(0, nullptr);
    }
    ~OpenSSLGlobalInit(){
        // OpenSSL 3 cleans up automatically; explicit cleanup discouraged.
    }
};

// Simple Base64 helpers using OpenSSL BIO
static std::string Base64Encode(const std::vector<unsigned char>& in){
    BIO* b64 = BIO_new(BIO_f_base64());
    BIO* mem = BIO_new(BIO_s_mem());
    BIO_set_flags(b64, BIO_FLAGS_BASE64_NO_NL);
    b64 = BIO_push(b64, mem);
    BIO_write(b64, in.data(), (int)in.size());
    BIO_flush(b64);
    BUF_MEM* bptr = nullptr;
    BIO_get_mem_ptr(b64, &bptr);
    std::string out(bptr->data, bptr->length);
    BIO_free_all(b64);
    return out;
}

static std::vector<unsigned char> Base64Decode(const std::string& in){
    BIO* b64 = BIO_new(BIO_f_base64());
    BIO* mem = BIO_new_mem_buf(in.data(), (int)in.size());
    BIO_set_flags(b64, BIO_FLAGS_BASE64_NO_NL);
    mem = BIO_push(b64, mem);
    std::vector<unsigned char> out(in.size());
    int len = BIO_read(mem, out.data(), (int)out.size());
    if(len < 0) len = 0;
    out.resize((size_t)len);
    BIO_free_all(mem);
    return out;
}

// Crockford/Base32 variant for Tor uses lowercase a-z2-7, no padding. Implement a minimal RFC4648 base32 (lowercase) used by .onion.
static const char* B32_ALPH = "abcdefghijklmnopqrstuvwxyz234567";

static std::string Base32Encode(const std::vector<unsigned char>& data){
    std::string out;
    size_t i=0; unsigned int buffer=0; int bitsLeft=0;
    while(i < data.size()){
        buffer = (buffer << 8) | data[i++];
        bitsLeft += 8;
        while(bitsLeft >= 5){
            out.push_back(B32_ALPH[(buffer >> (bitsLeft - 5)) & 0x1F]);
            bitsLeft -= 5;
        }
    }
    if(bitsLeft > 0){
        out.push_back(B32_ALPH[(buffer << (5 - bitsLeft)) & 0x1F]);
    }
    return out;
}

static std::vector<unsigned char> Base32Decode(const std::string& str){
    auto val = [](char c)->int{
        if(c>='a'&&c<='z') return c-'a';
        if(c>='2'&&c<='7') return 26+(c-'2');
        if(c>='A'&&c<='Z') return c-'A'; // tolerate uppercase
        return -1;
    };
    std::vector<unsigned char> out;
    unsigned int buffer=0; int bitsLeft=0;
    for(char c : str){
        if(c=='='||c==' ') continue;
        int v = val(c);
        if(v<0) continue;
        buffer = (buffer<<5) | (unsigned)v;
        bitsLeft += 5;
        if(bitsLeft >= 8){
            out.push_back((unsigned char)((buffer >> (bitsLeft - 8)) & 0xFF));
            bitsLeft -= 8;
        }
    }
    return out;
}

// WinHTTP simple HTTPS GET/POST utilities
static bool HttpRequest(const std::wstring& host, INTERNET_PORT port, const std::wstring& path,
                        const std::wstring& method,
                        const std::wstring& contentType,
                        const std::string& body,
                        std::string& outResponse, DWORD timeoutMs=30000){
    WinHttpHandle hSession(WinHttpOpen(L"WinHTTP Tor v3 Demo/1.0",
                                       WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                                       WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0));
    if(!hSession) { std::cerr << LastErrorMessage("WinHttpOpen") << "\n"; return false; }

    // Timeouts
    WinHttpSetTimeouts(hSession, timeoutMs, timeoutMs, timeoutMs, timeoutMs);

    DWORD flags = 0; // for HTTPS we will set WINHTTP_FLAG_SECURE at request time
    WinHttpHandle hConnect(WinHttpConnect(hSession, host.c_str(), port, 0));
    if(!hConnect){ std::cerr << LastErrorMessage("WinHttpConnect") << "\n"; return false; }

    WinHttpHandle hRequest(WinHttpOpenRequest(hConnect, method.c_str(), path.c_str(),
                                              NULL, WINHTTP_NO_REFERER,
                                              WINHTTP_DEFAULT_ACCEPT_TYPES,
                                              WINHTTP_FLAG_SECURE));
    if(!hRequest){ std::cerr << LastErrorMessage("WinHttpOpenRequest") << "\n"; return false; }

    // For HTTPS, ignore cert errors only if you know the endpoint. Here we use public HTTPS, so default checks.

    BOOL bResults = FALSE;
    LPCWSTR headers = contentType.empty() ? WINHTTP_NO_ADDITIONAL_HEADERS : contentType.c_str();

    std::vector<unsigned char> bodyBytes(body.begin(), body.end());

    bResults = WinHttpSendRequest(hRequest,
                                  headers,
                                  (DWORD)(contentType.empty()?0:wcslen(headers)),
                                  bodyBytes.empty()?WINHTTP_NO_REQUEST_DATA:(LPVOID)bodyBytes.data(),
                                  (DWORD)bodyBytes.size(),
                                  (DWORD)bodyBytes.size(),
                                  0);
    if(!bResults){ std::cerr << LastErrorMessage("WinHttpSendRequest") << "\n"; return false; }

    bResults = WinHttpReceiveResponse(hRequest, NULL);
    if(!bResults){ std::cerr << LastErrorMessage("WinHttpReceiveResponse") << "\n"; return false; }

    DWORD dwSize = 0;
    outResponse.clear();
    do {
        dwSize = 0;
        if(!WinHttpQueryDataAvailable(hRequest, &dwSize)){
            std::cerr << LastErrorMessage("WinHttpQueryDataAvailable") << "\n"; return false;
        }
        if(dwSize == 0) break;
        std::vector<char> buf(dwSize);
        DWORD dwDownloaded = 0;
        if(!WinHttpReadData(hRequest, buf.data(), dwSize, &dwDownloaded)){
            std::cerr << LastErrorMessage("WinHttpReadData") << "\n"; return false;
        }
        outResponse.append(buf.data(), buf.data()+dwDownloaded);
    } while(dwSize>0);

    return true;
}

// Minimal Tor consensus parsing (dir-spec). We parse rs (router status) lines and flags to find HSDirs.
struct RelayEntry {
    std::string nickname;
    std::string identity_b64; // deprecated field, but present as 20-byte digest base64
    std::string digest_b64;   // descriptor digest
    std::set<std::string> flags;
    std::string a_line;       // address
    std::string or_port;
    bool is_hsdir = false;
};

struct Consensus {
    std::vector<RelayEntry> relays;
};

static Consensus ParseConsensus(const std::string& text){
    Consensus c;
    std::istringstream iss(text);
    std::string line;
    RelayEntry cur;
    bool inRouter = false;
    while(std::getline(iss, line)){
        if(line.rfind("r ", 0) == 0){
            if(inRouter){ c.relays.push_back(cur); cur = RelayEntry(); }
            inRouter = true;
            // r nickname identity digest publication ip orport dirport
            // Fields are space-separated
            std::istringstream ls(line);
            std::string tag; ls >> tag;
            ls >> cur.nickname;
            ls >> cur.identity_b64; // base64 of RSA identity digest (legacy)
            ls >> cur.digest_b64;
            std::string pub1, pub2; ls >> pub1 >> pub2; // publication timestamp parts
            ls >> cur.a_line; // IP
            ls >> cur.or_port; // ORPort
            std::string dirport; ls >> dirport; (void)dirport;
        } else if(line.rfind("s ", 0) == 0 && inRouter){
            std::istringstream ls(line);
            std::string tag; ls >> tag;
            std::string flag;
            while(ls >> flag){ cur.flags.insert(flag); }
            if(cur.flags.count("HSDir")) cur.is_hsdir = true;
        } else if(line.rfind("r ", 0) != 0 && inRouter && (line.empty() || line[0] == 'r')){
            // If a new router starts, handled above. If empty, push current.
        }
    }
    if(inRouter){ c.relays.push_back(cur); }
    return c;
}

// Hidden service descriptor minimal parser (prop 224). We look for onion-service-descriptor
// and introduction-points sections. This is a textual, base64-encoded document.
struct HSDescriptorV3 {
    std::string blinded_pubkey_b64; // from descriptor
    std::string signature_b64;      // signature over descriptor
    std::string intro_points_b64;   // enc/cleartext depending on auth; here we expect clear for demo
};

static HSDescriptorV3 ParseHSDescriptor(const std::string& text){
    HSDescriptorV3 d;
    std::istringstream iss(text);
    std::string line;
    bool in_desc = false;
    bool in_sig = false;
    bool in_intro = false;
    std::string desc_b64, sig_b64, intro_b64;

    while(std::getline(iss, line)){
        if(line.find("onion-service-descriptor") != std::string::npos){ in_desc = true; continue; }
        if(in_desc){
            if(line.find("-----END ONION SERVICE DESCRIPTOR-----") != std::string::npos){ in_desc = false; }
            else desc_b64 += line; continue;
        }
        if(line.find("signature") != std::string::npos){ in_sig = true; continue; }
        if(in_sig){
            if(line.find("-----END SIGNATURE-----") != std::string::npos){ in_sig = false; }
            else sig_b64 += line; continue;
        }
        if(line.find("introduction-points") != std::string::npos){ in_intro = true; continue; }
        if(in_intro){
            if(line.find("-----END INTRODUCTION POINTS-----") != std::string::npos){ in_intro = false; }
            else intro_b64 += line; continue;
        }
    }

    d.blinded_pubkey_b64 = desc_b64; // For demo we store the raw block; proper parser would decode structure
    d.signature_b64 = sig_b64;
    d.intro_points_b64 = intro_b64;
    return d;
}

// Minimal helper to compute v3 onion public key bytes from hostname (base32). v3 .onion = base32(pubkey|checksum|version)
// This returns the 32-byte ed25519 pubkey (first 32 bytes after base32-decode) if the address is valid length (56 chars + .onion)
static std::optional<std::vector<unsigned char>> OnionV3PubkeyFromHostname(const std::string& onion){
    std::string h = onion;
    if(h.size() > 6 && h.substr(h.size()-6) == ".onion") h = h.substr(0, h.size()-6);
    if(h.size() != 56) return std::nullopt;
    auto raw = Base32Decode(h);
    if(raw.size() < 32) return std::nullopt;
    std::vector<unsigned char> pk(raw.begin(), raw.begin()+32);
    return pk;
}

// Fetch Tor consensus from a directory mirror over HTTPS.
static bool FetchConsensus(std::string& consensusOut){
    // A publicly accessible directory mirror (example). Path per dir-spec: /tor/status-vote/current/consensus
    // You may replace with any running Tor directory mirror over HTTPS.
    const std::wstring host = L"collector.torproject.org";
    const INTERNET_PORT port = INTERNET_DEFAULT_HTTPS_PORT;
    const std::wstring path = L"/tor/status-vote/current/consensus";

    std::string resp;
    if(!HttpRequest(host, port, path, L"GET", L"", "", resp)) return false;

    if(resp.find("network-status-version 3") == std::string::npos){
        std::cerr << "Downloaded document does not look like a v3 consensus" << std::endl;
        return false;
    }
    consensusOut = resp;
    return true;
}

// Pick an HSDir from consensus (just the first few for demo)
static std::optional<RelayEntry> PickHSDir(const Consensus& c){
    for(const auto& r : c.relays){
        if(r.is_hsdir) return r;
    }
    return std::nullopt;
}

// Compute HSv3 descriptor ID positions per prop224 requires blinded key and time period; here we demonstrate a simplified
// HSDir query using the client authless descriptor path at: /tor/hs/3/<descriptor-id>. This demo uses a gateway path
// commonly supported by HSDirs via the directory protocol (requires correct descriptor-id). We provide a best-effort
// placeholder by querying known directory endpoint that proxies descriptor lookup for demonstration only.

// For a real implementation you must compute descriptor IDs:
