// As WinHTTP cannot establish Tor circuits, we demonstrate GET/POST using a public onion gateway (e.g., https://onion.pet or https://onion.ws variants).
// This is ONLY to show WinHTTP request mechanics with a .onion hostname in the path at a gateway. Privacy is not preserved.
static bool GatewayGET(const std::string& onionHost, const std::string& resourcePath, std::string& out){
    const std::wstring host = L"onion.pet"; // example gateway domain; availability varies
    const INTERNET_PORT port = INTERNET_DEFAULT_HTTPS_PORT;
    std::wstring path = L"/http://" + std::wstring(onionHost.begin(), onionHost.end()) + std::wstring(resourcePath.begin(), resourcePath.end());
    return HttpRequest(host, port, path, L"GET", L"", "", out);
}

static bool GatewayPOST(const std::string& onionHost, const std::string& resourcePath, const std::string& jsonBody, std::string& out){
    const std::wstring host = L"onion.pet";
    const INTERNET_PORT port = INTERNET_DEFAULT_HTTPS_PORT;
    std::wstring path = L"/http://" + std::wstring(onionHost.begin(), onionHost.end()) + std::wstring(resourcePath.begin(), resourcePath.end());
    return HttpRequest(host, port, path, L"POST", L"Content-Type: application/json\r\n", jsonBody, out);
}

// Optional: verify an ed25519 signature (placeholder). For full verification, extract the correct message and key from descriptor.
static bool VerifyEd25519(const std::vector<unsigned char>& msg, const std::vector<unsigned char>& sig, const std::vector<unsigned char>& pub){
    if(pub.size()!=32 || sig.size()!=64) return false;
    int ok = ED25519_verify(msg.data(), msg.size(), sig.data(), pub.data());
