// -------------------- HTTP helpers (WinHTTP) --------------------
static bool ParseUrl(const std::wstring& url, std::wstring& scheme, std::wstring& host, INTERNET_PORT& port, std::wstring& path) {
    URL_COMPONENTS uc{}; uc.dwStructSize = sizeof(uc);
    wchar_t hostBuf[512] = {0};
    wchar_t pathBuf[2048] = {0};
    uc.lpszHostName = hostBuf; uc.dwHostNameLength = _countof(hostBuf);
    uc.lpszUrlPath  = pathBuf; uc.dwUrlPathLength  = _countof(pathBuf);
    if (!WinHttpCrackUrl(url.c_str(), (DWORD)url.size(), 0, &uc)) return false;
    scheme = (uc.nScheme == INTERNET_SCHEME_HTTPS) ? L"https" : L"http";
    host.assign(uc.lpszHostName, uc.dwHostNameLength);
    port = uc.nPort ? uc.nPort : (uc.nScheme == INTERNET_SCHEME_HTTPS ? 443 : 80);
    path.assign(uc.lpszUrlPath, uc.dwUrlPathLength);
    if (path.empty()) path = L"/";
    return true;
}

static bool HttpRequest(const std::wstring& method, const std::wstring& url, const std::wstring& headers, const std::string& body, std::string& out_body, DWORD timeout_ms = 30000) {
    out_body.clear();
    std::wstring scheme, host, path; INTERNET_PORT port = 0;
    if (!ParseUrl(url, scheme, host, port, path)) {
        std::wcerr << L"Invalid URL: " << url << L"\n";
        return false;
    }
    bool https = (scheme == L"https");

    WinHttpHandle hSession(WinHttpOpen(L"WinHTTP Tor Client/1.0", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY, WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0));
    if (!hSession) { std::wcerr << L"WinHttpOpen failed: " << FormatLastError() << L"\n"; return false; }

    // Timeouts
    WinHttpSetTimeouts(hSession, timeout_ms, timeout_ms, timeout_ms, timeout_ms);

    WinHttpHandle hConnect(WinHttpConnect(hSession, host.c_str(), port, 0));
    if (!hConnect) { std::wcerr << L"WinHttpConnect failed: " << FormatLastError() << L"\n"; return false; }

    DWORD flags = https ? WINHTTP_FLAG_SECURE : 0;
    WinHttpHandle hRequest(WinHttpOpenRequest(hConnect, method.c_str(), path.c_str(), nullptr, WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, flags));
    if (!hRequest) { std::wcerr << L"WinHttpOpenRequest failed: " << FormatLastError() << L"\n"; return false; }

    // Security options for HTTPS
    if (https) {
        DWORD secFlags = SECURITY_FLAG_IGNORE_UNKNOWN_CA | SECURITY_FLAG_IGNORE_CERT_CN_INVALID | SECURITY_FLAG_IGNORE_CERT_DATE_INVALID | SECURITY_FLAG_IGNORE_WRONG_USAGE;
        WinHttpSetOption(hRequest, WINHTTP_OPTION_SECURITY_FLAGS, &secFlags, sizeof(secFlags));
    }

    // Send request
    BOOL ok = WinHttpSendRequest(hRequest,
                                 headers.empty() ? WINHTTP_NO_ADDITIONAL_HEADERS : headers.c_str(),
                                 headers.empty() ? 0 : (DWORD)-1L,
                                 body.empty() ? WINHTTP_NO_REQUEST_DATA : (LPVOID)body.data(),
                                 (DWORD)body.size(),
                                 (DWORD)body.size(),
                                 0);
    if (!ok) { std::wcerr << L"WinHttpSendRequest failed: " << FormatLastError() << L"\n"; return false; }

    ok = WinHttpReceiveResponse(hRequest, nullptr);
    if (!ok) { std::wcerr << L"WinHttpReceiveResponse failed: " << FormatLastError() << L"\n"; return false; }

    DWORD status = 0; DWORD len = sizeof(status);
    WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER, WINHTTP_HEADER_NAME_BY_INDEX, &status, &len, WINHTTP_NO_HEADER_INDEX);

    std::string buf; buf.reserve(16 * 1024);
    for (;;) {
        DWORD avail = 0;
        if (!WinHttpQueryDataAvailable(hRequest, &avail)) {
            std::wcerr << L"WinHttpQueryDataAvailable failed: " << FormatLastError() << L"\n";
            return false;
        }
        if (avail == 0) break;
        std::vector<char> tmp(avail);
        DWORD read = 0;
        if (!WinHttpReadData(hRequest, tmp.data(), avail, &read)) {
            std::wcerr << L"WinHttpReadData failed: " << FormatLastError() << L"\n";
            return false;
        }
        buf.append(tmp.data(), tmp.data() + read);
    }
    out_body.swap(buf);

    if (status >= 400) {
        std::wcerr << L"HTTP error status: " << status << L"\n";
        return false;
    }
    return true;
}

static bool HttpGet(const std::wstring& url, std::string& out_body, DWORD timeout_ms = 30000) {
    return HttpRequest(L"GET", url, L"", "", out_body, timeout_ms);
}

static bool HttpPost(const std::wstring& url, const std::string& data, std::string& out_body, const std::wstring& contentType = L"application/x-www-form-urlencoded", DWORD timeout_ms = 30000) {
    std::wstringstream hs; hs << L"Content-Type: " << contentType << L"\r\n";
    return HttpRequest(L"POST", url, hs.str(), data, out_body, timeout_ms);
}

// -------------------- Tor consensus parsing (plaintext) --------------------
struct RelayInfo {
    std::string nickname;
    std::string fingerprint;
    std::string address;
    int or_port = 0;
    int dir_port = 0;
};

struct ConsensusSummary {
    std::string valid_after;
    std::string fresh_until;
    std::string valid_until;
    std::vector<RelayInfo> relays;
};

static ConsensusSummary ParseConsensus(const std::string& text) {
    ConsensusSummary cs;
    std::istringstream iss(text);
    std::string line;
    RelayInfo current;
    while (std::getline(iss, line)) {
        if (line.rfind("valid-after ", 0) == 0) cs.valid_after = line.substr(12);
        else if (line.rfind("fresh-until ", 0) == 0) cs.fresh_until = line.substr(12);
        else if (line.rfind("valid-until ", 0) == 0) cs.valid_until = line.substr(12);
        else if (line.rfind("r ", 0) == 0) {
            if (!current.nickname.empty()) cs.relays.push_back(current);
            current = RelayInfo{};
            // r nickname identity digest publication addr orport dirport
            std::istringstream rs(line);
            std::string tag; rs >> tag; // r
            rs >> current.nickname;
            std::string identity_b64, digest_b64, pub, addr; int orp=0, dirp=0;
            rs >> identity_b64 >> digest_b64 >> pub >> addr >> orp >> dirp;
            current.address = addr; current.or_port = orp; current.dir_port = dirp;
        } else if (line.rfind("s ", 0) == 0) {
            // flags line; ignore for this summary
        } else if (line.rfind("f ", 0) == 0) {
            // fingerprint line may appear in microdescs; skip here
        }
    }
    if (!current.nickname.empty()) cs.relays.push_back(current);
    return cs;
}

// -------------------- Tor v3 descriptor parsing (plaintext) --------------------
struct HSDescriptorV3 {
    std::string desc_sig_alg;
    std::string hs_public_key_b64;
    std::string intro_blinded_pub_b64;
    std::vector<std::string> intro_points_raw; // base64 blocks or lines
};

static HSDescriptorV3 ParseHSDescriptorV3(const std::string& text) {
    HSDescriptorV3 d;
    std::istringstream iss(text);
    std::string line;
    bool in_intro_points = false;
    std::ostringstream intro_accum;

    while (std::getline(iss, line)) {
        if (line.rfind("hs-descriptor 3", 0) == 0) {
            // marker
        } else if (line.rfind("descriptor-signing-key-cert", 0) == 0) {
            // skip cert block lines until END marker if present
        } else if (line.rfind("descriptor-signature ", 0) == 0) {
            d.desc_sig_alg = line.substr(std::string("descriptor-signature ").size());
        } else if (line.rfind("hs-addr ", 0) == 0) {
            // onion address
        } else if (line.rfind("create2-formats ", 0) == 0) {
            // ignore
        } else if (line.rfind("intro-auth-required ", 0) == 0) {
            // ignore
        } else if (line.rfind("hs-ntor-onion-key ", 0) == 0) {
            d.hs_public_key_b64 = line.substr(std::string("hs-ntor-onion-key ").size());
        } else if (line.rfind("intro-blinded-key ", 0) == 0) {
            d.intro_blinded_pub_b64 = line.substr(std::string("intro-blinded-key ").size());
        } else if (line.rfind("introduction-points", 0) == 0) {
            in_intro_points = true;
            intro_accum.str(""); intro_accum.clear();
        } else if (in_intro_points && line.rfind("-----END MESSAGE-----", 0) == 0) {
            in_intro_points = false;
            d.intro_points_raw.push_back(intro_accum.str());
        } else if (in_intro_points) {
            if (!line.empty()) intro_accum << line << "\n";
        }
    }
    return d;
}

// -------------------- High-level actions --------------------
static bool DownloadConsensus(const std::wstring& url, ConsensusSummary& out) {
    std::string body;
    if (!HttpGet(url, body)) return false;
    out = ParseConsensus(body);
    return true;
}

static bool DownloadHSDescriptor(const std::wstring& url, HSDescriptorV3& out) {
    std::string body;
    if (!HttpGet(url, body)) return false;
    out = ParseHSDescriptorV3(body);
    return true;
}

// -------------------- Demo GET/POST including .onion host strings --------------------
static void DemoHttp(const std::wstring& get_url, const std::wstring& post_url) {
    if (!get_url.empty()) {
        std::string body;
        std::wcout << L"GET: " << get_url << L"\n";
        bool ok = HttpGet(get_url, body);
        std::wcout << L"GET status: " << (ok ? L"OK" : L"FAIL") << L", bytes: " << (int)body.size() << L"\n";
        if (!ok) std::wcout << L"(GET failed; likely DNS/transport issues for .onion without Tor)\n";
    }
    if (!post_url.empty()) {
        std::string body, resp;
        body = "name=value&x=y";
        std::wcout << L"POST: " << post_url << L"\n";
        bool ok = HttpPost(post_url, body, resp);
        std::wcout << L"POST status: " << (ok ? L"OK" : L"FAIL") << L", bytes: " << (int)resp.size() << L"\n";
        if (!ok) std::wcout << L"(POST failed; likely DNS/transport issues for .onion without Tor)\n";
    }
}

// -------------------- Pretty printers --------------------
static void PrintConsensusSummary(const ConsensusSummary& cs) {
    std::cout << "Consensus valid-after: " << cs.valid_after << "\n";
    std::cout << "Consensus fresh-until: " << cs.fresh_until << "\n";
    std::cout << "Consensus valid-until: " << cs.valid_until << "\n";
    std::cout << "Relays parsed: " << cs.relays.size() << "\n";
    for (size_t i = 0; i < std::min<size_t>(cs.relays.size(), 5); ++i) {
        const auto& r = cs.relays[i];
        std::cout << "  [" << i << "] " << r.nickname << " " << r.address << ":" << r.or_port << " dir:" << r.dir_port << "\n";
    }
}

static void PrintHSDescriptor(const HSDescriptorV3& d) {
    std::cout << "Descriptor sig alg: " << d.desc_sig_alg << "\n";
    std::cout << "HS ntor key (b64, len): " << d.hs_public_key_b64.size() << "\n";
    std::cout << "Blinded key (b64, len): " << d.intro_blinded_pub_b64.size() << "\n";
    std::cout << "Introduction points blocks: " << d.intro_points_raw.size() << "\n";
}

// -------------------- Main --------------------
int wmain(int argc, wchar_t** argv) {
    std::wstring consensus_url;
    std::wstring hsdesc_url;
    std::wstring get_url;
    std::wstring post_url;

    for (int i = 1; i < argc; ++i) {
        std::wstring arg = argv[i];
        if (arg == L"--consensus-url" && i + 1 < argc) { consensus_url = argv[++i]; }
        else if (arg == L"--descriptor-url" && i + 1 < argc) { hsdesc_url = argv[++i]; }
        else if (arg == L"--get" && i + 1 < argc) { get_url = argv[++i]; }
        else if (arg == L"--post" && i + 1 < argc) { post_url = argv[++i]; }
        else {
            std::wcout << L"Usage: \n"
                          L"  --consensus-url <https-url-to-consensus>\n"
                          L"  --descriptor-url <https-url-to-hs-descriptor>\n"
                          L"  --get <url>\n"
                          L"  --post <url>\n";
            return 1;
        }
    }

    if (!consensus_url.empty()) {
        ConsensusSummary cs;
        if (DownloadConsensus(consensus_url, cs)) {
            PrintConsensusSummary(cs);
        } else {
            std::wcerr << L"Failed to download/parse consensus from: " << consensus_url << L"\n";
        }
    }

    if (!hsdesc_url.empty()) {
        HSDescriptorV3 d;
        if (DownloadHSDescriptor(hsdesc_url, d)) {
            PrintHSDescriptor(d);
            // Attempt to decode some keys to bytes using OpenSSL base64
            if (!d.hs_public_key_b64.empty()) {
                auto key = Base64Decode(d.hs_public_key_b64);
                std::cout << "Decoded hs-ntor-onion-key bytes: " << key.size() << "\n";
            }
            if (!d.intro_blinded_pub_b64.empty()) {
                auto key = Base64Decode(d.intro_blinded_pub_b64);
                std::cout << "Decoded intro-blinded-key bytes: " << key.size() << "\n";
            }
        } else {
            std::wcerr << L"Failed to download/parse hs descriptor from: " << hsdesc_url << L"\n";
        }
    }

    if (!get_url.empty() || !post_url.empty()) {
        DemoHttp(get_url, post_url);
    }

    return 0;
}

// Single-file C++ program (Windows) that:
//
// - Uses WinHTTP for HTTPS GET/POST with robust error handling.
// - Downloads a Tor consensus document from a provided HTTPS URL and parses key fields.
// - Downloads a Tor v3 hidden service descriptor from a provided HTTPS URL and parses key fields.
// - Validates and decodes a v3 .onion address (base32 -> pubkey/checksum/version) using OpenSSL SHA3-256.
// - Demonstrates OpenSSL initialization and digest usage.
//
// Build example:
//   cl /std:c++17 /O2 /EHsc tor_client.cpp winhttp.lib crypt32.lib ws2_32.lib
//   (also ensure OpenSSL libs are linked: libcrypto, libssl as appropriate on your setup)

#define UNICODE
#define _UNICODE
