// -------------------- UTF-8/UTF-16 helpers --------------------
static std::wstring Utf8ToWide(const std::string& s){ if(s.empty()) return L""; int n=MultiByteToWideChar(CP_UTF8,0,s.c_str(),(int)s.size(),nullptr,0); std::wstring w(n,0); MultiByteToWideChar(CP_UTF8,0,s.c_str(),(int)s.size(),&w[0],n); return w; }
static std::string WideToUtf8(const std::wstring& w){ if(w.empty()) return ""; int n=WideCharToMultiByte(CP_UTF8,0,w.c_str(),(int)w.size(),nullptr,0,nullptr,nullptr); std::string s(n,0); WideCharToMultiByte(CP_UTF8,0,w.c_str(),(int)w.size(),&s[0],n,nullptr,nullptr); return s; }

// -------------------- Error helpers --------------------
static std::string LastErrorMessage(DWORD err){ LPWSTR buf=nullptr; DWORD n=FormatMessageW(FORMAT_MESSAGE_ALLOCATE_BUFFER|FORMAT_MESSAGE_FROM_SYSTEM|FORMAT_MESSAGE_IGNORE_INSERTS,nullptr,err,MAKELANGID(LANG_NEUTRAL,SUBLANG_DEFAULT),(LPWSTR)&buf,0,nullptr); std::wstring w = (n? std::wstring(buf, n): L"Unknown error"); if(buf) LocalFree(buf); std::string s=WideToUtf8(w); while(!s.empty() && (s.back()=='\r'||s.back()=='\n')) s.pop_back(); return s; }
static void PrintWinHttpError(const char* where){ DWORD err=GetLastError(); std::cerr<<where<<" failed ("<<err<<"): "<<LastErrorMessage(err)<<"\n"; }

// -------------------- OpenSSL init --------------------
struct OpenSSLInit { OpenSSLInit(){ OPENSSL_init_ssl(0,nullptr); OpenSSL_add_all_algorithms(); ERR_load_crypto_strings(); } ~OpenSSLInit(){ EVP_cleanup(); ERR_free_strings(); }};

// -------------------- Base32 (RFC4648, lowercase for onion) --------------------
static bool Base32DecodeLower(const std::string& in, std::vector<uint8_t>& out){ static const int8_t map[256]=[]{ int8_t t[256]; std::fill(std::begin(t),std::end(t),-1); const char* a="abcdefghijklmnopqrstuvwxyz234567"; for(int i=0;i<32;i++) t[(unsigned char)a[i]]=i; for(int i='A';i<='Z';++i) t[i]=t[i+('a'-'A')]; return *reinterpret_cast<int8_t(*)[256]>(t); }(); int bits=0; int val=0; out.clear(); for(unsigned char c: in){ if(c=='='||c=='-'||c==' ') continue; int8_t v = map[c]; if(v<0) return false; val=(val<<5)|v; bits+=5; if(bits>=8){ bits-=8; out.push_back((uint8_t)((val>>bits)&0xFF)); } } if(bits>0){ if((val & ((1<<bits)-1))!=0) return false; } return true; }

// -------------------- WinHTTP client --------------------
class WinHttpClient{
public:
    WinHttpClient(){ session_=WinHttpOpen(L"TorHSClient/1.0", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY, WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0); }
    ~WinHttpClient(){ if(session_) WinHttpCloseHandle(session_); }

    bool Get(const std::wstring& url, std::vector<uint8_t>& body, std::map<std::string,std::string>* respHeaders=nullptr){ return Request(L"GET", url, std::string(), body, respHeaders); }
    bool Post(const std::wstring& url, const std::string& payload, std::vector<uint8_t>& body, std::map<std::string,std::string>* respHeaders=nullptr){ return Request(L"POST", url, payload, body, respHeaders); }

private:
    static bool ParseUrl(const std::wstring& url, std::wstring& host, INTERNET_PORT& port, std::wstring& path, BOOL& secure){ URL_COMPONENTS uc{}; uc.dwStructSize=sizeof(uc); wchar_t hostBuf[256]; wchar_t pathBuf[2048]; uc.lpszHostName=hostBuf; uc.dwHostNameLength=_countof(hostBuf); uc.lpszUrlPath=pathBuf; uc.dwUrlPathLength=_countof(pathBuf); if(!WinHttpCrackUrl(url.c_str(), (DWORD)url.size(), 0, &uc)) return false; host.assign(uc.lpszHostName, uc.dwHostNameLength); path.assign(uc.lpszUrlPath, uc.dwUrlPathLength); port=uc.nPort; secure=(uc.nScheme==INTERNET_SCHEME_HTTPS); if(path.empty()) path=L"/"; return true; }

    bool Request(const std::wstring& method, const std::wstring& url, const std::string& payload, std::vector<uint8_t>& body, std::map<std::string,std::string>* respHeaders){ body.clear(); std::wstring host,path; INTERNET_PORT port=0; BOOL secure=FALSE; if(!ParseUrl(url,host,port,path,secure)){ std::cerr<<"Invalid URL: "<<WideToUtf8(url)<<"\n"; return false; }
        HINTERNET connect=nullptr, request=nullptr; bool ok=false; DWORD flags = secure? WINHTTP_FLAG_SECURE: 0;
        connect = WinHttpConnect(session_, host.c_str(), port?port:(secure?443:80), 0);
        if(!connect){ PrintWinHttpError("WinHttpConnect"); goto cleanup; }
        request = WinHttpOpenRequest(connect, method.c_str(), path.c_str(), nullptr, WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, flags);
        if(!request){ PrintWinHttpError("WinHttpOpenRequest"); goto cleanup; }
        if(secure){ DWORD opt = SECURITY_FLAG_IGNORE_UNKNOWN_CA; WinHttpSetOption(request, WINHTTP_OPTION_SECURITY_FLAGS, &opt, sizeof(opt)); }
        if(!WinHttpSendRequest(request, WINHTTP_NO_ADDITIONAL_HEADERS, 0, payload.empty()? WINHTTP_NO_REQUEST_DATA : (LPVOID)payload.data(), (DWORD)payload.size(), (DWORD)payload.size(), 0)) { PrintWinHttpError("WinHttpSendRequest"); goto cleanup; }
        if(!WinHttpReceiveResponse(request, nullptr)){ PrintWinHttpError("WinHttpReceiveResponse"); goto cleanup; }
        if(respHeaders){ DWORD sz=0; WinHttpQueryHeaders(request, WINHTTP_QUERY_RAW_HEADERS_CRLF, WINHTTP_HEADER_NAME_BY_INDEX, WINHTTP_NO_OUTPUT_BUFFER, &sz, WINHTTP_NO_HEADER_INDEX); if(GetLastError()==ERROR_INSUFFICIENT_BUFFER){ std::wstring hdrs; hdrs.resize(sz/sizeof(wchar_t)); if(WinHttpQueryHeaders(request, WINHTTP_QUERY_RAW_HEADERS_CRLF, WINHTTP_HEADER_NAME_BY_INDEX, &hdrs[0], &sz, WINHTTP_NO_HEADER_INDEX)){ std::string h = WideToUtf8(hdrs); std::istringstream iss(h); std::string line; while(std::getline(iss,line)){ auto p=line.find(':'); if(p!=std::string::npos){ std::string k=line.substr(0,p); std::string v=line.substr(p+1); while(!v.empty() && (v.front()==' '||v.front()=='\t')) v.erase(v.begin()); while(!v.empty() && (v.back()=='\r'||v.back()=='\n')) v.pop_back(); (*respHeaders)[k]=v; } } } } }
        for(;;){ DWORD avail=0; if(!WinHttpQueryDataAvailable(request,&avail)){ PrintWinHttpError("WinHttpQueryDataAvailable"); goto cleanup; } if(avail==0) break; size_t off=body.size(); body.resize(off+avail); DWORD read=0; if(!WinHttpReadData(request, body.data()+off, avail, &read)){ PrintWinHttpError("WinHttpReadData"); goto cleanup; } if(read<avail) body.resize(off+read); }
        ok=true;
    cleanup:
        if(request) WinHttpCloseHandle(request);
        if(connect) WinHttpCloseHandle(connect);
        return ok; }

    HINTERNET session_{};
};

// -------------------- Minimal Tor consensus parsing --------------------
struct Relay{ std::string fingerprint; std::string nickname; std::vector<std::string> flags; std::string address; int or_port=0; };

static std::vector<Relay> ParseConsensus(const std::string& txt){ std::vector<Relay> out; std::istringstream ss(txt); std::string line; Relay cur; bool inRouter=false; while(std::getline(ss,line)){
        if(line.size()>0 && (line.back()=='\r')) line.pop_back();
        if(line.rfind("r ",0)==0){ if(inRouter){ out.push_back(cur); cur=Relay(); }
            inRouter=true; std::istringstream ls(line); std::string tag; ls>>tag>>cur.nickname; std::string id; ls>>id; cur.fingerprint=id; int y,m,d,hh,mm,ss2; ls>>y>>m>>d>>hh>>mm>>ss2; ls>>cur.address>>cur.or_port; }
        else if(line.rfind("s ",0)==0 && inRouter){ std::istringstream ls(line); std::string tag; ls>>tag; std::string flag; cur.flags.clear(); while(ls>>flag) cur.flags.push_back(flag); }
        else if(line.size()>0 && line[0]=='r' && !inRouter){ /* skip header */ }
        else if(line.size()>0 && line[0]=='\n'){ }
        else if(line.rfind("directory-footer",0)==0){ if(inRouter){ out.push_back(cur); } break; }
    }
    if(inRouter){ out.push_back(cur); }
    return out; }

// -------------------- Hidden service descriptor (v3) minimal parsing --------------------
struct HSDescriptor{
    std::string hs_intro_point_b64; // first intro point line (for demo)
    std::vector<std::string> intro_points_b64;
    std::map<std::string,std::string> fields;
};

static HSDescriptor ParseHSDescriptor(const std::string& txt){ HSDescriptor d; std::istringstream ss(txt); std::string line; while(std::getline(ss,line)){
        if(!line.empty() && line.back()=='\r') line.pop_back();
        if(line.rfind("introduction-point ",0)==0){ std::string tag,b64; std::istringstream ls(line); ls>>tag>>b64; d.intro_points_b64.push_back(b64); if(d.hs_intro_point_b64.empty()) d.hs_intro_point_b64=b64; }
        else if(!line.empty() && line[0]!='#'){
            auto p=line.find(' '); if(p!=std::string::npos){ std::string k=line.substr(0,p); std::string v=line.substr(p+1); d.fields[k]=v; }
        }
    }
    return d; }

// -------------------- .onion v3 address validation --------------------
static bool DecodeOnionV3(const std::string& onionHost, std::array<uint8_t,32>& pubkey){ std::string h=onionHost; if(h.size()>6 && h.rfind(".onion")==(h.size()-6)) h=h.substr(0,h.size()-6); std::transform(h.begin(),h.end(),h.begin(),[](unsigned char c){ return (char)std::tolower(c); }); if(h.size()!=56) return false; std::vector<uint8_t> dec; if(!Base32DecodeLower(h,dec)) return false; if(dec.size()!=35) return false; std::copy(dec.begin(), dec.begin()+32, pubkey.begin()); uint8_t ver = dec[34]; if(ver!=3) return false; // checksum not verified here
    return true; }

// -------------------- Utility: print hex --------------------
static std::string Hex(const uint8_t* d, size_t n){ std::ostringstream o; o<<std::hex<<std::setfill('0'); for(size_t i=0;i<n;i++) o<<std::setw(2)<<(int)d[i]; return o.str(); }

// -------------------- High-level operations --------------------
static bool DownloadText(WinHttpClient& http, const std::string& url, std::string& out){ std::vector<uint8_t> body; if(!http.Get(Utf8ToWide(url), body)) return false; out.assign((const char*)body.data(), body.size()); return true; }

static bool DownloadConsensus(WinHttpClient& http, const std::string& url, std::vector<Relay>& relays){ std::string txt; if(!DownloadText(http,url,txt)) return false; relays = ParseConsensus(txt); return true; }

static bool DownloadHSDescriptor(WinHttpClient& http, const std::string& url, HSDescriptor& d){ std::string txt; if(!DownloadText(http,url,txt)) return false; d = ParseHSDescriptor(txt); return true; }

// -------------------- GET/POST to .onion over HTTPS name (requires resolver/proxy) --------------------
static bool OnionHttpGet(WinHttpClient& http, const std::string& onionUrl, std::string& response){ std::vector<uint8_t> body; std::map<std::string,std::string> hdrs; if(!http.Get(Utf8ToWide(onionUrl), body, &hdrs)) return false; response.assign((const char*)body.data(), body.size()); return true; }
static bool OnionHttpPost(WinHttpClient& http, const std::string& onionUrl, const std::string& data, std::string& response){ std::vector<uint8_t> body; std::map<std::string,std::string> hdrs; if(!http.Post(Utf8ToWide(onionUrl), data, body, &hdrs)) return false; response.assign((const char*)body.data(), body.size()); return true; }

