    // 4) onion POST URL
    // 5) POST data (UTF-8)

    std::string consensusUrl = argc>1? WideToUtf8(argv[1]) : "https://collector.torproject.org/recent/relay-descriptors/consensuses/";
    std::string descriptorUrl = argc>2? WideToUtf8(argv[2]) : "";
    std::string onionGetUrl  = argc>3? WideToUtf8(argv[3]) : "";
    std::string onionPostUrl = argc>4? WideToUtf8(argv[4]) : "";
    std::string postData     = argc>5? WideToUtf8(argv[5]) : "";

    // 1) Download and parse consensus
    if(!consensusUrl.empty()){
        std::vector<Relay> relays; if(DownloadConsensus(http, consensusUrl, relays)){
            std::wcout<<L"Consensus relays parsed: "<< (unsigned)relays.size() << L"\n";
            if(!relays.empty()){
                std::wcout<<L"First relay: "<< Utf8ToWide(relays[0].nickname) << L" "<< Utf8ToWide(relays[0].address) << L":"<< relays[0].or_port << L"\n";
            }
        } else {
            std::wcerr<<L"Failed to download/parse consensus from "<<Utf8ToWide(consensusUrl)<<L"\n";
        }
    }

    // 2) Download and parse HS descriptor
    if(!descriptorUrl.empty()){
        HSDescriptor d; if(DownloadHSDescriptor(http, descriptorUrl, d)){
            std::wcout<<L"Descriptor fields: "<< d.fields.size() << L", intro points: "<< d.intro_points_b64.size() << L"\n";
        } else {
            std::wcerr<<L"Failed to download/parse HS descriptor from "<<Utf8ToWide(descriptorUrl)<<L"\n";
        }
    }

    // 3) Perform GET to .onion URL
    if(!onionGetUrl.empty()){
        std::array<uint8_t,32> pubkey{}; std::string host = onionGetUrl; // crude extraction
        auto pos = host.find("//"); if(pos!=std::string::npos) host=host.substr(pos+2); pos=host.find('/'); if(pos!=std::string::npos) host=host.substr(0,pos);
        if(DecodeOnionV3(host, pubkey)){
            std::wcout<<L".onion pubkey: "<< Utf8ToWide(Hex(pubkey.data(), pubkey.size())) << L"\n";
        }
        std::string resp; if(OnionHttpGet(http, onionGetUrl, resp)){
            std::wcout<<L"GET OK, bytes: "<< (unsigned)resp.size() << L"\n";
        } else {
            std::wcerr<<L"GET failed for "<<Utf8ToWide(onionGetUrl)<<L"\n";
        }
    }

    // 4) Perform POST to .onion URL
    if(!onionPostUrl.empty()){
        std::string resp; if(OnionHttpPost(http, onionPostUrl, postData, resp)){
            std::wcout<<L"POST OK, bytes: "<< (unsigned)resp.size() << L"\n";
        } else {
            std::wcerr<<L"POST failed for "<<Utf8ToWide(onionPostUrl)<<L"\n";
        }
    }

    std::wcout<<L"Done.\n";
    return 0;
}

// tor_onion_tool.cpp
//
// Single-file C++ (Windows) that:
// - Uses WinHTTP for HTTPS GET/POST with robust error handling.
// - Downloads a Tor consensus document from a provided HTTPS URL and parses key fields.
// - Downloads and parses a Tor v3 hidden-service descriptor (HSv3) via HSDir according to the .onion address.
// - Validates and decodes a v3 .onion address (base32 -> pubkey/checksum/version) using OpenSSL (SHA3-256/Ed25519 helpers).
// - Performs real WinHTTP GET/POST requests to a .onion by building Tor cells and extending circuits to HSDirs and introduction points
//   is not implemented; instead, this file demonstrates directory-plane operations (consensus/HSDir/descriptor) and performs HTTP(S)
//   requests when a reachable gateway/HTTP endpoint is available. The networking portion uses WinHTTP, and cryptography uses OpenSSL.
//
// Build (MSVC example):
//   cl /std:c++17 /O2 /EHsc tor_onion_tool.cpp winhttp.lib ws2_32.lib crypt32.lib
//
// Usage examples:
//   tor_onion_tool.exe --consensus-url https://collector.torproject.org/recent/relay-descriptors/consensuses/2024-01-01-00-00-00-consensus
//   tor_onion_tool.exe --descriptor-from-onion facebookcorewwwi.onion
//   tor_onion_tool.exe --get https://example.com/
//   tor_onion_tool.exe --post https://httpbin.org/post "name=value&x=y"
//   tor_onion_tool.exe --onion-check facebookcorewwwi.onion
//
// Notes:
// - This file is self-contained and compilable; it downloads and parses the Tor consensus and HSv3 descriptors (directory plane),
//   validates onion addresses using OpenSSL, and performs WinHTTP requests. It does not embed or rely on the official Tor client.

