                linePositions[i] = new Vector3(pt.x, pt.y, 0f);
            }

            // Place dot UI element on target canvas
            if (i < _dots.Count && _dots[i] != null && _canvasRect != null)
            {
                Vector2 canvasPos;
                RectTransformUtility.ScreenPointToLocalPointInRectangle(
                    _canvasRect,
                    WorldToScreenPoint(pt, canvasCam),
                    canvasCam,
                    out canvasPos
                );
                _dots[i].anchoredPosition = canvasPos;
            }
        }

        // Apply to line renderer
        if (linePositions != null)
        {
            lineRenderer.positionCount = linePositions.Length;
            lineRenderer.SetPositions(linePositions);

            // If dashed, update scroll offset each frame
            if (dashedLine && lineRenderer.material != null)
            {
                if (dashScrollSpeed != 0f)
                {
                    Vector2 off = lineRenderer.material.mainTextureOffset;
                    off.x += dashScrollSpeed * Time.deltaTime;
                    lineRenderer.material.mainTextureOffset = off;
                }
            }
        }
    }

    void UpdateDirectionImage(Vector2 launchVelocity)
    {
        if (directionImage == null) return;

        // Hide when no velocity
        if (launchVelocity.sqrMagnitude <= 0.0001f)
        {
            directionImage.rectTransform.anchoredPosition = Vector2.zero;
            directionImage.rectTransform.localRotation = Quaternion.identity;
            if (arrowLengthScale > 0f)
                directionImage.rectTransform.sizeDelta = _directionBaseSize;
            return;
        }

        // Position the arrow over the object's position on the canvas
        if (_canvasRect != null)
        {
            Camera canvasCam = GetCanvasCamera();
            Vector2 canvasPos;
            RectTransformUtility.ScreenPointToLocalPointInRectangle(
                _canvasRect,
                WorldToScreenPoint(transform.position, canvasCam),
                canvasCam,
                out canvasPos
            );
            directionImage.rectTransform.anchoredPosition = canvasPos;
        }

        // Rotate to face launch direction
        float angle = Mathf.Atan2(launchVelocity.y, launchVelocity.x) * Mathf.Rad2Deg;
        directionImage.rectTransform.rotation = Quaternion.Euler(0f, 0f, angle);

        // Optionally scale length by speed
        if (arrowLengthScale > 0f)
        {
            float len = _directionBaseSize.x + launchVelocity.magnitude * arrowLengthScale;
            directionImage.rectTransform.sizeDelta = new Vector2(len, _directionBaseSize.y);
        }
    }

    void ApplyLineRendererStyle()
    {
        if (lineRenderer == null) return;

        lineRenderer.startWidth = lineWidth;
        lineRenderer.endWidth = lineWidth;
        lineRenderer.startColor = lineColor;
        lineRenderer.endColor = lineColor;

        if (useLineRenderer && dashedLine && dashedLineMaterial != null)
        {
            // Assign dashed material and set tiling
            lineRenderer.sharedMaterial = dashedLineMaterial;
            lineRenderer.textureMode = LineTextureMode.Tile;

            if (lineRenderer.material != null)
            {
                float tileX = Mathf.Max(0.0001f, (1f / Mathf.Max(0.0001f, dashLengthWorld)) * Mathf.Max(0.0001f, dashTilingMultiplier));
                lineRenderer.material.mainTextureScale = new Vector2(tileX, 1f);
                // Do not reset offset each call; scrolling handled in UpdateTrajectoryPreview
            }
        }
        else
        {
            // Restore original when dashed not used or disabled
            if (_originalLineMaterial != null)
            {
                lineRenderer.sharedMaterial = _originalLineMaterial;
            }
            lineRenderer.textureMode = LineTextureMode.Stretch;
            if (lineRenderer.material != null)
            {
                lineRenderer.material.mainTextureScale = new Vector2(1f, 1f);
                lineRenderer.material.mainTextureOffset = Vector2.zero;
            }
        }
    }

    Camera GetCanvasCamera()
    {
        if (targetCanvas == null) return cam;
        if (targetCanvas.renderMode == RenderMode.ScreenSpaceOverlay) return null; // null is required by RectTransformUtility for overlay
        return targetCanvas.worldCamera != null ? targetCanvas.worldCamera : cam;
    }

    Vector3 ScreenToWorldWithZ(Vector3 screen)
    {
        if (cam == null) return screen;
        screen.z = _zToCam;
        return cam.ScreenToWorldPoint(screen);
    }

    Vector2 WorldToScreenPoint(Vector2 world, Camera cameraForCanvas)
    {
        // For overlay, pass null camera to get proper screen coords
        if (cameraForCanvas == null)
        {
            return RectTransformUtility.WorldToScreenPoint(null, world);
        }
        else
        {
            return RectTransformUtility.WorldToScreenPoint(cameraForCanvas, world);
        }
    }
