// TrajectoryLauncher2D.cs (C# for Unity)
// Usage / Setup:
// - Required components on the projectile: Rigidbody2D and a 2D Collider.
// - Attach this script to the projectile. It uses OnMouseDown/OnMouseDrag/OnMouseUp (also works with a single touch).
// - Canvas:
//   - Recommended: Screen Space - Overlay (no camera assignment needed).
//   - Also supported: Screen Space - Camera / World Space (assign Target Canvas, and set its World Camera).
// - Trajectory Dots:
//   - Create a small UI Image (e.g., a 4–8 px dot) and assign it as Dot Prefab.
//   - Assign the Target Canvas that should host the dots.
// - Line Renderer (optional):
//   - Add a LineRenderer, assign it in the inspector, and enable "Use Line Renderer".
//   - To render a dotted/dashed line, enable "Dashed Line", assign a dashed/dotted material (with tiling), set Dash Length (world units).
//     The script sets LineRenderer.textureMode = Tile, and adjusts material tiling/offset based on dashLengthWorld and dashScrollSpeed.

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

[DisallowMultipleComponent]
[RequireComponent(typeof(Rigidbody2D))]
[RequireComponent(typeof(Collider2D))]
public class TrajectoryLauncher2D : MonoBehaviour
{
    [Header("Input & Launch")]
    [Tooltip("Multiply world drag distance by this to get launch speed.")]
    public float power = 8f;

    [Tooltip("Cap the initial speed.")]
    public float maxLaunchSpeed = 20f;

    [Tooltip("Pull back to shoot forward (slingshot style).")]
    public bool invertDrag = true;

    [Tooltip("If true, the body is kinematic while dragging so it doesn't fall.")]
    public bool freezeWhileDragging = true;

    [Header("Trajectory UI (dots)")]
    public Canvas targetCanvas;
    [Tooltip("Prefab for the dot (UI Image) to display along the trajectory.")]
    public Image dotPrefab;
    [Tooltip("How many dots to show.")]
    public int dotsCount = 20;
    [Tooltip("Time step between dots in seconds.")]
    public float dotTimeStep = 0.08f;

    [Header("Line Renderer (optional)")]
    [Tooltip("Optionally draw the trajectory using a LineRenderer.")]
    public bool useLineRenderer = false;
    public LineRenderer lineRenderer;
    public Color lineColor = Color.white;
    public float lineWidth = 0.05f;

    [Header("Dashed/Dotted Line (optional)")]
    [Tooltip("Render the line as dashed/dotted using a tiled texture material.")]
    public bool dashedLine = false;
    [Tooltip("Material with a dashed/dotted texture set to repeat (use a shader that supports tiling).")]
    public Material dashedLineMaterial;
    [Tooltip("Approximate world length (in units) per dash cycle (affects tiling).")]
    public float dashLengthWorld = 1f;
    [Tooltip("Extra tiling multiplier to tweak dash density.")]
    public float dashTilingMultiplier = 1f;
    [Tooltip("Scroll speed for the dash texture along the line (optional).")]
    public float dashScrollSpeed = 0f;

    [Header("Camera")]
    [Tooltip("Camera used to convert between screen and world. Defaults to Camera.main.")]
    public Camera cam;

    // Internal state
    private Rigidbody2D _rb;
    private List<RectTransform> _dots = new List<RectTransform>();
    private bool _dragging;
    private Vector3 _startDragScreen;
    private Vector3 _startDragWorldProjected;
    private float _zToCam; // distance from cam to object for ScreenToWorldPoint
    private Vector2 _pendingLaunchVelocity; // computed while dragging
    private RigidbodyType2D _preDragBodyType;
    private RectTransform _canvasRect;
    private Material _originalLineMaterial;
    private float _dashOffsetPhase;

    void Awake()
    {
        _rb = GetComponent<Rigidbody2D>();
        if (cam == null) cam = Camera.main;

        if (targetCanvas == null)
        {
            targetCanvas = FindObjectOfType<Canvas>();
        }

        if (targetCanvas != null)
        {
            _canvasRect = targetCanvas.transform as RectTransform;
        }

        if (dotPrefab != null && targetCanvas != null)
        {
            CreateDotsPool();
            HideDots();
        }

        if (useLineRenderer && lineRenderer != null)
        {
            _originalLineMaterial = lineRenderer.sharedMaterial;
            lineRenderer.enabled = false;
            lineRenderer.positionCount = 0;
            lineRenderer.startWidth = lineWidth;
            lineRenderer.endWidth = lineWidth;
            lineRenderer.startColor = lineColor;
            lineRenderer.endColor = lineColor;
            lineRenderer.useWorldSpace = true;
            ApplyLineRendererStyle(0f); // initialize style
        }
    }

    void OnValidate()
    {
        power = Mathf.Max(0f, power);
        maxLaunchSpeed = Mathf.Max(0f, maxLaunchSpeed);
        dotsCount = Mathf.Max(0, dotsCount);
        dotTimeStep = Mathf.Max(0.001f, dotTimeStep);
        lineWidth = Mathf.Max(0.001f, lineWidth);
        dashLengthWorld = Mathf.Max(0.001f, dashLengthWorld);

        if (lineRenderer != null)
        {
            lineRenderer.startWidth = lineWidth;
            lineRenderer.endWidth = lineWidth;
            lineRenderer.startColor = lineColor;
            lineRenderer.endColor = lineColor;
        }
    }

    void OnDisable()
    {
        // Ensure UI and line are hidden if the object is disabled while dragging
        HideDots();
        if (useLineRenderer && lineRenderer != null)
        {
            lineRenderer.enabled = false;
            lineRenderer.positionCount = 0;

            // Restore original material and defaults
            if (_originalLineMaterial != null)
            {
                lineRenderer.sharedMaterial = _originalLineMaterial;
            }
            lineRenderer.textureMode = LineTextureMode.Stretch;
            if (lineRenderer.material != null)
            {
                lineRenderer.material.mainTextureScale = new Vector2(1f, 1f);
                lineRenderer.material.mainTextureOffset = Vector2.zero;
            }
        }
        _dragging = false;
    }

    void CreateDotsPool()
    {
        foreach (var d in _dots)
        {
            if (d != null) Destroy(d.gameObject);
        }
        _dots.Clear();

        if (dotPrefab == null || targetCanvas == null) return;

        for (int i = 0; i < dotsCount; i++)
        {
            var dot = Instantiate(dotPrefab, targetCanvas.transform);
            dot.transform.SetAsLastSibling();
            dot.gameObject.name = $"TrajectoryDot_{i}";
            dot.gameObject.SetActive(false);
            _dots.Add(dot.rectTransform);
        }
    }

    void EnsureDotsPool()
    {
        if (dotPrefab == null || targetCanvas == null) return;
        if (_dots.Count != dotsCount)
        {
            CreateDotsPool();
        }
    }

    void ShowDots()
    {
        foreach (var d in _dots)
        {
            if (d != null && !d.gameObject.activeSelf)
                d.gameObject.SetActive(true);
        }
    }

    void HideDots()
    {
        foreach (var d in _dots)
        {
            if (d != null && d.gameObject.activeSelf)
                d.gameObject.SetActive(false);
        }
    }

    void OnMouseDown()
    {
        if (cam == null) cam = Camera.main;

        _dragging = true;
        _startDragScreen = Input.mousePosition;

        // Compute depth relative to camera for consistent ScreenToWorldPoint conversion
        if (cam != null)
        {
            _zToCam = cam.WorldToScreenPoint(transform.position).z;
        }
        else
        {
            _zToCam = 0f;
        }

        _startDragWorldProjected = ScreenToWorldWithZ(_startDragScreen);

        if (freezeWhileDragging)
        {
            _preDragBodyType = _rb.bodyType;
            _rb.velocity = Vector2.zero;
            _rb.angularVelocity = 0f;
            _rb.bodyType = RigidbodyType2D.Kinematic;
        }

        EnsureDotsPool();
        if (useLineRenderer && lineRenderer != null)
        {
            lineRenderer.enabled = true;
            lineRenderer.positionCount = dotsCount;
        }
        ShowDots();
        UpdateTrajectoryPreview();
    }

    void OnMouseDrag()
    {
        if (!_dragging) return;
        // Update pending launch velocity based on drag
        Vector3 currentScreen = Input.mousePosition;
        Vector3 currentWorld = ScreenToWorldWithZ(currentScreen);
        Vector2 dragVec = (Vector2)(currentWorld - _startDragWorldProjected);
        if (invertDrag) dragVec = -dragVec;
        Vector2 v0 = dragVec * power;
        float speed = v0.magnitude;
        if (speed > maxLaunchSpeed) v0 = v0.normalized * maxLaunchSpeed;
        _pendingLaunchVelocity = v0;
        UpdateTrajectoryPreview();
    }

    void OnMouseUp()
    {
        if (!_dragging) return;
        _dragging = false;

        // Apply launch velocity
        if (freezeWhileDragging)
        {
            _rb.bodyType = _preDragBodyType;
        }
        _rb.velocity = _pendingLaunchVelocity;

        // Hide visuals and restore line material
        HideDots();
        if (useLineRenderer && lineRenderer != null)
        {
            lineRenderer.enabled = false;
            lineRenderer.positionCount = 0;
            if (_originalLineMaterial != null)
            {
                lineRenderer.sharedMaterial = _originalLineMaterial;
            }
            lineRenderer.textureMode = LineTextureMode.Stretch;
            if (lineRenderer.material != null)
            {
                lineRenderer.material.mainTextureScale = Vector2.one;
                lineRenderer.material.mainTextureOffset = Vector2.zero;
            }
        }
    }

    void Update()
    {
        // Animate dash offset while previewing
        if (_dragging && useLineRenderer && lineRenderer != null && dashedLine && dashScrollSpeed != 0f)
        {
            _dashOffsetPhase += dashScrollSpeed * Time.unscaledDeltaTime;
            ApplyLineRendererStyle(_dashOffsetPhase);
        }
    }

    // Compute ballistic points, convert to canvas space for UI dots, and update LineRenderer with world positions
    void UpdateTrajectoryPreview()
    {
        if (!_dragging) return;

        // Physics parameters
        Vector2 p0 = (Vector2)transform.position;
        Vector2 v0 = _pendingLaunchVelocity;
        Vector2 g = Physics2D.gravity * _rb.gravityScale; // world units / s^2

        // Prepare arrays for line
        if (useLineRenderer && lineRenderer != null)
        {
            lineRenderer.enabled = true;
            lineRenderer.positionCount = dotsCount;
        }

        // Iterate dots
        for (int i = 0; i < dotsCount; i++)
        {
            float t = (i + 1) * dotTimeStep; // start a bit ahead of launch point
            Vector2 worldPos = p0 + v0 * t + 0.5f * g * (t * t);

            // Update LineRenderer in world space
            if (useLineRenderer && lineRenderer != null)
            {
                lineRenderer.SetPosition(i, new Vector3(worldPos.x, worldPos.y, transform.position.z));
            }

            // Update UI dots on the target canvas
            if (_dots != null && i < _dots.Count && _dots[i] != null && targetCanvas != null)
            {
                Vector2 canvasPos;
                bool got = WorldToCanvasPosition(worldPos, out canvasPos);
                if (got)
                {
                    _dots[i].anchoredPosition = canvasPos;
                    if (!_dots[i].gameObject.activeSelf) _dots[i].gameObject.SetActive(true);
                }
                else
                {
                    if (_dots[i].gameObject.activeSelf) _dots[i].gameObject.SetActive(false);
                }
            }
        }

        // Apply line style tiling/offset based on current length/phase
        if (useLineRenderer && lineRenderer != null)
        {
            ApplyLineRendererStyle(_dashOffsetPhase);
        }
    }

    bool WorldToCanvasPosition(Vector2 world, out Vector2 anchored)
    {
        anchored = Vector2.zero;
        if (targetCanvas == null || _canvasRect == null) return false;

        // Convert world -> screen using the appropriate camera
        Camera canvasCam = null;
        if (targetCanvas.renderMode == RenderMode.ScreenSpaceOverlay)
        {
            // Screen Space Overlay ignores camera; use world to screen via main cam for perspective correctness
            canvasCam = cam != null ? cam : Camera.main;
        }
        else
        {
            canvasCam = targetCanvas.worldCamera != null ? targetCanvas.worldCamera : cam;
        }

        if (canvasCam == null) return false;

        Vector3 screenPos = canvasCam.WorldToScreenPoint(new Vector3(world.x, world.y, transform.position.z));
        // Convert screen -> canvas local point
        RectTransformUtility.ScreenPointToLocalPointInRectangle(_canvasRect, screenPos, targetCanvas.renderMode == RenderMode.ScreenSpaceOverlay ? null : canvasCam, out anchored);
        return true;
    }

    Vector3 ScreenToWorldWithZ(Vector3 screen)
    {
        if (cam == null) return transform.position;
        screen.z = _zToCam;
        return cam.ScreenToWorldPoint(screen);
    }

    // Style the LineRenderer using Tile mode, adjust mainTextureScale/Offset for dashLengthWorld & dashTilingMultiplier
    void ApplyLineRendererStyle(float phase = 0f)
    {
        if (!useLineRenderer || lineRenderer == null) return;

        if (dashedLine && dashedLineMaterial != null)
        {
            lineRenderer.textureMode = LineTextureMode.Tile;
            if (lineRenderer.sharedMaterial != dashedLineMaterial)
            {
                lineRenderer.sharedMaterial = dashedLineMaterial;
            }

            // Compute approximate total length to set tiling
            float totalLen = 0f;
            int n = lineRenderer.positionCount;
            if (n >= 2)
            {
                Vector3 prev = lineRenderer.GetPosition(0);
                for (int i = 1; i < n; i++)
                {
                    Vector3 p = lineRenderer.GetPosition(i);
                    totalLen += Vector3.Distance(prev, p);
                    prev = p;
                }
            }

            float cycles = (dashLengthWorld > 0f) ? Mathf.Max(0.0001f, totalLen / dashLengthWorld) : 1f;
            float tiling = cycles * Mathf.Max(0.0001f, dashTilingMultiplier);

            if (lineRenderer.material != null)
            {
                Vector2 scale = new Vector2(tiling, 1f);
                lineRenderer.material.mainTextureScale = scale;
                if (dashScrollSpeed != 0f || phase != 0f)
                {
                    lineRenderer.material.mainTextureOffset = new Vector2(phase, 0f);
                }
            }
        }
        else
        {
            // Solid line: restore original material if needed
            if (_originalLineMaterial != null && lineRenderer.sharedMaterial != _originalLineMaterial)
            {
                lineRenderer.sharedMaterial = _originalLineMaterial;
            }
            lineRenderer.textureMode = LineTextureMode.Stretch;
            if (lineRenderer.material != null)
            {
                lineRenderer.material.mainTextureScale = Vector2.one;
                lineRenderer.material.mainTextureOffset = Vector2.zero;
            }
        }
    }
}
