{
    [Header("Vista 2023")]
    [Tooltip("Reference to your Vista 2023 graph asset (ScriptableObject)")]
    public Graph vistaGraphAsset; // Pinwheel.Vista.Graph

    [Header("Resolutions")]
    [Tooltip("TerrainData.heightmapResolution (power of two + 1, e.g., 257)")]
