    [Tooltip("TerrainData.alphamapResolution (e.g., 512). Set 0 to skip splats.")]
    public int alphaResolution = 512;
    [Tooltip("Extra pixels around the chunk for edge safety; trimmed after readback")]
    public int bleedPixels = 2;

    [Header("Terrain Settings")]
    [Tooltip("Terrain vertical scale")]
    public float terrainHeight = 300f;
    [Tooltip("World-space offset if your graph expects non-zero origin")]
    public Vector2 worldOffset = Vector2.zero;
    [Tooltip("Seed for your graph if supported")]
    public int seed = 12345;

    [Header("Execution")]
    [Tooltip("If Vista supports GPU evaluation, prefer it")]
    public bool preferGPU = true;
    [Tooltip("Limit parallel evaluations to avoid spikes")]
    public int maxConcurrent = 2;

    private SemaphoreSlim _gate;
    private SynchronizationContext _unityContext;

    private GraphInstance _sharedInstance; // Reuse across chunks for speed where possible

    void Awake()
    {
        _gate = new SemaphoreSlim(Mathf.Max(1, maxConcurrent), Mathf.Max(1, maxConcurrent));
        _unityContext = SynchronizationContext.Current;

        if (vistaGraphAsset != null)
        {
            // Create a reusable instance of the Vista graph for runtime evaluation
            _sharedInstance = new GraphInstance(vistaGraphAsset);
            _sharedInstance.ExecutionDevice = preferGPU ? ExecutionDevice.GPU : ExecutionDevice.CPU; // choose device
            _sharedInstance.SetSeed(seed);
        }
    }

    void OnDestroy()
    {
        if (_sharedInstance != null)
        {
            _sharedInstance.Dispose();
            _sharedInstance = null;
        }
    }

    public async Task<ChunkData> GetChunkAsync(ChunkCoord coord, CancellationToken ct)
    {
        await _gate.WaitAsync(ct).ConfigureAwait(false);
        try
        {
            // Compute world-space bounds for this chunk (XZ rectangle)
            float wx = coord.x * coord.chunkSize + worldOffset.x;
            float wz = coord.z * coord.chunkSize + worldOffset.y;
            var bounds = new Rect(wx, wz, coord.chunkSize, coord.chunkSize);

            // Evaluate Vista graph and read height/alphamap outputs.
            var eval = await EvaluateVistaGraphAsync(bounds, heightResolution, alphaResolution, bleedPixels, ct)
                .ConfigureAwait(false);

            // Strip bleed border from heights so it fits the exact chunk resolution
            var heightsNoBleed = TrimBleed(eval.heights, bleedPixels);

            float[,,] alphamapsNoBleed = eval.alphamaps;
            if (alphamapsNoBleed != null && bleedPixels > 0)
            {
                alphamapsNoBleed = TrimBleedAlpha(eval.alphamaps, bleedPixels);
            }

            return new ChunkData
            {
                heights = heightsNoBleed,
                alphamaps = alphamapsNoBleed,
                heightResolution = heightResolution,
                alphaResolution = alphaResolution,
                layerCount = alphamapsNoBleed == null ? 0 : alphamapsNoBleed.GetLength(2)
            };
        }
        finally
        {
            _gate.Release();
        }
    }

    private float[,] TrimBleed(float[,] src, int bleed)
    {
        if (bleed <= 0) return src;
        int srcW = src.GetLength(0);
        int srcH = src.GetLength(1);
        int dstW = srcW - 2 * bleed;
        int dstH = srcH - 2 * bleed;
        var dst = new float[dstW, dstH];
        for (int y = 0; y < dstH; y++)
        {
            for (int x = 0; x < dstW; x++)
            {
                dst[x, y] = src[x + bleed, y + bleed];
            }
        }
        return dst;
    }

    private float[,,] TrimBleedAlpha(float[,,] src, int bleed)
    {
        int w = src.GetLength(0);
        int h = src.GetLength(1);
        int l = src.GetLength(2);
        int dw = w - 2 * bleed;
        int dh = h - 2 * bleed;
        var dst = new float[dw, dh, l];
        for (int y = 0; y < dh; y++)
        {
            for (int x = 0; x < dw; x++)
            {
                for (int k = 0; k < l; k++)
                {
                    dst[x, y, k] = src[x + bleed, y + bleed, k];
                }
            }
        }
        return dst;
    }

    private struct VistaEvalResult
    {
        public float[,] heights;     // [res+2b, res+2b]
        public float[,,] alphamaps;  // [alphaRes, alphaRes, layers]
    }

    private Task SwitchToUnityMainThread(CancellationToken ct)
    {
        var tcs = new TaskCompletionSource<bool>();
        _unityContext.Post(_ =>
        {
            if (ct.IsCancellationRequested)
            {
                tcs.TrySetCanceled(ct);
            }
            else
            {
                tcs.TrySetResult(true);
            }
        }, null);
        return tcs.Task;
    }

    // Vista 2023 concrete evaluation: create/prepare instance, set bounds/resolutions, evaluate async, read back.
    private async Task<VistaEvalResult> EvaluateVistaGraphAsync(
        Rect worldBounds,
        int heightRes,
        int alphaRes,
        int bleed,
        CancellationToken ct)
    {
        await SwitchToUnityMainThread(ct); // Vista graph eval must run on main thread

        // Ensure instance
        if (_sharedInstance == null)
        {
            _sharedInstance = new GraphInstance(vistaGraphAsset);
            _sharedInstance.ExecutionDevice = preferGPU ? ExecutionDevice.GPU : ExecutionDevice.CPU;
            _sharedInstance.SetSeed(seed);
        }

        int evalHeightRes = heightRes + 2 * bleed;

        // Configure per-chunk world bounds and resolutions
        _sharedInstance.SetWorldBounds(worldBounds.xMin, worldBounds.yMin, worldBounds.width, worldBounds.height);
        _sharedInstance.SetHeightmapResolution(evalHeightRes);
        if (alphaRes > 0)
        {
            _sharedInstance.SetAlphamapResolution(alphaRes);
        }

        // Kick async evaluation
        await _sharedInstance.EvaluateAsync(ct);

        // Read back height output as float[,]
        float[,] heights = _sharedInstance.ReadHeightmap();

        // Read back splat/alpha outputs if present
        float[,,] alphamaps = null;
        if (alphaRes > 0 && _sharedInstance.HasAlphamapOutput)
        {
            alphamaps = _sharedInstance.ReadAlphamaps();
        }

        return new VistaEvalResult
        {
            heights = heights,
            alphamaps = alphamaps
        };
    }
}

