public class TerrainChunkStreamer : MonoBehaviour
{
    [Header("References")]
    public Transform player;                   // player/camera transform
    public GameObject chunkPrefab;             // prefab with Terrain + TerrainCollider
    public VistaGraphAdapter dataProvider;     // adapter to Vista graph

    [Header("Tiling")]
    public float chunkSize = 256f;             // meters per chunk (Terrain size.x/z)
    public int heightResolution = 257;         // must match adapter
    public int alphaResolution = 512;          // must match adapter
    public float terrainHeight = 300f;         // vertical scale

    [Header("Streaming")]
    public int renderRadius = 3;               // chunks in Chebyshev distance (3 => 7x7 grid)
    public float updateInterval = 0.25f;       // seconds between culling passes

    private readonly Dictionary<(int,int), Terrain> _live = new();
    private readonly Dictionary<(int,int), CancellationTokenSource> _pending = new();

    void Start()
    {
        if (dataProvider != null)
        {
            dataProvider.heightResolution = heightResolution;
            dataProvider.alphaResolution = alphaResolution;
            dataProvider.terrainHeight = terrainHeight;
        }
        StartCoroutine(StreamingLoop());
    }

    private IEnumerator StreamingLoop()
    {
        var wait = new WaitForSeconds(updateInterval);
        while (true)
        {
            Tick();
            yield return wait;
        }
    }

    private void Tick()
    {
        if (player == null) return;
        Vector3 p = player.position;
        int cx = Mathf.FloorToInt(p.x / chunkSize);
        int cz = Mathf.FloorToInt(p.z / chunkSize);

        // Desired set within radius (Chebyshev distance)
        var desired = new HashSet<(int,int)>();
        for (int dz = -renderRadius; dz <= renderRadius; dz++)
        {
            for (int dx = -renderRadius; dx <= renderRadius; dx++)
            {
                if (Mathf.Max(Mathf.Abs(dx), Mathf.Abs(dz)) <= renderRadius)
                {
                    desired.Add((cx + dx, cz + dz));
                }
            }
        }

        // Spawn missing
        foreach (var key in desired)
        {
            if (_live.ContainsKey(key) || _pending.ContainsKey(key))
                continue;
            SpawnAsync(key.Item1, key.Item2);
        }

        // Unload far chunks (not desired)
        var toRemove = new List<(int,int)>();
        foreach (var kv in _live)
        {
            if (!desired.Contains(kv.Key))
            {
                toRemove.Add(kv.Key);
            }
        }
        foreach (var key in toRemove)
        {
            var t = _live[key];
            _live.Remove(key);
            if (t != null)
            {
                Destroy(t.gameObject);
            }
        }

        // Cancel pending that left the radius
        var cancelKeys = new List<(int,int)>();
        foreach (var kv in _pending)
        {
            if (!desired.Contains(kv.Key))
            {
                kv.Value.Cancel();
                cancelKeys.Add(kv.Key);
            }
        }
        foreach (var k in cancelKeys) _pending.Remove(k);
    }

    private async void SpawnAsync(int cx, int cz)
    {
        var key = (cx, cz);
        var cts = new CancellationTokenSource();
        _pending[key] = cts;
        try
        {
            var coord = new ChunkCoord { x = cx, z = cz, chunkSize = chunkSize };
            ChunkData data = await dataProvider.GetChunkAsync(coord, cts.Token);
            if (cts.IsCancellationRequested) return;

            // Create chunk GameObject
            var go = Instantiate(chunkPrefab);
            go.name = $"Chunk_{cx}_{cz}";
            go.transform.position = new Vector3(cx * chunkSize, 0, cz * chunkSize);

            var terrain = go.GetComponent<Terrain>();
            if (terrain == null) terrain = go.AddComponent<Terrain>();
            var collider = go.GetComponent<TerrainCollider>();
            if (collider == null) collider = go.AddComponent<TerrainCollider>();

            // Configure TerrainData
            var td = new TerrainData();
            td.heightmapResolution = data.heightResolution;
            td.alphamapResolution = Math.Max(16, data.alphaResolution);
            td.size = new Vector3(chunkSize, terrainHeight, chunkSize);

            // Apply heights
            td.SetHeights(0, 0, data.heights);

            // Apply alphamaps if any
            if (data.alphamaps != null && data.layerCount > 0)
            {
                // Ensure terrain has matching layers set up in advance (via inspector) or set here.
                td.alphamapLayers = data.layerCount; // Vista layers must correspond to TerrainLayers order
                td.SetAlphamaps(0, 0, data.alphamaps);
            }

            terrain.terrainData = td;
            collider.terrainData = td;

            _live[key] = terrain;
        }
        catch (OperationCanceledException) { }
        catch (Exception ex)
        {
            Debug.LogException(ex);
        }
        finally
        {
            if (_pending.ContainsKey(key)) _pending.Remove(key);
            cts.Dispose();
        }
    }
}

