        var worldRect = new Rect(xMin, zMin, coord.chunkSize, coord.chunkSize);

        // Resolutions with bleed. Height typically needs +bleed to avoid seams; alpha may or may not support margins.
        int hResWithBleed = Mathf.Max(2, heightResolution) + bleedPixels * 2;
        int aRes = Mathf.Max(0, alphaResolution);

        // Create and configure the Vista runtime runner for this tile.
        using (var runner = new VistaRuntimeRunner(vistaGraphAsset))
        {
            runner.SetSeed(seed);
            // Y range: 0..terrainHeight (heights are normalized later to [0..1])
            runner.SetWorldBounds(worldRect, 0f, terrainHeight);
            runner.SetResolutions(hResWithBleed, aRes);

            // Kick async evaluation. Vista should schedule GPU/CPU work internally and resume here when done.
            VistaOutputs outputs = await runner.EvaluateAsync(ct).ConfigureAwait(false);
            ct.ThrowIfCancellationRequested();

            // Read back height data (normalized [0..1]) and trim bleed to requested heightResolution.
            int srcHRes = outputs.Heightmap?.Resolution ?? hResWithBleed;
            float[] h1D = outputs.Heightmap != null ? outputs.Heightmap.GetHeights1D() : new float[srcHRes * srcHRes];
            if (h1D == null || h1D.Length != srcHRes * srcHRes)
                throw new Exception("Vista height readback failed or unexpected resolution.")
                ;

            // Convert 1D -> 2D and crop out bleed.
            int dstHRes = heightResolution;
            var heights = new float[dstHRes, dstHRes];
            int start = bleedPixels;
            for (int z = 0; z < dstHRes; z++)
            {
                int srcZ = z + start;
                for (int x = 0; x < dstHRes; x++)
                {
                    int srcX = x + start;
                    float v = h1D[srcZ * srcHRes + srcX]; // already 0..1
                    heights[z, x] = Mathf.Clamp01(v);
                }
            }

            // Read back splat/alphamaps if requested
            float[,,] alphamaps = null;
            int layerCount = 0;
            if (aRes > 0 && outputs.Splatmap != null)
            {
                int srcARes = outputs.Splatmap.Resolution;
                layerCount = Mathf.Max(1, outputs.Splatmap.LayerCount);
                float[] a1D = outputs.Splatmap.GetAlphamaps1D(); // length = srcARes*srcARes*layers
                if (a1D != null && a1D.Length == srcARes * srcARes * layerCount)
                {
                    // Unity expects [y, x, layer] with size [alphaRes, alphaRes, layers]
                    alphamaps = new float[aRes, aRes, layerCount];
                    for (int y = 0; y < aRes; y++)
                    {
                        float vY = (y + 0.5f) / aRes * srcARes - 0.5f;
                        int sy = Mathf.Clamp(Mathf.RoundToInt(vY), 0, srcARes - 1);
                        for (int x = 0; x < aRes; x++)
                        {
                            float vX = (x + 0.5f) / aRes * srcARes - 0.5f;
                            int sx = Mathf.Clamp(Mathf.RoundToInt(vX), 0, srcARes - 1);
                            int srcBase = (sy * srcARes + sx) * layerCount;
                            float sum = 0f;
                            for (int l = 0; l < layerCount; l++)
                            {
                                float w = a1D[srcBase + l];
                                alphamaps[y, x, l] = w;
                                sum += w;
                            }
                            if (sum > 1e-5f)
                            {
                                for (int l = 0; l < layerCount; l++) alphamaps[y, x, l] /= sum;
                            }
                            else
                            {
                                // default to layer 0 if Vista returned zeros
                                alphamaps[y, x, 0] = 1f;
                            }
                        }
                    }
                }
            }

            return new ChunkData
            {
                heights = heights,
                alphamaps = alphamaps,
                heightResolution = heightResolution,
                alphaResolution = aRes,
                layerCount = layerCount
            };
        }
    }
}

#endregion

#region Terrain streamer (scene controller)

public class TerrainChunkStreamer : MonoBehaviour
{
    [Header("References")]
    public Transform player;
    public VistaGraphAdapter dataProvider;

    [Header("Chunking")]
    public float chunkSize = 256f;           // meters per chunk (X/Z)
    public int renderRadiusChunks = 2;       // Chebyshev radius (e.g., 2 -> 5x5 chunks)
    public float updateInterval = 0.2f;      // seconds between stream ticks

    [Header("Terrain Defaults")]
    public Material terrainMaterial;

    private readonly Dictionary<(int x, int z), Terrain> _terrains = new();
    private readonly Dictionary<(int x, int z), CancellationTokenSource> _inflight = new();
    private float _nextTick;

    void OnEnable()
    {
        _nextTick = Time.time;
    }

    void OnDisable()
    {
        foreach (var kv in _inflight) kv.Value.Cancel();
        foreach (var kv in _terrains) if (kv.Value != null) Destroy(kv.Value.gameObject);
        _inflight.Clear();
        _terrains.Clear();
    }

    void Update()
    {
        if (player == null || dataProvider == null) return;
        if (Time.time < _nextTick) return;
        _nextTick = Time.time + updateInterval;
        StreamTick();
    }

    private void StreamTick()
    {
        // Determine center chunk under player
        int cx = Mathf.FloorToInt(player.position.x / chunkSize);
        int cz = Mathf.FloorToInt(player.position.z / chunkSize);

        // Desired set within Chebyshev radius
        var desired = new HashSet<(int x, int z)>();
        for (int dz = -renderRadiusChunks; dz <= renderRadiusChunks; dz++)
        {
            for (int dx = -renderRadiusChunks; dx <= renderRadiusChunks; dx++)
            {
                if (Mathf.Max(Mathf.Abs(dx), Mathf.Abs(dz)) <= renderRadiusChunks)
                {
                    desired.Add((cx + dx, cz + dz));
                }
            }
        }

        // Spawn missing
        foreach (var key in desired)
        {
            if (_terrains.ContainsKey(key)) continue;
            if (_inflight.ContainsKey(key)) continue;
            var cts = new CancellationTokenSource();
            _inflight[key] = cts;
            _ = SpawnChunkAsync(key.x, key.z, cts.Token);
        }

        // Unload far
        var toRemove = new List<(int x, int z)>();
        foreach (var kv in _terrains)
        {
            if (!desired.Contains(kv.Key))
            {
                toRemove.Add(kv.Key);
            }
        }
        foreach (var key in toRemove)
        {
            if (_terrains.TryGetValue(key, out var t) && t != null)
            {
                Destroy(t.gameObject);
            }
            _terrains.Remove(key);
            if (_inflight.TryGetValue(key, out var genCts))
            {
                genCts.Cancel();
                _inflight.Remove(key);
            }
        }

        // Cancel inflight that left the radius
        var inflightToCancel = new List<(int x, int z)>();
        foreach (var kv in _inflight)
        {
            if (!desired.Contains(kv.Key)) inflightToCancel.Add(kv.Key);
        }
        foreach (var key in inflightToCancel)
        {
            _inflight[key].Cancel();
            _inflight.Remove(key);
        }

        // Wire neighbors to minimize cracks
        WireNeighbors();
    }

    private async Task SpawnChunkAsync(int x, int z, CancellationToken ct)
    {
        try
        {
            var coord = new ChunkCoord { x = x, z = z, chunkSize = chunkSize };
            ChunkData data = await dataProvider.GetChunkAsync(coord, ct);
            ct.ThrowIfCancellationRequested();

            // Create TerrainData
            var tData = new TerrainData();
            tData.heightmapResolution = data.heightResolution;
            tData.alphamapResolution = Mathf.Max(16, data.alphaResolution == 0 ? 16 : data.alphaResolution);
            tData.size = new Vector3(chunkSize, dataProvider.terrainHeight, chunkSize);

            // Apply heights
            tData.SetHeights(0, 0, data.heights);

            // Apply splats if present
            if (data.alphamaps != null && data.layerCount > 0)
            {
                int layers = data.layerCount;
                // Ensure terrain has matching layers set up in the project
                if (TerrainLayerValidation(layers))
                {
                    tData.alphamapResolution = data.alphaResolution;
                    tData.SetAlphamaps(0, 0, data.alphamaps);
                }
            }

            // Create terrain GO
            var go = Terrain.CreateTerrainGameObject(tData);
            go.name = $"Chunk_{x}_{z}";
            go.transform.position = new Vector3(x * chunkSize, 0f, z * chunkSize);
            var terrain = go.GetComponent<Terrain>();
            if (terrainMaterial != null) terrain.materialTemplate = terrainMaterial;

            _terrains[(x, z)] = terrain;
            _inflight.Remove((x, z));

            WireNeighbors();
        }
        catch (OperationCanceledException)
        {
            // Swallow cancellations (chunk left radius)
        }
        catch (Exception e)
        {
            Debug.LogError($"Chunk ({x},{z}) generation failed: {e.Message}");
            _inflight.Remove((x, z));
        }
    }

    private void WireNeighbors()
    {
        foreach (var kv in _terrains)
        {
            int x = kv.Key.x; int z = kv.Key.z;
            Terrain t = kv.Value;
            _terrains.TryGetValue((x - 1, z), out var left);
            _terrains.TryGetValue((x + 1, z), out var right);
            _terrains.TryGetValue((x, z + 1), out var top);
            _terrains.TryGetValue((x, z - 1), out var bottom);
            if (t != null) t.SetNeighbors(left, top, right, bottom);
        }
    }

    private bool TerrainLayerValidation(int neededLayers)
    {
        // You can extend this to auto-assign TerrainLayers from resources.
        return neededLayers > 0; // assume project has layers configured
    }
}

#endregion

Below is a complete, runnable MATLAB script that implements a simple ABS braking system (single wheel, quarter-car approximation). It includes full implementations for Braking_torque, ramp, slip, ABScycle, and tiremodel as local functions with brief input/output comments, and fixes the plotting so the script runs end-to-end in a single .m file.

You can save it as abs_simulation.m and run it in MATLAB (R2016b or newer supports local functions at the end of scripts).

% ABS braking system simulation (single wheel, quarter-car approximation)
% Mechatronics-oriented implementation with:
% - Braking_torque function
% - ramp function
% - slip function
% - ABScycle function
% - tiremodel function
% - main script

clear; clc; close all;

%% Parameters
% Vehicle and wheel
m_total   = 1500;           % total vehicle mass [kg]
m_q       = m_total/4;      % quarter-vehicle mass [kg]
g         = 9.81;           % gravity [m/s^2]
Fz        = m_q * g;        % normal load per wheel [N]
R         = 0.30;           % wheel effective radius [m]
Iw        = 1.8;            % wheel rotational inertia [kg*m^2]

% Initial conditions
v0        = 30;             % initial vehicle speed [m/s] ~108 km/h
w0        = v0 / R;         % initial wheel angular speed [rad/s]

% Brake actuator and ABS controller
T_brk_max = 1500;           % max brake torque per wheel [N*m]
P_min     = 0.0;            % min brake pressure command (normalized)
P_max     = 1.0;            % max brake pressure command (normalized)
dP_up     = 30;             % pressure increase rate [1/s]
dP_down   = 60;             % pressure decrease rate [1/s]
s_low     = 0.12;           % ABS slip lower threshold
s_high    = 0.20;           % ABS slip upper threshold
v_cutoff  = 0.5;            % below this vehicle speed, disable ABS and pressure [m/s]

% Tire model (Burckhardt coefficients: dry road)
tire.a1 = 1.28;
tire.a2 = 23.99;
tire.a3 = 0.52;

% Simulation settings
dt        = 1e-3;           % time step [s]
t_end     = 10.0;           % maximum simulation time [s]
N         = ceil(t_end/dt)+1;

% Toggle ABS on/off for comparison (1=ABS enabled, 0=full pressure)
ABS_on    = 1;

%% Preallocate arrays
t    = zeros(N,1);
v    = zeros(N,1);    v(1) = v0;
w    = zeros(N,1);    w(1) = w0;
sl   = zeros(N,1);
mu   = zeros(N,1);
Fx   = zeros(N,1);
Tb   = zeros(N,1);
P    = zeros(N,1);    P(1) = 0.0; % start with no pressure, ABS will ramp up

%% Simulation loop
k_stop = N;
for k = 1:N-1
    t(k+1) = t(k) + dt;

    % Compute slip (use current v, w)
    sl(k) = slip(v(k), w(k), R);

    % Tire force from tire model
    mu(k) = tiremodel(sl(k), tire);
    Fx(k) = mu(k) * Fz;                 % longitudinal tire force [N]

    % Control pressure via ABS cycle
    if ABS_on
        if v(k) > v_cutoff
            P(k+1) = ABScycle(sl(k), s_low, s_high, P(k), dt, dP_up, dP_down, P_min, P_max);
        else
            P(k+1) = 0.0; % below cutoff, release brake to prevent standstill chatter
        end
    else
        % No ABS: constant full brake pressure (rate limited ramp-up for realism)
        P(k+1) = ramp(P(k), P_max, dP_up, dP_down, dt, P_min, P_max);
    end

    % Brake torque from current pressure
    Tb(k) = Braking_torque(P(k), T_brk_max);

    % Wheel and vehicle dynamics
    % Iw * w_dot = Tb - Fx * R
    w_dot = (Tb(k) - Fx(k)*R) / Iw;
    v_dot = -Fx(k) / m_q;

    % Integrate (Euler) with non-negative clamps
    w(k+1) = max(0, w(k) + w_dot*dt);
    v(k+1) = max(0, v(k) + v_dot*dt);

    % Stop condition
    if v(k+1) <= 0.05
        k_stop = k+1;
        v(k+1) = 0;
        w(k+1) = 0;
        P(k+1) = 0;
        break;
    end
end

% Trim arrays to actual simulation length
t  = t(1:k_stop);
v  = v(1:k_stop);
w  = w(1:k_stop);
P  = P(1:k_stop);
Tb = Tb(1:k_stop);
sl = sl(1:k_stop);
mu = mu(1:k_stop);
Fx = Fx(1:k_stop);

% Ensure last slip and mu are consistent with final states
sl(end) = slip(v(end), w(end), R);
mu(end) = tiremodel(sl(end), tire);
Fx(end) = mu(end) * Fz;

%% Outputs
disp('Simulation finished.');
distance = trapz(t, v);
fprintf('Stopping time: %.2f s, Distance (approx. via trapezoid): %.1f m\n', t(end), distance);

%% Plots
figure('Name','ABS Simulation','Color','w');

% Speeds
subplot(3,1,1);
plot(t, v, 'b', 'LineWidth',1.5); hold on;
plot(t, w*R, 'r--', 'LineWidth',1.2);
ylabel('Speed [m/s]'); grid on;
legend({'Vehicle v','Wheel peripheral v = \omega R'},'Location','best');
title('Speeds');

% Slip with thresholds
subplot(3,1,2);
plot(t, sl, 'k', 'LineWidth',1.5); hold on;
plot(t, s_low*ones(size(t)), 'g--', 'LineWidth',1.0);
plot(t, s_high*ones(size(t)), 'r--', 'LineWidth',1.0);
ylabel('Slip [-]'); grid on;
legend({'Slip','s_{low}','s_{high}'},'Location','best');
title('Wheel Slip and ABS Thresholds');

% Brake pressure and torque
subplot(3,1,3);
yyaxis left;
plot(t, P, 'm', 'LineWidth',1.5);
ylabel('Brake Pressure (norm)'); ylim([0 1]); grid on;
yyaxis right;
plot(t, Tb, 'c', 'LineWidth',1.2);
ylabel('Brake Torque [N*m]');
xlabel('Time [s]');
legend({'Pressure','Torque'},'Location','best');
title('Brake Actuation');

figure('Name','Forces and Friction','Color','w');
subplot(2,1,1);
plot(t, mu, 'b', 'LineWidth',1.5); grid on;
ylabel('\mu [-]');
title('Tire Friction Coefficient');
subplot(2,1,2);
plot(t, Fx, 'r', 'LineWidth',1.5); grid on;
ylabel('Fx [N]'); xlabel('Time [s]');
title('Longitudinal Tire Force');

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Local functions
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

function T = Braking_torque(P, T_brk_max)
% Braking_torque
% Inputs:
%   P         - normalized brake pressure command [0..1]
%   T_brk_max - maximum brake torque [N*m]
% Output:
%   T         - brake torque [N*m]
    P = max(0.0, min(1.0, P));
    T = P * T_brk_max;
end

function P_new = ramp(P_cur, P_target, dP_up, dP_down, dt, P_min, P_max)
% ramp
% Rate-limited ramp from current pressure to target pressure.
% Inputs:
%   P_cur    - current pressure (normalized)
%   P_target - target pressure (normalized)
%   dP_up    - max increase rate [1/s]
%   dP_down  - max decrease rate [1/s]
%   dt       - timestep [s]
%   P_min    - minimum pressure clamp
%   P_max    - maximum pressure clamp
% Output:
%   P_new    - updated pressure after rate limit and clamping
    delta = P_target - P_cur;
    if delta > 0
        step = min(delta, dP_up*dt);
    else
        step = max(delta, -dP_down*dt);
    end
    P_new = P_cur + step;
    P_new = max(P_min, min(P_max, P_new));
end

function s = slip(v, w, R)
% slip
% Computes braking slip s = (v - w*R) / v, guarded near zero speed.
% Inputs:
%   v - vehicle longitudinal speed [m/s]
%   w - wheel angular speed [rad/s]
%   R - wheel effective radius [m]
% Output:
%   s - slip (bounded to [0, 1] for braking)
    if v <= 0.1
        s = 0.0;
        return;
    end
    s = (v - w*R) / max(v, 1e-3);
    % Bound slip to [0,1] for braking scenario
    s = max(0.0, min(1.0, s));
end

function P_next = ABScycle(slip_k, s_low, s_high, P_cur, dt, dP_up, dP_down, P_min, P_max)
% ABScycle
% Simple on-off ABS logic that modulates brake pressure to keep slip within [s_low, s_high].
% Inputs:
%   slip_k  - current slip [-]
%   s_low   - lower slip threshold [-]
%   s_high  - upper slip threshold [-]
%   P_cur   - current brake pressure (normalized)
%   dt      - time step [s]
%   dP_up   - pressure increase rate [1/s]
%   dP_down - pressure decrease rate [1/s]
%   P_min   - minimum allowable pressure
%   P_max   - maximum allowable pressure
% Output:
%   P_next  - next-step brake pressure after ABS modulation
    if slip_k > s_high
        % Too much slip (incipient lock) -> release pressure fast
        P_target = P_min;
    elseif slip_k < s_low
        % Too little slip -> build pressure
        P_target = P_max;
    else
        % Within band -> hold (small creep toward current level)
        P_target = P_cur;
    end
    P_next = ramp(P_cur, P_target, dP_up, dP_down, dt, P_min, P_max);
end

function mu = tiremodel(slip_k, tire)
% tiremodel
% Burckhardt tire model for longitudinal friction coefficient.
% Inputs:
%   slip_k - current slip [-]
%   tire   - struct with fields a1, a2, a3 (Burckhardt coefficients)
% Output:
%   mu     - longitudinal friction coefficient [-]
    s = max(0.0, min(1.0, slip_k));
    a1 = tire.a1; a2 = tire.a2; a3 = tire.a3;
    mu = a1 .* (1 - exp(-a2 .* s)) - a3 .* s;
    % Ensure non-negative and reasonable upper bound
    mu = max(0.0, mu);
end

Below is a minimal Rust-based init named sysx for Devuan that avoids systemd/sysvinit, dbus, X (x11/xorg/xinit), elogind, systemctl, and server daemons. It mounts /proc, /sys, and /dev, runs fsck, mounts filesystems, brings up networking with iproute2, spawns a getty, supervises tasks with simple restart policy and logging, and includes a sysx CLI to list/start/stop tasks.

Notes:
- Build static or with minimal dependencies. Requires CAP_SYS_ADMIN and running as PID 1.
- Expects basic tools available in /sbin or /bin: mount, umount, fsck, ip, mdev (optional), busybox/getty or agetty.
- Devuan without sysv/systemd: place /sbin/init -> /sbin/sysx and set as init in bootloader.

Cargo.toml

[package]
name = "sysx"
version = "0.1.0"
edition = "2021"

[profile.release]
lto = true
codegen-units = 1
panic = "abort"

[dependencies]
nix = { version = "0.29", default-features = false, features = ["process", "sched", "mount", "term", "fs", "signal", "errno"] }
serde = { version = "1.0", features = ["derive"] }
serde_json = "1.0"
thiserror = "1.0"

src/main.rs

use nix::errno::Errno;
use nix::libc;
use nix::mount::{mount, umount2, MntFlags, MsFlags};
use nix::sys::signal::{kill, Signal};
use nix::sys::wait::{waitpid, WaitPidFlag, WaitStatus};
use nix::unistd::{fork, ForkResult, Pid};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs::{self, File, OpenOptions};
use std::io::{Read, Write};
use std::os::unix::fs::PermissionsExt;
use std::path::Path;
use std::process::Command;
use std::time::{Duration, Instant};

// Simple task model and supervision
#[derive(Debug, Clone, Serialize, Deserialize)]
struct TaskSpec {
    name: String,
    cmd: Vec<String>,
    restart: RestartPolicy,
    stdout_log: String,
    stderr_log: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type")]
enum RestartPolicy {
    Never,
    Always,
    OnFailure { max_retries: Option<u32>, backoff_secs: u64 },
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct RuntimeState {
    // pid of running tasks
    pids: HashMap<String, i32>,
    // crash counters
    crashes: HashMap<String, u32>,
}

const STATE_FILE: &str = "/run/sysx/state.json";
const TASKS_FILE: &str = "/etc/sysx/tasks.json";

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() > 1 && args[1] == "cli" {
        cli(&args[2..]);
        return;
    }

    // Act as PID 1
    if unsafe { libc::getpid() } != 1 {
        eprintln!("sysx must run as PID 1 for init mode. Use 'sysx cli ...' for CLI.");
        std::process::exit(1);
    }

    if let Err(e) = init_main() {
        eprintln!("sysx init fatal: {}", e);
        // As PID 1, last resort: sleep to avoid kernel panic loop
        loop { std::thread::sleep(Duration::from_secs(60)); }
    }
}

#[derive(thiserror::Error, Debug)]
enum InitError {
    #[error("io: {0}")] Io(#[from] std::io::Error),
    #[error("nix: {0}")] Nix(#[from] nix::Error),
    #[error("serde: {0}")] Serde(#[from] serde_json::Error),
    #[error("other: {0}")] Other(String),
}

fn init_main() -> Result<(), InitError> {
    // Ensure basic fs hierarchy
    fs::create_dir_all("/proc");
    fs::create_dir_all("/sys");
    fs::create_dir_all("/dev");
    fs::create_dir_all("/run/sysx");
    fs::create_dir_all("/var/log/sysx");

    // Mount essential virtual filesystems
    safe_mount("proc", "/proc", MsFlags::MS_NOEXEC | MsFlags::MS_NOSUID | MsFlags::MS_NODEV, Some("proc"))?;
    safe_mount("sysfs", "/sys", MsFlags::MS_NOEXEC | MsFlags::MS_NOSUID | MsFlags::MS_NODEV, Some("sysfs"))?;
    safe_mount("devtmpfs", "/dev", MsFlags::empty(), Some("devtmpfs")).or_else(|_| safe_mount("tmpfs", "/dev", MsFlags::empty(), Some("mode=0755")))?;
    // /dev/pts for pty support
    fs::create_dir_all("/dev/pts")?;
    safe_mount("devpts", "/dev/pts", MsFlags::MS_NOEXEC | MsFlags::MS_NOSUID, Some("gid=5,mode=0620"))?;
    // /dev/shm
    fs::create_dir_all("/dev/shm")?;
    safe_mount("tmpfs", "/dev/shm", MsFlags::MS_NOEXEC | MsFlags::MS_NOSUID, Some("mode=1777"))?;

    // Optional: uevent handler (no dbus). If mdev exists, run once to populate /dev
    if Path::new("/sbin/mdev").exists() {
        let _ = Command::new("/sbin/mdev").arg("-s").status();
    }

    // Run fsck (skip root if mounted rw; typically kernel mounts root ro then remount rw)
    run_fsck_all()?;

    // Mount remaining filesystems from /etc/fstab
    run_mount_all()?;

    // Bring up networking using iproute2; assumes simple DHCP via busybox udhcpc if present
    bring_up_loopback()?;
    bring_up_first_iface()?;

    // Load tasks configuration, start supervised tasks (e.g., getty)
    let specs = load_task_specs()?;
    let mut state = load_state();

    // Spawn supervisor thread
    supervisor(specs, &mut state)?;

    // Reap zombies and wait forever
    reap_loop();
    Ok(())
}

fn safe_mount(src: &str, tgt: &str, flags: MsFlags, fstype_or_opts: Option<&str>) -> Result<(), InitError> {
    let (fstype, data): (Option<&str>, Option<&str>) = match src {
        "proc" | "sysfs" | "devtmpfs" | "devpts" | "tmpfs" => (Some(src), fstype_or_opts),
        _ => (None, fstype_or_opts),
    };
    let fstype_c = fstype.map(|s| std::ffi::CString::new(s).unwrap());
    let src_c = std::ffi::CString::new(src).unwrap();
    let tgt_c = std::ffi::CString::new(tgt).unwrap();
    let data_c = data.map(|s| std::ffi::CString::new(s).unwrap());

    let res = unsafe {
        mount(
            Some(&src_c),
            &tgt_c,
            fstype_c.as_ref().map(|c| c.as_c_str()),
            flags,
            data_c.as_ref().map(|c| c.as_c_str()),
        )
    };
    match res {
        Ok(_) => Ok(()),
        Err(e) if e == nix::Error::from(Errno::EBUSY) => Ok(()), // already mounted
        Err(e) => Err(InitError::Nix(e)),
    }
}

fn run_fsck_all() -> Result<(), InitError> {
    // Conservative: run fsck -A -T -a; ignore non-zero for clean filesystems (exit 0/1 ok)
    if Path::new("/sbin/fsck").exists() {
        let status = Command::new("/sbin/fsck").args(["-A", "-T", "-a"]).status()?;
        // Status codes: 0/1 ok, 2 errors corrected, 4 errors uncorrected
        if let Some(code) = status.code() {
            if code == 4 { return Err(InitError::Other("fsck reported uncorrected errors".into())); }
        }
    }
    Ok(())
}

fn run_mount_all() -> Result<(), InitError> {
    let status = Command::new("/bin/mount").args(["-a"]).status()?;
    if !status.success() { return Err(InitError::Other("mount -a failed".into())); }
    Ok(())
}

fn bring_up_loopback() -> Result<(), InitError> {
    let _ = Command::new("/sbin/ip").args(["link", "set", "lo", "up"]).status();
    let _ = Command::new("/sbin/ip").args(["addr", "add", "127.0.0.1/8", "dev", "lo"]).status();
    Ok(())
}

fn bring_up_first_iface() -> Result<(), InitError> {
    // List non-loopback interfaces via /sys (no dbus)
    let mut ifaces: Vec<String> = Vec::new();
    if let Ok(entries) = fs::read_dir("/sys/class/net") {
        for e in entries.flatten() {
            let name = e.file_name().into_string().unwrap_or_default();
            if name != "lo" { ifaces.push(name); }
        }
    }
    if let Some(iface) = ifaces.get(0) {
        let _ = Command::new("/sbin/ip").args(["link", "set", iface, "up"]).status();
        // Try DHCP via busybox udhcpc if present; otherwise leave up
        if Path::new("/sbin/udhcpc").exists() {
            let _ = Command::new("/sbin/udhcpc").args(["-i", iface, "-q", "-n"]).status();
        }
    }
    Ok(())
}

fn load_task_specs() -> Result<Vec<TaskSpec>, InitError> {
    // Provide a default getty on tty1 if no config exists
    if !Path::new(TASKS_FILE).exists() {
        let default = vec![TaskSpec {
            name: "getty-tty1".into(),
            cmd: vec![find_getty(), "--noclear".into(), "tty1".into(), "115200".into()],
            restart: RestartPolicy::Always,
            stdout_log: "/var/log/sysx/getty-tty1.out".into(),
            stderr_log: "/var/log/sysx/getty-tty1.err".into(),
        }];
        fs::create_dir_all("/etc/sysx").ok();
        let _ = fs::write(TASKS_FILE, serde_json::to_vec_pretty(&default)?);
        return Ok(default);
    }
    let mut buf = String::new();
    File::open(TASKS_FILE)?.read_to_string(&mut buf)?;
    Ok(serde_json::from_str(&buf)?)
}

fn find_getty() -> String {
    for c in [
        "/sbin/agetty",
        "/bin/agetty",
        "/sbin/getty",
        "/bin/getty",
        "/sbin/busybox",
        "/bin/busybox",
    ] {
        if Path::new(c).exists() {
            if c.ends_with("busybox") { return format!("{} getty", c); }
            return c.into();
        }
    }
    // Fallback name (may fail at spawn time)
    "/sbin/agetty".into()
}

fn load_state() -> RuntimeState {
    if let Ok(mut f) = File::open(STATE_FILE) {
        let mut s = String::new();
        if f.read_to_string(&mut s).is_ok() {
            if let Ok(st) = serde_json::from_str(&s) { return st; }
        }
    }
    RuntimeState::default()
}

fn save_state(st: &RuntimeState) {
    if let Ok(mut f) = OpenOptions::new().create(true).write(true).truncate(true).open(STATE_FILE) {
        let _ = f.write_all(serde_json::to_string_pretty(st).unwrap_or_default().as_bytes());
    }
}

fn supervisor(specs: Vec<TaskSpec>, state: &mut RuntimeState) -> Result<(), InitError> {
    // Start all configured tasks
    for spec in specs.iter() {
        start_task(spec, state)?;
    }
    save_state(state);

    // Supervision loop runs in background thread
    std::thread::spawn(move || {
        loop {
            match waitpid(None, Some(WaitPidFlag::WNOHANG)) {
                Ok(WaitStatus::Exited(pid, status)) | Ok(WaitStatus::Signaled(pid, _, _)) => {
                    // Find which task died
                    // Reload state and tasks each iteration to stay consistent
                    let mut st = load_state();
                    let specs = load_task_specs().unwrap_or_default();
                    let mut maybe_task: Option<TaskSpec> = None;
                    let mut task_name = String::new();
                    for (name, p) in st.pids.clone() {
                        if p == pid.as_raw() { task_name = name; break; }
                    }
                    if !task_name.is_empty() {
                        for s in specs {
                            if s.name == task_name { maybe_task = Some(s); break; }
                        }
                    }
                    if let Some(spec) = maybe_task {
                        st.pids.remove(&spec.name);
                        let crashes = st.crashes.entry(spec.name.clone()).or_insert(0);
                        *crashes += 1;
                        save_state(&st);
                        handle_restart(&spec, &mut st);
                    }
                }
                Ok(WaitStatus::StillAlive) | Err(_) => {
                    std::thread::sleep(Duration::from_millis(200));
                }
                _ => {}
            }
        }
    });

    Ok(())
}

fn start_task(spec: &TaskSpec, state: &mut RuntimeState) -> Result<(), InitError> {
    // Prepare logs
    let mut out = OpenOptions::new().create(true).append(true).open(&spec.stdout_log)?;
    let mut err = OpenOptions::new().create(true).append(true).open(&spec.stderr_log)?;
    let _ = fs::set_permissions(&spec.stdout_log, fs::Permissions::from_mode(0o640));
    let _ = fs::set_permissions(&spec.stderr_log, fs::Permissions::from_mode(0o640));

    // Support busybox getty form "busybox getty"
    let mut parts: Vec<String> = Vec::new();
    if !spec.cmd.is_empty() {
        let first = &spec.cmd[0];
        if first.ends_with("busybox") && spec.cmd.len() > 1 {
            parts.push(first.clone());
            parts.extend_from_slice(&spec.cmd[1..]);
        } else {
            parts = spec.cmd.clone();
        }
    }
    if parts.is_empty() { return Err(InitError::Other("empty cmd".into())); }

    match unsafe { fork() }? {
        ForkResult::Child => {
            // Redirect stdout/stderr
            let _ = nix::unistd::dup2(out.as_raw_fd(), 1);
            let _ = nix::unistd::dup2(err.as_raw_fd(), 2);
            // Make child its own session leader for TTY handling
            let _ = nix::unistd::setsid();
            // Exec
            let prog = &parts[0];
            let args: Vec<&str> = parts.iter().skip(1).map(|s| s.as_str()).collect();
            // Use sh -c if command contains space within busybox fallback
            if prog.ends_with("busybox") && args.first() == Some(&"getty") {
                let _ = Command::new(prog).args(&args).status();
                std::process::exit(127);
            } else {
                let err = nix::unistd::execvp(&std::ffi::CString::new(prog.as_str()).unwrap(),
                    &parts.iter().map(|s| std::ffi::CString::new(s.as_str()).unwrap()).collect::<Vec<_>>()
                        .iter().map(|c| c.as_c_str()).collect::<Vec<_>>());
                match err { _ => std::process::exit(127) }
            }
        }
        ForkResult::Parent { child } => {
            state.pids.insert(spec.name.clone(), child.as_raw());
            save_state(state);
            writeln!(out, "[sysx] started pid {}", child).ok();
        }
    }
    Ok(())
}

fn handle_restart(spec: &TaskSpec, state: &mut RuntimeState) {
    match &spec.restart {
        RestartPolicy::Never => {}
        RestartPolicy::Always => {
            std::thread::sleep(Duration::from_secs(1));
            let _ = start_task(spec, state);
        }
        RestartPolicy::OnFailure { max_retries, backoff_secs } => {
            let count = *state.crashes.get(&spec.name).unwrap_or(&0);
            if max_retries.map(|m| count <= m).unwrap_or(true) {
                std::thread::sleep(Duration::from_secs(*backoff_secs));
                let _ = start_task(spec, state);
            }
        }
    }
}

fn reap_loop() {
    loop {
        match waitpid(None, None) {
            Ok(WaitStatus::Exited(_, _)) | Ok(WaitStatus::Signaled(_, _, _)) | Ok(WaitStatus::StillAlive) => {}
            Err(_) => {}
        }
    }
}

// ------------------ sysx CLI ------------------
// Usage examples:
//   sysx cli list
//   sysx cli start getty-tty1
//   sysx cli stop getty-tty1
//   sysx cli status

fn cli(args: &[String]) {
    match args.get(0).map(|s| s.as_str()) {
        Some("list") => {
            let specs = load_task_specs().unwrap_or_default();
            for s in specs { println!("{} => {:?}", s.name, s.cmd); }
        }
        Some("status") => {
            let st = load_state();
            for (name, pid) in st.pids { println!("{} pid={}", name, pid); }
        }
        Some("start") => {
            if let Some(name) = args.get(1) {
                let mut specs = load_task_specs().unwrap_or_default();
                let mut st = load_state();
                if let Some(spec) = specs.iter().find(|s| &s.name == name).cloned() {
                    if st.pids.contains_key(name) {
                        println!("{} already running (pid={})", name, st.pids[name]);
                    } else {
                        if let Err(e) = start_task(&spec, &mut st) { eprintln!("start failed: {}", e); }
                        save_state(&st);
                    }
                } else { eprintln!("task not found: {}", name); }
            } else { eprintln!("usage: sysx cli start <task>"); }
        }
        Some("stop") => {
            if let Some(name) = args.get(1) {
                let mut st = load_state();
                if let Some(pid) = st.pids.get(name).copied() {
                    let _ = kill(Pid::from_raw(pid), Signal::SIGTERM);
                    // Grace period, then SIGKILL
                    let start = Instant::now();
                    loop {
                        match waitpid(Pid::from_raw(pid), Some(WaitPidFlag::WNOHANG)) {
                            Ok(WaitStatus::StillAlive) | Err(_) => {
                                if start.elapsed() > Duration::from_secs(5) { break; }
                                std::thread::sleep(Duration::from_millis(100));
                            }
                            _ => break,
                        }
                    }
                    let _ = kill(Pid::from_raw(pid), Signal::SIGKILL);
                    st.pids.remove(name);
                    save_state(&st);
                    println!("stopped {}", name);
                } else { eprintln!("{} not running", name); }
            } else { eprintln!("usage: sysx cli stop <task>"); }
        }
        _ => {
            eprintln!("sysx CLI usage:\n  sysx cli list\n  sysx cli status\n  sysx cli start <task>\n  sysx cli stop <task>");
        }
    }
}

Below is a single-crate, compilable Rust example of a minimal 'sysx' init and CLI for Devuan that:
- Runs as PID 1 (init mode) when executed as /sbin/init or pid=1 in a container/VM
- Mounts /proc, /sys, /dev; runs fsck; mounts filesystems
- Brings up networking (via iproute2 and ifupdown if present)
- Spawns a login getty on tty1
- Supervises tasks with restart policies and logs stdout/stderr
- Provides a simple 'sysx' CLI for list/start/stop/status
- Avoids systemd/sysvinit, dbus, X (x11/xorg/xinit/xorg), elogind, and systemctl

Notes:
- Uses only standard userspace tools available on minimal Devuan (mount, fsck, ip, ifup, ifconfig, route, agetty/login or busybox alternatives). Adjust commands/paths to your system.
- Uses nix crate for low-level syscalls and libc for setsid.
- For a real system, add proper error handling, udev or mdev as needed, multiple TTYs, and secure logging.

