}

#[derive(Debug, Serialize, Deserialize)]
pub struct TaskInfo {
    pub name: String,
    pub pid: Option<i32>,
    pub running: bool,
    pub restarts: u32,
    pub command: Vec<String>,
    pub log_path: String,
}

#[derive(Debug, Serialize, Deserialize)]
