use nix::libc;
use nix::mount::{mount, MsFlags};
use nix::sys::signal::{self, SigSet, Signal};
use nix::sys::wait::{waitpid, WaitPidFlag, WaitStatus};
use nix::unistd::{chdir, fork, getpid, setsid, ForkResult, Pid};
use serde_json::{from_slice, to_vec};
use std::collections::HashMap;
use std::fs::{create_dir_all, File, OpenOptions};
use std::io::{Read, Write};
use std::os::fd::{AsRawFd, FromRawFd, RawFd};
use std::os::unix::net::{UnixListener, UnixStream};
use std::os::unix::prelude::PermissionsExt;
use std::path::Path;
use std::process::Command;
use std::time::{Duration, Instant};

mod common;
use common::{Request, Response, TaskInfo, SOCK_PATH};

// Simple supervised task definition: command, restart policy, and state.
struct TaskDef {
    command: Vec<String>,
    restart: bool,
    restarts: u32,
    pid: Option<Pid>,
    log_path: String,
}

// Spawn a child with stdout/stderr redirected to a log file.
fn spawn_task(cmd: &[String], log_path: &str) -> Option<Pid> {
    if cmd.is_empty() { return None; }
    let log_file = OpenOptions::new().create(true).append(true).open(log_path).ok()?;
    unsafe {
        match fork() {
            Ok(ForkResult::Parent { child }) => Some(child),
            Ok(ForkResult::Child) => {
                // Create a fresh session for the service.
                let _ = setsid();
                // Redirect stdio to log.
                let fd = log_file.as_raw_fd();
                let _ = libc::dup2(fd, libc::STDOUT_FILENO);
                let _ = libc::dup2(fd, libc::STDERR_FILENO);
                // Exec the command.
                let c0 = std::ffi::CString::new(cmd[0].clone()).unwrap();
                let mut cargs: Vec<std::ffi::CString> = cmd.iter().map(|s| std::ffi::CString::new(s.as_str()).unwrap()).collect();
                // execvp requires args[0] = program name
                let mut argv: Vec<*const i8> = cargs.iter().map(|c| c.as_ptr()).collect();
                argv.push(std::ptr::null());
                libc::execvp(c0.as_ptr(), argv.as_ptr());
                // If exec fails:
                let _ = writeln!(std::io::stderr(), "exec failed: {}", cmd[0]);
                libc::_exit(127);
            }
            Err(_) => None,
        }
    }
}

// One-shot command helper used during boot steps; logs to console.
fn run_cmd(name: &str, args: &[&str]) -> std::io::Result<()> {
    let status = Command::new(name).args(args).status()?;
    if !status.success() {
        eprintln!("{name} {:?} exited with {status}", args);
    }
    Ok(())
}

fn mount_once(source: Option<&str>, target: &str, fstype: Option<&str>, flags: MsFlags, data: Option<&str>) {
    let src_c = source.map(|s| std::ffi::CString::new(s).unwrap());
    let tgt_c = std::ffi::CString::new(target).unwrap();
    let typ_c = fstype.map(|s| std::ffi::CString::new(s).unwrap());
    let dat_c = data.map(|s| std::ffi::CString::new(s).unwrap());
    if let Err(e) = unsafe {
        mount(
            src_c.as_ref().map(|c| c.as_c_str()),
            &tgt_c,
            typ_c.as_ref().map(|c| c.as_c_str()),
            flags,
            dat_c.as_ref().map(|c| c.as_c_str()),
        )
    } {
        eprintln!("mount {target} failed: {e}");
    }
}

// Basic signal-safe reaper loop utility: reap one child if available.
fn reap_one() -> Option<(Pid, i32)> {
    match waitpid(Pid::from_raw(-1), Some(WaitPidFlag::WNOHANG)) {
        Ok(WaitStatus::Exited(pid, status)) => Some((pid, status)),
        Ok(WaitStatus::Signaled(pid, sig, _)) => Some((pid, 128 + sig as i32)),
        Ok(WaitStatus::StillAlive) => None,
        Ok(_) => None,
        Err(_) => None,
    }
}

fn ensure_dirs() {
    let _ = create_dir_all("/run/sysx/logs");
    // Make socket dir writeable by root only.
    if let Ok(md) = std::fs::metadata("/run/sysx") { 
        let mut p = md.permissions();
        p.set_mode(0o755);
        let _ = std::fs::set_permissions("/run/sysx", p);
    }
}

fn setup_mounts_and_fs() {
    // Mount essential virtual filesystems early.
    let _ = create_dir_all("/proc");
    let _ = create_dir_all("/sys");
    let _ = create_dir_all("/dev");
    mount_once(None, "/proc", Some("proc"), MsFlags::empty(), None);
    mount_once(None, "/sys", Some("sysfs"), MsFlags::empty(), None);
    // devtmpfs usually mounted by kernel if CONFIG_DEVTMPFS_MOUNT, else do it here.
    mount_once(None, "/dev", Some("devtmpfs"), MsFlags::empty(), Some("mode=0755"));

    // Run filesystem checks (non-interactive). Adjust devices according to fstab.
    let _ = run_cmd("fsck", &["-A", "-T", "-t", "noopts=discard", "-a"]);

    // Mount all filesystems from fstab.
    let _ = run_cmd("mount", &["-a"]);
}

fn bring_up_networking() {
    // Minimal: try to bring up loopback and request DHCP on first non-lo.
    let _ = run_cmd("ip", &["link", "set", "lo", "up"]);

    // Attempt to auto-configure first interface (other than lo) using dhclient if present.
    if let Ok(output) = Command::new("sh").arg("-c").arg("ip -o link show | awk -F': ' '$2!="."lo" {print $2; exit}'").output() {
        if output.status.success() {
            let iface = String::from_utf8_lossy(&output.stdout).trim().to_string();
            if !iface.is_empty() {
                // Try ifup (if ifupdown configured), else dhclient.
                let tried_ifup = Command::new("which").arg("ifup").status().map(|s| s.success()).unwrap_or(false);
                if tried_ifup {
                    let _ = run_cmd("ifup", &[&iface]);
                } else if Command::new("which").arg("dhclient").status().map(|s| s.success()).unwrap_or(false) {
                    let _ = run_cmd("dhclient", &[&iface]);
                } else {
                    eprintln!("No ifup or dhclient found; interface {iface} not configured");
                }
            }
        }
    }
}

fn spawn_getty() -> Option<Pid> {
    // Use agetty on tty1; it will exec /bin/login.
    let log_path = "/run/sysx/logs/getty-tty1.log";
    spawn_task(&vec![
        "/sbin/agetty".into(),
        "--noclear".into(),
        "tty1".into(),
        "115200".into(),
        "linux".into(),
    ], log_path)
}

fn install_signal_handlers() {
    // Ignore SIGPIPE; handle SIGCHLD by using a self-pipe/select loop approach below.
    let _ = unsafe { signal::signal(Signal::SIGPIPE, signal::SigHandler::SigIgn) };
}

fn serve_control_socket(tasks: &HashMap<String, TaskDef>) -> std::io::Result<UnixListener> {
    // Create /run and /run/sysx for socket and logs.
    let _ = create_dir_all("/run");
    let _ = create_dir_all("/run/sysx");
    ensure_dirs();
    if Path::new(SOCK_PATH).exists() { let _ = std::fs::remove_file(SOCK_PATH); }
    let listener = UnixListener::bind(SOCK_PATH)?;
    // Restrict permissions: rw for owner.
    let _ = std::fs::set_permissions(SOCK_PATH, std::fs::Permissions::from_mode(0o600));
    Ok(listener)
}

fn handle_client(mut stream: UnixStream, tasks: &mut HashMap<String, TaskDef>) {
    let mut buf = Vec::new();
    if let Ok(_) = stream.read_to_end(&mut buf) {
        if buf.is_empty() { return; }
        match from_slice::<Request>(&buf) {
            Ok(Request::List) => {
                let list: Vec<TaskInfo> = tasks.iter().map(|(name, t)| TaskInfo {
                    name: name.clone(),
                    pid: t.pid.map(|p| p.as_raw()),
                    running: t.pid.is_some(),
                    restarts: t.restarts,
                    command: t.command.clone(),
                    log_path: t.log_path.clone(),
                }).collect();
                let _ = stream.write_all(&to_vec(&Response::List(list)).unwrap());
            }
            Ok(Request::Start { name }) => {
                let resp = if let Some(t) = tasks.get_mut(&name) {
                    if t.pid.is_none() {
                        if let Some(pid) = spawn_task(&t.command, &t.log_path) { t.pid = Some(pid); }
                        Response::Ok
                    } else { Response::Error("already running".into()) }
                } else { Response::Error("unknown task".into()) };
                let _ = stream.write_all(&to_vec(&resp).unwrap());
            }
            Ok(Request::Stop { name }) => {
                let resp = if let Some(t) = tasks.get_mut(&name) {
                    if let Some(pid) = t.pid { let _ = signal::kill(pid, Signal::SIGTERM); }
                    Response::Ok
                } else { Response::Error("unknown task".into()) };
                let _ = stream.write_all(&to_vec(&resp).unwrap());
            }
            Err(e) => {
                let _ = stream.write_all(&to_vec(&Response::Error(format!("bad request: {e}"))).unwrap());
            }
        }
    }
}

fn main() {
    // Must be PID 1 to act as init.
    if getpid().as_raw() != 1 {
        eprintln!("sysx-init must run as PID 1");
    }
    // Become session leader, chdir to root.
    let _ = setsid();
    let _ = chdir("/");
    install_signal_handlers();

    // Boot sequence: mount core filesystems, fsck, mount -a, networking.
    setup_mounts_and_fs();
    bring_up_networking();

    // Define managed tasks: agetty on tty1 and an example long-running logger (optional).
    let mut tasks: HashMap<String, TaskDef> = HashMap::new();
    tasks.insert("getty-tty1".into(), TaskDef {
        command: vec!["/sbin/agetty".into(), "--noclear".into(), "tty1".into(), "115200".into(), "linux".into()],
        restart: true, // restart on exit
        restarts: 0,
        pid: None,
        log_path: "/run/sysx/logs/getty-tty1.log".into(),
    });

    // Start default tasks.
    if let Some(t) = tasks.get_mut("getty-tty1") {
        t.pid = spawn_task(&t.command, &t.log_path);
    }

    // Control socket server for CLI.
    let listener = serve_control_socket(&tasks).expect("control socket");
    listener.set_nonblocking(true).ok();

    // Main supervision loop: accept control requests, reap children, apply restart policy.
    let mut last_check = Instant::now();
    loop {
        // 1) Handle incoming CLI connections.
        match listener.accept() {
            Ok((stream, _addr)) => {
                handle_client(stream, &mut tasks);
            }
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => { /* no client now */ }
            Err(e) => { eprintln!("socket accept error: {e}"); }
        }

        // 2) Reap children if any exited.
        while let Some((pid, status)) = reap_one() {
            // Map pid back to task.
            for (_name, t) in tasks.iter_mut() {
                if t.pid == Some(pid) {
                    let _ = append_log(&t.log_path, &format!("\n[sysx-init] task exited pid={} status={}\n", pid, status));
                    t.pid = None;
                    t.restarts = t.restarts.saturating_add(1);
                }
            }
        }

        // 3) Apply restart policy with a small backoff.
        if last_check.elapsed() > Duration::from_millis(500) {
            for (_name, t) in tasks.iter_mut() {
                if t.pid.is_none() && t.restart {
                    // naive backoff: don't spin too fast; allow a short pause
                    let _ = std::thread::sleep(Duration::from_millis(50));
                    t.pid = spawn_task(&t.command, &t.log_path);
                }
            }
            last_check = Instant::now();
        }

        // 4) Idle briefly to reduce CPU usage.
        std::thread::sleep(Duration::from_millis(50));
    }
}

fn append_log(path: &str, msg: &str) -> std::io::Result<()> {
    let mut f = OpenOptions::new().create(true).append(true).open(path)?;
    f.write_all(msg.as_bytes())
}

src/cli.rs (sysx CLI):

use serde_json::{from_slice, to_vec};
use std::env;
use std::io::{Read, Write};
use std::os::unix::net::UnixStream;

mod common;
use common::{Request, Response, SOCK_PATH};

fn usage() {
    eprintln!("sysx - simple controller for sysx-init\n\nCommands:\n  sysx list\n  sysx start <task>\n  sysx stop <task>\n");
}

fn send(req: &Request) -> std::io::Result<Response> {
    let mut s = UnixStream::connect(SOCK_PATH)?;
    s.write_all(&to_vec(req).unwrap())?;
    s.shutdown(std::net::Shutdown::Write)?;
    let mut buf = Vec::new();
    s.read_to_end(&mut buf)?;
    Ok(from_slice(&buf).unwrap_or(Response::Error("bad reply".into())))
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { usage(); return; }
    let resp = match args[1].as_str() {
        "list" => send(&Request::List),
        "start" if args.len() >= 3 => send(&Request::Start { name: args[2].clone() }),
        "stop" if args.len() >= 3 => send(&Request::Stop { name: args[2].clone() }),
        _ => { usage(); return; }
    };
    match resp {
        Ok(Response::Ok)) => println!("ok"),
        Ok(Response::List(list)) => {
            for t in list {
                println!("{}\trunning={}\tpid={:?}\trestarts={}\tcmd={:?}\tlog={}",
                    t.name, t.running, t.pid, t.restarts, t.command, t.log_path);
            }
        }
        Ok(Response::Error(e)) => eprintln!("error: {e}"),
        Err(e) => eprintln!("io error: {e}"),
    }
}

