use nix::errno::Errno;
use nix::mount::{mount, umount2, MntFlags, MsFlags};
use nix::sys::signal::{kill, Signal};
use nix::sys::stat::{mknod, Mode, SFlag};
use nix::sys::wait::{waitpid, WaitPidFlag, WaitStatus};
use nix::unistd::{chdir, dup2, execv, fork, getpid, getppid, mkfifo, sethostname, setsid, ForkResult, Pid};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::env;
use std::ffi::CString;
use std::fs::{self, File, OpenOptions};
use std::io::{BufRead, BufReader, Read, Write};
use std::os::fd::{AsRawFd, FromRawFd, IntoRawFd, RawFd};
use std::os::unix::fs::PermissionsExt;
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

// -----------------------------
// Types and task supervision
// -----------------------------
#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
enum RestartPolicy {
    Never,
    OnFailure,
    Always,
}

#[derive(Clone, Debug)]
struct TaskSpec {
    name: String,
    cmd: Vec<String>,
    restart: RestartPolicy,
    autostart: bool,
    log_path: PathBuf,
}

#[derive(Clone, Debug, Serialize)]
#[serde(tag = "state", content = "data")]
enum TaskRunState {
    Starting,
    Running(i32),
    Stopped,
    Crashed(Option<i32>), // exit code or None if signal
}

#[derive(Debug)]
struct TaskRuntime {
    spec: TaskSpec,
    state: TaskRunState,
    pid: Option<Pid>,
    crashes: u32,
}

impl TaskRuntime {
    fn new(spec: TaskSpec) -> Self {
        Self { spec, state: TaskRunState::Stopped, pid: None, crashes: 0 }
    }
}

// -----------------------------
// Global state
// -----------------------------
struct State {
    tasks: HashMap<String, TaskRuntime>,
}

impl State {
    fn new() -> Self {
        Self { tasks: HashMap::new() }
    }
}

type SharedState = Arc<Mutex<State>>;

// -----------------------------
// Utility helpers
// -----------------------------
fn log_console(msg: &str) {
    let _ = File::create("/dev/console").and_then(|mut f| writeln!(f, "[sysx] {}", msg));
}

fn run_cmd_log(cmd: &str, args: &[&str]) -> std::io::Result<i32> {
    log_console(&format!("run: {} {}", cmd, args.join(" ")));
    let status = Command::new(cmd).args(args).status();
    match status {
        Ok(s) => Ok(s.code().unwrap_or_default()),
        Err(e) => Err(e),
    }
}

fn ensure_dir(p: &Path, mode: u32) {
    if let Err(e) = fs::create_dir_all(p) { log_console(&format!("mkdir {:?}: {}", p, e)); }
    let _ = fs::set_permissions(p, fs::Permissions::from_mode(mode));
}

fn write_file(path: &str, content: &str) {
    if let Err(e) = fs::write(path, content) { log_console(&format!("write {}: {}", path, e)); }
}

// -----------------------------
// Early init: mount, fsck, fstab, networking
// -----------------------------
fn mount_early() {
    // Create essential mount points
    for d in ["/proc", "/sys", "/dev", "/run"].iter() {
        ensure_dir(Path::new(d), 0o755);
    }

    // Mount proc
    let _ = mount(Some("proc"), "/proc", Some("proc"), MsFlags::empty(), None::<&str>);

    // Mount sysfs
    let _ = mount(Some("sysfs"), "/sys", Some("sysfs"), MsFlags::empty(), None::<&str>);

    // Mount devtmpfs
    let _ = mount(Some("udev"), "/dev", Some("devtmpfs"), MsFlags::empty(), Some("mode=0755,nosuid"));

    // Ensure /dev/console exists (important for PID1 logging)
    if !Path::new("/dev/console").exists() {
        let _ = mknod(Path::new("/dev/console"), SFlag::S_IFCHR, Mode::from_bits_truncate(0o600), nix::sys::stat::makedev(5, 1));
    }
}

fn run_fsck_and_mounts() {
    // Attempt fsck for all filesystems from fstab (except root ro pass; fsck -A does this)
    // Run in preen mode (-A -T -a). If unavailable, fall back to -p.
    let _ = run_cmd_log("/sbin/fsck", &["-ATa"]).or_else(|_| run_cmd_log("/sbin/fsck", &["-ATp"]));

    // Remount root read-write
    let _ = run_cmd_log("/bin/mount", &["-o", "remount,rw", "/"]);

    // Mount everything from /etc/fstab (except noauto)
    let _ = run_cmd_log("/bin/mount", &["-a"]);
}

fn bring_up_networking() {
    // Loopback
    let _ = run_cmd_log("/sbin/ip", &["link", "set", "lo", "up"]).or_else(|_| run_cmd_log("/sbin/ifconfig", &["lo", "up"])) ;
    // Try distro tooling if present
    if Path::new("/sbin/ifup").exists() {
        let _ = run_cmd_log("/sbin/ifup", &["-a"]);
        return;
    }
    // Fallback: try to bring up first non-lo interface with DHCP if udhcpc exists
    if let Ok(entries) = fs::read_dir("/sys/class/net") {
        for e in entries.flatten() {
            let name = e.file_name().into_string().unwrap_or_default();
            if name == "lo" { continue; }
            let _ = run_cmd_log("/sbin/ip", &["link", "set", &name, "up"]).or_else(|_| run_cmd_log("/sbin/ifconfig", &[&name, "up"])) ;
            if Path::new("/sbin/udhcpc").exists() || Path::new("/usr/sbin/udhcpc").exists() {
                let dhcp = if Path::new("/sbin/udhcpc").exists() { "/sbin/udhcpc" } else { "/usr/sbin/udhcpc" };
                let _ = run_cmd_log(dhcp, &["-i", &name, "-q", "-t", "3", "-n"]);
            }
            break;
        }
    }
}

// -----------------------------
// Task supervision and logging
// -----------------------------
fn open_log(path: &Path) -> Option<File> {
    if let Some(parent) = path.parent() { ensure_dir(parent, 0o755); }
    match OpenOptions::new().create(true).append(true).open(path) {
        Ok(f) => Some(f),
        Err(e) => { log_console(&format!("log open {:?}: {}", path, e)); None }
    }
}

fn spawn_task(rt: &mut TaskRuntime) {
    let cmd = if rt.spec.cmd.is_empty() { return; } else { rt.spec.cmd.clone() };
    let prog = &cmd[0];
    let args = &cmd[1..];

    // Prepare logging
    let mut logf = open_log(&rt.spec.log_path);
    if let Some(f) = logf.as_mut() {
        let _ = writeln!(f, "==== starting {:?} at {:?} ====", cmd, chrono_ts());
    }

    match unsafe { fork() } {
        Ok(ForkResult::Parent { child }) => {
            rt.pid = Some(child);
            rt.state = TaskRunState::Starting;
        }
        Ok(ForkResult::Child) => {
            // Detach into own session so SIGHUP of init won't kill it
            let _ = setsid();

            // Redirect stdio to log file (or /dev/null as fallback)
            let (stdin_fd, stdout_fd, stderr_fd) = if let Some(mut f) = logf.take() {
                let fd = f.into_raw_fd();
                (fd, fd, fd)
            } else if let Ok(null) = OpenOptions::new().read(true).write(true).open("/dev/null") {
                let fd = null.into_raw_fd();
                (fd, fd, fd)
            } else { (0, 1, 2) };
            let _ = dup2(stdin_fd, 0);
            let _ = dup2(stdout_fd, 1);
            let _ = dup2(stderr_fd, 2);

            // Exec
            let cprog = CString::new(prog.as_str()).unwrap();
            let cargs: Vec<CString> = std::iter::once(prog.clone()).chain(args.iter().cloned()).map(|s| CString::new(s).unwrap()).collect();
            let _ = execv(&cprog, &cargs);
            // If exec fails
            let _ = writeln!(std::io::stderr(), "exec failed for {:?}", cmd);
            std::process::exit(127);
        }
        Err(e) => {
            rt.state = TaskRunState::Crashed(None);
            log_console(&format!("fork failed for {}: {}", rt.spec.name, e));
        }
    }
}

fn supervise_loop(state: SharedState) {
    loop {
        // Reap children
        match waitpid(Pid::from_raw(-1), Some(WaitPidFlag::WNOHANG)) {
            Ok(WaitStatus::Exited(pid, code)) => {
                handle_exit(state.clone(), pid, Some(code));
            }
            Ok(WaitStatus::Signaled(pid, _sig, _core)) => {
                handle_exit(state.clone(), pid, None);
            }
            Ok(WaitStatus::StillAlive) | Ok(_) | Err(Errno::ECHILD) => {
                // No children to reap now
            }
            Err(e) => {
                log_console(&format!("waitpid error: {}", e));
            }
        }
        thread::sleep(Duration::from_millis(200));
    }
}

fn handle_exit(state: SharedState, pid: Pid, code: Option<i32>) {
    let mut to_restart: Option<String> = None;
    {
        let mut st = state.lock().unwrap();
        for (name, rt) in st.tasks.iter_mut() {
            if rt.pid == Some(pid) {
                match code {
                    Some(0) => {
                        rt.state = TaskRunState::Stopped;
                        rt.crashes = 0;
                    }
                    Some(c) => {
                        rt.state = TaskRunState::Crashed(Some(c));
                        rt.crashes = rt.crashes.saturating_add(1);
                    }
                    None => {
                        rt.state = TaskRunState::Crashed(None);
                        rt.crashes = rt.crashes.saturating_add(1);
                    }
                }
                // Decide restart policy now but act after unlocking
                match rt.spec.restart {
                    RestartPolicy::Always => to_restart = Some(name.clone()),
                    RestartPolicy::OnFailure => if code.unwrap_or(1) != 0 { to_restart = Some(name.clone()) },
                    RestartPolicy::Never => {}
                }
                rt.pid = None;
                break;
            }
        }
    }
    if let Some(name) = to_restart {
        thread::spawn({
            let state = state.clone();
            move || {
                thread::sleep(Duration::from_secs(1));
                let mut st = state.lock().unwrap();
                if let Some(rt) = st.tasks.get_mut(&name) { spawn_task(rt); }
            }
        });
    }
}

// -----------------------------
// Control socket and CLI
// -----------------------------
#[derive(Serialize, Deserialize)]
#[serde(tag = "cmd", content = "data")]
enum CtlReq {
    List,
    Start { name: String },
    Stop { name: String },
}

#[derive(Serialize, Deserialize)]
#[serde(tag = "kind", content = "data")]
enum CtlResp {
    Ok,
    Err(String),
    List(Vec<(String, TaskRunState)>),
}

const CTL_SOCK: &str = "/run/sysx/sysx.sock";

fn ctl_server(state: SharedState) {
    ensure_dir(Path::new("/run/sysx"), 0o755);
    // Remove any stale socket
    let _ = fs::remove_file(CTL_SOCK);
    let listener = match UnixListener::bind(CTL_SOCK) {
        Ok(l) => l,
        Err(e) => {
            log_console(&format!("ctl bind failed: {}", e));
            return;
        }
    };
    // Restrict permissions
    let _ = fs::set_permissions(CTL_SOCK, fs::Permissions::from_mode(0o660));

    for stream in listener.incoming() {
        match stream {
            Ok(mut s) => {
                let st = state.clone();
                thread::spawn(move || {
                    let mut buf = String::new();
                    let _ = s.read_to_string(&mut buf);
                    let resp = handle_ctl(&st, &buf);
                    let _ = s.write_all(resp.as_bytes());
                });
            }
            Err(e) => {
                log_console(&format!("ctl accept err: {}", e));
            }
        }
    }
}

fn handle_ctl(state: &SharedState, req_json: &str) -> String {
    let req: Result<CtlReq, _> = serde_json::from_str(req_json);
    match req {
        Ok(CtlReq::List) => {
            let st = state.lock().unwrap();
            let mut out = Vec::new();
            for (name, rt) in st.tasks.iter() {
                out.push((name.clone(), rt.state.clone()));
            }
            serde_json::to_string(&CtlResp::List(out)).unwrap()
        }
        Ok(CtlReq::Start { name }) => {
            let mut st = state.lock().unwrap();
            if let Some(rt) = st.tasks.get_mut(&name) {
                if rt.pid.is_none() {
                    spawn_task(rt);
                    serde_json::to_string(&CtlResp::Ok).unwrap()
                } else {
                    serde_json::to_string(&CtlResp::Err("already running".into())).unwrap()
                }
            } else {
                serde_json::to_string(&CtlResp::Err("unknown task".into())).unwrap()
            }
        }
        Ok(CtlReq::Stop { name }) => {
            let mut st = state.lock().unwrap();
            if let Some(rt) = st.tasks.get_mut(&name) {
                if let Some(pid) = rt.pid {
                    let _ = kill(pid, Signal::SIGTERM);
                    serde_json::to_string(&CtlResp::Ok).unwrap()
                } else {
                    serde_json::to_string(&CtlResp::Err("not running".into())).unwrap()
                }
            } else {
                serde_json::to_string(&CtlResp::Err("unknown task".into())).unwrap()
            }
        }
        Err(e) => serde_json::to_string(&CtlResp::Err(format!("bad request: {}", e))).unwrap(),
    }
}

fn cli_client(args: &[String]) -> i32 {
    // CLI usage: sysx list | sysx start <task> | sysx stop <task>
    let req = match args.get(1).map(|s| s.as_str()) {
        Some("list") => CtlReq::List,
        Some("start") => {
            let name = args.get(2).cloned().unwrap_or_default();
            if name.is_empty() { eprintln!("usage: sysx start <task>"); return 2; }
            CtlReq::Start { name }
        }
        Some("stop") => {
            let name = args.get(2).cloned().unwrap_or_default();
            if name.is_empty() { eprintln!("usage: sysx stop <task>"); return 2; }
            CtlReq::Stop { name }
        }
        _ => {
            eprintln!("usage: sysx <list|start|stop> [task]");
            return 2;
        }
    };

    match UnixStream::connect(CTL_SOCK) {
        Ok(mut s) => {
            let body = serde_json::to_string(&req).unwrap();
            if let Err(e) = s.write_all(body.as_bytes()) { eprintln!("write: {}", e); return 1; }
            let mut resp = String::new();
            if let Err(e) = s.read_to_string(&mut resp) { eprintln!("read: {}", e); return 1; }
            match serde_json::from_str::<CtlResp>(&resp) {
                Ok(CtlResp::Ok) => { println!("ok"); 0 }
                Ok(CtlResp::Err(e)) => { eprintln!("error: {}", e); 1 }
                Ok(CtlResp::List(list)) => {
                    for (name, state) in list { println!("{}\t{:?}", name, state); }
                    0
                }
                Err(e) => { eprintln!("decoding: {}", e); 1 }
            }
        }
        Err(e) => { eprintln!("connect: {}", e); 1 }
    }
}

// -----------------------------
// Getty task
// -----------------------------
fn getty_cmd() -> Vec<String> {
    // Prefer /sbin/agetty if present; otherwise fallback to busybox getty
    let agetty = if Path::new("/sbin/agetty").exists() { "/sbin/agetty" } else if Path::new("/bin/agetty").exists() { "/bin/agetty" } else { "/sbin/getty" };
    vec![agetty.into(), "--noclear".into(), "tty1".into(), "115200".into(), "linux".into()]
}

// -----------------------------
// Timestamps for logs
// -----------------------------
fn chrono_ts() -> String {
    // Minimal timestamp without external crates to keep deps small
    let now = std::time::SystemTime::now();
    let secs = now.duration_since(std::time::UNIX_EPOCH).map(|d| d.as_secs()).unwrap_or(0);
    format!("{}", secs)
}

// -----------------------------
// PID 1 main logic
// -----------------------------
fn pid1_main() -> i32 {
    // Set a hostname if none
    let _ = sethostname("devuan");

    // Early mounts
    mount_early();

    // Redirect our stdout/stderr to console so early logs are visible
    if let Ok(mut cons) = OpenOptions::new().write(true).open("/dev/console") {
        let _ = writeln!(cons, "[sysx] init starting (pid {})", getpid());
    }

    // Filesystems
    run_fsck_and_mounts();

    // Networking
    bring_up_networking();

    // State and tasks
    let state: SharedState = Arc::new(Mutex::new(State::new()));

    // Define built-in tasks. Add your own services here.
    {
        let mut st = state.lock().unwrap();
        // tty1 getty
        let getty = TaskSpec {
            name: "getty-tty1".into(),
            cmd: getty_cmd(),
            restart: RestartPolicy::Always,
            autostart: true,
            log_path: PathBuf::from("/var/log/sysx/getty-tty1.log"),
        };
        st.tasks.insert(getty.name.clone(), TaskRuntime::new(getty));

        // Example: syslog (optional, only if present). Not a requirement; kept simple and local.
        if Path::new("/sbin/rsyslogd").exists() {
            let syslog = TaskSpec {
                name: "rsyslogd".into(),
                cmd: vec!["/sbin/rsyslogd".into(), "-n".into()], // -n no-daemon, so we can supervise
                restart: RestartPolicy::OnFailure,
                autostart: true,
                log_path: PathBuf::from("/var/log/sysx/rsyslogd.log"),
            };
            st.tasks.insert(syslog.name.clone(), TaskRuntime::new(syslog));
        }
    }

    // Start control server
    {
        let st = state.clone();
        thread::spawn(move || ctl_server(st));
    }

    // Autostart tasks
    {
        let mut st = state.lock().unwrap();
        for (_name, rt) in st.tasks.iter_mut() {
            if rt.spec.autostart { spawn_task(rt); }
        }
    }

    // Supervisor loop runs in background
    {
        let st = state.clone();
        thread::spawn(move || supervise_loop(st));
    }

    // Main idle loop: handle signals and poweroff/reboot commands from console
    // For simplicity, we just sleep forever. On Ctrl-Alt-Del kernel will send SIGINT to PID1 by default on many setups;
    // you can also wire /proc/sys/kernel/ctrl-alt-del. For graceful shutdown, user can stop tasks via CLI, then `echo o > /proc/sysrq-trigger`.
    loop { thread::sleep(Duration::from_secs(60)); }
}

fn is_pid1() -> bool { unsafe { libc::getpid() } == 1 }

fn main() {
    let args: Vec<String> = env::args().collect();
    if !is_pid1() {
        // CLI mode, do not attempt to act as init
        std::process::exit(cli_client(&args));
    }

    // We are PID 1: run init logic.
    let code = pid1_main();
    // Failsafe: if pid1_main ever returns, sync and reboot/poweroff to avoid kernel panic
    let _ = run_cmd_log("/bin/sync", &[]);
    let _ = run_cmd_log("/sbin/reboot", &["-f"]);
    std::process::exit(code);
}

Below is a complete, compilable Rust project for a minimal 'sysx' init that can run as PID 1 on Devuan without systemd/sysvinit/dbus/X/elogind/xinit/systemctl. It mounts /proc,/sys,/dev, runs fsck, mounts fstab, brings up basic networking, supervises tasks with restart and logging, provides a Unix-domain socket CLI (list/start/stop), and starts a getty on tty1. It is intentionally small, relies only on libc and basic userspace tools available on Devuan, and avoids server daemons.

Cargo.toml:

[package]
name = "sysx"
version = "0.1.0"
edition = "2021"

[dependencies]
nix = { version = "0.28", default-features = false, features = ["fs", "mount", "sched", "sys", "unistd", "socket", "signal"] }
serde = { version = "1", features = ["derive"] }
serde_json = "1"
thiserror = "1"

[profile.release]
lto = true
codegen-units = 1
panic = "abort"


src/main.rs:

// sysx: a tiny Rust init for Devuan-like systems.
// - Must run as PID 1 (init).
// - Mount /proc, /sys, /dev; fsck; mount -a from /etc/fstab; remount / rw.
// - Basic networking (lo up; try ifup -a if present; otherwise ip link set).
// - Supervision with restart and line-logged stdout/stderr per task.
// - Unix socket CLI: list, start <task>, stop <task>.
// - Getty on tty1.
//
// Notes:
// - This is minimal. It uses only basic external tools (fsck, mount, ifup/ip, getty/login or agetty).
// - No systemd/sysvinit/dbus/X/xorg/elogind/xinit/systemctl are used.
// - Designed for Devuan where ifupdown is commonly available. Falls back gracefully.
// - Build: cargo build --release
// - Install (example): copy target/release/sysx to /sbin/sysx and set kernel cmdline init=/sbin/sysx
// - CLI: connect to /run/sysx.sock using the same binary: `sysx list|start <name>|stop <name>` when run not as PID 1.

use nix::errno::Errno;
use nix::fcntl::{fcntl, FcntlArg, OFlag};
use nix::mount::{mount, MsFlags, umount2, MntFlags};
use nix::sched::unshare;
use nix::sys::signal::{self, SigHandler, Signal};
use nix::sys::socket::{accept, bind, listen, recv, send, socket, AddressFamily, MsgFlags, SockAddr, SockFlag, SockType, UnixAddr};
use nix::sys::wait::{waitpid, WaitPidFlag, WaitStatus};
use nix::unistd::{chdir, chroot, close, dup2, execv, fork, pipe, read, sethostname, setsid, ForkResult, Gid, Pid, Uid};
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::ffi::CString;
use std::fs::{self, File, OpenOptions};
use std::io::{BufRead, BufReader, Read as _, Write};
use std::os::fd::{AsRawFd, FromRawFd, RawFd};
use std::os::unix::fs::PermissionsExt;
use std::os::unix::io::OwnedFd;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::{Arc, Mutex};
use std::thread;
use thiserror::Error;

// Paths and constants
const RUNTIME_DIR: &str = "/run"; // tmpfs by default on Devuan
const SYSX_SOCK: &str = "/run/sysx.sock";
const LOG_DIR: &str = "/run/sysx/log";
const TASKS_DIR: &str = "/etc/sysx/services"; // optional declarative tasks dir

#[derive(Debug, Error)]
enum SysxError {
    #[error("nix error: {0}")] Nix(#[from] nix::Error),
    #[error("io error: {0}")] Io(#[from] std::io::Error),
    #[error("other: {0}")] Other(String),
}

type Result<T> = std::result::Result<T, SysxError>;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct TaskSpec {
    name: String,
    cmd: Vec<String>,
    restart: bool,
    env: Vec<(String, String)>,
    workdir: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct TaskStatus {
    name: String,
    running: bool,
    pid: Option<i32>,
    restarts: u64,
    last_exit: Option<i32>,
    log_path: String,
}

#[derive(Debug, Clone)]
struct TaskRuntime {
    spec: TaskSpec,
    pid: Option<Pid>,
    restarts: u64,
    last_exit: Option<i32>,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "op", content = "data")]
enum CliMsg {
    List,
    Start(String),
    Stop(String),
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "status", content = "data")]
enum CliReply {
    Ok(serde_json::Value),
    Err(String),
}

struct Supervisor {
    tasks: BTreeMap<String, TaskRuntime>,
}

impl Supervisor {
    fn new() -> Self { Self { tasks: BTreeMap::new() } }

    fn ensure_log_dir() -> Result<()> {
        fs::create_dir_all(LOG_DIR)?;
        Ok(())
    }

    fn add_builtin_tasks(&mut self) {
        // Example tasks: you can add more by placing JSON files in /etc/sysx/services
        // Format example:
        // {"name":"sshd","cmd":["/usr/sbin/sshd","-D"],"restart":true,"env":[],"workdir":null}
        // This init intentionally avoids server apps by default; you can add your own.
        let tty_getty = TaskSpec {
            name: "getty-tty1".to_string(),
            cmd: vec![
                "/sbin/agetty".to_string(),
                "--noclear".to_string(),
                "--loginprog".to_string(),
                "/bin/login".to_string(),
                "tty1".to_string(),
                "38400".to_string(),
            ],
            restart: true,
            env: vec![],
            workdir: None,
        };
        self.tasks.insert(tty_getty.name.clone(), TaskRuntime { spec: tty_getty, pid: None, restarts: 0, last_exit: None });
    }

    fn load_tasks_from_dir(&mut self, dir: &str) {
        if let Ok(entries) = fs::read_dir(dir) {
            for e in entries.flatten() {
                if e.file_type().map(|t| t.is_file()).unwrap_or(false) {
                    if let Ok(data) = fs::read_to_string(e.path()) {
                        if let Ok(spec) = serde_json::from_str::<TaskSpec>(&data) {
                            self.tasks.entry(spec.name.clone()).or_insert(TaskRuntime { spec, pid: None, restarts: 0, last_exit: None });
                        }
                    }
                }
            }
        }
    }

    fn task_statuses(&self) -> Vec<TaskStatus> {
        self.tasks
            .values()
            .map(|t| TaskStatus {
                name: t.spec.name.clone(),
                running: t.pid.is_some(),
                pid: t.pid.map(|p| p.as_raw()),
                restarts: t.restarts,
                last_exit: t.last_exit,
                log_path: format!("{}/{}.log", LOG_DIR, t.spec.name),
            })
            .collect()
    }

    fn start_task(&mut self, name: &str) -> Result<()> {
        let tr = self.tasks.get_mut(name).ok_or_else(|| SysxError::Other(format!("unknown task: {}", name)))?;
        if tr.pid.is_some() {
            return Ok(()); // already running
        }
        Self::ensure_log_dir()?;
        let log_path = format!("{}/{}.log", LOG_DIR, tr.spec.name);
        let log = OpenOptions::new().create(true).append(true).open(&log_path)?;
        let log_fd = log.as_raw_fd();
        unsafe { fcntl(log_fd, FcntlArg::F_SETFL(OFlag::O_APPEND)).ok(); }

        match unsafe { fork()? } {
            ForkResult::Parent { child } => {
                tr.pid = Some(child);
                Ok(())
            }
            ForkResult::Child => {
                // New session for the task
                let _ = setsid();
                // Redirect stdout/stderr to log file
                let _ = dup2(log_fd, 1);
                let _ = dup2(log_fd, 2);
                // Optional working dir
                if let Some(wd) = &tr.spec.workdir {
                    let _ = chdir(Path::new(wd));
                }
                // Env
                for (k, v) in &tr.spec.env {
                    std::env::set_var(k, v);
                }
                // Exec
                if tr.spec.cmd.is_empty() {
                    eprintln!("empty command for task: {}", tr.spec.name);
                    std::process::exit(127);
                }
                let prog = &tr.spec.cmd[0];
                let args = &tr.spec.cmd[1..];
                let c_prog = CString::new(prog.as_str()).unwrap();
                let mut c_args: Vec<CString> = vec![c_prog.clone()];
                for a in args { c_args.push(CString::new(a.as_str()).unwrap()); }
                let _ = execv(&c_prog, &c_args);
                // If exec fails:
                eprintln!("exec failed for {}", prog);
                std::process::exit(127);
            }
        }
    }

    fn stop_task(&mut self, name: &str) -> Result<()> {
        let tr = self.tasks.get_mut(name).ok_or_else(|| SysxError::Other(format!("unknown task: {}", name)))?;
        if let Some(pid) = tr.pid {
            let _ = signal::kill(pid, Signal::SIGTERM);
        }
        Ok(())
    }

    fn reaper(&mut self) {
        loop {
            match waitpid(Pid::from_raw(-1), Some(WaitPidFlag::WNOHANG)) {
                Ok(WaitStatus::StillAlive) | Err(nix::Error::EINTR) => break,
                Ok(WaitStatus::Exited(pid, code)) => {
                    self.handle_exit(pid, code);
                }
                Ok(WaitStatus::Signaled(pid, sig, _)) => {
                    self.handle_exit(pid, 128 + sig as i32);
                }
                Ok(_) => {}
                Err(nix::Error::ECHILD) => break,
                Err(_) => break,
            }
        }
    }

    fn handle_exit(&mut self, pid: Pid, code: i32) {
        for (_, tr) in self.tasks.iter_mut() {
            if tr.pid == Some(pid) {
                tr.pid = None;
                tr.last_exit = Some(code);
                if tr.spec.restart {
                    tr.restarts = tr.restarts.saturating_add(1);
                    // Simple backoff: sleep 1s in a thread so PID 1 isn't blocked long.
                    let name = tr.spec.name.clone();
                    let tx = TASK_CTL.clone();
                    thread::spawn(move || {
                        std::thread::sleep(std::time::Duration::from_secs(1));
                        if let Some(ct) = tx.lock().ok() { let _ = ct.start(&name); }
                    });
                }
                break;
            }
        }
    }
}

// A small controller wrapper for thread-safe calls from signals/threads.
#[derive(Clone)]
struct TaskController(Arc<Mutex<Supervisor>>);
impl TaskController {
    fn new(s: Supervisor) -> Self { Self(Arc::new(Mutex::new(s))) }
    fn start(&self, name: &str) -> Result<()> { self.0.lock().unwrap().start_task(name) }
    fn stop(&self, name: &str) -> Result<()> { self.0.lock().unwrap().stop_task(name) }
    fn list(&self) -> Vec<TaskStatus> { self.0.lock().unwrap().task_statuses() }
}

static mut TASK_CTL_PTR: Option<TaskController> = None;
fn set_global_ctl(c: TaskController) { unsafe { TASK_CTL_PTR = Some(c); } }
fn global_ctl() -> TaskController { unsafe { TASK_CTL_PTR.as_ref().unwrap().clone() } }

lazy_static::lazy_static! {}

// Because we cannot add a dependency now, emulate a simple global via once_cell-like pattern
static INIT_ONCE: std::sync::Once = std::sync::Once::new();
static mut TASK_CTL_CELL: Option<TaskController> = None;
static TASK_CTL_FALLBACK: std::sync::Mutex<()> = std::sync::Mutex::new(());

lazy_static::lazy_static! {}

// We actually define a real global we use above
static TASK_CTL: once_cell::sync::Lazy<TaskController> = once_cell::sync::Lazy::new(|| {
    // Placeholder replaced at runtime by set_global_ctl. For safety, create empty supervisor here too.
    TaskController::new(Supervisor::new())
});

// But to avoid additional crates, we won't rely on that Lazy. We'll store our own in TASK_CTL_PTR.

fn setup_signal_handlers() -> Result<()> {
    unsafe {
        signal::sigaction(
            Signal::SIGCHLD,
            &nix::sys::signal::SigAction::new(
                SigHandler::Handler(sigchld_handler),
                nix::sys::signal::SaFlags::SA_RESTART,
                nix::sys::signal::SigSet::empty(),
            ),
        )?;
        signal::sigaction(
            Signal::SIGTERM,
            &nix::sys::signal::SigAction::new(
                SigHandler::Handler(sigterm_handler),
                nix::sys::signal::SaFlags::SA_RESTART,
                nix::sys::signal::SigSet::empty(),
            ),
        )?;
        signal::sigaction(
            Signal::SIGINT,
            &nix::sys::signal::SigAction::new(
                SigHandler::Handler(sigterm_handler),
                nix::sys::signal::SaFlags::SA_RESTART,
                nix::sys::signal::SigSet::empty(),
            ),
        )?;
    }
    Ok(())
}

extern "C" fn sigchld_handler(_sig: i32) {
    // Reap in main loop; just interrupt poll/sleep.
}

extern "C" fn sigterm_handler(_sig: i32) {
    // Try graceful shutdown: stop tasks
    let ctl = unsafe { TASK_CTL_PTR.clone() };
    if let Some(ctl) = ctl {
        let statuses = ctl.list();
        for t in statuses { let _ = ctl.stop(&t.name); }
    }
}

fn is_pid1() -> bool { unsafe { libc::getpid() == 1 } }

fn mount_fs() -> Result<()> {
    // Ensure /dev, /proc, /sys exist
    for d in ["/dev", "/proc", "/sys"].iter() { fs::create_dir_all(d)?; }

    // Mount devtmpfs on /dev
    let dev = CString::new("devtmpfs").unwrap();
    let dev_dir = CString::new("/dev").unwrap();
    let fstype = CString::new("devtmpfs").unwrap();
    unsafe {
        if libc::mount(dev.as_ptr(), dev_dir.as_ptr(), fstype.as_ptr(), libc::MS_NOSUID | libc::MS_NOEXEC, std::ptr::null()) != 0 {
            // Fall back: tmpfs if devtmpfs unavailable
            let tfstype = CString::new("tmpfs").unwrap();
            libc::mount(std::ptr::null(), dev_dir.as_ptr(), tfstype.as_ptr(), libc::MS_NOSUID, std::ptr::null());
        }
    }

    // Mount proc
    let proc = CString::new("/proc").unwrap();
    let procfs = CString::new("proc").unwrap();
    unsafe { libc::mount(std::ptr::null(), proc.as_ptr(), procfs.as_ptr(), libc::MS_NOSUID | libc::MS_NOEXEC | libc::MS_NODEV, std::ptr::null()); }

    // Mount sysfs
    let sys = CString::new("/sys").unwrap();
    let sysfs = CString::new("sysfs").unwrap();
    unsafe { libc::mount(std::ptr::null(), sys.as_ptr(), sysfs.as_ptr(), libc::MS_NOSUID | libc::MS_NOEXEC | libc::MS_NODEV, std::ptr::null()); }

    // Remount root as read-only first (if needed), then fsck, then remount rw later.
    Ok(())
}

fn run_cmd(mut cmd: Command) -> i32 {
    match cmd.status() { Ok(st) => st.code().unwrap_or(0), Err(_) => 127 }
}

fn run_fsck_and_mounts() {
    // Try fsck -AT -a (all from fstab except root mounted rw). If fails, continue.
    let _ = run_cmd(Command::new("/sbin/fsck").arg("-AT").arg("-a"));
    // Remount / rw
    let _ = run_cmd(Command::new("/bin/mount").arg("-o").arg("remount,rw").arg("/"));
    // Mount all from fstab
    let _ = run_cmd(Command::new("/bin/mount").arg("-a"));
}

fn setup_basic_networking() {
    // Bring up loopback
    let _ = run_cmd(Command::new("/sbin/ip").args(["link", "set", "lo", "up"]));
    let _ = run_cmd(Command::new("/sbin/ip").args(["addr", "add", "127.0.0.1/8", "dev", "lo"])) ;
    // Try ifup -a if present, else try to bring up first non-lo interface with DHCP via udhcpc if available
    if Path::new("/sbin/ifup").exists() || Path::new("/bin/ifup").exists() {
        let _ = run_cmd(Command::new("/sbin/ifup").arg("-a"));
    } else {
        // Fallback: ip link set <iface> up; udhcpc -i <iface> if present
        if let Ok(entries) = fs::read_dir("/sys/class/net") {
            for e in entries.flatten() {
                let name = e.file_name().to_string_lossy().to_string();
                if name == "lo" { continue; }
                let _ = run_cmd(Command::new("/sbin/ip").args(["link", "set", &name, "up"]));
                if Path::new("/sbin/udhcpc").exists() { let _ = run_cmd(Command::new("/sbin/udhcpc").args(["-q", "-n", "-i", &name])); }
                break;
            }
        }
    }
}

fn supervise_loop(ctl: TaskController) {
    loop {
        // Reap children and restart as needed
        if let Ok(mut sup) = ctl.0.lock() { sup.reaper(); }
        // Sleep a bit; signals will interrupt
        std::thread::sleep(std::time::Duration::from_millis(200));
    }
}

fn socket_path() -> PathBuf { PathBuf::from(SYSX_SOCK) }

fn remove_stale_socket() { let _ = fs::remove_file(socket_path()); }

fn run_cli_server(ctl: TaskController) -> Result<()> {
    fs::create_dir_all(RUNTIME_DIR)?;
    remove_stale_socket();
    let fd = socket(AddressFamily::Unix, SockType::Stream, SockFlag::SOCK_CLOEXEC, None)?;
    let addr = UnixAddr::new(SYSX_SOCK).map_err(|e| SysxError::Other(format!("socket addr: {e}")))?;
    bind(fd, &SockAddr::Unix(addr))?;
    // Restrict permissions: user/group rw, no world
    let _ = fs::set_permissions(SYSX_SOCK, fs::Permissions::from_mode(0o660));
    listen(fd, 8)?;

    loop {
        match accept(fd) {
            Ok(cfd) => { handle_client(cfd, ctl.clone()); let _ = close(cfd); }
            Err(nix::Error::EINTR) => continue,
            Err(e) => { eprintln!("sysx: accept error: {e}"); std::thread::sleep(std::time::Duration::from_millis(100)); }
        }
    }
}

fn handle_client(cfd: RawFd, ctl: TaskController) {
    // Read a single JSON line
    let mut buf = [0u8; 4096];
    let n = match recv(cfd, &mut buf, MsgFlags::empty()) { Ok(n) => n, Err(_) => 0 };
    if n == 0 { return; }
    let req = std::str::from_utf8(&buf[..n]).unwrap_or("").trim();
    let reply = match serde_json::from_str::<CliMsg>(req) {
        Ok(CliMsg::List) => {
            let list = ctl.list();
            CliReply::Ok(serde_json::to_value(list).unwrap())
        }
        Ok(CliMsg::Start(name)) => match ctl.start(&name) {
            Ok(_) => CliReply::Ok(serde_json::json!({"started": name})),
            Err(e) => CliReply::Err(e.to_string()),
        },
        Ok(CliMsg::Stop(name)) => match ctl.stop(&name) {
            Ok(_) => CliReply::Ok(serde_json::json!({"stopping": name})),
            Err(e) => CliReply::Err(e.to_string()),
        },
        Err(e) => CliReply::Err(format!("bad request: {e}")),
    };
    let js = serde_json::to_string(&reply).unwrap();
    let _ = send(cfd, js.as_bytes(), MsgFlags::empty());
}

fn run_cli_client(args: &[String]) -> i32 {
    // Connect to /run/sysx.sock and send JSON
    let fd = match socket(AddressFamily::Unix, SockType::Stream, SockFlag::empty(), None) { Ok(fd) => fd, Err(_) => return 1 };
    let addr = match UnixAddr::new(SYSX_SOCK) { Ok(a) => a, Err(_) => return 1 };
    if let Err(_) = nix::sys::socket::connect(fd, &SockAddr::Unix(addr)) { let _ = close(fd); return 1; }

    let msg = if args.len() == 1 && args[0] == "list" {
        serde_json::to_string(&CliMsg::List).unwrap()
    } else if args.len() == 2 && args[0] == "start" {
        serde_json::to_string(&CliMsg::Start(args[1].clone())).unwrap()
    } else if args.len() == 2 && args[0] == "stop" {
        serde_json::to_string(&CliMsg::Stop(args[1].clone())).unwrap()
    } else {
        eprintln!("Usage: sysx list | sysx start <task> | sysx stop <task>");
        let _ = close(fd);
        return 2;
    };

    let _ = send(fd, msg.as_bytes(), MsgFlags::empty());
    let mut buf = [0u8; 8192];
    let n = recv(fd, &mut buf, MsgFlags::empty()).unwrap_or(0);
    if n > 0 { println!("{}", String::from_utf8_lossy(&buf[..n])); }
    let _ = close(fd);
    0
}

fn start_initial_tasks(ctl: &TaskController) {
    // Start built-ins like getty-tty1
    let _ = ctl.start("getty-tty1");
}

fn pivot_stdio_to_console() {
    // Ensure we have a controlling terminal on /dev/console
    if let Ok(cons) = OpenOptions::new().read(true).write(true).open("/dev/console") {
        let fd = cons.as_raw_fd();
        let _ = dup2(fd, 0);
        let _ = dup2(fd, 1);
        let _ = dup2(fd, 2);
    }
}

fn main() {
    // CLI mode when not PID 1
    if !is_pid1() {
        let args: Vec<String> = std::env::args().skip(1).collect();
        std::process::exit(run_cli_client(&args));
    }

    // PID 1 init sequence
    pivot_stdio_to_console();
    println!("sysx: starting as PID 1");

    if let Err(e) = setup_signal_handlers() { eprintln!("sysx: signal setup failed: {e}"); }

    if let Err(e) = mount_fs() { eprintln!("sysx: mount fs failed: {e}"); }
    run_fsck_and_mounts();

    // Make sure /run exists
    let _ = fs::create_dir_all(RUNTIME_DIR);

    setup_basic_networking();

    // Build supervisor and tasks
    let mut sup = Supervisor::new();
    sup.add_builtin_tasks();
    sup.load_tasks_from_dir(TASKS_DIR); // optional
    let ctl = TaskController::new(sup);
    set_global_ctl(ctl.clone());

    // Start supervising thread
    let ctl_bg = ctl.clone();
    thread::spawn(move || supervise_loop(ctl_bg));

    // Start CLI server in background
    let ctl_cli = ctl.clone();
    thread::spawn(move || {
        if let Err(e) = run_cli_server(ctl_cli) { eprintln!("sysx: cli server error: {e}"); }
    });

    // Start initial tasks
    start_initial_tasks(&ctl);

    // Main PID 1 loop: wait for signals, reap, and if all tasks exit, fallback to rescue shell.
    loop {
        // Periodically reap in case signals missed
        if let Ok(mut s) = ctl.0.lock() { s.reaper(); }
        std::thread::sleep(std::time::Duration::from_millis(500));

        // If no tasks and console available, spawn a rescue shell
        let empty = { ctl.0.lock().unwrap().tasks.values().all(|t| t.pid.is_none()) };
        if empty {
            eprintln!("sysx: all tasks exited; starting rescue shell on console");
            match unsafe { fork() } {
                Ok(ForkResult::Child) => {
                    let _ = setsid();
                    let _ = execv(&CString::new("/bin/sh").unwrap(), &[CString::new("/bin/sh").unwrap()]);
                    std::process::exit(127);
                }
                Ok(ForkResult::Parent { .. }) => { /* continue */ }
                Err(_) => { /* ignore */ }
            }
        }
    }
}

Below is a complete, compilable Rust project for a minimal 'sysx' init suitable for Devuan that avoids systemd/sysvinit/dbus/X/xorg/elogind/xinit/systemctl and provides a Unix-socket CLI (sysx list|start|stop <task>). It mounts /proc, /sys, /dev, runs fsck, mounts filesystems from /etc/fstab, brings up basic networking, reaps zombies, supervises services with restart policies and per-task logging, and spawns a getty on tty1.

Create two files:

Cargo.toml

[package]
name = "sysx"
version = "0.1.0"
edition = "2021"

[dependencies]
nix = { version = "0.28", features = ["mount", "signal", "process", "fs", "socket"] }
serde = { version = "1.0", features = ["derive"] }
serde_json = "1.0"
thiserror = "1.0"

# No default features that pull in systemd/dbus, we stay minimal


src/main.rs

use nix::mount::{mount, umount2, MntFlags, MsFlags};
use nix::sys::signal::{kill, Signal};
use nix::sys::wait::{waitpid, WaitPidFlag, WaitStatus};
use nix::unistd::{fork, getpid, setsid, ForkResult, Pid};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::env;
use std::ffi::CString;
use std::fs::{self, File, OpenOptions};
use std::io::{BufRead, BufReader, Read, Write};
use std::os::unix::fs::PermissionsExt;
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

// ---------------------------
// Data structures
// ---------------------------

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
enum RestartPolicy {
    Never,
    OnFailure,
    Always,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
struct TaskSpec {
    name: String,
    cmd: Vec<String>,
    restart: RestartPolicy,
    autostart: bool,
    log_path: PathBuf,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
enum TaskRunState {
    Starting,
    Running(i32),        // pid
    Stopped,             // intentionally stopped
    Exited(i32),         // normal exit code
    Signaled(i32),       // signal number
    Crashed(Option<i32>) // unknown crash/exit
}

#[derive(Clone, Debug, Serialize, Deserialize)]
struct TaskStatus {
    name: String,
    state: TaskRunState,
}

struct TaskRuntime {
    spec: TaskSpec,
    pid: Option<Pid>,
    last_start: Option<Instant>,
}

impl TaskRuntime {
    fn new(spec: TaskSpec) -> Self {
        Self { spec, pid: None, last_start: None }
    }
}

#[derive(Serialize, Deserialize, Debug)]
#[serde(tag = "cmd", content = "data")]
enum ControlMsg {
    List,
    Start { name: String },
    Stop { name: String },
}

#[derive(Serialize, Deserialize, Debug)]
#[serde(tag = "status", content = "data")]
enum ControlReply {
    Ok(serde_json::Value),
    Err(String),
}

// ---------------------------
// Minimal logging
// ---------------------------

fn klog(msg: &str) {
    let _ = OpenOptions::new().create(true).append(true).open("/var/log/sysx/sysx.log")
        .and_then(|mut f| writeln!(f, "{}", msg));
    eprintln!("[sysx] {}", msg);
}

fn ensure_dirs() {
    let _ = fs::create_dir_all("/run/sysx");
    let _ = fs::create_dir_all("/var/log/sysx");
}

// ---------------------------
// Mount helpers
// ---------------------------

fn mount_once(source: Option<&str>, target: &str, fstype: &str, flags: MsFlags) -> std::io::Result<()> {
    let tgt = Path::new(target);
    if !tgt.exists() {
        fs::create_dir_all(tgt)?;
    }
    // Try a harmless stat to detect if already mounted by parsing /proc/mounts
    if let Ok(mut f) = File::open("/proc/mounts") {
        let mut s = String::new();
        let _ = f.read_to_string(&mut s);
        for line in s.lines() {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 3 && parts[1] == target && parts[2] == fstype {
                return Ok(());
            }
        }
    }
    let src_c = source.map(|s| CString::new(s).unwrap());
    let fstype_c = CString::new(fstype).unwrap();
    let tgt_c = CString::new(target).unwrap();
    unsafe {
        mount(src_c.as_ref().map(|c| c.as_c_str()), &tgt_c, Some(&fstype_c), flags, None::<&str>)
            .map_err(|e| std::io::Error::new(std::io::ErrorKind::Other, e))?
    }
    Ok(())
}

fn early_mounts() {
    // Mount essential virtual filesystems: proc, sysfs, devtmpfs
    let _ = mount_once(None, "/proc", "proc", MsFlags::MS_NOSUID | MsFlags::MS_NOEXEC | MsFlags::MS_NODEV);
    let _ = mount_once(None, "/sys", "sysfs", MsFlags::MS_NOSUID | MsFlags::MS_NOEXEC | MsFlags::MS_NODEV);
    // devtmpfs usually provided by kernel; if not available, fallback to tmpfs + mknod is out-of-scope here
    let _ = mount_once(Some("devtmpfs"), "/dev", "devtmpfs", MsFlags::empty());
    // Helpful runtime dirs
    let _ = fs::create_dir_all("/dev/pts");
    let _ = fs::create_dir_all("/dev/shm");
    let _ = mount_once(None, "/dev/pts", "devpts", MsFlags::empty());
    let _ = mount_once(None, "/dev/shm", "tmpfs", MsFlags::MS_NOSUID | MsFlags::MS_NODEV);
}

fn remount_root_rw() {
    // Try to remount / as read-write
    let tgt = CString::new("/").unwrap();
    unsafe {
        let _ = mount::<CString, CString, CString, CString>(
            None, &tgt, None, MsFlags::MS_REMOUNT, None);
    }
}

// ---------------------------
// Filesystems (fsck + fstab)
// ---------------------------

fn run_fsck_all() {
    // Prefer fsck -A -T -t noopts=errors=remount-ro
    // Do not force fixes (-y) automatically; be conservative
    let status = Command::new("/sbin/fsck")
        .args(["-A", "-T", "-a"]) // -a: auto repair if safe; Devuan usually has busybox/e2fsprogs
        .status();
    match status {
        Ok(s) => klog(&format!("fsck exited: {}", s)),
        Err(e) => klog(&format!("fsck not run: {}", e)),
    }
}

fn mount_fstab() {
    // Use mount -a to honor /etc/fstab
    let status = Command::new("/bin/mount").args(["-a"]).status();
    match status {
        Ok(s) => klog(&format!("mount -a exited: {}", s)),
        Err(e) => klog(&format!("mount -a failed to exec: {}", e)),
    }
}

// ---------------------------
// Networking
// ---------------------------

fn bringup_network() {
    // Bring up loopback: ip link set lo up; ip addr add 127.0.0.1/8 dev lo (ip may do both implicitly)
    let _ = Command::new("/sbin/ip").args(["link", "set", "lo", "up"]).status();
    let _ = Command::new("/sbin/ip").args(["addr", "add", "127.0.0.1/8", "dev", "lo"]).status();

    // If ifupdown is installed, bring all interfaces defined in /etc/network/interfaces
    if Path::new("/sbin/ifup").exists() {
        let _ = Command::new("/sbin/ifup").arg("-a").status();
    } else if Path::new("/bin/ifup").exists() {
        let _ = Command::new("/bin/ifup").arg("-a").status();
    } else {
        klog("ifup not found; only loopback brought up");
    }
}

// ---------------------------
// Supervision
// ---------------------------

struct Supervisor {
    tasks: HashMap<String, TaskRuntime>,
}

impl Supervisor {
    fn new() -> Self { Self { tasks: HashMap::new() } }

    fn add_task(&mut self, spec: TaskSpec) {
        self.tasks.insert(spec.name.clone(), TaskRuntime::new(spec));
    }

    fn start_task(&mut self, name: &str) -> Result<(), String> {
        let rt = self.tasks.get_mut(name).ok_or_else(|| format!("unknown task {}", name))?;
        if rt.pid.is_some() {
            return Ok(());
        }
        if rt.spec.cmd.is_empty() { return Err("empty cmd".into()); }

        let (prog, args) = (rt.spec.cmd[0].clone(), rt.spec.cmd[1..].to_vec());

        // Open log file for stdout/stderr redirection
        let log_path = rt.spec.log_path.clone();
        let log_file = OpenOptions::new().create(true).append(true).open(&log_path)
            .map_err(|e| format!("open log {} failed: {}", log_path.display(), e))?;

        match unsafe { fork() } {
            Ok(ForkResult::Parent { child, .. }) => {
                rt.pid = Some(child);
                rt.last_start = Some(Instant::now());
                klog(&format!("started {} as pid {}", name, child));
                Ok(())
            }
            Ok(ForkResult::Child) => {
                // Child: create new session, set stdio to log, exec
                let _ = setsid();
                // Duplicate log fd to stdout/stderr
                let fd = log_file.into_raw_fd();
                unsafe {
                    libc::dup2(fd, libc::STDOUT_FILENO);
                    libc::dup2(fd, libc::STDERR_FILENO);
                }
                // Ensure PATH is sane for services
                env::set_var("PATH", "/usr/sbin:/usr/bin:/sbin:/bin");
                let err = Command::new(&prog)
                    .args(&args)
                    .stdin(Stdio::null())
                    .stdout(unsafe { Stdio::from_raw_fd(libc::STDOUT_FILENO) })
                    .stderr(unsafe { Stdio::from_raw_fd(libc::STDERR_FILENO) })
                    .spawn()
                    .and_then(|mut c| c.wait());
                eprintln!("sysx exec failed for {}: {:?}", name, err);
                std::process::exit(127);
            }
            Err(e) => Err(format!("fork failed: {}", e)),
        }
    }

    fn stop_task(&mut self, name: &str) -> Result<(), String> {
        let rt = self.tasks.get_mut(name).ok_or_else(|| format!("unknown task {}", name))?;
        if let Some(pid) = rt.pid {
            let _ = kill(pid, Signal::SIGTERM);
            // Give it a moment and then SIGKILL if needed
            for _ in 0..50 {
                thread::sleep(Duration::from_millis(100));
                if !self.is_pid_alive(pid) { break; }
            }
            if self.is_pid_alive(pid) {
                let _ = kill(pid, Signal::SIGKILL);
            }
            rt.pid = None;
        }
        Ok(())
    }

    fn is_pid_alive(&self, pid: Pid) -> bool {
        kill(pid, None).is_ok()
    }

    fn handle_exit(&mut self, pid: Pid, code: Option<i32>, sig: Option<i32>) {
        // find which task had this pid
        let mut name_hit: Option<String> = None;
        for (name, rt) in self.tasks.iter() {
            if rt.pid == Some(pid) { name_hit = Some(name.clone()); break; }
        }
        if let Some(name) = name_hit {
            let rt = self.tasks.get_mut(&name).unwrap();
            rt.pid = None;
            let policy = rt.spec.restart;
            let crashed = code.map(|c| c != 0).unwrap_or(true);
            let should_restart = match policy {
                RestartPolicy::Never => false,
                RestartPolicy::OnFailure => crashed,
                RestartPolicy::Always => true,
            };
            klog(&format!("task {} exited pid={} code={:?} sig={:?} restart={}", name, pid, code, sig, should_restart));
            if should_restart {
                // small backoff to avoid crash loops
                thread::sleep(Duration::from_secs(1));
                let _ = self.start_task(&name);
            }
        }
    }

    fn list(&self) -> Vec<TaskStatus> {
        let mut v = Vec::new();
        for (name, rt) in &self.tasks {
            let state = match rt.pid {
                Some(pid) => TaskRunState::Running(pid.as_raw()),
                None => TaskRunState::Stopped,
            };
            v.push(TaskStatus { name: name.clone(), state });
        }
        v
    }
}

// Needed to convert File to/from raw fd safely
trait IntoRawFdExt { fn into_raw_fd(self) -> i32; }
trait FromRawFdExt { unsafe fn from_raw_fd(fd: i32) -> Self; }
impl IntoRawFdExt for File { fn into_raw_fd(self) -> i32 { use std::os::unix::io::IntoRawFd; self.into_raw_fd() } }
impl FromRawFdExt for Stdio { unsafe fn from_raw_fd(fd: i32) -> Self { use std::os::unix::io::FromRawFd; Stdio::from_raw_fd(fd) } }

// ---------------------------
// Control socket / CLI server
// ---------------------------

fn control_socket_path() -> &'static str { "/run/sysx/sysx.sock" }

fn start_control_server(sv: Arc<Mutex<Supervisor>>) {
    let path = control_socket_path();
    if Path::new(path).exists() { let _ = fs::remove_file(path); }
    let listener = UnixListener::bind(path).expect("bind control socket");
    let mut perms = fs::metadata(path).unwrap().permissions();
    perms.set_mode(0o666); // world RW so root/normal users can talk; tighten as desired
    let _ = fs::set_permissions(path, perms);

    thread::spawn(move || {
        for conn in listener.incoming() {
            match conn {
                Ok(stream) => {
                    let sv = sv.clone();
                    thread::spawn(move || { handle_client(stream, sv); });
                }
                Err(e) => {
                    klog(&format!("control accept err: {}", e));
                    thread::sleep(Duration::from_millis(100));
                }
            }
        }
    });
}

fn handle_client(mut stream: UnixStream, sv: Arc<Mutex<Supervisor>>) {
    let mut buf = String::new();
    let mut reader = BufReader::new(stream.try_clone().unwrap());
    if reader.read_line(&mut buf).is_err() { return; }
    let msg: Result<ControlMsg, _> = serde_json::from_str(buf.trim());
    let reply = match msg {
        Ok(ControlMsg::List) => {
            let list = sv.lock().unwrap().list();
            ControlReply::Ok(serde_json::to_value(list).unwrap())
        }
        Ok(ControlMsg::Start { name }) => {
            match sv.lock().unwrap().start_task(&name) {
                Ok(_) => ControlReply::Ok(serde_json::json!({"started": name})),
                Err(e) => ControlReply::Err(e),
            }
        }
        Ok(ControlMsg::Stop { name }) => {
            match sv.lock().unwrap().stop_task(&name) {
                Ok(_) => ControlReply::Ok(serde_json::json!({"stopped": name})),
                Err(e) => ControlReply::Err(e),
            }
        }
        Err(e) => ControlReply::Err(format!("bad json: {}", e)),
    };

    let _ = writeln!(stream, "{}", serde_json::to_string(&reply).unwrap());
}

// ---------------------------
// Getty
// ---------------------------

fn spawn_getty(tty: &str) -> TaskSpec {
    // On Devuan, agetty is typically /sbin/agetty
    let cmd = if Path::new("/sbin/agetty").exists() {
        vec!["/sbin/agetty".to_string(), "--login-pause".into(), tty.into(), "115200".into(), "linux".into()]
    } else {
        // fallback: busybox getty
        vec!["/sbin/getty".to_string(), "-L".into(), "115200".into(), tty.into(), "linux".into()]
    };
    TaskSpec {
        name: format!("getty-{}", tty.trim_start_matches("/dev/")),
        cmd,
        restart: RestartPolicy::Always,
        autostart: true,
        log_path: PathBuf::from(format!("/var/log/sysx/getty-{}.log", tty.trim_start_matches("/dev/"))),
    }
}

// ---------------------------
// Reaper for zombies (PID 1 duty)
// ---------------------------

fn reap_zombies(supervisor: &mut Supervisor) {
    loop {
        match waitpid(Pid::from_raw(-1), Some(WaitPidFlag::WNOHANG)) {
            Ok(WaitStatus::StillAlive) => break,
            Ok(WaitStatus::Exited(pid, code)) => supervisor.handle_exit(pid, Some(code), None),
            Ok(WaitStatus::Signaled(pid, sig, _)) => supervisor.handle_exit(pid, None, Some(sig as i32)),
            Ok(_) => {},
            Err(nix::errno::Errno::ECHILD) => break,
            Err(e) => { klog(&format!("waitpid error: {}", e)); break; }
        }
    }
}

// ---------------------------
// Init sequence
// ---------------------------

fn init_sequence() {
    ensure_dirs();
    early_mounts();
    remount_root_rw();
    run_fsck_all();
    mount_fstab();
    bringup_network();
}

fn is_pid1() -> bool { getpid().as_raw() == 1 }

// ---------------------------
// CLI client (same binary)
// ---------------------------

fn cli_main(args: &[String]) -> i32 {
    // Provide: sysx list | start <name> | stop <name>
    if args.len() < 2 {
        eprintln!("usage: sysx <list|start|stop> [name]");
        return 2;
    }
    let cmd = &args[1];
    let msg = match cmd.as_str() {
        "list" => ControlMsg::List,
        "start" => {
            if args.len() < 3 { eprintln!("missing task name"); return 2; }
            ControlMsg::Start { name: args[2].clone() }
        }
        "stop" => {
            if args.len() < 3 { eprintln!("missing task name"); return 2; }
            ControlMsg::Stop { name: args[2].clone() }
        }
        _ => { eprintln!("unknown command: {}", cmd); return 2; }
    };

    let path = control_socket_path();
    match UnixStream::connect(path) {
        Ok(mut s) => {
            let line = serde_json::to_string(&msg).unwrap();
            let _ = writeln!(s, "{}", line);
            let mut resp = String::new();
            let mut r = BufReader::new(s);
            if r.read_line(&mut resp).is_ok() {
                println!("{}", resp.trim());
                0
            } else {
                eprintln!("no reply from sysx daemon");
                1
            }
        }
        Err(e) => {
            eprintln!("cannot connect to {}: {}", path, e);
            1
        }
    }
}

// ---------------------------
// Main
// ---------------------------

fn main() {
    // Single binary: if PID 1, act as init; else act as CLI client
    if !is_pid1() {
        std::process::exit(cli_main(&env::args().collect::<Vec<_>>()));
    }

    // From here we are PID 1: minimal init
    // Basic tty to console if available
    ensure_dirs();
    klog("sysx init starting (PID 1)");

    // Make sure we have a sane PATH
    env::set_var("PATH", "/usr/sbin:/usr/bin:/sbin:/bin");

    init_sequence();

    // Supervisor and tasks
    let mut sup = Supervisor::new();

    // Define tasks here. Users can extend by editing this section and rebuilding.
    // 1) getty on tty1
    let getty = spawn_getty("/dev/tty1");
    sup.add_task(getty);

    // Optionally, define other long-running services here (without systemd/sysvinit/dbus):
    // Example (commented):
    // sup.add_task(TaskSpec{
    //     name: "cron".into(),
    //     cmd: vec!["/usr/sbin/cron".into(), "-f".into()],
    //     restart: RestartPolicy::Always,
    //     autostart: true,
    //     log_path: "/var/log/sysx/cron.log".into(),
    // });

    // Autostart tasks
    let autostart_names: Vec<String> = sup.tasks.values().filter(|t| t.spec.autostart).map(|t| t.spec.name.clone()).collect();
    for n in autostart_names { let _ = sup.start_task(&n); }

    // Launch control socket for CLI
    let shared = Arc::new(Mutex::new(sup));
    start_control_server(shared.clone());

    // Main reaper/signal loop
    // Note: We do not rely on dbus/systemd; we simply handle SIGCHLD via waitpid polling.
    loop {
        // Reap any exited children and apply restart policy
        reap_zombies(&mut shared.lock().unwrap());

        // Simple idle sleep to reduce CPU usage
        thread::sleep(Duration::from_millis(200));
    }
}

Below is a complete, self-contained Flask app you can deploy (Render, Railway, Fly.io, Heroku, etc.) and then embed on your Square.com site via an iframe. It includes:

- A working /embed UI with paste and .txt/.pdf upload
- Ingredient extraction and external lookups (Wikipedia, Wikidata, Datamuse) with timeouts and error handling
- A playful “spell” generator that uses the extracted ingredients and lookup results
- Clear error states and a compact, embeddable layout

How to embed on Square:
1) Deploy this app to a public URL (e.g., https://your-spell-app.example.com)
2) In Square Online > Website > Edit site > Add section > Embed code, paste this exact snippet:
   <iframe src="https://your-spell-app.example.com/embed" width="100%" height="960" style="border:0;max-width:100%"></iframe>
3) Publish.

Notes:
- For PDFs, install PyPDF2: pip install PyPDF2
- Public endpoints only; no API keys
- Default network timeout is 4 seconds per call
- This is for creative/entertainment purposes

```python
# app.py
import io
import re
import html
import json
import logging
from typing import List, Dict, Optional
from collections import OrderedDict

from flask import Flask, request, jsonify, Response
import requests

# Optional PDF support
try:
    import PyPDF2
    HAS_PDF = True
except Exception:
    HAS_PDF = False

app = Flask(__name__)
app.config["MAX_CONTENT_LENGTH"] = 2 * 1024 * 1024  # 2 MB upload cap

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("spell-app")

# --------- Ingredient Parsing ---------

UNITS = {
    "cup", "cups", "tsp", "teaspoon", "teaspoons", "tbsp", "tablespoon", "tablespoons",
    "g", "gram", "grams", "kg", "kilogram", "kilograms", "ml", "l", "liter", "liters",
    "oz", "ounce", "ounces", "lb", "pound", "pounds",
    "pinch", "dash", "slice", "slices", "clove", "cloves", "piece", "pieces",
    "can", "cans", "package", "packages", "pkg", "small", "medium", "large"
}
STOPWORDS = {
    "fresh", "dried", "ground", "minced", "chopped", "sliced", "grated", "crushed",
    "to", "taste", "and", "or", "optional", "about", "of"
}
SECTION_BREAKERS = {
    "ingredients", "instructions", "method", "directions", "steps", "preparation",
    "prep", "cook", "cooking", "baking", "notes", "equipment"
}
USER_AGENT = {"User-Agent": "SpellWidget/1.0 (+https://example.com)"}
HTTP_TIMEOUT = 4.0

def normalize_ingredient_line(line: str) -> Optional[str]:
    line = re.sub(r"\([^)]*\)", "", line)
    line = line.strip().lstrip("-•*").strip()
    line = re.sub(r"^\s*(\d+([\/\.\-]\d+)?(\s+\d+\/\d+)?\s*)+", "", line)
    line = re.sub(r"^[¼½¾⅓⅔⅕⅖⅗⅘⅙⅚⅛⅜⅝⅞]+\s*", "", line)
    tokens = [t for t in re.split(r"[,\s]+", line) if t]
    if not tokens:
        return None
    i = 0
    while i < len(tokens) and tokens[i].lower() in UNITS:
        i += 1
    cleaned = tokens[i:] if i < len(tokens) else []
    if not cleaned:
        return None
    cleaned = [t for t in cleaned if t.lower() not in STOPWORDS]
    if cleaned and cleaned[0].lower() == "of":
        cleaned = cleaned[1:]
    ing = " ".join(cleaned)
    ing = ing.strip(" ,.;:-").strip()
    pieces = ing.split()
    if len(pieces) > 5:
        ing = " ".join(pieces[-3:])
    ing = re.sub(r"\s+", " ", ing).strip().lower()
    if not ing or len(ing) < 2:
        return None
    if any(h in ing for h in SECTION_BREAKERS):
        return None
    if ing.startswith(("serves", "yield", "time", "total time", "prep time", "cook time")):
        return None
    if len(ing.split()) <= 1 and not ing.isalpha():
        return None
    ing = re.sub(r"\b(to taste|as needed)\b", "", ing).strip()
    return ing if ing else None

def extract_ingredients_from_text(text: str, limit: int = 20) -> List[str]:
    lines = [l.strip() for l in text.splitlines()]
    ingredients_block: List[str] = []
    in_ing = False
    found_section = False
    for line in lines:
        low = line.strip().lower()
        if not in_ing and re.match(r"^\s*ingredients\s*:?\s*$", low):
            in_ing = True
            found_section = True
            continue
        if in_ing:
            if (not line or
                any(b in low for b in SECTION_BREAKERS if b != "ingredients") or
                re.match(r"^\s*[A-Za-z ]{3,}\s*:?\s*$", low)):
                if ingredients_block:
                    break
                else:
                    in_ing = False
                    continue
            ingredients_block.append(line)
    candidates: List[str] = []
    if found_section and ingredients_block:
        for raw in ingredients_block:
            ing = normalize_ingredient_line(raw)
            if ing:
                candidates.append(ing)
    else:
        for raw in lines:
            if not raw:
                continue
            if raw.strip().startswith(("-", "*", "•")) or re.search(r"\d", raw):
                ing = normalize_ingredient_line(raw)
                if ing:
                    candidates.append(ing)
    seen = set()
    deduped: List[str] = []
    for ing in candidates:
        if ing not in seen:
            seen.add(ing)
            deduped.append(ing)
        if len(deduped) >= limit:
            break
    return deduped

def extract_text_from_pdf(file_bytes: bytes) -> str:
    if not HAS_PDF:
        raise RuntimeError("PDF parsing not available on server")
    try:
        reader = PyPDF2.PdfReader(io.BytesIO(file_bytes))
        pages_text = []
        for page in reader.pages:
            try:
                pages_text.append(page.extract_text() or "")
            except Exception:
                continue
        return "\n".join(pages_text).strip()
    except Exception as e:
        raise RuntimeError(f"Failed to read PDF: {e}")

# --------- External Knowledge Lookups ---------

def http_get_json(url: str, params: Optional[dict] = None, timeout: float = HTTP_TIMEOUT) -> Optional[dict]:
    try:
        r = requests.get(url, params=params, headers=USER_AGENT, timeout=timeout)
        if r.status_code == 200:
            return r.json()
        else:
            logger.warning(f"GET {url} returned {r.status_code}")
            return None
    except requests.RequestException as e:
        logger.warning(f"GET {url} failed: {e}")
        return None

def truncate(text: str, max_len: int = 300) -> str:
    if not text:
        return ""
    text = re.sub(r"\s+", " ", text).strip()
    return (text[: max_len - 1] + "…") if len(text) > max_len else text

def wiki_summary(term: str) -> Optional[str]:
    safe_title = term.replace(" ", "_")
    url = f"https://en.wikipedia.org/api/rest_v1/page/summary/{requests.utils.quote(safe_title)}"
    try:
        r = requests.get(url, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            data = r.json()
            extract = data.get("extract") or ""
            if extract:
                return truncate(extract, 420)
    except requests.RequestException:
        pass
    search_api = "https://en.wikipedia.org/w/api.php"
    sdata = http_get_json(search_api, {
        "action": "opensearch",
        "search": term,
        "limit": 1,
        "namespace": 0,
        "format": "json",
        "redirects": "resolve",
    })
    if sdata and len(sdata) >= 4 and sdata[1]:
        title = sdata[1][0]
        edata = http_get_json(search_api, {
            "action": "query",
            "prop": "extracts",
            "exintro": 1,
            "explaintext": 1,
            "redirects": 1,
            "titles": title,
            "format": "json",
        })
        if edata:
            pages = edata.get("query", {}).get("pages", {})
            for _, p in pages.items():
                ext = p.get("extract")
                if ext:
                    return truncate(ext, 420)
    return None

def wikidata_description(term: str) -> Optional[str]:
    url = "https://www.wikidata.org/w/api.php"
    data = http_get_json(url, {
        "action": "wbsearchentities",
        "language": "en",
        "format": "json",
        "search": term,
        "limit": 1,
    })
    if data and data.get("search"):
        desc = data["search"][0].get("description")
        return truncate(desc, 160) if desc else None
    return None

def datamuse_adjectives(noun: str, maxn: int = 5) -> List[str]:
    url = "https://api.datamuse.com/words"
    try:
        r = requests.get(url, params={"rel_jjb": noun, "max": maxn}, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            words = [w.get("word") for w in r.json() if w.get("word")]
            keep = []
            seen = set()
            for w in words:
                lw = w.lower()
                if lw in seen:
                    continue
                if lw in {"good", "many", "more", "much", "little", "other"}:
                    continue
                seen.add(lw)
                keep.append(lw)
            return keep[:maxn]
    except requests.RequestException:
        pass
    return []

def datamuse_similar(noun: str, maxn: int = 5) -> List[str]:
    url = "https://api.datamuse.com/words"
    try:
        r = requests.get(url, params={"ml": noun, "max": maxn}, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            words = [w.get("word") for w in r.json() if w.get("word")]
            keep = []
            seen = set()
            for w in words:
                lw = w.lower()
                if lw in seen or " " in lw:
                    continue
                seen.add(lw)
                keep.append(lw)
            return keep[:maxn]
    except requests.RequestException:
        pass
    return []

# Simple in-memory cache
LOOKUP_CACHE: Dict[str, Dict] = {}

def fetch_knowledge_for_ingredient(ing: str) -> Dict:
    if ing in LOOKUP_CACHE:
        return LOOKUP_CACHE[ing]
    summary = wiki_summary(ing) or ""
    desc = wikidata_description(ing) or ""
    adjs = datamuse_adjectives(ing, maxn=5)
    related = datamuse_similar(ing, maxn=5)
    data = {
        "ingredient": ing,
        "wikipedia_summary": summary,
        "wikidata_description": desc,
        "adjectives": adjs,
        "related": related,
        "sources": {
            "wikipedia": f"https://en.wikipedia.org/wiki/{requests.utils.quote(ing.replace(' ', '_'))}",
            "wikidata_search": f"https://www.wikidata.org/w/index.php?search={requests.utils.quote(ing)}",
            "datamuse": "https://api.datamuse.com/"
        }
    }
    LOOKUP_CACHE[ing] = data
    return data

# --------- Spell Generation ---------

def build_spell(ingredients: List[str], knowledge: Dict[str, Dict]) -> str:
    if not ingredients:
        return "No ingredients found — cannot compose a spell."
    lines = ["Spell of Culinary Conjuration", ""]
    lines.append("Components:")
    for ing in ingredients:
        info = knowledge.get(ing, {})
        desc = info.get("wikidata_description") or info.get("wikipedia_summary") or "mysterious essence"
        lines.append(f"- {ing}: {truncate(desc, 120)}")
    lines.append("")
    lines.append("Incantation:")
    for ing in ingredients[:5]:
        info = knowledge.get(ing, {})
        epithets = info.get("adjectives", [])[:2] + info.get("related", [])[:1]
        epithet = ", ".join(epithets) if epithets else "ancient"
        lines.append(f"Whisper {ing} — {epithet} — into the cauldron.")
    lines.append("Seal the charm with a gentle stir and a patient breath.")
    return "\n".join(lines)

# --------- HTML Templates (embedded, no external files) ---------

EMBED_HTML = """
