function esc(s){
  const d = document.createElement('div'); d.textContent = s; return d.innerHTML;
}

function render(data){
  if(data.error){
    out.innerHTML = '<div class="error">' + esc(data.error) + '</div>';
    return;
  }
  const ings = (data.ingredients||[]).map(i=>'<span class="pill">'+esc(i)+'</span>').join(' ');
  const kblocks = (data.knowledge||[]).map(k=>{
    return `<div class="card"><strong>${esc(k.ingredient)}</strong><div class="muted">`+
      `${k.wikidata_description?esc(k.wikidata_description):''}`+
