      `<div class="muted">`+
      `${k.adjectives && k.adjectives.length? 'Adjectives: ' + esc(k.adjectives.join(', ')) : ''}`+
      `${k.related && k.related.length? '<br>Related: ' + esc(k.related.join(', ')) : ''}`+
      `</div></div>`;
  }).join('');

  const spell = data.spell ? esc(data.spell) : 'No spell generated.';

  out.innerHTML = `
    <div class="grid">
      <div>
        <div class="ok">Found ${data.ingredients.length} ingredient(s).</div>
        <div style="margin:8px 0">${ings||'<span class="muted">No ingredients extracted.</span>'}</div>
        <h3>Knowledge</h3>
        ${kblocks||'<div class="card"><span class="muted">No external info available (timeouts or no matches).</span></div>'}
      </div>
      <div>
        <h3>Spell</h3>
        <pre>${spell}</pre>
      </div>
    </div>`;
}
</script>
</body>
</html>
"""

# --------- Routes ---------

@app.get("/")
def root():
    return Response("OK. Try /embed", mimetype="text/plain")

@app.get("/embed")
def embed():
    return Response(EMBED_HTML, mimetype="text/html")

@app.post("/process")
def process():
    try:
        text = (request.form.get("recipe_text") or "").strip()
        up = request.files.get("recipe_file")
        if up and up.filename:
            fname = (up.filename or "").lower()
            b = up.read()
            if not b:
                return jsonify({"error": "Uploaded file is empty."}), 400
            if fname.endswith(".txt"):
                try:
                    text = b.decode("utf-8", errors="ignore")
                except Exception:
                    text = b.decode("latin-1", errors="ignore")
            elif fname.endswith(".pdf"):
                try:
                    text = extract_text_from_pdf(b)
                except Exception as e:
                    return jsonify({"error": f"PDF error: {e}"}), 400
            else:
                return jsonify({"error": "Unsupported file type. Please upload .txt or .pdf"}), 400
        if not text:
            return jsonify({"error": "Please paste recipe text or upload a .txt/.pdf file."}), 400
        ingredients = extract_ingredients_from_text(text, limit=20)
        if not ingredients:
            return jsonify({"error": "No ingredients detected. Please include an Ingredients section or bullet list with quantities."}), 200
        knowledge_list = []
        for ing in ingredients:
            try:
                knowledge_list.append(fetch_knowledge_for_ingredient(ing))
            except Exception as e:
                logger.warning(f"Lookup failed for {ing}: {e}")
                knowledge_list.append({
                    "ingredient": ing,
                    "wikipedia_summary": "",
                    "wikidata_description": "",
                    "adjectives": [],
                    "related": [],
                    "sources": {}
                })
        kmap: Dict[str, Dict] = {k["ingredient"]: k for k in knowledge_list}
        spell = build_spell(ingredients, kmap)
        return jsonify({
            "ingredients": ingredients,
            "knowledge": knowledge_list,
            "spell": spell
        })
    except Exception as e:
        logger.exception("Process error")
        return jsonify({"error": f"Unexpected server error: {e}"}), 500

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8000, debug=False)
