"""


def embed_form(error: Optional[str] = None, last_text: str = "") -> str:
    err_html = f"<div class='error'>{html.escape(error)}</div>" if error else ""
    return layout(
        "Spell from Recipe",
        f"""
        <h1>Spell from Recipe</h1>
        <div class=\"card\">
          <form method=\"post\" action=\"/process\" enctype=\"multipart/form-data\">
            <label class=\"muted\">Paste your recipe text</label>
            <textarea name=\"recipe_text\" placeholder=\"Paste ingredients or full recipe here...\">{html.escape(last_text)}</textarea>
            <div class=\"row files\">
              <input type=\"file\" name=\"recipe_file\" accept=\".txt,application/pdf\" />
              <span class=\"muted\">.txt or .pdf (max 2 MB)</span>
            </div>
            <div class=\"row\">
              <button class=\"btn\" type=\"submit\">Conjure Spell</button>
              <a class=\"muted\" href=\"/embed\" style=\"text-decoration:none\">Reset</a>
            </div>
            <div class=\"hr\"></div>
            <div class=\"muted\">We extract ingredients, fetch a few public facts, and spin a whimsical spell. No personal data stored.</div>
          </form>
          {err_html}
        </div>
        """
    )


def result_page(ingredients: List[str], spell: str, sources: Dict[str, Dict], raw_text: str) -> str:
    if not ingredients:
        warn = "<div class='error'>We couldn't find any ingredients. Please paste a list like '2 cups flour, 1 tsp salt' or upload a file.</div>"
    else:
        warn = ""
    pills = "".join(f"<span class='pill'>{html.escape(i)}</span>" for i in ingredients)

    # Sources list (compact)
    src_html_parts = []
    for ing, info in sources.items():
        s = info.get("sources", {})
        w = s.get("wikipedia")
        d = s.get("wikidata_search")
        dm = s.get("datamuse")
        links = []
        if w:
            links.append(f"<a href='{html.escape(w)}' target='_blank' rel='noopener'>Wikipedia</a>")
        if d:
            links.append(f"<a href='{html.escape(d)}' target='_blank' rel='noopener'>Wikidata</a>")
        if dm:
            links.append(f"<a href='{html.escape(dm)}' target='_blank' rel='noopener'>Datamuse</a>")
        if links:
            src_html_parts.append(f"<div class='muted'>&#8226; {html.escape(ing)}: " + ", ".join(links) + "</div>")
    src_html = "".join(src_html_parts)

    return layout(
        "Your Conjured Spell",
        f"""
        <h1>Your Conjured Spell</h1>
        <div class=\"card\">
          {warn}
          <div>{pills}</div>
          <div class=\"ok\" style=\"margin-top:10px\">{html.escape(spell)}</div>
          <div class=\"hr\"></div>
          <details>
            <summary class=\"muted\">Show original text</summary>
            <pre class=\"muted\" style=\"white-space:pre-wrap\">{html.escape(raw_text[:5000])}</pre>
          </details>
          <div class=\"hr\"></div>
          <div>
            <div class=\"muted\">Sources consulted:</div>
            {src_html}
          </div>
          <div class=\"row\" style=\"margin-top:12px\">
            <a class=\"btn\" href=\"/embed\">Conjure Another</a>
          </div>
        </div>
        """
    )


# --------- Routes ---------

@app.route("/")
def index():
    return redirect(url_for('embed'))


@app.route("/embed", methods=["GET"])
def embed():
    # Embeddable UI route for Square iframe
    return make_response(embed_form(), 200)


@app.route("/process", methods=["POST"])
def process():
    try:
        text_input = (request.form.get("recipe_text") or "").strip()

        uploaded = request.files.get("recipe_file")
        file_text = ""
        if uploaded and uploaded.filename:
            fn = uploaded.filename.lower()
            data = uploaded.read()
            if not data:
                return make_response(embed_form("Uploaded file is empty.", text_input), 400)
            if fn.endswith(".txt"):
                try:
                    file_text = data.decode("utf-8", errors="replace")
                except Exception:
                    file_text = data.decode("latin-1", errors="replace")
            elif fn.endswith(".pdf"):
                try:
                    file_text = extract_text_from_pdf(data)
                except RuntimeError as e:
                    return make_response(embed_form(str(e), text_input), 400)
            else:
                return make_response(embed_form("Unsupported file type. Please upload .txt or .pdf.", text_input), 400)

        combined_text = (text_input + "\n\n" + file_text).strip() if file_text else text_input
        if not combined_text:
            return make_response(embed_form("Please paste recipe text or upload a .txt/.pdf file."), 400)

        ingredients = extract_ingredients_from_text(combined_text)

        # Lookups per ingredient with caching
        knowledge_map: Dict[str, Dict] = {}
        for ing in ingredients:
            try:
                knowledge_map[ing] = fetch_knowledge_for_ingredient(ing)
            except Exception as e:
                logger.warning(f"Knowledge fetch failed for {ing}: {e}")
                knowledge_map[ing] = {"ingredient": ing, "adjectives": [], "related": [], "wikipedia_summary": "", "wikidata_description": "", "sources": {}}

        spell_text = build_spell(ingredients, knowledge_map)
        return make_response(result_page(ingredients, spell_text, knowledge_map, combined_text), 200)

    except Exception as e:
        logger.exception("Processing failed")
        return make_response(embed_form(f"Unexpected error: {e}"), 500)


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8080, debug=False)
