# --------- Helpers to render HTML safely ---------

def esc(s: str) -> str:
    return html.escape(s or "", quote=True)


def error_html(msg: Optional[str]) -> str:
    if not msg:
        return ""
    return f"<div class=\"error\">{esc(msg)}</div>"


def render_embed_form(prefill: str = "", error: Optional[str] = None):
    doc = EMBED_HTML_HEAD + EMBED_FORM.format(error_block=error_html(error), prefill=esc(prefill))
    r = make_response(doc)
    r.headers["Content-Security-Policy"] = "default-src 'self'; img-src 'self' data:; style-src 'unsafe-inline' 'self'; frame-ancestors *; connect-src 'self' https://en.wikipedia.org https://www.wikidata.org https://api.datamuse.com;"
    r.headers["X-Frame-Options"] = "ALLOWALL"
    r.headers["Cache-Control"] = "no-store"
    return r


def render_result(ingredients: List[str], knowledge_map: Dict[str, Dict], spell: str, error: Optional[str] = None):
    badges = "".join(f"<span class='badge'>{esc(ing)}</span>" for ing in ingredients) or "<span class='badge'>None</span>"
    src_blocks = []
    for ing in ingredients:
        info = knowledge_map.get(ing, {})
        ws = esc((info.get("wikipedia_summary") or "")[:300])
        wd = esc((info.get("wikidata_description") or ""))
        wurl = esc(info.get("sources", {}).get("wikipedia", ""))
        kd = ""
        if ws:
            kd += f"<div class='code'><strong>Wikipedia:</strong> {ws}</div>"
        if wd:
            kd += f"<div class='code'><strong>Wikidata:</strong> {wd}</div>"
        if wurl:
            kd += f"<div><a href='{wurl}' target='_blank' rel='noopener'>Visit wiki</a></div>"
        if not kd:
            kd = "<div class='code'>No external details found within time limits.</div>"
        src_blocks.append(f"<div style='margin:8px 0'><div class='badge'>{esc(ing)}</div>{kd}</div>")
    sources_html = "".join(src_blocks)

    doc = EMBED_HTML_HEAD + RESULT_HTML.format(
        error_block=error_html(error),
        ingredient_badges=badges,
        spell=esc(spell),
        source_blocks=sources_html,
    )
    r = make_response(doc)
    r.headers["Content-Security-Policy"] = "default-src 'self'; img-src 'self' data:; style-src 'unsafe-inline' 'self'; frame-ancestors *; connect-src 'self' https://en.wikipedia.org https://www.wikidata.org https://api.datamuse.com;"
    r.headers["X-Frame-Options"] = "ALLOWALL"
    r.headers["Cache-Control"] = "no-store"
    return r

# --------- Routes ---------

@app.route("/")
def root():
    return redirect("/embed", code=302)


@app.route("/embed", methods=["GET"])
def embed():
    return render_embed_form()


@app.route("/process", methods=["POST"])
def process():
    try:
        raw_text = (request.form.get("recipe") or "").strip()
        file_text = ""

        if not raw_text and "file" in request.files:
            f = request.files.get("file")
            if f and f.filename:
                filename = (f.filename or "").lower()
                data = f.read() or b""
                if len(data) == 0:
                    return render_embed_form(error="Uploaded file was empty.")
                if len(data) > app.config["MAX_CONTENT_LENGTH"]:
                    return render_embed_form(error="File exceeds 2 MB limit.")
                if filename.endswith(".txt"):
                    try:
                        file_text = data.decode("utf-8", errors="ignore")
                    except Exception:
                        return render_embed_form(error="Could not decode text file.")
                elif filename.endswith(".pdf"):
                    try:
                        file_text = extract_text_from_pdf(data)
                    except Exception as e:
                        return render_embed_form(error=f"PDF error: {e}")
                else:
                    return render_embed_form(error="Unsupported file type. Please upload .txt or .pdf.")

        text = raw_text or file_text
        if not text:
            return render_embed_form(error="Please paste a recipe or upload a .txt/.pdf file.")

        ingredients = extract_ingredients_from_text(text, limit=12)
        if not ingredients:
            return render_embed_form(prefill=text, error="No ingredients detected. Try simpler lines or include an Ingredients section.")

        knowledge: Dict[str, Dict] = {}
        for ing in ingredients:
            try:
                knowledge[ing] = fetch_knowledge_for_ingredient(ing)
            except Exception as e:
                logger.warning(f"lookup failed for {ing}: {e}")
                knowledge[ing] = {"ingredient": ing, "adjectives": [], "related": [], "sources": {}}

        spell = craft_spell(ingredients, knowledge)
        if not spell:
            return render_embed_form(prefill=text, error="Could not craft a spell. Please try another recipe.")

        return render_result(ingredients, knowledge, spell)

    except Exception as e:
        logger.exception("/process crashed")
        return render_embed_form(error=f"Unexpected error: {e}")


# --------- Local Dev Entrypoint ---------

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000, debug=False)
```

What this does:
- /embed: Renders the full UI with a textarea and .txt/.pdf upload, plus inline CSS for clean iframe embedding.
- /process: Handles pasted text and file uploads, extracts ingredients, fetches info from Wikipedia/Wikidata/Datamuse with short timeouts, then renders the spell and sources. Provides clear error messages for empty input, unsupported files, PDF issues, and unexpected errors.
- Security/perf: 2 MB upload cap, simple CSP headers, no API keys, request timeouts, basic escaping, and no storage.
- Embedding: The iframe snippet provided loads /embed directly and the form posts to /process on the same origin for an end-to-end flow.

Below is a complete, runnable Flask app that delivers a working /embed UI for pasting recipe text or uploading .txt/.pdf files, extracts ingredients, fetches playful knowledge from Wikipedia/Wikidata/Datamuse with timeouts and error handling, generates a whimsical spell, and renders clear success/error pages.

How to use:
- Run locally: pip install flask requests PyPDF2 (PyPDF2 is optional; PDFs will show a clear error if not installed)
- Start: python app.py (defaults to port 8000)
- Deploy to a public URL (Render, Railway, Fly.io, Heroku, etc.)
- Embed in Square: paste this exact snippet (replacing the domain with yours)
  <iframe src="https://your-spell-app.example.com/embed" width="100%" height="960" style="border:0;max-width:100%"></iframe>

