# app.py
import io
import os
import re
import html
import random
import logging
from typing import List, Dict, Optional

from flask import Flask, request, make_response, redirect
import requests

# Optional PDF support
try:
    import PyPDF2
    HAS_PDF = True
except Exception:
    HAS_PDF = False

app = Flask(__name__)
app.config["MAX_CONTENT_LENGTH"] = 2 * 1024 * 1024  # 2 MB upload limit

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("spell-app")

# --------- Ingredient Parsing ---------

UNITS = {
    "cup", "cups", "tsp", "teaspoon", "teaspoons", "tbsp", "tablespoon", "tablespoons",
    "g", "gram", "grams", "kg", "kilogram", "kilograms", "ml", "l", "liter", "liters",
    "oz", "ounce", "ounces", "lb", "pound", "pounds",
    "pinch", "dash", "slice", "slices", "clove", "cloves", "piece", "pieces",
    "can", "cans", "package", "packages", "pkg", "small", "medium", "large"
}
STOPWORDS = {
    "fresh", "dried", "ground", "minced", "chopped", "sliced", "grated", "crushed",
    "to", "taste", "and", "or", "optional", "about", "of"
}
SECTION_BREAKERS = {
    "ingredients", "instructions", "method", "directions", "steps", "preparation",
    "prep", "cook", "cooking", "baking", "notes", "equipment"
}
USER_AGENT = {"User-Agent": "SpellWidget/1.0 (+https://example.com)"}
HTTP_TIMEOUT = 4.0


def normalize_ingredient_line(line: str) -> Optional[str]:
    # Remove parenthetical notes
    line = re.sub(r"\([^)]*\)", "", line)
    # Normalize and trim bullets
    line = line.strip().lstrip("-•*").strip()
    # Remove leading quantities like "1 1/2", "2", "2-3", "200 g", etc.
    line = re.sub(r"^\s*(\d+([\/\.\-]\d+)?(\s+\d+\/\d+)?\s*)+", "", line)
    # Remove unicode fractions like "½"
    line = re.sub(r"^[¼½¾⅓⅔⅕⅖⅗⅘⅙⅚⅛⅜⅝⅞]+\s*", "", line)

    tokens = [t for t in re.split(r"[,\s]+", line) if t]
    if not tokens:
        return None

    # Skip initial unit tokens
    i = 0
    while i < len(tokens) and tokens[i].lower() in UNITS:
        i += 1
    cleaned = tokens[i:] if i < len(tokens) else []

    if not cleaned:
        return None

    # Remove stopwords
    cleaned = [t for t in cleaned if t.lower() not in STOPWORDS]

    if cleaned and cleaned[0].lower() == "of":
        cleaned = cleaned[1:]

    ing = " ".join(cleaned)
    ing = ing.strip(" ,.;:-").strip()

    pieces = ing.split()
    if len(pieces) > 5:
        # Keep likely core, e.g., "brown sugar"
        ing = " ".join(pieces[-3:])

    ing = re.sub(r"\s+", " ", ing).strip().lower()

    if not ing or len(ing) < 2:
        return None

    # Exclude section headers and non-ingredient lines
    if any(h in ing for h in SECTION_BREAKERS):
        return None
    if ing.startswith(("serves", "yield", "time", "total time", "prep time", "cook time")):
        return None
    # Avoid lines that are likely headings with non-alpha characters
    if len(ing.split()) <= 1 and not ing.isalpha():
        return None

    # Trim trailing descriptors like "to taste" or "as needed"
    ing = re.sub(r"\b(to taste|as needed)\b", "", ing).strip()
    return ing if ing else None


def extract_ingredients_from_text(text: str, limit: int = 12) -> List[str]:
    lines = [l.strip() for l in text.splitlines()]
    ingredients_block: List[str] = []
    in_ing = False
    found_section = False

    # Try to find an "Ingredients" section
    for line in lines:
        low = line.strip().lower()
        if not in_ing and re.match(r"^\s*ingredients\s*:?\s*$", low):
            in_ing = True
            found_section = True
            continue
        if in_ing:
            if (
                not line
                or any(b in low for b in SECTION_BREAKERS if b != "ingredients")
                or re.match(r"^\s*[A-Za-z ]{3,}\s*:?\s*$", low)
            ):
                # End on blank or another section header
                if ingredients_block:
                    break
                else:
                    in_ing = False
                    continue
            ingredients_block.append(line)

    candidates: List[str] = []
    if found_section and ingredients_block:
        for raw in ingredients_block:
            ing = normalize_ingredient_line(raw)
            if ing:
                candidates.append(ing)
    else:
        # Fallback: scan all lines, prefer bullets or lines with quantities
        for raw in lines:
            if not raw:
                continue
            if raw.strip().startswith(("-", "*", "•")) or re.search(r"\d", raw):
                ing = normalize_ingredient_line(raw)
                if ing:
                    candidates.append(ing)

    # Deduplicate while preserving order, limit count
    seen = set()
    deduped: List[str] = []
    for ing in candidates:
        if ing not in seen:
            seen.add(ing)
            deduped.append(ing)
        if len(deduped) >= limit:
            break
    return deduped


def extract_text_from_pdf(file_bytes: bytes) -> str:
    if not HAS_PDF:
        raise RuntimeError("PDF parsing not available on server")
    try:
        reader = PyPDF2.PdfReader(io.BytesIO(file_bytes))
        pages_text = []
        for page in reader.pages:
            try:
                pages_text.append(page.extract_text() or "")
            except Exception:
                continue
        return "\n".join(pages_text).strip()
    except Exception as e:
        raise RuntimeError(f"Failed to read PDF: {e}")


# --------- External Knowledge Lookups ---------

def http_get_json(url: str, params: Optional[dict] = None, timeout: float = HTTP_TIMEOUT) -> Optional[dict]:
    try:
        r = requests.get(url, params=params, headers=USER_AGENT, timeout=timeout)
        if r.status_code == 200:
            return r.json()
        else:
            logger.warning(f"GET {url} returned {r.status_code}")
            return None
    except requests.RequestException as e:
        logger.warning(f"GET {url} failed: {e}")
        return None


def truncate(text: str, max_len: int = 300) -> str:
    if not text:
        return ""
    text = re.sub(r"\s+", " ", text).strip()
    return (text[: max_len - 1] + "…") if len(text) > max_len else text


def wiki_summary(term: str) -> Optional[str]:
    # Try REST summary first
    safe_title = term.replace(" ", "_")
    url = f"https://en.wikipedia.org/api/rest_v1/page/summary/{requests.utils.quote(safe_title)}"
    try:
        r = requests.get(url, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            data = r.json()
            extract = data.get("extract") or ""
            if extract:
                return truncate(extract, 420)
    except requests.RequestException:
        pass

    # Action API search fallback
    search_api = "https://en.wikipedia.org/w/api.php"
    sdata = http_get_json(search_api, {
        "action": "opensearch",
        "search": term,
        "limit": 1,
        "namespace": 0,
        "format": "json",
        "redirects": "resolve",
    })
    if sdata and len(sdata) >= 4 and sdata[1]:
        title = sdata[1][0]
        edata = http_get_json(search_api, {
            "action": "query",
            "prop": "extracts",
            "exintro": 1,
            "explaintext": 1,
            "redirects": 1,
            "titles": title,
            "format": "json",
        })
        if edata:
            pages = edata.get("query", {}).get("pages", {})
            for _, p in pages.items():
                ext = p.get("extract")
                if ext:
                    return truncate(ext, 420)
    return None


def wikidata_description(term: str) -> Optional[str]:
    url = "https://www.wikidata.org/w/api.php"
    data = http_get_json(url, {
        "action": "wbsearchentities",
        "language": "en",
        "format": "json",
        "search": term,
        "limit": 1,
    })
    if data and data.get("search"):
        desc = data["search"][0].get("description")
        return truncate(desc, 160) if desc else None
    return None


def datamuse_adjectives(noun: str, maxn: int = 5) -> List[str]:
    url = "https://api.datamuse.com/words"
    try:
        r = requests.get(url, params={"rel_jjb": noun, "max": maxn}, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            words = [w.get("word") for w in r.json() if w.get("word")]
            keep = []
            seen = set()
            for w in words:
                lw = w.lower()
                if lw in seen:
                    continue
                if lw in {"good", "many", "more", "much", "little", "other"}:
                    continue
                seen.add(lw)
                keep.append(lw)
            return keep[:maxn]
    except requests.RequestException:
        pass
    return []


def datamuse_similar(noun: str, maxn: int = 5) -> List[str]:
    url = "https://api.datamuse.com/words"
    try:
        r = requests.get(url, params={"ml": noun, "max": maxn}, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            words = [w.get("word") for w in r.json() if w.get("word")]
            keep = []
            seen = set()
            for w in words:
                lw = w.lower()
                if lw in seen or " " in lw:
                    continue
                seen.add(lw)
                keep.append(lw)
            return keep[:maxn]
    except requests.RequestException:
        pass
    return []


LOOKUP_CACHE: Dict[str, Dict] = {}


def fetch_knowledge_for_ingredient(ing: str) -> Dict:
    if ing in LOOKUP_CACHE:
        return LOOKUP_CACHE[ing]

    summary = wiki_summary(ing) or ""
    desc = wikidata_description(ing) or ""
    adjs = datamuse_adjectives(ing, maxn=5)
    related = datamuse_similar(ing, maxn=5)

    data = {
        "ingredient": ing,
        "wikipedia_summary": summary,
        "wikidata_description": desc,
        "adjectives": adjs,
        "related": related,
        "sources": {
            "wikipedia": f"https://en.wikipedia.org/wiki/{requests.utils.quote(ing.replace(' ', '_'))}",
            "wikidata_search": f"https://www.wikidata.org/w/index.php?search={requests.utils.quote(ing)}",
            "datamuse": "https://api.datamuse.com/words"
        }
    }
    LOOKUP_CACHE[ing] = data
    return data

# --------- Spell Generator ---------

def build_spell(ingredients: List[str]) -> str:
    if not ingredients:
        return ""
    opening = [
        "By whisk and will, let flavors swell,",
        "O hearth and herb, attend my spell,",
        "From pantry's hush to cauldron's bell,",
        "Where spice winds rise and secrets dwell,",
    ]
    verbs = ["summon", "stir", "bind", "kindle", "entwine", "awaken", "brighten"]
    lines = [random.choice(opening)]

    for ing in ingredients[:8]:
        k = fetch_knowledge_for_ingredient(ing)
        adjs = k.get("adjectives") or []
        rel = k.get("related") or []
        flair = (adjs + rel)[:3]
        flair_txt = ", ".join(flair) if flair else "true"
        lines.append(f"we {random.choice(verbs)} the {flair_txt} spirit of {ing}.")

    lines.append("Let warmth enfold, let comfort dwell; by taste made bright, so works this spell.")
    return "\n".join(lines)


# --------- HTML Templates (inline for simplicity) ---------

def render_page(title: str, body_html: str, status: int = 200):
    html_doc = f"""
    <!doctype html>
    <html lang=\"en\">
    <head>
      <meta charset=\"utf-8\">
      <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">
      <title>{html.escape(title)}</title>
      <style>
        body {{ font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif; margin: 0; color: #222; }}
        .wrap {{ max-width: 800px; margin: 0 auto; padding: 24px; }}
        h1, h2 {{ margin: 0 0 12px; }}
        .card {{ background: #fff; border: 1px solid #e5e7eb; border-radius: 10px; padding: 16px; box-shadow: 0 1px 2px rgba(0,0,0,0.04); }}
        textarea {{ width: 100%; min-height: 160px; padding: 10px; border: 1px solid #d1d5db; border-radius: 8px; resize: vertical; }}
        .row {{ display: grid; grid-template-columns: 1fr; gap: 12px; }}
        @media (min-width: 720px) {{ .row-2 {{ grid-template-columns: 1fr 1fr; }} }}
        input[type=file] {{ padding: 6px; border: 1px dashed #cbd5e1; border-radius: 8px; background: #f8fafc; }}
        .btn {{ display: inline-block; background: #111827; color: #fff; padding: 10px 14px; border-radius: 8px; text-decoration: none; border: none; cursor: pointer; }}
        .muted {{ color: #6b7280; font-size: 0.9em; }}
        .error {{ background: #fef2f2; color: #991b1b; border: 1px solid #fecaca; padding: 10px; border-radius: 8px; margin: 12px 0; }}
        .ok {{ background: #f0fdf4; color: #14532d; border: 1px solid #bbf7d0; padding: 10px; border-radius: 8px; margin: 12px 0; }}
        .pill {{ display:inline-block; background:#eef2ff; color:#3730a3; padding:4px 8px; border-radius:999px; margin:2px; font-size:12px; }}
        .mono {{ font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 12px; }}
        footer {{ margin-top: 16px; }}
      </style>
    </head>
    <body>
      <div class=\"wrap\">
        {body_html}
      </div>
    </body>
    </html>
    """
    resp = make_response(html_doc, status)
    resp.headers["Content-Security-Policy"] = "default-src 'self' 'unsafe-inline' https://en.wikipedia.org https://www.wikidata.org https://api.datamuse.com; img-src 'self' data:; style-src 'self' 'unsafe-inline'; frame-ancestors *;"
    resp.headers["X-Content-Type-Options"] = "nosniff"
    resp.headers["Referrer-Policy"] = "no-referrer"
    return resp


def render_embed_form(error: Optional[str] = None):
    err_html = f"<div class='error'>{html.escape(error)}</div>" if error else ""
    body = f"""
    <h1>Recipe to Spell</h1>
    <p class=\"muted\">Paste your recipe text or upload a .txt/.pdf. We'll extract ingredients and weave a playful spell.</p>
    {err_html}
    <div class=\"card\">
      <form method=\"post\" action=\"/process_text\" enctype=\"application/x-www-form-urlencoded\">
        <label for=\"recipe_text\"><strong>Paste recipe text</strong></label>
        <textarea id=\"recipe_text\" name=\"recipe_text\" placeholder=\"Ingredients\n- 2 cups flour\n- 1 tsp salt\n...\"></textarea>
        <div style=\"margin-top:10px\">
          <button class=\"btn\" type=\"submit\">Generate Spell</button>
          <span class=\"muted\">No data is stored; external lookups use public endpoints with short timeouts.</span>
        </div>
      </form>
    </div>

    <div style=\"height:14px\"></div>

    <div class=\"card\">
      <form method=\"post\" action=\"/process_upload\" enctype=\"multipart/form-data\">
        <label for=\"file\"><strong>Or upload a file (.txt or .pdf, max 2 MB)</strong></label><br>
        <input id=\"file\" name=\"file\" type=\"file\" accept=\".txt,application/pdf\">
        <div style=\"margin-top:10px\">
          <button class=\"btn\" type=\"submit\">Generate Spell</button>
          <span class=\"muted\">PDF support requires PyPDF2 on the server.</span>
        </div>
      </form>
    </div>

    <footer class=\"muted\">For entertainment purposes. Sources: Wikipedia, Wikidata, Datamuse.</footer>
    """
    return render_page("Recipe to Spell — Embed", body)


def render_result(ingredients: List[str], spell: str, sources: Dict[str, str]):
    if not ingredients:
        return render_embed_form("We couldn't find any ingredients. Please paste a clearer ingredients list or upload a different file.")

    pills = " ".join(f"<span class='pill'>{html.escape(ing)}</span>" for ing in ingredients)
    src_html = f"""
      <details style=\"margin-top:10px\">
        <summary class=\"muted\">About these results</summary>
        <div class=\"muted mono\">Lookups use: {html.escape(sources.get('wikipedia','wikipedia'))}, {html.escape(sources.get('wikidata','wikidata'))}, Datamuse</div>
      </details>
    """
    body = f"""
      <a href=\"/embed\" class=\"muted\">← Back</a>
      <h1>Your Kitchen Spell</h1>
      <div class=\"ok\">Ingredients recognized:</div>
      <div>{pills}</div>
      <div class=\"card\" style=\"white-space:pre-wrap;margin-top:12px\">{html.escape(spell)}</div>
      {src_html}
    """
    return render_page("Your Spell", body)


# --------- Routes ---------

@app.route("/")
def root():
    return redirect("/embed")


@app.route("/embed", methods=["GET"])
def embed():
    return render_embed_form()


@app.route("/process_text", methods=["POST"]))

def process_text():
    text = (request.form.get("recipe_text") or "").strip()
    if not text or len(text) < 10:
        return render_embed_form("Please paste your recipe text (at least 10 characters).")

    ings = extract_ingredients_from_text(text)
    if not ings:
        return render_embed_form("No ingredients detected. Try formatting as a bulleted list under an Ingredients section.")

    spell = build_spell(ings)
    if not spell:
        return render_embed_form("Something went wrong building the spell. Please try again.")

    # For disclosure display only
    sources = {"wikipedia": "Wikipedia", "wikidata": "Wikidata", "datamuse": "Datamuse"}
    return render_result(ings, spell, sources)


@app.route("/process_upload", methods=["POST"]) 
def process_upload():
    if "file" not in request.files:
        return render_embed_form("No file part in the request.")

    f = request.files["file"]
    if not f or f.filename == "":
        return render_embed_form("Please choose a .txt or .pdf file (max 2 MB).")

    filename = f.filename.lower()
    if not (filename.endswith(".txt") or filename.endswith(".pdf")):
        return render_embed_form("Unsupported file type. Please upload a .txt or .pdf file.")

    try:
        file_bytes = f.read()
        if not file_bytes:
            return render_embed_form("The uploaded file was empty.")
        if len(file_bytes) > app.config["MAX_CONTENT_LENGTH"]:
            return render_embed_form("File too large. Please upload a file under 2 MB.")

        if filename.endswith(".txt"):
            try:
                text = file_bytes.decode("utf-8", errors="ignore")
            except Exception:
                text = file_bytes.decode("latin-1", errors="ignore")
        else:
            try:
                text = extract_text_from_pdf(file_bytes)
            except RuntimeError as e:
                return render_embed_form(str(e))

        text = (text or "").strip()
        if not text:
            return render_embed_form("We couldn't read any text from that file.")

        ings = extract_ingredients_from_text(text)
        if not ings:
            return render_embed_form("No ingredients detected in the file. Please try another file or paste the text.")

        spell = build_spell(ings)
        if not spell:
            return render_embed_form("Something went wrong building the spell. Please try again.")

        sources = {"wikipedia": "Wikipedia", "wikidata": "Wikidata", "datamuse": "Datamuse"}
        return render_result(ings, spell, sources)

    except Exception as e:
        logger.exception("Upload processing failed")
        return render_embed_form("Unexpected error while processing the upload. Please try again.")


if __name__ == "__main__":
    port = int(os.environ.get("PORT", "8000"))
    app.run(host="0.0.0.0", port=port)
