    resp = make_response(tpl, status)
    resp.headers["Content-Security-Policy"] = "default-src 'self'; img-src 'self' data:; style-src 'unsafe-inline' 'self'; script-src 'self' 'unsafe-inline'; connect-src 'self' https://api.datamuse.com https://en.wikipedia.org https://www.wikidata.org"
    resp.headers["X-Frame-Options"] = "ALLOWALL"
    resp.headers["Cache-Control"] = "no-store"
    return resp


def render_form(error: Optional[str] = None) -> "flask.Response":
    err_html = f"<div class=\"error\">{html.escape(error)}</div>" if error else ""
    body = f"""
    <h1>Spell Generator — from your recipe</h1>
    <div class=\"card\">{err_html}
      <form method=\"post\" action=\"/submit-text\" enctype=\"application/x-www-form-urlencoded\">
        <label for=\"recipe\"><strong>Paste recipe text</strong></label>
        <textarea id=\"recipe\" name=\"recipe\" placeholder=\"Paste a full recipe or an Ingredients list...\"></textarea>
        <div class=\"row\" style=\"align-items:center; justify-content:space-between; margin-top:8px;\">
          <span class=\"muted\">We only use public info to inspire the spell. No data is stored.</span>
          <button type=\"submit\">Make my spell</button>
        </div>
      </form>
    </div>

    <div class=\"card\">
      <form method=\"post\" action=\"/submit-file\" enctype=\"multipart/form-data\">
        <label for=\"file\"><strong>Or upload a .txt or .pdf</strong></label>
        <input id=\"file\" name=\"file\" type=\"file\" accept=\".txt,application/pdf\">
        <div class=\"row\" style=\"align-items:center; justify-content:space-between; margin-top:8px;\">
          <span class=\"muted\">Max 2 MB. PDFs require server PDF support.</span>
          <button type=\"submit\">Upload and make spell</button>
        </div>
      </form>
    </div>
    <p class=\"muted\">Embed via iframe at /embed.</p>
    """
    return html_page("Spell Generator", body)


def render_result(ingredients: List[str], spell: str, lore: Dict[str, Dict]) -> "flask.Response":
    if not ingredients:
        return render_form("We could not detect any ingredients. Please paste a clearer ingredients list or upload a .txt/.pdf file.")

    items = []
    for ing in ingredients:
        info = lore.get(ing, {})
        srcs = info.get("sources", {})
        lines = [f"<strong>{html.escape(ing.title())}</strong>"]
        if info.get("wikidata_description"):
            lines.append(html.escape(info["wikidata_description"]))
        elif info.get("wikipedia_summary"):
            lines.append(html.escape(truncate(info["wikipedia_summary"], 200)))
        links = []
        if srcs.get("wikipedia"):
            links.append(f"<a href=\"{html.escape(srcs['wikipedia'])}\" target=\"_blank\" rel=\"noopener\">Wikipedia</a>")
        if srcs.get("wikidata_search"):
            links.append(f"<a href=\"{html.escape(srcs['wikidata_search'])}\" target=\"_blank\" rel=\"noopener\">Wikidata</a>")
        if links:
            lines.append(" ".join(links))
        items.append("<li>" + " — ".join(lines) + "</li>")

    body = f"""
    <h1>Your Ingredient-born Incantation</h1>
    <div class=\"card success\">
      <pre>{html.escape(spell)}</pre>
    </div>
    <div class=\"card\">
      <h2 style=\"margin-top:0\">Ingredients & Lore</h2>
      <ul>{''.join(items)}</ul>
      <div class=\"muted\">This playful content is inspired by public sources and word associations.</div>
    </div>
    <div style=\"margin:16px 0\"><a href=\"/embed\">Make another</a></div>
    """
    return html_page("Your Spell", body)

