@app.route("/embed", methods=["GET"])
def embed() -> "flask.Response":
    # Renders the embeddable form UI
    return render_form()


def validate_and_extract_from_text(recipe_text: str) -> List[str]:
    text = (recipe_text or "").strip()
    if not text:
        raise ValueError("Please paste a recipe or ingredients list.")
    ings = extract_ingredients_from_text(text)
    if not ings:
        raise ValueError("We couldn't find any ingredients in the pasted text.")
    return ings


def validate_and_extract_from_file(file_storage) -> List[str]:
    if not file_storage or not getattr(file_storage, "filename", ""):
        raise ValueError("Please choose a .txt or .pdf file to upload.")
    filename = file_storage.filename or ""
    name_lower = filename.lower()
    if not (name_lower.endswith(".txt") or name_lower.endswith(".pdf")):
        raise ValueError("Only .txt or .pdf files are allowed.")
    try:
        data = file_storage.read()
        if not data:
            raise ValueError("The uploaded file was empty.")
        if len(data) > app.config["MAX_CONTENT_LENGTH"]:
            raise ValueError("The file is too large (limit 2 MB).")
        if name_lower.endswith(".txt"):
            try:
                text = data.decode("utf-8", errors="ignore")
            except Exception:
                text = data.decode("latin-1", errors="ignore")
        else:  # pdf
            text = extract_text_from_pdf(data)
        ings = extract_ingredients_from_text(text)
        if not ings:
            raise ValueError("We couldn't find any ingredients in that file.")
        return ings
    finally:
        try:
            file_storage.close()
        except Exception:
            pass


@app.route("/submit-text", methods=["POST"])
def submit_text() -> "flask.Response":
    try:
        recipe = request.form.get("recipe", "")
        ingredients = validate_and_extract_from_text(recipe)
    except ValueError as e:
        return render_form(str(e))
    except Exception:
        return render_form("Something went wrong while reading your text. Please try again.")

    # Lookups and spell generation
    lore = {ing: fetch_knowledge_for_ingredient(ing) for ing in ingredients}
    spell = build_spell(ingredients, lore)
    return render_result(ingredients, spell, lore)


@app.route("/submit-file", methods=["POST"])
def submit_file() -> "flask.Response":
    try:
        file = request.files.get("file")
        ingredients = validate_and_extract_from_file(file)
    except ValueError as e:
        return render_form(str(e))
    except RuntimeError as e:
        return render_form(str(e))
    except Exception:
        return render_form("Something went wrong while processing your file. Please try again with a .txt or .pdf.")

    lore = {ing: fetch_knowledge_for_ingredient(ing) for ing in ingredients}
    spell = build_spell(ingredients, lore)
    return render_result(ingredients, spell, lore)


