// C# code that embeds drawing primitives into a nanoCAD McTable cell using the MultiCAD .NET API.
//
// The function below:
//   1) Creates (or recreates) a dedicated block definition for the target cell.
//   2) Converts input geometry to McDbEntity instances and appends them to that block.
//   3) Computes a fitting scale for the block so it fits inside the cell with optional padding.
//   4) Assigns the block as content of the specified cell [row, col].
//   5) Commits the transaction.
//
// Notes:
// - Replace EntityGeometry.ToEntity() implementations in your codebase to produce concrete McDbEntity objects
//   (e.g., McDbLine, McDbCircle, etc.).
// - This example assumes common MultiCAD .NET API class names found in nanoCAD SDKs. Adjust namespaces/types
//   if your SDK version differs slightly.

using System;
using System.Collections.Generic;
using Multicad.ApplicationServices;
using Multicad.DatabaseServices;
using Multicad.Geometry;
using Multicad.Runtime;

namespace YourCompany.YourPlugin
{
    // Abstraction for input geometry. Implement ToEntity() in your project.
    public abstract class EntityGeometry
    {
        public abstract McDbEntity ToEntity();
    }

    public static class TableCellGeometryEmbedder
    {
        /// <summary>
        /// Embeds drawing primitives (as a block) into a nanoCAD McTable cell at [row, col].
        /// </summary>
        /// <param name="table">Target McDbTable already present in the database.</param>
        /// <param name="row">Zero-based row index of the target cell.</param>
        /// <param name="col">Zero-based column index of the target cell.</param>
        /// <param name="entityGeometry">List of geometry descriptors that can produce McDbEntity instances.</param>
        /// <param name="padding">Optional padding (drawing units) around content inside the cell.</param>
        /// <param name="blockNamePrefix">Prefix used to name the per-cell block definition.</param>
        public static void EmbedGeometryIntoCell(
            McDbTable table,
            int row,
            int col,
            IList<EntityGeometry> entityGeometry,
            double padding = 0.0,
            string blockNamePrefix = "_CellGeom_")
        {
            if (table == null) throw new ArgumentNullException(nameof(table));
            if (entityGeometry == null || entityGeometry.Count == 0)
                throw new ArgumentException("entityGeometry must contain at least one item.", nameof(entityGeometry));
            if (row < 0 || row >= table.RowsCount)
                throw new ArgumentOutOfRangeException(nameof(row));
            if (col < 0 || col >= table.ColsCount)
                throw new ArgumentOutOfRangeException(nameof(col));
            if (padding < 0)
                throw new ArgumentOutOfRangeException(nameof(padding), "Padding cannot be negative.");

            var db = table.Database ?? throw new InvalidOperationException("Table is not database-resident.");

            // Build a unique block name for the cell so it can be updated on subsequent calls.
            string blockName = $"{blockNamePrefix}R{row}C{col}";

            using (var tr = db.TransactionManager.StartTransaction())
            {
                // Open essential tables
                var btId = db.BlockTableId;
                var bt = (McDbBlockTable)tr.GetObject(btId, OpenMode.ForRead);

                // If a block with the same name exists, erase it so we can recreate with fresh contents.
                if (bt.Has(blockName))
                {
                    var oldBtrId = bt[blockName];
                    var oldBtr = (McDbBlockTableRecord)tr.GetObject(oldBtrId, OpenMode.ForWrite);
                    oldBtr.Erase(true);
                }

                // Create a new block definition
                var btr = new McDbBlockTableRecord { Name = blockName };
                bt.UpgradeOpen();
                var newBtrId = bt.Add(btr);
                tr.AddNewlyCreatedDBObject(btr, true);

                // Convert input geometry to entities and append them to the block
                Extents3d? extOpt = null;
                foreach (var eg in entityGeometry)
                {
                    if (eg == null) continue; // Skip null entries
                    McDbEntity ent = eg.ToEntity();
                    if (ent == null) continue; // Skip if conversion failed

                    btr.AppendEntity(ent);
                    tr.AddNewlyCreatedDBObject(ent, true);

                    // Accumulate extents for fitting
                    try
                    {
                        if (ent.Bounds.HasValue)
                        {
                            var e = ent.Bounds.Value; // Extents3d
                            extOpt = extOpt.HasValue ? Union(extOpt.Value, e) : e;
                        }
                    }
                    catch
                    {
                        // Some entities may not provide bounds until regen; ignore safely
                    }
                }

                // If no extents available (e.g., all zero-length), create a tiny extents to avoid div-by-zero
                var contentExt = extOpt ?? new Extents3d(new Point3d(0, 0, 0), new Point3d(1e-6, 1e-6, 0));

                // Compute cell geometry (width/height in drawing units)
                // Open table for write to assign content
                var tblForWrite = (McDbTable)tr.GetObject(table.ObjectId, OpenMode.ForWrite);
                double cellWidth = tblForWrite.GetColumnWidth(col);
                double cellHeight = tblForWrite.GetRowHeight(row);

                // Apply padding
                double innerW = Math.Max(0.0, cellWidth - 2.0 * padding);
                double innerH = Math.max(0.0, cellHeight - 2.0 * padding);

                // Compute block extents size
                double bx = contentExt.MaxPoint.X - contentExt.MinPoint.X;
                double by = contentExt.MaxPoint.Y - contentExt.MinPoint.Y;
                if (bx <= 0) bx = 1e-6;
                if (by <= 0) by = 1e-6;

                // Uniform scale to fit inside cell
                double sx = innerW / bx;
                double sy = innerH / by;
                double scale = Math.Min(sx, sy);
                if (double.IsInfinity(scale) || double.IsNaN(scale) || scale <= 0) scale = 1.0;

                // Compute insertion so that block is centered in cell
                // Cell bottom-left in table coordinates
                Point3d cellOrigin = tblForWrite.GetCellOrigin(row, col); // bottom-left corner of cell in WCS
                // Target center point inside cell
                var targetCenter = new Point3d(
                    cellOrigin.X + padding + innerW / 2.0,
                    cellOrigin.Y + padding + innerH / 2.0,
                    cellOrigin.Z);

                // Block extents center
                var srcCenter = new Point3d(
                    contentExt.MinPoint.X + bx / 2.0,
                    contentExt.MinPoint.Y + by / 2.0,
                    0.0);

                // Create block reference and transform it: translate(-srcCenter) -> scale -> translate(targetCenter)
                var br = new McDbBlockReference
                {
                    BlockTableRecord = newBtrId,
                    Position = targetCenter
                };

                // Compose transform: T = S(at origin after shifting to source center)
                var toOrigin = Matrix3d.Displacement(new Vector3d(-srcCenter.X, -srcCenter.Y, 0.0));
                var scaleMat = Matrix3d.Scaling(scale, Point3d.Origin);
                Matrix3d xf = Matrix3d.Identity;
                xf = xf.PreMultiplyBy(toOrigin);
                xf = xf.PreMultiplyBy(scaleMat);
                br.TransformBy(xf);

                // Add the block reference to the table's owner space (model space or paper space)
                var btrOwnerId = tblForWrite.OwnerId;
                var ownerBtr = (McDbBlockTableRecord)tr.GetObject(btrOwnerId, OpenMode.ForWrite);
                ownerBtr.AppendEntity(br);
                tr.AddNewlyCreatedDBObject(br, true);

                // Assign the block definition to the cell content with scale and centered alignment
                tblForWrite.SetCellType(row, col, McTableCellType.Block);
                tblForWrite.SetCellBlock(row, col, newBtrId, scale, CellContentAlignment.MiddleCenter);

                tr.Commit();
            }
        }

        // Union of two extents
        private static Extents3d Union(Extents3d a, Extents3d b)
        {
            var min = new Point3d(
                Math.Min(a.MinPoint.X, b.MinPoint.X),
                Math.Min(a.MinPoint.Y, b.MinPoint.Y),
                Math.Min(a.MinPoint.Z, b.MinPoint.Z));
            var max = new Point3d(
                Math.Max(a.MaxPoint.X, b.MaxPoint.X),
                Math.Max(a.MaxPoint.Y, b.MaxPoint.Y),
                Math.Max(a.MaxPoint.Z, b.MaxPoint.Z));
            return new Extents3d(min, max);
        }
    }
}
