public static bool EmbedGeometryIntoTableCell(List<EntityGeometry> geometries, McTable table, int row, int col, string blockName)
{
    // Purpose: Convert List<EntityGeometry> to McDbEntity objects, place them into a block,
    // scale/fit the block to the target McTable cell [row, col], assign it to the cell, and commit.
    // Returns true if successful; false otherwise.

    // Minimal input validation
    if (table == null) throw new ArgumentNullException(nameof(table));
    if (geometries == null) throw new ArgumentNullException(nameof(geometries));
    if (row < 0 || row >= table.RowsCount) throw new ArgumentOutOfRangeException(nameof(row));
    if (col < 0 || col >= table.ColsCount) throw new ArgumentOutOfRangeException(nameof(col));
    if (string.IsNullOrWhiteSpace(blockName)) blockName = "_CellGeomBlock";

    try
    {
        // Start a database transaction
        using (var tr = McTransaction.Start())
        {
            var db = McApplication.ActiveDocument.Database;

            // Collect converted entities
            var createdEntities = new List<McDbEntity>();

            // Helper: convert EntityGeometry to concrete McDbEntity primitives.
            // Assumes EntityGeometry exposes Type and data for typical primitives.
            // Replace switch cases as appropriate for your EntityGeometry schema.
            foreach (var g in geometries)
            {
                if (g == null) continue;

                switch (g.Type)
                {
                    case EntityGeometryType.Line:
                    {
                        var ln = new McDbLine(g.StartPoint, g.EndPoint);
                        createdEntities.Add(ln);
                        break;
                    }
                    case EntityGeometryType.Circle:
                    {
                        var c = new McDbCircle(g.Center, g.Radius);
                        createdEntities.Add(c);
                        break;
                    }
                    case EntityGeometryType.Arc:
                    {
                        var a = new McDbArc(g.Center, g.Radius, g.StartAngle, g.EndAngle);
                        createdEntities.Add(a);
                        break;
                    }
                    case EntityGeometryType.Polyline:
                    {
                        var pl = new McDbPolyline();
                        foreach (var v in g.Vertices) pl.AddVertexAt(v);
                        createdEntities.Add(pl);
                        break;
                    }
                    case EntityGeometryType.Text:
                    {
                        var t = new McDbText(g.TextPosition, g.TextString, g.TextHeight, 0.0);
                        createdEntities.Add(t);
                        break;
                    }
                    default:
                        // Skip unsupported geometry types
                        break;
                }
            }

            if (createdEntities.Count == 0)
            {
                // Nothing to place
                tr.Abort();
                return false;
            }

            // Create or update block definition
            McDbBlockTable bt = (McDbBlockTable)tr.GetObject(db.BlockTableId, OpenMode.ForRead);
            McDbObjectId btrId;
            McDbBlockTableRecord btr;

            if (bt.Has(blockName))
            {
                btrId = bt[blockName];
                btr = (McDbBlockTableRecord)tr.GetObject(btrId, OpenMode.ForWrite);

                // Clear existing contents of the block
                var toErase = new List<McDbObjectId>();
                foreach (var id in btr)
                    toErase.Add(id);
                foreach (var id in toErase)
                {
                    var ent = (McDbEntity)tr.GetObject(id, OpenMode.ForWrite);
                    ent.Erase();
                }
            }
            else
            {
                bt.UpgradeOpen();
                btr = new McDbBlockTableRecord { Name = blockName };
                btrId = bt.Add(btr);
                tr.AddNewlyCreatedDBObject(btr, true);
            }

            // Append created entities to block definition
            foreach (var ent in createdEntities)
            {
                btr.AppendEntity(ent);
                tr.AddNewlyCreatedDBObject(ent, true);
            }

            // Compute the block content extents to fit into table cell
            // Create a temporary block reference at origin to get extents
            var tempRef = new McDbBlockReference(Point3d.Origin, btrId);
            var extOk = tempRef.GeometricExtents(out Extents3d ext);
            if (!extOk)
            {
                tempRef.Dispose();
                tr.Abort();
                return false;
            }

            var width = Math.Max(1e-9, ext.MaxPoint.X - ext.MinPoint.X);
            var height = Math.Max(1e-9, ext.MaxPoint.Y - ext.MinPoint.Y);
            tempRef.Dispose();

            // Get cell geometry (in WCS) to compute target placement and scale
            var cellRect = table.GetCellExtents(row, col); // returns Extents3d in WCS for the cell
            var cellW = Math.Max(1e-9, cellRect.MaxPoint.X - cellRect.MinPoint.X);
            var cellH = Math.Max(1e-9, cellRect.MaxPoint.Y - cellRect.MinPoint.Y);

            // Uniform scale to fit inside cell with small margin
            const double margin = 0.95; // 95% of cell size
            double sx = (cellW * margin) / width;
            double sy = (cellH * margin) / height;
            double s = Math.Min(sx, sy);

            // Target base point: center of the cell
            var cellCenter = new Point3d(
                (cellRect.MinPoint.X + cellRect.MaxPoint.X) * 0.5,
                (cellRect.MinPoint.Y + cellRect.MaxPoint.Y) * 0.5,
                0.0);

            // Compute insertion point so that block content center goes to cell center
            var contentCenter = new Point3d((ext.MinPoint.X + ext.MaxPoint.X) * 0.5, (ext.MinPoint.Y + ext.MaxPoint.Y) * 0.5, 0.0);
            var offset = (Vector3d)(cellCenter - contentCenter) * s;
            var insPt = new Point3d(contentCenter.X + offset.X, contentCenter.Y + offset.Y, 0.0);

            // Create the final block reference with transform
            var blkRef = new McDbBlockReference(insPt, btrId)
            {
                ScaleFactors = new Scale3d(s, s, 1.0),
                Rotation = 0.0
            };

            // Add block reference to ModelSpace (or appropriate owner)
            McDbBlockTableRecord ms = (McDbBlockTableRecord)tr.GetObject(bt[McDbSymbolUtilityServices.ModelSpaceName], OpenMode.ForWrite);
            var brId = ms.AppendEntity(blkRef);
            tr.AddNewlyCreatedDBObject(blkRef, true);

            // Assign the block reference to the target table cell
            table.UpgradeOpen();
            table.SetCellContent(row, col, new McTableCellContent(blkRef));

            // Commit all changes
            tr.Commit();
            return true;
        }
    }
    catch (System.Exception)
    {
        // Swallow or rethrow as needed; here we signal failure.
        return false;
    }
}

// Placeholder types for compilation context expectations:
// - EntityGeometry and EntityGeometryType are assumed to be user-defined structures
//   describing primitive data. Replace with your actual definitions.

using System;
using System.Collections.Generic;
using System.Linq;
using Multicad;
using Multicad.DatabaseServices;
using Multicad.DatabaseServices.Table;
using Multicad.Geometry;
using Multicad.Runtime;

public static class TableEmbedder
{
    /// <summary>
    /// Converts a list of EntityGeometry primitives into McDbEntity objects, creates or updates a block
    /// containing these entities, inserts the block reference into the specified McTable cell, and commits the transaction.
    /// </summary>
    /// <param name="table">Target McTable instance.</param>
    /// <param name="row">Zero-based row index of the target cell.</param>
    /// <param name="col">Zero-based column index of the target cell.</param>
    /// <param name="geometries">List of EntityGeometry primitives to embed.</param>
    /// <param name="blockName">Optional block name. If null or empty, a deterministic name will be generated.</param>
    public static void EmbedPrimitivesIntoTableCell(McTable table, int row, int col, List<EntityGeometry> geometries, string blockName = null)
    {
        // Minimal input validation
        if (table == null) throw new ArgumentNullException(nameof(table));
        if (geometries == null) throw new ArgumentNullException(nameof(geometries));
        if (row < 0 || row >= table.RowsCount) throw new ArgumentOutOfRangeException(nameof(row));
        if (col < 0 || col >= table.ColumnsCount) throw new ArgumentOutOfRangeException(nameof(col));
        if (geometries.Count == 0) return; // Nothing to embed

        try
        {
            var db = McContext.Database;
            if (db == null) throw new InvalidOperationException("No active database context.");

            // Resolve or generate block name
            string name = string.IsNullOrWhiteSpace(blockName)
                ? $"_EMBED_{Math.Abs(string.Join(";", geometries.Select(g => g?.ToString() ?? "")).GetHashCode())}"
                : blockName.Trim();

            using (var tr = db.TransactionManager.StartTransaction())
            {
                // Get block table
                var btId = db.BlockTableId;
                var bt = (McDbBlockTable)tr.GetObject(btId, OpenMode.ForRead);

                // Create or open block definition
                McObjectId btrId;
                McDbBlockTableRecord btr;
                if (bt.Has(name))
                {
                    btrId = bt[name];
                    btr = (McDbBlockTableRecord)tr.GetObject(btrId, OpenMode.ForWrite);
                    // Clear existing entities in the block to "update" it with new geometry
                    var toErase = btr.Cast<McDbEntity>().Select(e => e.Id).ToList();
                    foreach (var id in toErase)
                    {
                        var ent = (McDbEntity)tr.GetObject(id, OpenMode.ForWrite);
                        ent.Erase();
                    }
                }
                else
                {
                    bt.UpgradeOpen();
                    btr = new McDbBlockTableRecord { Name = name };
                    btrId = bt.Add(btr);
                    tr.AddNewlyCreatedDBObject(btr, true);
                }

                // Convert EntityGeometry list to concrete McDbEntity objects and append to block
                var createdIds = new List<McObjectId>(geometries.Count);
                foreach (var g in geometries)
                {
                    if (g == null) continue;
                    McDbEntity ent = CreateEntityFromGeometry(g);
                    if (ent == null) continue;
                    var id = btr.AppendEntity(ent);
                    tr.AddNewlyCreatedDBObject(ent, true);
                    createdIds.Add(id);
                }

                if (createdIds.Count == 0)
                    throw new InvalidOperationException("No valid entities were created from the provided geometries.");

                // Compute extents of entities inside the block to scale into the target cell
                Extents3d ext = ComputeBlockExtents(createdIds, tr);
                if (ext.IsEmpty)
                    throw new InvalidOperationException("Cannot compute extents for the created entities.");

                // Determine target cell rectangle in WCS
                var cellRange = table.GetCellRange(row, col, row, col);
                var cellGeom = table.GetCellGeometry(cellRange);
                // cellGeom returns points for the cell polygon; derive a fit box
                // Assume bottom-left to top-right rectangle from polygon extents
                var cellExt = new Extents3d();
                foreach (var p in cellGeom)
                    cellExt.AddPoint(new Point3d(p.X, p.Y, 0.0));

                // Build a block reference and fit it into cell
                var br = new McDbBlockReference
                {
                    BlockTableRecord = btrId,
                    Position = cellExt.MinPoint
                };

                // Scale and move to fit
                var srcSize = new Vector3d(ext.MaxPoint.X - ext.MinPoint.X, ext.MaxPoint.Y - ext.MinPoint.Y, 0.0);
                var dstSize = new Vector3d(cellExt.MaxPoint.X - cellExt.MinPoint.X, cellExt.MaxPoint.Y - cellExt.MinPoint.Y, 0.0);
                if (srcSize.X <= 1e-9 || srcSize.Y <= 1e-9)
                    throw new InvalidOperationException("Source geometry has degenerate extents.");

                double sx = dstSize.X / srcSize.X;
                double sy = dstSize.Y / srcSize.Y;
                double s = Math.Min(sx, sy);

                // Normalize block so its extents start at origin, then scale, then move into cell
                var moveToOrigin = Matrix3d.Displacement(new Vector3d(-ext.MinPoint.X, -ext.MinPoint.Y, 0.0));
                var scale = Matrix3d.Scaling(s, Point3d.Origin);
                var place = Matrix3d.Displacement(new Vector3d(cellExt.MinPoint.X, cellExt.MinPoint.Y, 0.0));
                br.TransformBy(moveToOrigin * scale * place);

                // Place the block reference in model space (owner per table context). We use the table's owner space.
                var ownerId = table.OwnerId;
                var owner = (McDbBlockTableRecord)tr.GetObject(ownerId, OpenMode.ForWrite);
                var brId = owner.AppendEntity(br);
                tr.AddNewlyCreatedDBObject(br, true);

                // Assign the block reference to the cell: set cell content as block reference if supported, else attach as field geometry
                // Using SetCellBlock to assign block name and adjust scale by cell if API supports; fallback is geometric placement already done.
                try
                {
                    table.UpgradeOpen();
                    table.SetCellBlock(row, col, name);
                    // Optional: center alignment
                    table.SetCellAlignment(row, col, McTableCellAlignment.MiddleCenter);
                }
                catch
                {
                    // If SetCellBlock is unavailable in the current environment, we already placed the reference visually.
                }

                tr.Commit();
            }
        }
        catch (System.Exception ex)
        {
            // Minimal robust error reporting within plugin context
            McContext.ShowAlert($"EmbedPrimitivesIntoTableCell failed: {ex.Message}");
            throw;
        }
    }

    // Convert a single EntityGeometry into a concrete McDbEntity
    private static McDbEntity CreateEntityFromGeometry(EntityGeometry g)
    {
        switch (g.Type)
        {
            case EntityGeometryType.Line:
                return new McDbLine
                {
                    StartPoint = new Point3d(g.P1.X, g.P1.Y, g.P1.Z),
                    EndPoint = new Point3d(g.P2.X, g.P2.Y, g.P2.Z)
                };
            case EntityGeometryType.Circle:
                return new McDbCircle
                {
                    Center = new Point3d(g.Center.X, g.Center.Y, g.Center.Z),
                    Radius = g.Radius
                };
            case EntityGeometryType.Arc:
                return new McDbArc
                {
                    Center = new Point3d(g.Center.X, g.Center.Y, g.Center.Z),
                    Radius = g.Radius,
                    StartAngle = g.StartAngle,
                    EndAngle = g.EndAngle
                };
            case EntityGeometryType.Polyline:
                var pl = new McDbPolyline();
                foreach (var p in g.Vertices)
                    pl.AddVertexAt(pl.NumberOfVertices, new Point2d(p.X, p.Y), 0.0, 0.0, 0.0);
                pl.Closed = g.Closed;
                return pl;
            default:
                return null;
        }
    }

    // Compute extents for a set of entities contained in a block
    private static Extents3d ComputeBlockExtents(IEnumerable<McObjectId> ids, McTransaction tr)
    {
        var ext = new Extents3d();
        bool inited = false;
        foreach (var id in ids)
        {
            var ent = tr.GetObject(id, OpenMode.ForRead) as McDbEntity;
            if (ent == null) continue;
            try
            {
                var e = ent.GeometricExtents;
                if (!inited)
                {
                    ext = e;
                    inited = true;
                }
                else
                {
                    ext.AddExtents(e);
                }
            }
            catch
            {
                // ignore entities that fail to provide extents
            }
        }
        return ext;
    }
}

// NOTE: The EntityGeometry and related enums/structs are assumed to be part of your codebase
// that describes drawing primitives. They should expose properties used above:
// - Type: EntityGeometryType (Line, Circle, Arc, Polyline)
// - For Line: P1, P2 (Point3d-like with X,Y,Z)
// - For Circle/Arc: Center, Radius; for Arc: StartAngle, EndAngle
// - For Polyline: Vertices (collection with X,Y[,Z]), Closed

//@version=5
indicator("Pivot High/Low + Missed Reversals (with Alerts)", overlay=true, timeframe="")

// =====================
// Inputs
// =====================
phLen      = input.int(5,   "Pivot High Left/Right Bars", minval=1)
plLen      = input.int(5,   "Pivot Low Left/Right Bars",  minval=1)
lookaheadB = input.int(200, "Bars to look back for missed pivots", minval=1, tooltip="How far back to search for an untested pivot before declaring it 'missed'")

// Missed pivot definition options
confirmBars     = input.int(3, "Bars to confirm a miss", minval=1, tooltip="How many bars after a pivot without a test/violation before we flag it as missed")
requireRetest   = input.bool(true, "Require price to revisit pivot zone to avoid 'miss'", tooltip="If enabled, a pivot is considered missed only if price never revisits the pivot level +/- tolerance before confirmation bars elapse")
retestTolerance = input.float(0.0, "Retest tolerance (ticks)", minval=0.0, tooltip="Allowable distance from pivot price to consider it revisited. 0 = exact price only")

// Plot styling
showPivots      = input.bool(true,  "Show regular pivot labels/lines")
showMissed      = input.bool(true,  "Show missed pivot warnings/markers")
phColor         = input.color(color.new(color.red,   0), "Pivot High Color")
plColor         = input.color(color.new(color.lime,  0), "Pivot Low Color")
missHighColor   = input.color(color.new(color.orange, 0), "Missed High Color")
missLowColor    = input.color(color.new(color.aqua,   0), "Missed Low Color")
lineStyle       = input.string("Dotted", "Pivot Line Style", options=["Solid","Dotted","Dashed"])
lineWidth       = input.int(1, "Pivot Line Width", minval=1, maxval=4)

// Alerts
enableAlerts    = input.bool(true,  "Enable alerts for missed pivots")
alertOnCreate   = input.bool(true,  "Alert when a missed pivot is detected")
alertOnTouch    = input.bool(false, "Alert when price later touches a missed pivot")

// =====================
// Helpers
// =====================
var line_style_map = input.string == na ? line.style_dotted : 0
f_style(str) => str == "Solid" ? line.style_solid : str == "Dashed" ? line.style_dashed : line.style_dotted

// Pine pivots (confirmed)
pH = ta.pivothigh(high, phLen, phLen)
pL = ta.pivotlow(low,  plLen, plLen)

// Pivot values and bar index at confirmation
pivotHighVal = na(pH) ? na : pH
pivotLowVal  = na(pL) ? na : pL
pivotHighBar = ta.bar_index(phLen)  // bar_index of the pivot confirmation bar
pivotLowBar  = ta.bar_index(plLen)

// =====================
// Plot regular pivots
// =====================
if showPivots and not na(pivotHighVal)
    // Mark the pivot bar with a label and optional line
    label.new(pivotHighBar, pivotHighVal, text="PH", style=label.style_label_down, color=color.new(phColor, 0), textcolor=color.white)
    line.new(pivotHighBar - 50, pivotHighVal, bar_index, pivotHighVal, extend=extend.right, color=color.new(phColor, 70), style=f_style(lineStyle), width=lineWidth)

if showPivots and not na(pivotLowVal)
    label.new(pivotLowBar, pivotLowVal, text="PL", style=label.style_label_up, color=color.new(plColor, 0), textcolor=color.white)
    line.new(pivotLowBar - 50, pivotLowVal, bar_index, pivotLowVal, extend=extend.right, color=color.new(plColor, 70), style=f_style(lineStyle), width=lineWidth)

// =====================
// Missed pivot tracking
// A pivot high is considered 'missed' if, within `confirmBars` after confirmation,
// price does not revisit the pivot level (within tolerance if enabled) and then
// moves away without testing it. Similarly for pivot lows.
// We will track recent pivots in arrays and decide after confirmBars bars.
// =====================
var float[] ph_vals = array.new_float()
var int[]   ph_bars = array.new_int()
var bool[]  ph_missed = array.new_bool()

var float[] pl_vals = array.new_float()
var int[]   pl_bars = array.new_int()
var bool[]  pl_missed = array.new_bool()

// Push new pivots when they confirm
if not na(pivotHighVal)
    array.push(ph_vals, pivotHighVal)
    array.push(ph_bars, pivotHighBar)
    array.push(ph_missed, false)

if not na(pivotLowVal)
    array.push(pl_vals, pivotLowVal)
    array.push(pl_bars, pivotLowBar)
    array.push(pl_missed, false)

// Trim arrays to lookback window
f_trim(arrVals, arrBars) =>
    for i = array.size(arrBars) - 1 to 0
        if bar_index - array.get(arrBars, i) > lookaheadB
            array.remove(arrBars, i)
            array.remove(arrVals, i)

f_trim_miss(arrMiss) =>
    for i = array.size(arrMiss) - 1 to 0
        // Keep miss array aligned externally where we remove in the value/bar trim
        na

// Apply trim while keeping alignment across parallel arrays
if array.size(ph_bars) > 0
    for i = array.size(ph_bars) - 1 to 0
        if bar_index - array.get(ph_bars, i) > lookaheadB
            array.remove(ph_bars, i)
            array.remove(ph_vals, i)
            array.remove(ph_missed, i)

if array.size(pl_bars) > 0
    for i = array.size(pl_bars) - 1 to 0
        if bar_index - array.get(pl_bars, i) > lookaheadB
            array.remove(pl_bars, i)
            array.remove(pl_vals, i)
            array.remove(pl_missed, i)

// Determine revisit condition
f_revisited(piv, isHigh) =>
    tol = retestTolerance
    // If tolerance is disabled (requireRetest = false), any bar after pivot counts as revisited-allowed
    cond = not requireRetest ? true : (isHigh ? high >= piv - tol and low <= piv + tol and (high >= piv - tol or low <= piv + tol) : high >= piv - tol and low <= piv + tol and (high >= piv - tol or low <= piv + tol))
    // Better revisit definition: price touches the level within tolerance
    cond2 = requireRetest ? (high >= piv - tol and low <= piv + tol) : true
    cond2

// Check and flag missed pivots after confirmBars have elapsed
var bool newMissHigh = false
var bool newMissLow  = false
var float lastMissHigh = na
var float lastMissLow  = na

if array.size(ph_vals) > 0
    for i = 0 to array.size(ph_vals) - 1
        if not array.get(ph_missed, i)
            pivBar = array.get(ph_bars, i)
            pivVal = array.get(ph_vals, i)
            barsSince = bar_index - pivBar
            if barsSince >= confirmBars
                // Evaluate revisit in the window [pivBar+1, current]
                // We'll approximate using the running highest/lowest since pivot using ta.highest/lowest over barsSince
                // If price touched within tolerance -> not missed
                // If not touched -> missed
                touched = false
                barsWindow = math.min(barsSince, 5000)
                // Scan last N bars for touch efficiently using series ops across the whole window is tricky; here we approximate with range overlap
                // If within the window, highest high >= piv - tol and lowest low <= piv + tol -> a touch occurred at some point
                tol = retestTolerance
                hh = ta.highest(high, math.max(1, barsWindow))
                ll = ta.lowest(low,  math.max(1, barsWindow))
                touched := (hh >= pivVal - tol) and (ll <= pivVal + tol)
                if not requireRetest
                    touched := true
                if not touched
                    array.set(ph_missed, i, true)
                    newMissHigh := true
                    lastMissHigh := pivVal

if array.size(pl_vals) > 0
    for i = 0 to array.size(pl_vals) - 1
        if not array.get(pl_missed, i)
            pivBar = array.get(pl_bars, i)
            pivVal = array.get(pl_vals, i)
            barsSince = bar_index - pivBar
            if barsSince >= confirmBars
                tol = retestTolerance
                barsWindow = math.min(barsSince, 5000)
                hh = ta.highest(high, math.max(1, barsWindow))
                ll = ta.lowest(low,  math.max(1, barsWindow))
                touched = (hh >= pivVal - tol) and (ll <= pivVal + tol)
                if not requireRetest
                    touched := true
                if not touched
                    array.set(pl_missed, i, true)
                    newMissLow := true
                    lastMissLow := pivVal

// =====================
// Plot and warn for missed pivots
// =====================
// Draw markers and lines for missed pivot levels
if showMissed
    if newMissHigh and not na(lastMissHigh)
        label.new(bar_index, lastMissHigh, text="Missed PH", style=label.style_label_down, color=color.new(missHighColor, 0), textcolor=color.white)
        line.new(bar_index - 50, lastMissHigh, bar_index, lastMissHigh, extend=extend.right, color=color.new(missHighColor, 0), style=f_style(lineStyle), width=lineWidth)
    if newMissLow and not na(lastMissLow)
        label.new(bar_index, lastMissLow, text="Missed PL", style=label.style_label_up, color=color.new(missLowColor, 0), textcolor=color.white)
        line.new(bar_index - 50, lastMissLow, bar_index, lastMissLow, extend=extend.right, color=color.new(missLowColor, 0), style=f_style(lineStyle), width=lineWidth)

// Optional: alert when price later touches a missed level
var bool touchedMissNow = false
var string touchedSide  = ""
if showMissed and (alertOnTouch or alertOnCreate)
    // Check current bar touch against any previously marked missed pivots
    // High side
    for i = 0 to array.size(ph_vals) - 1
        if array.size(ph_missed) > i and array.get(ph_missed, i)
            piv = array.get(ph_vals, i)
            if high >= piv - retestTolerance and low <= piv + retestTolerance
                touchedMissNow := true
                touchedSide := "high"
                break
    // Low side (only if not already detected)
    if not touchedMissNow
        for i = 0 to array.size(pl_vals) - 1
            if array.size(pl_missed) > i and array.get(pl_missed, i)
                piv = array.get(pl_vals, i)
                if high >= piv - retestTolerance and low <= piv + retestTolerance
                    touchedMissNow := true
                    touchedSide := "low"
                    break

// =====================
// Alerts
// =====================
missHighFired = enableAlerts and alertOnCreate and newMissHigh
missLowFired  = enableAlerts and alertOnCreate and newMissLow
missTouchFired= enableAlerts and alertOnTouch  and touchedMissNow

alertcondition(missHighFired, title="Missed Pivot High Detected", message="A missed pivot high has been detected at {{ticker}} {{close}}.")
alertcondition(missLowFired,  title="Missed Pivot Low Detected",  message="A missed pivot low has been detected at {{ticker}} {{close}}.")
alertcondition(missTouchFired, title="Missed Pivot Level Touched", message="Price has touched a previously missed pivot ({{ticker}} {{close}}) on the {{touchedSide}} side.")

// Real-time alert firing (for users who use 'Once per bar' alerts on this script, these fire programmatically too)
if missHighFired
    alert("Missed Pivot High detected.", alert.freq_once_per_bar)
if missLowFired
    alert("Missed Pivot Low detected.", alert.freq_once_per_bar)
if missTouchFired
    alert("Missed Pivot level touched.", alert.freq_once_per_bar)

// =====================
// Visual warnings on the chart for regular pivots (optional labels already drawn)
// Add small plotshapes for quick glance
// =====================
plotshape(showPivots and not na(pivotHighVal), title="Pivot High", style=shape.triangledown, color=phColor, location=location.abovebar, size=size.tiny, offset=-phLen)
plotshape(showPivots and not na(pivotLowVal),  title="Pivot Low",  style=shape.triangleup,   color=plColor, location=location.belowbar, size=size.tiny, offset=-plLen)

// Notes:
// - Use the Inputs to adjust pivot sensitivity and how/when a pivot becomes 'missed'.
// - Create alerts in TradingView using the three alert conditions provided.
// - Lines extend to the right for both regular and missed pivots to act as reference levels.

//@version=5
indicator("Pivot High/Low with Missed Pivot Alerts", overlay=true, timeframe="", timeframe_gaps=true)

// Inputs
leftLen  = input.int(5,  "Left pivot length",  minval=1)
rightLen = input.int(5,  "Right pivot length", minval=1)
showLabels = input.bool(true, "Show pivot labels")
showLines  = input.bool(true,  "Show connector lines")

// Alert behavior inputs
enableMissedHighAlert = input.bool(true,  "Enable missed pivot HIGH alerts")
enableMissedLowAlert  = input.bool(true,  "Enable missed pivot LOW alerts")
maxBarsToFill         = input.int(100, "Bars allowed to fill a pivot (miss window)", minval=1)

// Pivot detection
phPrice = ta.pivothigh(high, leftLen, rightLen)
plPrice = ta.pivotlow(low,  leftLen, rightLen)

phBarIndex = ta.valuewhen(not na(phPrice), bar_index[rightLen], 0)
plBarIndex = ta.valuewhen(not na(plPrice), bar_index[rightLen], 0)

// Track last confirmed pivot high/low
var float lastPH = na
var int   lastPHBar = na
var float lastPL = na
var int   lastPLBar = na

if not na(phPrice)
    lastPH := phPrice
    lastPHBar := phBarIndex
if not na(plPrice)
    lastPL := plPrice
    lastPLBar := plBarIndex

// Plot shapes for pivots at their confirmation bar
plotshape(not na(phPrice), title="Pivot High", style=shape.triangledown, color=color.red, size=size.tiny, location=location.abovebar, text=showLabels ? "PH" : "")
plotshape(not na(plPrice), title="Pivot Low",  style=shape.triangleup,   color=color.lime, size=size.tiny, location=location.belowbar, text=showLabels ? "PL" : "")

// Optional connector lines from pivot point to current bar for visual tracking
if showLines and not na(lastPH)
    line.new(lastPHBar, lastPH, bar_index, lastPH, xloc=xloc.bar_index, extend=extend.none, color=color.new(color.red, 70), width=1)
if showLines and not na(lastPL)
    line.new(lastPLBar, lastPL, bar_index, lastPL, xloc=xloc.bar_index, extend=extend.none, color=color.new(color.lime, 70), width=1)

// Logic for missed pivots:
// A pivot high is considered missed if price never revisits (fills) that pivot level within maxBarsToFill bars after confirmation.
// For a pivot HIGH, a fill happens if high >= pivot price within the window.
// For a pivot LOW, a fill happens if low  <= pivot price within the window.

// Helper: has a pivot been filled since its confirmation?
var bool lastPHFilled = true
var bool lastPLFilled = true

// Reset fill status when a new pivot is confirmed
if not na(phPrice)
    lastPHFilled := false
if not na(plPrice)
    lastPLFilled := false

// Update fill status while within the allowed window
if not na(lastPH) and not lastPHFilled and not na(lastPHBar)
    within = bar_index - lastPHBar <= maxBarsToFill and bar_index >= lastPHBar
    if within and high >= lastPH
        lastPHFilled := true
if not na(lastPL) and not lastPLFilled and not na(lastPLBar)
    within = bar_index - lastPLBar <= maxBarsToFill and bar_index >= lastPLBar
    if within and low <= lastPL
        lastPLFilled := true

// Determine when a pivot becomes missed (window expired without fill)
missedPH = enableMissedHighAlert and not na(lastPH) and not lastPHFilled and not na(lastPHBar) and bar_index - lastPHBar > maxBarsToFill
missedPL = enableMissedLowAlert  and not na(lastPL) and not lastPLFilled and not na(lastPLBar) and bar_index - lastPLBar > maxBarsToFill

// Create alerts for missed pivots
alertcondition(missedPH, title="Missed Pivot High", message="Missed Pivot HIGH at {{ticker}} price {{close}}. Pivot level: {{plot_0}}")
alertcondition(missedPL, title="Missed Pivot Low",  message="Missed Pivot LOW at {{ticker}} price {{close}}. Pivot level: {{plot_1}}")

// Visual warnings on chart for missed pivots
plotshape(missedPH, title="Missed PH Warn", style=shape.labeldown, color=color.new(color.red, 0), textcolor=color.white, location=location.abovebar, text="Missed PH\n" + str.tostring(lastPH, format.mintick))
plotshape(missedPL, title="Missed PL Warn", style=shape.labelup,   color=color.new(color.green, 0), textcolor=color.white, location=location.belowbar, text="Missed PL\n" + str.tostring(lastPL, format.mintick))

// Also plot lines at current last pivot levels for reference
plot(lastPH, title="Last Pivot High Level", style=plot.style_linebr, color=color.new(color.red, 0), linewidth=2)
plot(lastPL, title="Last Pivot Low Level",  style=plot.style_linebr, color=color.new(color.lime, 0), linewidth=2)

// Notes for users (via comments):
// - Adjust left/right lengths to change pivot sensitivity.
// - maxBarsToFill controls the window after confirmation to consider a pivot as missed.
// - Enable/disable missed pivot alerts via the inputs, then add an alert on this script selecting the desired condition.

Below is a complete Pine Script v5 that compiles and runs in TradingView. It plots clearly visible pivot highs/lows with adjustable left/right lengths and implements input-controlled alertcondition alerts for missed pivots. A pivot is considered "missed" if price fails to retest the pivot level within a user-defined number of bars and tolerance. You can toggle the alerts and on-chart missed-pivot markers per side via inputs.

//@version=5
indicator("Pivot High/Low with Missed Retest Alerts (v5)", overlay=true, max_labels_count=500)

// =========================
// Inputs
// =========================
grpPivot   = "Pivot Settings"
leftLen    = input.int(3,  "Left length",  minval=1, maxval=100, group=grpPivot)
rightLen   = input.int(3,  "Right length", minval=1, maxval=100, group=grpPivot)
showPH     = input.bool(true,  "Show Pivot High markers", group=grpPivot)
showPL     = input.bool(true,  "Show Pivot Low markers",  group=grpPivot)

grpMiss    = "Missed Pivot Settings"
winBars    = input.int(20,  "Retest window (bars)", minval=1, maxval=2000, group=grpMiss)
 tolPctInp = input.float(0.25, "Retest tolerance (%)", minval=0.0, maxval=10.0, step=0.05, group=grpMiss)
markMissed = input.bool(true,  "Draw labels for missed pivots", group=grpMiss)

grpAlerts  = "Alert Toggles"
alertMissPH = input.bool(true,  "Enable missed Pivot High alerts", group=grpAlerts)
alertMissPL = input.bool(true,  "Enable missed Pivot Low alerts",  group=grpAlerts)

// Convert percent to factor
var float tolPct = na
if barstate.isfirst
    tolPct := tolPctInp / 100.0
else
    tolPct := tolPctInp / 100.0

// =========================
// Pivot detection
// =========================
ph = ta.pivothigh(high, leftLen, rightLen)
pl = ta.pivotlow(low,  leftLen, rightLen)

// Pivot occurs at bar index offset = rightLen from current bar
phBarIndex = ta.valuewhen(not na(ph), bar_index[rightLen], 0)
plBarIndex = ta.valuewhen(not na(pl), bar_index[rightLen], 0)

// =========================
// Plot regular pivot markers
// =========================
plotshape(showPH and not na(ph), title="Pivot High", style=shape.triangledown, color=color.red, size=size.large, location=location.abovebar, offset=-rightLen, text="PH")
plotshape(showPL and not na(pl), title="Pivot Low",  style=shape.triangleup,   color=color.lime, size=size.large, location=location.belowbar, offset=-rightLen, text="PL")

// Optional: small lines at pivot level for clarity
pivotLineLen = math.max(2, rightLen)
plot(showPH and not na(ph) ? ph : na, title="PH Line", color=color.new(color.red, 20), linewidth=2, offset=-rightLen)
plot(showPL and not na(pl) ? pl : na, title="PL Line", color=color.new(color.lime,20), linewidth=2, offset=-rightLen)

// =========================
// Missed pivot tracking logic
// We track the latest unresolved pivot high and low separately.
// A pivot is "retested" if price returns within tolerance before the window expires.
// =========================
var bool   phActive      = false
var float  phLevel       = na
var int    phStartBar    = na
var bool   phRetested    = false

var bool   plActive      = false
var float  plLevel       = na
var int    plStartBar    = na
var bool   plRetested    = false

// When a new pivot is confirmed, start its tracking window
if not na(ph)
    phActive   := true
    phLevel    := ph
    phStartBar := phBarIndex
    phRetested := false

if not na(pl)
    plActive   := true
    plLevel    := pl
    plStartBar := plBarIndex
    plRetested := false

// Check retests only while active and before the window expires
// For Pivot High: consider retested if high >= phLevel * (1 - tolPct)
if phActive and not phRetested and bar_index > phStartBar and bar_index - phStartBar <= winBars
    if high >= phLevel * (1 - tolPct)
        phRetested := true

// For Pivot Low: consider retested if low <= plLevel * (1 + tolPct)
if plActive and not plRetested and bar_index > plStartBar and bar_index - plStartBar <= winBars
    if low <= plLevel * (1 + tolPct)
        plRetested := true

// Determine when windows expire (exactly when bar_index - start > winBars)
missPH = phActive and not phRetested and bar_index - phStartBar > winBars
missPL = plActive and not plRetested and bar_index - plStartBar > winBars

// Once missed, deactivate to avoid repeated triggers
if missPH
    phActive := false
if missPL
    plActive := false

// =========================
// On-chart labels for missed pivots (optional)
// =========================
if markMissed and missPH
    label.new(bar_index, high, text="Missed PH\n" + str.tostring(phLevel, format.mintick), style=label.style_label_down, color=color.new(color.red, 0), textcolor=color.white)
if markMissed and missPL
    label.new(bar_index, low,  text="Missed PL\n" + str.tostring(plLevel, format.mintick), style=label.style_label_up,   color=color.new(color.green, 0), textcolor=color.white)

// =========================
// Alerts (input-controlled)
// Conditions include the user toggles so a single alert setup can respect inputs.
// =========================
missPH_cond = alertMissPH and missPH
missPL_cond = alertMissPL and missPL

alertcondition(missPH_cond, title="Missed Pivot High", message="Missed Pivot High at {{ticker}} {{interval}} near {{close}}; pivot level: " + str.tostring(phLevel, format.mintick))
alertcondition(missPL_cond, title="Missed Pivot Low",  message="Missed Pivot Low at {{ticker}} {{interval}} near {{close}}; pivot level: " + str.tostring(plLevel, format.mintick))

// Optional real-time visual hint using plotshape when a missed event happens
plotshape(missPH_cond, title="Missed PH Marker", style=shape.xcross, color=color.red, location=location.abovebar, size=size.tiny)
plotshape(missPL_cond, title="Missed PL Marker", style=shape.xcross, color=color.green, location=location.belowbar, size=size.tiny)

// End of script

//@version=5
indicator("Pivot High/Low with Missed Retest Alerts", overlay=true, max_labels_count=500, max_lines_count=500)

//===============================
// Inputs
//===============================
// Pivot detection
leftLen  = input.int(5,  "Pivot left bars",  minval=1)
rightLen = input.int(5,  "Pivot right bars", minval=1)

// Plot styling
showPH   = input.bool(true,  "Show Pivot High markers")
showPL   = input.bool(true,  "Show Pivot Low markers")
phColor  = input.color(color.new(color.red,  0), "Pivot High color")
plColor  = input.color(color.new(color.lime, 0), "Pivot Low color")
phShape  = input.string("triangle down", "Pivot High shape", options=["triangle down","diamond","circle","cross"])
plShape  = input.string("triangle up",   "Pivot Low shape",  options=["triangle up","diamond","circle","cross"])

// Missed retest alert controls
enableMissedPH = input.bool(true,  "Enable missed-retest alerts for Pivot Highs")
enableMissedPL = input.bool(true,  "Enable missed-retest alerts for Pivot Lows")
retestBars     = input.int(20,     "Retest window (bars)", minval=1)
tolerancePct  = input.float(0.10,  "Retest tolerance (%)", minval=0.0, step=0.01)
createAlertNow = input.bool(true,  "Fire alerts immediately when missed window closes")

// Optional timeframe source for pivots (same symbol). Use "" for chart timeframe.
useHTF        = input.bool(false, "Use higher timeframe for pivots")
htf           = input.timeframe("60", "HTF when enabled")

//===============================
// Utility
//===============================
shapeOf(s) =>
    s == "triangle down" ? shape.triangledown :
    s == "triangle up"   ? shape.triangleup   :
    s == "diamond"       ? shape.diamond      :
    s == "circle"        ? shape.circle       : shape.cross

//===============================
// Source series (optionally HTF)
//===============================
var useRes = useHTF ? htf : timeframe.period
srcHigh = request.security(syminfo.tickerid, useRes, high,  barmerge.gaps_off, barmerge.lookahead_off)
srcLow  = request.security(syminfo.tickerid, useRes, low,   barmerge.gaps_off, barmerge.lookahead_off)
srcTime = request.security(syminfo.tickerid, useRes, time,  barmerge.gaps_off, barmerge.lookahead_off)

//===============================
// Pivot detection
//===============================
pH = ta.pivothigh(srcHigh, leftLen, rightLen)
pL = ta.pivotlow(srcLow,  leftLen, rightLen)

// Capture finalized pivot bar index/time/value (appears after rightLen bars)
phConfirmed   = not na(pH)
plConfirmed   = not na(pL)
phPrice       = pH
plPrice       = pL
phFinalBarT   = ta.valuewhen(phConfirmed, srcTime[rightLen], 0)
plFinalBarT   = ta.valuewhen(plConfirmed, srcTime[rightLen], 0)

//===============================
// Plot markers for pivots
//===============================
plotshape(showPH and phConfirmed, title="Pivot High", style=shapeOf(phShape), location=location.abovebar, color=phColor, size=size.tiny, text="PH")
plotshape(showPL and plConfirmed, title="Pivot Low",  style=shapeOf(plShape), location=location.belowbar, color=plColor, size=size.tiny, text="PL")

//===============================
// Missed retest logic
// Definition:
//  - For a Pivot High: A retest occurs if high reaches >= pivot_high_price * (1 - tol) within 'retestBars' after pivot is finalized.
//  - For a Pivot Low:  A retest occurs if low  reaches <= pivot_low_price  * (1 + tol) within 'retestBars' after pivot is finalized.
// If no retest occurs by the end of the window, flag a "missed retest".
//===============================
var float lastPHPrice = na
var float lastPLPrice = na
var int   lastPHOpenBarIndex = na
var int   lastPLOpenBarIndex = na
var bool  phRetested = na
var bool  plRetested = na

// Convert tolerance percent to multiplier
phTolMult = 1.0 - tolerancePct * 0.01
plTolMult = 1.0 + tolerancePct * 0.01

// When a new pivot finalizes, open a tracking window
if phConfirmed
    lastPHPrice := phPrice
    lastPHOpenBarIndex := bar_index
    phRetested := false

if plConfirmed
    lastPLPrice := plPrice
    lastPLOpenBarIndex := bar_index
    plRetested := false

// While window is open, check for retest hits
if not na(lastPHPrice) and not na(lastPHOpenBarIndex) and not phRetested
    // retest level for highs (price gets back near the pivot from below)
    phRetestLevel = lastPHPrice * phTolMult
    if high >= phRetestLevel
        phRetested := true

if not na(lastPLPrice) and not na(lastPLOpenBarIndex) and not plRetested
    // retest level for lows (price gets back near the pivot from above)
    plRetestLevel = lastPLPrice * plTolMult
    if low <= plRetestLevel
        plRetested := true

// Detect window expiry and "missed" condition
phWindowExpired = not na(lastPHOpenBarIndex) and bar_index - lastPHOpenBarIndex > retestBars
plWindowExpired = not na(lastPLOpenBarIndex) and bar_index - lastPLOpenBarIndex > retestBars

missedPH = enableMissedPH and phWindowExpired and not na(lastPHPrice) and not phRetested
missedPL = enableMissedPL and plWindowExpired and not na(lastPLPrice) and not plRetested

// Once window closes (hit or miss), clear state so a new pivot can be tracked
if phWindowExpired or (not na(lastPHPrice) and phRetested)
    lastPHPrice := na
    lastPHOpenBarIndex := na
    phRetested := na

if plWindowExpired or (not na(lastPLPrice) and plRetested)
    lastPLPrice := na
    lastPLOpenBarIndex := na
    plRetested := na

//===============================
// On-chart warnings/markers for missed retests
//===============================
missColorH = color.new(color.orange, 0)
missColorL = color.new(color.teal,   0)

plotshape(missedPH, title="Missed PH Retest", style=shape.flag, location=location.abovebar, color=missColorH, size=size.tiny, text="Missed PH")
plotshape(missedPL, title="Missed PL Retest", style=shape.flag, location=location.belowbar, color=missColorL, size=size.tiny, text="Missed PL")

//===============================
// Alertconditions
//===============================
// Users can attach alerts to these and choose "Once per bar" or "Once per bar close".
alertcondition(createAlertNow and missedPH, title="Missed Pivot High Retest", message="Missed retest for Pivot High within the configured window.")
alertcondition(createAlertNow and missedPL, title="Missed Pivot Low Retest",  message="Missed retest for Pivot Low within the configured window.")

// Optional informational alerts when a regular pivot is confirmed (can help debugging)
alertOnPivotConfirm = input.bool(false, "Alert when a pivot confirms")
alertcondition(alertOnPivotConfirm and phConfirmed, title="Pivot High Confirmed", message="A Pivot High has confirmed.")
alertcondition(alertOnPivotConfirm and plConfirmed, title="Pivot Low Confirmed",  message="A Pivot Low has confirmed.")

//===============================
// Notes for users (comments only)
// - Adjust left/right lengths to tune pivot sensitivity.
// - Retest window counts bars after the pivot confirms (after rightLen bars).
// - Tolerance is in percent. Example: 0.10 = 0.10%.
// - Enable/disable missed retest alerts independently for highs/lows.
// - Alerts fire the moment the retest window closes without a retest (missed).

Below is a complete, runnable MATLAB example that:

- Generates a binary order-1 Markov source
- Encodes it with a context-adaptive binary arithmetic coder (order-k contexts with adaptive counts)
- Transmits the compressed bitstream through a Binary Symmetric Channel (BSC)
- Decodes on the receiver side with the same adaptive model
- Computes the BER between the original and decoded sequences

Note: Arithmetic coding is extremely sensitive to bit errors; even a single flipped bit often causes catastrophic decoding error propagation. This script still demonstrates the full pipeline as requested.

Copy the entire block into a new MATLAB script file (e.g., demo_ca_ac_bsc.m) and run.

% demo_ca_ac_bsc.m
% Context-adaptive arithmetic coding (binary), BSC channel, and BER in MATLAB.

function demo_ca_ac_bsc
    clc; clear; rng(0);  % Reproducible

    % Parameters
    N = 2000;              % Number of source bits
    P = [0.95, 0.05;       % Transition matrix P(x_t | x_{t-1})
         0.10, 0.90];      % rows = prev state (0/1), cols = next state (0/1)
    p1_init = 0.5;         % Initial P(X1=1)
    ctx_order = 2;         % Context order (number of previous bits used)
    bsc_p = 1e-3;          % BSC crossover probability for channel

    % 1) Generate Markov source
    x = gen_markov_binary(N, P, p1_init);

    % 2) Context-adaptive arithmetic encode (binary)
    % We encode x into a binary bitstream 'code_bits' and send model length N and ctx_order.
    [code_bits, enc_state] = ca_arith_encode_binary(x, ctx_order);

    % 3) Transmit through BSC
    rx_bits = bsc(code_bits, bsc_p);

    % 4) Decode using same adaptive model and message length N
    [x_hat, ok] = ca_arith_decode_binary(rx_bits, N, ctx_order, enc_state.seed);

    % 5) Compute BER
    if ok
        ber = mean(x ~= x_hat);
    else
        ber = NaN;  % decoding failed (e.g., due to catastrophic error)
    end

    % Report
    fprintf('Source length N = %d\n', N);
    fprintf('Context order   = %d\n', ctx_order);
    fprintf('BSC p           = %.2e\n', bsc_p);
    fprintf('Encoded bits    = %d (rate = %.3f bpb)\n', numel(code_bits), numel(code_bits)/N);
    fprintf('Decode status   = %d (1=OK,0=fail)\n', ok);
    fprintf('BER             = %g\n', ber);
end

function x = gen_markov_binary(N, P, p1_init)
% gen_markov_binary: Generate a length-N binary Markov chain given transition matrix P.
% P is 2x2: rows = prev state (0/1)+1, cols = next state (0/1)+1.
    x = zeros(N,1,'uint8');
    x(1) = rand < p1_init;  % 1 with prob p1_init
    for t = 2:N
        prev = x(t-1);
        p1 = P(prev+1, 2);   % P(next=1 | prev)
        x(t) = rand < p1;
    end
end

function [bits, state] = ca_arith_encode_binary(x, k)
% ca_arith_encode_binary: Context-adaptive arithmetic coding for binary data.
% - x: column vector of 0/1 (uint8/double)
% - k: context order (0..say 8). Context is previous k bits as an index.
% Returns:
% - bits: row vector of 0/1 uint8 containing the arithmetic-coded bitstream.
% - state: struct with any metadata needed for decoding (e.g., RNG seed for tie-breaking, if used).

    x = uint8(x(:));
    N = numel(x);

    % Context table size
    C = 2^k;               % number of contexts
    % Adaptive counts with Laplace smoothing (1,1) to avoid zero-probability
    cnt0 = ones(C,1,'uint32');
    cnt1 = ones(C,1,'uint32');

    % Arithmetic coder state (range coding style with 32-bit)
    % Using integer arithmetic in [0, TOP]
    TOP = uint64(2^32 - 1);
    LOW = uint64(0);
    HIGH = TOP;

    % Output bit buffer
    out = false(1, max(64, 2*N)); % preallocate; will grow if needed
    out_len = 0;

    % Pending bits for underflow handling (E3 condition)
    pending = 0;

    % Helper to emit a bit and its pendings
    function emit_bit(b)
        nonlocal out out_len pending
        out_len = out_len + 1;
        if out_len > numel(out)
            out = [out, false(1, max(64, numel(out)))]; %#ok<AGROW>
        end
        out(out_len) = logical(b);
        while pending > 0
            out_len = out_len + 1;
            if out_len > numel(out)
                out = [out, false(1, max(64, numel(out)))]; %#ok<AGROW>
            end
            out(out_len) = ~logical(b);
            pending = pending - 1;
        end
    end

    % Context index function
    function c = ctx_of(hist)
        % hist is a uint32 holding last k bits (LSB=most recent)
        c = bitand(hist, uint32(C-1));
        c = double(c) + 1; % 1-based index
    end

    hist = uint32(0);

    for t = 1:N
        c = ctx_of(hist);
        f0 = double(cnt0(c));
        f1 = double(cnt1(c));
        tot = f0 + f1;

        % Interval split for symbol 0 then 1
        range = HIGH - LOW + 1;
        % Use floor to stay within integer range coder
        split = LOW + uint64(floor(double(range) * (f0 / tot))) - 1;

        if x(t) == 0
            HIGH = split;
        else
            LOW = split + 1;
        end

        % Renormalization (E1/E2/E3)
        while true
            if bitshift(HIGH, -31) == 0 && bitshift(LOW, -31) == 0
                % MSB=0 for both -> output 0
                emit_bit(0);
                LOW  = bitshift(LOW  - uint64(0), 1);
                HIGH = bitshift(HIGH - uint64(0), 1) + 1;
                HIGH = bitor(bitshift(bitand(HIGH, TOP), 0), uint64(0)); %#ok<NASGU>
            elseif bitshift(HIGH, -31) == 1 && bitshift(LOW, -31) == 1
                % MSB=1 for both -> output 1
                emit_bit(1);
                LOW  = bitshift(LOW  - uint64(2^31), 1);
                HIGH = bitshift(HIGH - uint64(2^31), 1) + 1;
            elseif bitshift(LOW, -30) == 1 && bitshift(HIGH, -30) == 2
                % E3 condition: 01xxxx.. to 10xxxx.. (underflow)
                pending = pending + 1;
                LOW  = bitshift(LOW  - uint64(2^30), 1);
                HIGH = bitshift(HIGH - uint64(2^30), 1) + 1;
            else
                break;
            end
            % Clamp
            LOW = bitand(LOW, TOP);
            HIGH = bitand(HIGH, TOP);
        end

        % Update model counts
        if x(t) == 0
            cnt0(c) = cnt0(c) + 1;
        else
            cnt1(c) = cnt1(c) + 1;
        end

        % Update context history (shift in x(t) at LSB)
        hist = bitor(bitshift(hist, 1), uint32(x(t)));
    end

    % Termination: push MSB and pending clean-up
    pending = pending + 1; % ensures bitstream is prefix-free termination
    if LOW < 2^31
        emit_bit(0);
    else
        emit_bit(1);
    end

    bits = uint8(out(1:out_len));

    % Provide any metadata useful for decoder
    state = struct('seed', uint32(0)); %#ok<NASGU>
end

function [x, ok] = ca_arith_decode_binary(bits, N, k, ~)
% ca_arith_decode_binary: Decode binary stream produced by ca_arith_encode_binary.
% - bits: row/col logical or 0/1 uint8
% - N: number of symbols to decode
% - k: context order
% Returns:
% - x: reconstructed 0/1 vector (uint8)
% - ok: 1 if decoding proceeded without internal overflow issues

    ok = 1;
    b = logical(bits(:)).';
    b_len = numel(b);
    b_idx = 1;

    function v = get_bit()
        nonlocal b b_idx b_len
        if b_idx <= b_len
            v = b(b_idx);
            b_idx = b_idx + 1;
        else
            v = false; % pad zeros if stream ends
        end
    end

    TOP = uint64(2^32 - 1);
    LOW = uint64(0);
    HIGH = TOP;

    % Initialize code value by reading 32 bits
    code = uint64(0);
    for i = 1:32
        code = bitshift(code, 1);
        code = code + uint64(get_bit());
    end

    C = 2^k;
    cnt0 = ones(C,1,'uint32');
    cnt1 = ones(C,1,'uint32');

    function c = ctx_of(hist)
        c = bitand(hist, uint32(C-1));
        c = double(c) + 1;
    end

    hist = uint32(0);
    x = zeros(N,1,'uint8');

    for t = 1:N
        c = ctx_of(hist);
        f0 = double(cnt0(c));
        f1 = double(cnt1(c));
        tot = f0 + f1;

        range = HIGH - LOW + 1;
        % Compute threshold corresponding to symbol 0 cumulative
        split = LOW + uint64(floor(double(range) * (f0 / tot))) - 1;

        if code <= split
            sym = uint8(0);
            HIGH = split;
        else
            sym = uint8(1);
            LOW = split + 1;
        end

        % Renormalization and input bits (mirror of encoder)
        while true
            if bitshift(HIGH, -31) == 0 && bitshift(LOW, -31) == 0
                % output 0
                LOW  = bitshift(LOW, 1);
                HIGH = bitshift(HIGH, 1) + 1;
                code = bitshift(code, 1) + uint64(get_bit());
            elseif bitshift(HIGH, -31) == 1 && bitshift(LOW, -31) == 1
                % output 1
                LOW  = bitshift(LOW  - uint64(2^31), 1);
                HIGH = bitshift(HIGH - uint64(2^31), 1) + 1;
                code = bitshift(code - uint64(2^31), 1) + uint64(get_bit());
            elseif bitshift(LOW, -30) == 1 && bitshift(HIGH, -30) == 2
                % E3 condition
                LOW  = bitshift(LOW  - uint64(2^30), 1);
                HIGH = bitshift(HIGH - uint64(2^30), 1) + 1;
                code = bitshift(code - uint64(2^30), 1) + uint64(get_bit());
            else
                break;
            end
            LOW = bitand(LOW, TOP);
            HIGH = bitand(HIGH, TOP);
            code = bitand(code, TOP);
        end

        % Commit symbol
        x(t) = sym;

        % Update model
        if sym == 0
            cnt0(c) = cnt0(c) + 1;
        else
            cnt1(c) = cnt1(c) + 1;
        end

        % Update history
        hist = bitor(bitshift(hist, 1), uint32(sym));
    end
end

function y = bsc(x, p)
% bsc: Apply Binary Symmetric Channel to a 0/1 bit vector with flip prob p.
    x = uint8(x(:)).';
    flips = rand(size(x)) < p;
    y = bitxor(x, uint8(flips));
    y = uint8(y);
end

