function demo_markov_caac_bsc
% demo_markov_caac_bsc
% Complete, runnable MATLAB script:
% - Binary order-1 Markov source
% - Context-adaptive binary arithmetic encoder (order-k, adaptive counts)
% - BSC channel simulation
% - Matching decoder
% - BER calculation

clc; clear; rng(1);

% Parameters
N = 2000;                 % Number of source bits
P = [0.95, 0.05;          % Transition matrix P(x_t | x_{t-1})
     0.10, 0.90];         % rows = prev(0/1), cols = next(0/1)
p_init1 = 0.5;            % Prior Pr(X1=1)
ctx_order = 2;            % Context order (k). Use small (0..4)
alpha = 1;                % Laplace smoothing pseudo-count
p_bsc = 0.02;             % BSC crossover probability

% 1) Generate Markov source bits
x = gen_markov_binary(N, P, p_init1);

% 2) Context-adaptive arithmetic encode to a binary code stream
%    We produce a self-contained bytestream: header + payload bits
[code_bits, header] = caac_encode_binary(x, ctx_order, alpha);

% 3) Transmit through BSC
rx_bits = bsc(code_bits, p_bsc);

% 4) Decode
[x_hat, ok] = caac_decode_binary(rx_bits, header);

% 5) BER (on source sequence)
if ok && numel(x_hat) == numel(x)
    ber = mean(x ~= x_hat);
else
    ber = NaN;
end

% Report
fprintf('Length(src) = %d bits\n', numel(x));
fprintf('Length(code)= %d bits (rate = %.3f bpb)\n', numel(code_bits), numel(code_bits)/numel(x));
fprintf('BSC p = %.4f\n', p_bsc);
if ok
    fprintf('Decode status: OK\n');
else
    fprintf('Decode status: FAILED (likely due to channel errors)\n');
end
fprintf('BER on source = %s\n', num2str(ber));

end

% ===== Local functions =====
function x = gen_markov_binary(N, P, p_init1)
% Generate a binary order-1 Markov chain of length N
% P is 2x2: rows = prev state (0/1)+1, cols = next state (0/1)+1
x = zeros(1,N);
x(1) = rand < p_init1;
for t = 2:N
    prev = x(t-1);
    p1 = P(prev+1, 2);  % prob of next=1
    x(t) = rand < p1;
end
x = logical(x);
end

function [code_bits, header] = caac_encode_binary(x, k, alpha)
% Context-adaptive binary arithmetic coding, order k with adaptive counts.
% Returns code_bits (row logical vector) and a header struct for decoding.
%
% We implement range coding with 32-bit integers.

x = x(:)';
N = numel(x);

% Header packs: magic, version, k, alpha, N, and the first k context seed bits
header.magic = uint32(hex2dec('A1C0DE01'));
header.version = uint16(1);
header.k = uint16(k);
header.alpha = uint16(alpha);
header.N = uint32(N);

% Seed bits for initial context: we store k bits explicitly
seed_len = k;
if seed_len > 0
    seed = false(1, seed_len);
    m = min(seed_len, N);
    seed(1:m) = x(1:m);
else
    seed = false(1,0);
end
header.seed = seed;

% Prepare context model: for each context we keep counts [c0, c1]
num_ctx = 2^k;
counts = repmat(uint32(alpha), num_ctx, 2); % start with [alpha, alpha]

% Range coder init
rc_low = uint32(0);
rc_range = uint32(hex2dec('FFFFFFFF')); % 2^32-1 full range
out_bits = false(1, 0);
underflow = 0;

% Helper lambdas
get_ctx = @(hist) uint32(bin2dec_fast(hist))+1; % 1..num_ctx

% Build initial history buffer of length k (MSB-first)
hist = false(1,k);
if k>0
    hist(1:seed_len) = seed;
end

% Encode header first as raw bits (fixed layout)
out_bits = [out_bits, pack_header_bits(header)];

% Encode the remaining source bits using arithmetic coding
start_idx = max(1, seed_len+1);
for t = start_idx:N
    bit = uint32(x(t));
    % Compute context index
    if k==0
        ctx = uint32(1);
    else
        ctx = get_ctx(hist);
    end
    c0 = counts(ctx,1);
    c1 = counts(ctx,2);
    tot = c0 + c1; % uint32

    % Probability of 1 is c1/tot. Map to cumulative for range splitting
    % We use 16-bit precision for probability partition to stay robust
    scale = uint32(65536);
    p1 = max(uint32(1), uint32( floor(double(c1) * double(scale) / double(tot)) ));
    if p1>=scale, p1 = scale-1; end
    p0 = scale - p1;

    % Range split: low..low+range-1; cum0=0, cum1=p0
    r = rc_range / scale; % implicit floor in integer div
    if bit==0
        rc_range = uint32(r * p0);
    else
        rc_low   = rc_low + uint32(r * p0);
        rc_range = uint32(r * p1);
    end

    % Renormalize
    while true
        if bitand(rc_low, uint32(hex2dec('80000000'))) == bitand(rc_low+rc_range-1, uint32(hex2dec('80000000')))
            % MSB equal -> output that bit
            msb = bitshift(rc_low, -31);
            out_bits = [out_bits, logical(msb)]; %#ok<AGROW>
            % Output underflow bits (complement of msb)
            if underflow>0
                out_bits = [out_bits, repmat(~logical(msb), 1, underflow)]; %#ok<AGROW>
                underflow = 0;
            end
            % shift left
            rc_low   = bitshift(bitand(rc_low, uint32(hex2dec('7FFFFFFF'))), 1);
            rc_range = bitshift(rc_range, 1);
        elseif rc_range <= uint32(hex2dec('40000000')) % range small -> E3 underflow condition
            underflow = underflow + 1;
            rc_low   = bitshift(bitand(rc_low, uint32(hex2dec('3FFFFFFF'))), 1);
            rc_range = bitshift(rc_range, 1);
            rc_low   = bitxor(rc_low, uint32(hex2dec('40000000')));
        else
            break;
        end
    end

    % Update counts adaptively
    if bit==0
        counts(ctx,1) = c0 + 1;
    else
        counts(ctx,2) = c1 + 1;
    end

    % Update context history
    if k>0
        hist = [hist(2:end), logical(bit)];
    end
end

% Terminate coder: flush one more MSB and pending underflow
msb = bitshift(rc_low, -31);
out_bits = [out_bits, logical(msb)];
if underflow>0
    out_bits = [out_bits, repmat(~logical(msb), 1, underflow)];
end

code_bits = out_bits;
end

function [x_hat, ok] = caac_decode_binary(rx_bits, header)
% Decode the bytestream from caac_encode_binary after BSC.
% If any header bits are corrupted, sizes may be wrong; we try to parse.

% Parse header
[idx, hdr, hdr_ok] = unpack_header_bits(rx_bits);
if ~hdr_ok
    x_hat = false(1,0); ok = false; return;
end
k = double(hdr.k);
alpha = double(hdr.alpha);
N = double(hdr.N);
seed = hdr.seed;

% Init context model
num_ctx = 2^k;
counts = repmat(uint32(alpha), num_ctx, 2);

% Range decoder init
rc_low = uint32(0);
rc_range = uint32(hex2dec('FFFFFFFF'));

% Initialize code value by consuming 32 bits (or as many as available)
[code, idx] = read_bits_as_uint32(rx_bits, idx);

% Prepare output
x_hat = false(1,N);
seed_len = numel(seed);
if seed_len>0
    x_hat(1:seed_len) = seed(1:min(seed_len,N));
end

% Helper
get_ctx = @(hist) uint32(bin2dec_fast(hist))+1;
hist = false(1,k);
if k>0
    hist(1:seed_len) = seed;
end

scale = uint32(65536);
start_idx = max(1, seed_len+1);
for t = start_idx:N
    if k==0
        ctx = uint32(1);
    else
        ctx = get_ctx(hist);
    end
    c0 = counts(ctx,1); c1 = counts(ctx,2); tot = c0 + c1;
    p1 = max(uint32(1), uint32( floor(double(c1) * double(scale) / double(tot)) ));
    if p1>=scale, p1 = scale-1; end
    p0 = scale - p1;

    r = rc_range / scale;
    % Determine symbol from code position
    threshold = uint32(r * p0);
    if code - rc_low < threshold
        bit = 0;
        rc_range = threshold;
    else
        bit = 1;
        rc_low  = rc_low + threshold;
        rc_range = uint32(r * p1);
    end

    % Renormalize, consuming bits from rx_bits
    while true
        if bitand(rc_low, uint32(hex2dec('80000000'))) == bitand(rc_low+rc_range-1, uint32(hex2dec('80000000')))
            % shift left and bring in next bit
            rc_low   = bitshift(bitand(rc_low, uint32(hex2dec('7FFFFFFF'))), 1);
            rc_range = bitshift(rc_range, 1);
            [b, idx] = read_bit(rx_bits, idx);
            code = bitor(bitshift(bitand(code, uint32(hex2dec('7FFFFFFF'))),1), uint32(b));
        elseif rc_range <= uint32(hex2dec('40000000'))
            rc_low   = bitshift(bitand(rc_low, uint32(hex2dec('3FFFFFFF'))), 1);
            rc_range = bitshift(rc_range, 1);
            rc_low   = bitxor(rc_low, uint32(hex2dec('40000000')));
            [b, idx] = read_bit(rx_bits, idx);
            code = bitxor( bitor(bitshift(bitand(code, uint32(hex2dec('3FFFFFFF'))),1), uint32(b)) , uint32(hex2dec('40000000')) );
        else
            break;
        end
    end

    % Output bit
    x_hat(t) = logical(bit);

    % Update counts and history
    if bit==0
        counts(ctx,1) = c0 + 1;
    else
        counts(ctx,2) = c1 + 1;
    end
    if k>0
        hist = [hist(2:end), logical(bit)];
    end
end

ok = true;
end

function y = bsc(x, p)
% Binary Symmetric Channel: flips bits with prob p
x = logical(x(:)');
flips = rand(size(x)) < p;
y = xor(x, flips);
end

function bits = pack_header_bits(h)
% Fixed layout:
% magic(32) | version(16) | k(16) | alpha(16) | N(32) | seed_len(16) | seed_bits
bits = [ ...
    uint_to_bits(h.magic, 32), ...
    uint_to_bits(uint32(h.version), 16), ...
    uint_to_bits(uint32(h.k), 16), ...
    uint_to_bits(uint32(h.alpha), 16), ...
    uint_to_bits(h.N, 32), ...
    uint_to_bits(uint32(numel(h.seed)), 16), ...
    logical(h.seed(:)') ...
];
end

function [idx, h, ok] = unpack_header_bits(bits)
idx = 1; ok = true; h = struct();
[magic, idx, ok]   = read_uint(bits, idx, 32); if ~ok, return; end
[version, idx, ok] = read_uint(bits, idx, 16); if ~ok, return; end
[k, idx, ok]       = read_uint(bits, idx, 16); if ~ok, return; end
[alpha, idx, ok]   = read_uint(bits, idx, 16); if ~ok, return; end
[N, idx, ok]       = read_uint(bits, idx, 32); if ~ok, return; end
[seed_len, idx, ok]= read_uint(bits, idx, 16); if ~ok, return; end
if ~ok || numel(bits) < idx+double(seed_len)-1
    ok = false; return;
end
seed = false(1, double(seed_len));
if seed_len>0
    seed = logical(bits(idx:idx+double(seed_len)-1));
end
idx = idx + double(seed_len);

h.magic = uint32(magic);
h.version = uint16(version);
h.k = uint16(k);
h.alpha = uint16(alpha);
h.N = uint32(N);
h.seed = seed;

if h.magic ~= uint32(hex2dec('A1C0DE01'))
    ok = false;
end
end

function [val, idx, ok] = read_uint(bits, idx, nbits)
ok = true;
if numel(bits) < idx+nbits-1
    ok = false; val = uint32(0); return;
end
val = bits_to_uint32(bits(idx:idx+nbits-1));
idx = idx + nbits;
end

function [val, idx] = read_bits_as_uint32(bits, idx)
% Read up to 32 bits (pad zeros if not enough)
remain = numel(bits) - idx + 1;
nb = min(32, max(0, remain));
chunk = false(1,32);
if nb>0
    chunk(1:nb) = bits(idx:idx+nb-1);
end
val = bits_to_uint32(chunk);
idx = idx + nb;
end

function [b, idx] = read_bit(bits, idx)
if idx<=numel(bits)
    b = bits(idx);
    idx = idx + 1;
else
    b = false; % pad zero if depleted
end
end

function u = uint_to_bits(v, n)
% v: uint32 scalar; n: number of bits (<=32)
mask = uint32(1);
u = false(1,n);
for i = n:-1:1
    u(i) = bitand(v, mask) ~= 0;
    v = bitshift(v, -1);
end
u = fliplr(u);
end

function u = bits_to_uint32(b)
% b: logical vector up to 32 bits, MSB-first
u = uint32(0);
for i = 1:numel(b)
    u = bitor(bitshift(u,1), uint32(b(i))); %#ok<AGROW>
end
end

function v = bin2dec_fast(bits)
% bits: logical row vector, MSB-first. Returns double index 0..2^k-1
v = 0;
for i = 1:numel(bits)
    v = bitshift(v,1) + bits(i);
end
end

