Step 4 — JavaScript: load NASA data, map to simulation params, render (src/main.js)

const canvas = document.querySelector('#view');
const ctx = canvas.getContext('2d');
const DPR = Math.max(1, window.devicePixelRatio || 1);

// Simulation config — mapping NASA data to pixels/time
const AU_TO_PX = 120;              // world scale: 1 AU → 120 px
const R_KM_TO_PX = 1 / 3000;       // compress radii for visibility (tweak)
let userTimeScale = 5;             // user-selected time acceleration (slider)

// State
let planets = [];
let t = 0;                         // simulation time in days
let lastTs = 0;

function resize() {
  const rect = canvas.getBoundingClientRect();
  canvas.width = Math.max(600, rect.width) * DPR;
  canvas.height = Math.max(400, rect.height) * DPR;
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
}
window.addEventListener('resize', resize);
resize();

document.getElementById('timeScale').addEventListener('input', (e) => {
  userTimeScale = parseFloat(e.target.value);
});

// EXACTLY HOW WE FETCH/PARSE NASA DATA (produced by Step 1)
// We consume the generated JSON so the site is static and fast.
async function loadPlanets() {
  const res = await fetch('../data/planets.json');
  const json = await res.json();
  // Example record: { id, name, a_AU, period_days, radius_km }
  // Map to render parameters: distance in px, angular rate rad/day, display radius in px
  return json.planets.map(p => ({
    ...p,
    a_px: p.a_AU * AU_TO_PX,                   // distance scale
    omega_rad_per_day: (2 * Math.PI) / p.period_days, // angular speed from period
    r_px: Math.max(2, p.radius_km * R_KM_TO_PX) // visual radius (ensure min size)
  }));
}

function drawBackground() {
  const { width, height } = canvas;
  ctx.save();
  ctx.fillStyle = '#020409';
  ctx.fillRect(0, 0, width, height);
  ctx.restore();
}

function drawSun(cx, cy) {
  const r = 12; // display radius for the Sun (not to scale)
  const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, r*2);
  grad.addColorStop(0, '#ffec97');
  grad.addColorStop(1, '#c88a00');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI*2);
  ctx.fill();
}

function drawOrbit(cx, cy, radiusPx) {
  ctx.save();
  ctx.strokeStyle = 'rgba(180,200,255,0.15)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(cx, cy, radiusPx, 0, Math.PI*2);
  ctx.stroke();
  ctx.restore();
}

function drawPlanet(x, y, r, label) {
  ctx.save();
  ctx.fillStyle = '#9ecbff';
  ctx.beginPath();
  ctx.arc(x, y, r, 0, Math.PI*2);
  ctx.fill();
  // label
  ctx.fillStyle = '#cdd6f4';
  ctx.font = '12px system-ui, sans-serif';
  ctx.fillText(label, x + r + 4, y - r - 4);
  ctx.restore();
}

function step(dtMs) {
  // Convert real milliseconds → simulation days; 86_400_000 ms per day
  const days = (dtMs / 86_400_000) * userTimeScale * 500; // 500x base acceleration for visibility
  t += days;
}

function render() {
  drawBackground();
  const w = canvas.width / DPR, h = canvas.height / DPR;
  const cx = w / 2, cy = h / 2;

  drawSun(cx, cy);

  // Orbits + planets
  for (const p of planets) {
    drawOrbit(cx, cy, p.a_px);
    const theta = p.omega_rad_per_day * t; // simple circular approximation using period
    const x = cx + p.a_px * Math.cos(theta);
    const y = cy + p.a_px * Math.sin(theta);
    drawPlanet(x, y, p.r_px, p.name);
  }
}

function loop(ts) {
  if (!lastTs) lastTs = ts;
  const dt = Math.min(50, ts - lastTs); // clamp dt for stability
  lastTs = ts;
  step(dt);
  render();
  requestAnimationFrame(loop);
}

loadPlanets().then(list => {
  planets = list;
  requestAnimationFrame(loop);
});

Step 5 — How the NASA/JPL data are mapped into the simulation
- Semimajor axis (a): From Planetary Fact Sheet row "Semimajor axis" (in 10^6 km). We convert to km, then to AU, then pixels via AU_TO_PX. Code: a_px = a_AU * AU_TO_PX.
- Orbital period (P): From "Orbital period" (days). We compute angular rate omega = 2π / P (rad/day) and advance angle by omega * t.
- Mean radius (R): From "Mean radius" (km). We compress to pixels via R_KM_TO_PX, clamped to a minimum so small planets remain visible.
- Time scaling: Real time ms → simulation days via (ms / 86,400,000) * userTimeScale * 500. The slider controls userTimeScale so you can speed up or slow down orbits.

Optional: Using JPL HORIZONS for real‑time ephemerides
- For higher fidelity (eccentricity, inclination, current mean anomaly), you can query HORIZONS server‑side and cache results.
- API docs: https://ssd.jpl.nasa.gov/api/horizons.api
- Example (Node) snippet fetching state vectors for Earth barycentric (target 399) at daily steps, then writing a time‑keyed positions file your client can interpolate from.

