scripts/fetch-planets.js (parses NASA Planetary Fact Sheet: semimajor axis, orbital period, mean radius)
```js
// scripts/fetch-planets.js
// Fetch and parse NASA Planetary Fact Sheet (Metric):
// https://nssdc.gsfc.nasa.gov/planetary/factsheet/planetfact_table_m.html
//
// Extracts semimajor axis (10^6 km), orbital period (days), and mean radius (km) for
// Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune. Converts semimajor axis to AU.

import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import * as cheerio from 'cheerio';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const URL_FACTSHEET = 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/planetfact_table_m.html';
const AU_KM = 149_597_870.7; // IAU 2012: 1 AU in km

// Mapping to lowercase IDs for our JSON
const PLANET_IDS = {
  Mercury: 'mercury',
  Venus: 'venus',
  Earth: 'earth',
  Mars: 'mars',
  Jupiter: 'jupiter',
  Saturn: 'saturn',
  Uranus: 'uranus',
  Neptune: 'neptune',
};

function cleanNumber(text) {
  // Remove commas, footnote markers, and trim
  const t = text.replace(/\[.*?\]|\(.*?\)|,/g, '').trim();
  const val = parseFloat(t);
  return Number.isFinite(val) ? val : null;
}

function parseTable($) {
  // Find the main data table. We’ll look for a table containing key row labels.
  let table;
  $('table').each((_, el) => {
    const txt = $(el).text();
    if (/Semimajor axis/i.test(txt) && /Orbital period/i.test(txt) && /Mean radius/i.test(txt)) {
      table = el;
    }
  });
  if (!table) throw new Error('Could not locate data table in the NASA Planetary Fact Sheet.');

  // Extract header row with planet names
  let planetNames = [];
  $(table)
    .find('tr')
    .each((_, tr) => {
      const cells = $(tr).find('th,td').toArray().map(td => $(td).text().trim());
      if (cells.length >= 9 && /Mercury/i.test(cells.join(' ')) && /Neptune/i.test(cells.join(' '))) {
        planetNames = cells.slice(1).map(n => n.replace(/\s*\(.*\)/, '').trim());
      }
    });

  if (planetNames.length < 8) throw new Error('Failed to parse planet header row.');

  const rowValues = (label) => {
    let values = null;
    $(table)
      .find('tr')
      .each((_, tr) => {
        const cells = $(tr).find('th,td').toArray().map(td => $(td).text().trim());
        if (cells.length >= 9 && new RegExp(label, 'i').test(cells[0])) {
          values = cells.slice(1);
        }
      });
    if (!values) throw new Error('Failed to find row for: ' + label);
    return values;
  };

  const aRow = rowValues('Semimajor axis');
  const periodRow = rowValues('Orbital period');
  const radiusRow = rowValues('Mean radius');

  const records = [];

  for (let i = 0; i < planetNames.length; i++) {
    const name = planetNames[i];
    const id = PLANET_IDS[name];
    if (!id) continue;

    const a_million_km = cleanNumber(aRow[i]);        // in 10^6 km
    const a_km = a_million_km != null ? a_million_km * 1e6 : null;
    const a_AU = a_km != null ? a_km / AU_KM : null;  // AU

    const period_days = cleanNumber(periodRow[i]);    // days
    const radius_km = cleanNumber(radiusRow[i]);      // km

    if (a_AU == null || period_days == null || radius_km == null) {
      continue;
    }

    records.push({
      id,
      name,
      a_AU: +a_AU.toFixed(6),
      period_days: +period_days.toFixed(3),
      radius_km: +radius_km.toFixed(1),
    });
  }

  return records;
}

async function main() {
  console.log('Fetching NASA Planetary Fact Sheet...');
  const res = await fetch(URL_FACTSHEET);
  if (!res.ok) throw new Error(`HTTP ${res.status} fetching fact sheet`);
  const html = await res.text();

  const $ = cheerio.load(html);
  const planets = parseTable($);

  // Assign simple colors
  const colors = {
    mercury: '#b5b0a4',
    venus: '#d8c17f',
    earth: '#4ea1d3',
    mars: '#c1440e',
    jupiter: '#d6b38c',
    saturn: '#e8d8a5',
    uranus: '#7ad0e5',
    neptune: '#5579c6',
  };
  for (const p of planets) p.color = colors[p.id] || '#cccccc';

  const outDir = path.join(__dirname, '..', 'data');
  await fs.mkdir(outDir, { recursive: true });
  const outPath = path.join(outDir, 'planets.json');
  await fs.writeFile(outPath, JSON.stringify({ source: URL_FACTSHEET, au_km: AU_KM, planets }, null, 2));
  console.log('Wrote', outPath);
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});
```

