```js
// src/render/scale.js
export const WORLD = {
  // Map 1 AU to pixels for orbit distances
  AU_TO_PX: 180, // adjust to fit your viewport
  // Planet size exaggeration so small planets are visible
  KM_TO_PX: 1 / 3000, // base scale, then clamped with a minimum
  MIN_RADIUS_PX: 3,   // enforce a visible minimum radius
};

export function auToPx(au) {
  return au * WORLD.AU_TO_PX;
}

export function kmToPx(km) {
  return Math.max(WORLD.MIN_RADIUS_PX, km * WORLD.KM_TO_PX);
}
```

