```js
// src/main.js
import { auToPx, kmToPx } from './render/scale.js';
import { createState } from './core/state.js';

const DPR = Math.max(1, window.devicePixelRatio || 1);

const canvas = document.getElementById('scene');
const ctx = canvas.getContext('2d');
const timeScaleInput = document.getElementById('timeScale');
const timeScaleLabel = document.getElementById('timeScaleLabel');

// Load data generated from NASA page
async function loadPlanets() {
  const res = await fetch('../data/planets.json', { cache: 'no-cache' });
  if (!res.ok) throw new Error('Failed to load planets.json');
  const json = await res.json();
  // json = { source, au_km, planets: [{ id, name, a_AU, period_days, radius_km, color }] }
  return json.planets;
}

function resize() {
  const cssW = canvas.clientWidth;
  const cssH = canvas.clientHeight;
  canvas.width = Math.max(1, Math.floor(cssW * DPR));
  canvas.height = Math.max(1, Math.floor(cssH * DPR));
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0); // draw in CSS pixels
}

function clear() {
  ctx.fillStyle = '#0b1020';
  ctx.fillRect(0, 0, canvas.width / DPR, canvas.height / DPR);
}

function drawSun(cx, cy) {
  const sunRadiusPx = 12; // stylized
  const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, sunRadiusPx * 1.8);
  grad.addColorStop(0, '#fffbcc');
  grad.addColorStop(1, 'rgba(255, 220, 120, 0)');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(cx, cy, sunRadiusPx * 1.8, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#ffd75e';
  ctx.beginPath();
  ctx.arc(cx, cy, sunRadiusPx, 0, Math.PI * 2);
  ctx.fill();
}

function drawOrbits(cx, cy, planets) {
  ctx.strokeStyle = 'rgba(255,255,255,0.15)';
  ctx.lineWidth = 1;
  for (const p of planets) {
    const r = auToPx(p.a_AU);
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.stroke();
  }
}

function drawPlanets(cx, cy, planets, tDays) {
  for (const p of planets) {
    // Angular rate: 2π per orbital period (days)
    const omega = (2 * Math.PI) / p.period_days; // rad/day
    const theta = omega * tDays; // simple circular orbit

    const r = auToPx(p.a_AU);
    const x = cx + r * Math.cos(theta);
    const y = cy + r * Math.sin(theta);

    const rp = kmToPx(p.radius_km);

    // Planet body
    ctx.fillStyle = p.color || '#ccc';
    ctx.beginPath();
    ctx.arc(x, y, rp, 0, Math.PI * 2);
    ctx.fill();

    // Label
    ctx.fillStyle = 'rgba(230,230,230,0.9)';
    ctx.font = '12px system-ui, sans-serif';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillText(p.name, x + rp + 4, y);
  }
}

function animate(state) {
  let lastTs = performance.now();

  function frame(now) {
    const dtMs = now - lastTs;
    lastTs = now;

    // Map real milliseconds to simulated days. Base: 1 sec real = 1 day sim.
    const daysPerMsBase = 1 / 1000; // 1 day / 1000 ms
    const tAdvance = dtMs * daysPerMsBase * state.timeScale;
    state.tDays += tAdvance;

    resize();
    clear();

    const cx = canvas.width / DPR / 2;
    const cy = canvas.height / DPR / 2;

    drawSun(cx, cy);
    drawOrbits(cx, cy, state.planets);
    drawPlanets(cx, cy, state.planets, state.tDays);

    requestAnimationFrame(frame);
  }

  requestAnimationFrame(frame);
}

function wireUI(state) {
  function updateLabel() {
    timeScaleLabel.textContent = `${Number(state.timeScale).toFixed(1)}x`;
  }
  timeScaleInput.addEventListener('input', () => {
    state.timeScale = parseFloat(timeScaleInput.value);
    updateLabel();
  });
  state.timeScale = parseFloat(timeScaleInput.value);
  updateLabel();
}

(async function main() {
  const planets = await loadPlanets();
  const state = createState(planets);
  wireUI(state);
  animate(state);
})();
```

How the NASA data maps into the simulation
- Semimajor axis a_AU → pixel distance: r_px = a_AU * AU_TO_PX (see auToPx in scale.js). This sets each planet’s orbit radius on the canvas.
- Orbital period (days) → angular speed: omega = 2π / period_days; angle θ = omega * tDays.
- Mean radius (km) → planet size: radius_px = max(MIN_RADIUS_PX, radius_km * KM_TO_PX) so small planets remain visible.
- Time scaling: UI slider multiplies simulated days per real second.

Optional: Use JPL HORIZONS instead of the static fact sheet
- For higher fidelity (elliptical orbits, current phase angles), query HORIZONS API (https://ssd.jpl.nasa.gov/api/horizons.api) server-side and produce a planets.json with osculating elements (a, e, i, Ω, ω, M0, epoch) and then propagate with Kepler’s equation in the client. This is beyond the minimal runnable example above but follows the same mapping pattern.

Performance and visual tips
- Keep Canvas DPR-aware and redraw only per frame (already in code).
- Clamp minimum planet radius so Mercury/Mars remain visible without excessive overdraw.
- Limit shadows/gradients; a single radial gradient around the Sun is cheap and effective.
- If you add moons or many labels, consider culling distant labels or drawing trails at reduced alpha every N frames.

How to run
1) Run the fetch script to create data/planets.json:
   - node scripts/fetch-planets.js
2) Serve the public/ folder with any static server (e.g., npx http-server public or VS Code Live Server).
3) Open http://localhost:8080 (or the port your server uses).

That’s it — copy-paste each file into the specified path, run the fetch script (which cites and pulls from NASA), and open the page to see the simulation.

