    toggleLabels.addEventListener('change', () => state.showLabels = toggleLabels.checked);

    function resizeCanvas() {
      const dpr = Math.max(1, window.devicePixelRatio || 1);
      const cssW = canvas.clientWidth;
      const cssH = canvas.clientHeight;
      canvas.width = Math.floor(cssW * dpr);
      canvas.height = Math.floor(cssH * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0); // draw using CSS pixels
      state.center.x = cssW / 2;
      state.center.y = cssH / 2;
      computeScale();
    }

    // --- Mapping formulas (explicit):
    // 1) orbitRadiusPx = a_AU * pxPerAU
    // 2) omega = 2π / (period_days * 86400) [rad / simulated second]
    // 3) theta_t = theta_0 + omega * t_sim
    function computeScale() {
      if (!state.planets.length) return;
      const maxA = Math.max(...state.planets.map(p => p.a_AU));
      const maxPossible = Math.min(canvas.clientWidth, canvas.clientHeight) / 2 - state.marginPx;
      state.pxPerAU = maxA > 0 ? maxPossible / maxA : 100;
    }

    function drawScene() {
      const w = canvas.clientWidth;
      const h = canvas.clientHeight;

      // Clear background
      ctx.clearRect(0, 0, w, h);
      ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--bg');
      ctx.fillRect(0, 0, w, h);

      // Draw Sun (with halo)
      const sunColor = getComputedStyle(document.documentElement).getPropertyValue('--sun').trim();
      const halo = getComputedStyle(document.documentElement).getPropertyValue('--halo').trim();
      const sunPx = 10; // visual size only (not to scale)
      ctx.beginPath();
      ctx.fillStyle = halo;
      ctx.arc(state.center.x, state.center.y, sunPx * 3.2, 0, Math.PI * 2);
      ctx.fill();
      ctx.beginPath();
      ctx.fillStyle = sunColor;
      ctx.arc(state.center.x, state.center.y, sunPx, 0, Math.PI * 2);
      ctx.fill();

      // Draw orbits
      if (state.showOrbits) {
        ctx.strokeStyle = getComputedStyle(document.documentElement).getPropertyValue('--orbit').trim();
        ctx.lineWidth = 1;
        for (const p of state.planets) {
          const r = p.a_AU * state.pxPerAU; // orbitRadiusPx = a_AU * pxPerAU
          ctx.beginPath();
          ctx.arc(state.center.x, state.center.y, r, 0, Math.PI * 2);
          ctx.stroke();
        }
      }

      // Draw planets
      for (const p of state.planets) {
        const rOrbit = p.a_AU * state.pxPerAU; // mapping
        const theta = state.angles.get(p.id) || 0;
        const x = state.center.x + rOrbit * Math.cos(theta);
        const y = state.center.y + rOrbit * Math.sin(theta);

        // Visual radius: map physical radius_km to pixels with a sublinear scale for visibility
        const visR = Math.max(2, Math.pow(p.radius_km, 0.45) * 0.2); // tweakable aesthetic scale

        ctx.beginPath();
        ctx.fillStyle = p.color || '#ccc';
        ctx.arc(x, y, visR, 0, Math.PI * 2);
        ctx.fill();

        if (state.showLabels) {
          ctx.fillStyle = '#cfd6e6';
          ctx.font = '12px system-ui, sans-serif';
          ctx.textAlign = 'center';
          ctx.fillText(p.name, x, y - visR - 6);
        }
      }

      // HUD readout
      const maxA = Math.max(...state.planets.map(p => p.a_AU));
      readout.textContent = `pxPerAU: ${state.pxPerAU.toFixed(2)} | outermost a (AU): ${maxA.toFixed(3)}`;
    }

    function step(ts) {
      if (!state.lastTs) state.lastTs = ts;
      const dtMs = ts - state.lastTs;
      state.lastTs = ts;
      const dtRealSec = dtMs / 1000;
      const dtSim = dtRealSec * state.timeScale; // simulated seconds elapsed this frame

      // Update angles: theta += omega * dtSim, with omega = 2π / (period_days * 86400)
      const SEC_PER_DAY = 86400;
      for (const p of state.planets) {
        const omega = (2 * Math.PI) / (p.period_days * SEC_PER_DAY);
        const thetaPrev = state.angles.get(p.id) || 0;
        const thetaNext = thetaPrev + omega * dtSim;
        state.angles.set(p.id, thetaNext % (2 * Math.PI));
      }

      drawScene();
      requestAnimationFrame(step);
    }

    function initAngles() {
      // Start each planet at a different phase to make the scene more interesting
      const n = state.planets.length;
      state.planets.forEach((p, i) => state.angles.set(p.id, (i / n) * 2 * Math.PI));
    }

    async function main() {
      updateSpeedLabel();
      state.planets = await loadPlanets();
      initAngles();
      resizeCanvas();
      window.addEventListener('resize', resizeCanvas);
      requestAnimationFrame(step);
    }

    main();
  </script>
</body>
</html>
