Below are concrete steps for Unity and Unreal to render terrain and mountain to separate color/depth targets and composite them in a post pass that blends only near the depth-contact band. This preserves each object’s own diffuse and prevents cross-diffuse.

Unity (URP/HDRP or Built-in with command buffers)
Goal: Render terrain and mountain into two offscreen color+depth pairs, then run a full-screen pass to composite using depth proximity.

A) Create render targets
- Two color RTs: TerrainColor, MountainColor (R11G11B10 or R16G16B16F)
- Two depth RTs: TerrainDepth, MountainDepth (R32_SFloat or Depth-only with copy to texture)

B) Tag your renderers
- Put Terrain objects on layer: TerrainLayer
- Put Mountain objects on layer: MountainLayer

C) URP example (Renderer Feature)
1) Create a ScriptableRendererFeature with two ScriptableRenderPasses to draw each layer to its own RT, then a third pass to composite.

// TerrainMountainCompositeFeature.cs
public class TerrainMountainCompositeFeature : ScriptableRendererFeature {
    class LayerPass : ScriptableRenderPass {
        FilteringSettings filtering;
        ShaderTagId shaderTag = new ShaderTagId("UniversalForward");
        RenderTargetIdentifier color, depth;
        string profilerTag;
        public LayerPass(string tag, LayerMask layer, RenderTargetIdentifier colorRT, RenderTargetIdentifier depthRT) {
            profilerTag = tag;
            filtering = new FilteringSettings(RenderQueueRange.all, layer);
            color = colorRT; depth = depthRT;
        }
        public override void Configure(CommandBuffer cmd, RenderTextureDescriptor cameraTextureDescriptor) {
            var desc = cameraTextureDescriptor;
            desc.colorFormat = RenderTextureFormat.DefaultHDR; desc.depthBufferBits = 0;
            cmd.GetTemporaryRT(color, desc, FilterMode.Bilinear);
            var depthDesc = cameraTextureDescriptor; depthDesc.colorFormat = RenderTextureFormat.Depth; depthDesc.depthBufferBits = 32;
            cmd.GetTemporaryRT(depth, depthDesc, FilterMode.Point);
            ConfigureTarget(color, depth);
            ConfigureClear(ClearFlag.All, Color.clear);
        }
        public override void Execute(ScriptableRenderContext context, ref RenderingData renderingData) {
            var cmd = CommandBufferPool.Get(profilerTag);
            using (new ProfilingScope(cmd, new ProfilingSampler(profilerTag))) {
                context.ExecuteCommandBuffer(cmd); cmd.Clear();
                var sort = new SortingSettings(renderingData.cameraData.camera) { criteria = SortingCriteria.CommonOpaque };
                var draw = new DrawingSettings(shaderTag, sort) { perObjectData = PerObjectData.None };
                var filter = filtering;
                context.DrawRenderers(renderingData.cullResults, ref draw, ref filter);
            }
            context.ExecuteCommandBuffer(cmd); CommandBufferPool.Release(cmd);
        }
        public override void FrameCleanup(CommandBuffer cmd) {
            cmd.ReleaseTemporaryRT(color); cmd.ReleaseTemporaryRT(depth);
        }
    }

    class CompositePass : ScriptableRenderPass {
        Material mat; RenderTargetIdentifier srcA, depthA, srcB, depthB;
        RenderTargetIdentifier cameraColor;
        public CompositePass(Material m, RenderTargetIdentifier a, RenderTargetIdentifier ad, RenderTargetIdentifier b, RenderTargetIdentifier bd) {
            mat = m; srcA = a; depthA = ad; srcB = b; depthB = bd;
        }
        public void Setup(RenderTargetIdentifier cameraColorTarget) { cameraColor = cameraColorTarget; }
        public override void Execute(ScriptableRenderContext context, ref RenderingData data) {
            var cmd = CommandBufferPool.Get("Composite Terrain/Mountain");
            mat.SetTexture("_TerrainColor", srcA);
            mat.SetTexture("_TerrainDepth", depthA);
            mat.SetTexture("_MountainColor", srcB);
            mat.SetTexture("_MountainDepth", depthB);
            Blit(cmd, source: cameraColor, destination: cameraColor, mat, pass: 0);
            context.ExecuteCommandBuffer(cmd); CommandBufferPool.Release(cmd);
        }
    }

    public LayerMask terrainLayer, mountainLayer;
    public Material compositeMaterial;
    RenderTargetIdentifier tCol = new RenderTargetIdentifier("_TerrainCol");
    RenderTargetIdentifier tDepth = new RenderTargetIdentifier("_TerrainDepthTex");
    RenderTargetIdentifier mCol = new RenderTargetIdentifier("_MountainCol");
    RenderTargetIdentifier mDepth = new RenderTargetIdentifier("_MountainDepthTex");

    LayerPass terrainPass, mountainPass; CompositePass compositePass;

    public override void Create() {
        terrainPass = new LayerPass("Terrain Pass", terrainLayer, tCol, tDepth) { renderPassEvent = RenderPassEvent.BeforeRenderingTransparents };
        mountainPass = new LayerPass("Mountain Pass", mountainLayer, mCol, mDepth) { renderPassEvent = RenderPassEvent.BeforeRenderingTransparents + 1 };
        compositePass = new CompositePass(compositeMaterial, tCol, tDepth, mCol, mDepth) { renderPassEvent = RenderPassEvent.BeforeRenderingPostProcessing };
    }

    public override void AddRenderPasses(ScriptableRenderer renderer, ref RenderingData data) {
        renderer.EnqueuePass(terrainPass);
        renderer.EnqueuePass(mountainPass);
        compositePass.Setup(renderer.cameraColorTarget);
        renderer.EnqueuePass(compositePass);
    }
}

2) Composite shader (HLSL)
// TerrainMountainComposite.hlsl (URP full-screen pass)
TEXTURE2D(_TerrainColor); SAMPLER(sampler_TerrainColor);
TEXTURE2D(_TerrainDepth); SAMPLER(sampler_TerrainDepth);
TEXTURE2D(_MountainColor); SAMPLER(sampler_MountainColor);
TEXTURE2D(_MountainDepth); SAMPLER(sampler_MountainDepth);
float _SeamThickness; // in linear depth units
float _SeamFeather;

float LinearizeDepth(float z, float4 zParams) {
    // For URP: zParams = float4(1.0 - far/near, far/near, (1.0 - far/near)/far, 1.0/far)
    return 1.0 / (zParams.x * z + zParams.y); // or pass linear depths directly
}

float smoothstep1(float e0, float e1, float x) {
    float t = saturate((x - e0) / max(e1 - e0, 1e-6));
    return t * t * (3.0 - 2.0 * t);
}

float4 Frag(Varyings i) : SV_Target {
    float2 uv = i.texcoord;
    float3 tc = SAMPLE_TEXTURE2D(_TerrainColor, sampler_TerrainColor, uv).rgb;
    float3 mc = SAMPLE_TEXTURE2D(_MountainColor, sampler_MountainColor, uv).rgb;

    float td = SAMPLE_TEXTURE2D(_TerrainDepth, sampler_TerrainDepth, uv).r;
    float md = SAMPLE_TEXTURE2D(_MountainDepth, sampler_MountainDepth, uv).r;

    bool tValid = td < 0.9999; // or use separate valid mask
    bool mValid = md < 0.9999;

    // Assume depths are already linear; if not, linearize here.
    float terrainD = td;
    float mountainD = md;

    bool mInFront = mValid && (!tValid || mountainD <= terrainD);
    bool tInFront = tValid && (!mValid || terrainD < mountainD);

    float3 baseCol = tValid || mValid ? (mInFront ? mc : tc) : float3(0,0,0);

    bool both = tValid && mValid;
    float delta = abs(terrainD - mountainD);
    float w = 0.0;
    if (both) {
        w = 1.0 - smoothstep1(_SeamThickness, _SeamFeather, delta);
    }

    float3 outCol = baseCol;
    if (both && mInFront) {
        outCol = mc * (1.0 - w) + tc * w;
    } else if (both && tInFront) {
        outCol = tc * (1.0 - w) + mc * w;
    }

    return float4(saturate(outCol), 1.0);
}

D) HDRP note
- Implement with a Custom Pass: one Custom Pass to render TerrainLayer into an RT set, another for MountainLayer, and a FullScreen Custom Pass for the composite using the same fragment logic as above.

E) Built-in RP alternative
- Use CommandBuffer with CameraEvent.BeforeImageEffects to:
  - SetRenderTarget(TerrainColor, TerrainDepth) and DrawRenderers for TerrainLayer
  - SetRenderTarget(MountainColor, MountainDepth) and DrawRenderers for MountainLayer
  - Blit with the composite material to the backbuffer.

Unreal Engine (UE5/UE4)
Goal: Two SceneCapture2D actors to produce terrain-only and mountain-only color+depth, then a post-process material to composite by depth proximity.

A) Create two capture pipelines
1) Place two SceneCapture2D actors in the level: Capture_Terrain and Capture_Mountain, aligned with the main camera (copy transforms in Tick or attach to camera).
2) For each capture, create a Render Target 2D for color (e.g., RGBA16f) and one for depth (R32f). In Capture settings:
   - Capture Source: Final Color (HDR) in RGB, SceneDepth in A (or use separate depth capture if needed).
   - ShowOnly List: add only Terrain meshes to Capture_Terrain; only Mountain meshes to Capture_Mountain. Alternatively, use Actor Hidden In Game or Custom Depth Stencil for inclusion masks.

B) Extract linear depth
- If using SceneDepth in alpha, it’s already in device depth; convert to linear in the material using CameraDepthToWorld.
- Alternatively, enable "Capture Every Frame" off and manually UpdateResource if you need control.

C) Post-process composite material (Material Domain: Post Process)
1) Create Texture2D parameters: TerrainColorRT, MountainColorRT; TerrainDepthRT, MountainDepthRT.
2) In the material graph:
   - Sample TerrainColorRT -> tc (RGB)
   - Sample MountainColorRT -> mc (RGB)
   - Sample TerrainDepthRT -> tdRaw, MountainDepthRT -> mdRaw
   - Convert to linear depth: use Transform node SceneDepth -> View Space, or custom HLSL via MaterialFunction. If td/md are already linear, skip.
   - Compute delta = abs(td - md)
   - w = 1 - SmoothStep(SeamThickness, SeamFeather, delta)
   - mInFront = md <= td; tInFront = td < md
   - base = Select(mInFront, mc, tc)
   - out = If(bothValid, Lerp(front, back, w), base) where
     - bothValid = (td < FarClip) && (md < FarClip) or use "is finite" masks via compares
     - When mInFront: front=mc back=tc; when tInFront: front=tc back=mc
3) Output to Emissive Color = out; Opacity = 1.

D) Apply the post-process
- Create a Post Process Material (Blendable Location: Before Tonemapping). Add it to your camera’s Post Process Settings or a global PostProcessVolume. Assign the four RT textures and set SeamThickness/SeamFeather parameters.

E) Minimal HLSL custom node (optional)
In a Custom node (Material Graph), inputs: tc, mc, td, md, seamThickness, seamFeather. Output float3 color.
// UE HLSL snippet
float smoothstep1(float e0, float e1, float x){ float t = saturate((x - e0)/max(e1-e0,1e-6)); return t*t*(3-2*t);} 
float3 Blend(float3 tc, float3 mc, float td, float md, float seamThickness, float seamFeather){
    bool tValid = isfinite(td);
    bool mValid = isfinite(md);
    bool mInFront = mValid && (!tValid || md <= td);
    bool tInFront = tValid && (!mValid || td < md);
    float3 baseCol = (tValid || mValid) ? (mInFront ? mc : tc) : float3(0,0,0);
    bool both = tValid && mValid;
    float delta = abs(td - md);
    float w = both ? (1 - smoothstep1(seamThickness, seamFeather, delta)) : 0;
    float3 outCol = baseCol;
    if (both && mInFront) outCol = mc*(1-w) + tc*w;
    else if (both && tInFront) outCol = tc*(1-w) + mc*w;
    return saturate(outCol);
}

Parameter tips
- SeamThickness: start of strong blend band near contact (e.g., 0.05–0.2 in view-space meters)
- SeamFeather: end of blend band where mixing fades to 0 (e.g., 0.15–0.4); must be > SeamThickness
- Ensure you linearize depths consistently across both targets. If using device depth, use engine-provided linearization functions.

Why this prevents diffuse leakage
- Terrain and mountain are shaded in isolation into their own color RTs. No material samples the other’s textures. The composite pass only mixes final colors based on depth proximity near the seam, so diffuse from one never affects how the other was lit.

Simple diagram (ASCII)
Camera view (side):
[Cam] --->  depth increases --->
Terrain -----\\\\\----
                 \\  contact band (blend)  <= small depth delta
Mountain ---///////----

Blend weight w:
- delta = |depth_terrain - depth_mountain|
- w = 1 - smoothstep(SeamThickness, SeamFeather, delta)
- Mix only where both are present and close in depth.

Minimal checklist
- Separate color/depth targets for terrain and mountain
- Composite full-screen pass using depth proximity and smoothstep
- Depth linearization handled consistently
- Works in Unity (URP/HDRP/Built-in) and Unreal (SceneCapture2D + PostProcess)
- No cross-sampling of diffuse; blending only near seam

Below are concrete steps for Unity (URP/HDRP) and Unreal (UE5) to render terrain and mountain into separate color/depth targets, then composite with a contact-band blend so each object keeps its own diffuse.

ASCII: contact-band at seam

 Camera view (side)
   |\            mountain (front)
   | \_____====<- contact band ->====_____ terrain (back)
   |      
 Mix weight w: 1.0 at contact, fades to 0 by feather distance
 front_out = lerp(front, back, w) only within band; elsewhere pick strict front-most

Unity — URP
1) Create two Render Textures (R8G8B8A8) and depth buffers:
   - TerrainColor, TerrainDepth (RFloat or DepthTexture)
   - MountainColor, MountainDepth
2) Add two Renderer Features (ScriptableRendererFeature):
   - RenderTerrainToRT: draws only Terrain layer to TerrainColor/TerrainDepth
   - RenderMountainToRT: draws only Mountain layer to MountainColor/MountainDepth
   Order: Terrain pass, Mountain pass, then a Fullscreen Composite pass.
3) Layer setup:
   - Put your terrain mesh on Layer "Terrain", mountain mesh on Layer "Mountain".
   - In each feature, set FilteringSettings to that layer, and override camera color/depth targets to the RTs.
4) Minimal URP feature (C#) to direct draws to RTs (terrain example; duplicate for mountain):

 using UnityEngine;
 using UnityEngine.Rendering;
 using UnityEngine.Rendering.Universal;

 public class RenderTerrainToRTFeature : ScriptableRendererFeature {
   class Pass : ScriptableRenderPass {
     static readonly ShaderTagId Tag = new ShaderTagId("UniversalForward");
     FilteringSettings filter;
     RenderTargetIdentifier color, depth;
     string profilerTag;
     public Pass(LayerMask layer, RenderTargetIdentifier color, RenderTargetIdentifier depth, string tag){
       filter = new FilteringSettings(RenderQueueRange.all, layer);
       this.color = color; this.depth = depth; profilerTag = tag;
       renderPassEvent = RenderPassEvent.AfterRenderingPrePasses; // before main opaque
     }
     public override void Configure(CommandBuffer cmd, RenderTextureDescriptor cameraTexDesc){
       var desc = cameraTexDesc; desc.depthBufferBits = 24; desc.msaaSamples = 1;
       ConfigureTarget(color, depth);
       ConfigureClear(ClearFlag.All, Color.clear);
     }
     public override void Execute(ScriptableRenderContext ctx, ref RenderingData data){
       CommandBuffer cmd = CommandBufferPool.Get(profilerTag);
       using (new ProfilingScope(cmd, new ProfilingSampler(profilerTag))) {
         ctx.ExecuteCommandBuffer(cmd); cmd.Clear();
         var sort = SortingCriteria.CommonOpaque;
         var draw = new DrawingSettings(Tag, new SortingSettings(data.cameraData.camera){ criteria = sort });
         var filt = filter;
         ctx.DrawRenderers(data.cullResults, ref draw, ref filt);
       }
       ctx.ExecuteCommandBuffer(cmd);
       CommandBufferPool.Release(cmd);
     }
   }
   public LayerMask terrainLayer;
   public RenderTexture terrainColor;
   public RenderTexture terrainDepth;
   Pass pass;
   public override void Create(){ }
   public override void AddRenderPasses(ScriptableRenderer renderer, ref RenderingData data){
     if (pass == null) pass = new Pass(terrainLayer, terrainColor, terrainDepth, "RenderTerrainRT");
     renderer.EnqueuePass(pass);
   }
 }

5) Fullscreen composite material/shader (URP/HLSL). It samples the four RTs, does depth proximity check, and blends only in the contact band.

 Shader "Hidden/CompositeTerrainMountain" {
   Properties{}
   SubShader{
     Tags{"RenderType"="Opaque"}
     Pass{
       ZTest Always ZWrite Off Cull Off
       HLSLPROGRAM
       #pragma vertex VertDefault
       #pragma fragment Frag
       #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"
       TEXTURE2D(_TerrainColor); SAMPLER(sampler_TerrainColor);
       TEXTURE2D(_TerrainDepth); SAMPLER(sampler_TerrainDepth);
       TEXTURE2D(_MountainColor); SAMPLER(sampler_MountainColor);
       TEXTURE2D(_MountainDepth); SAMPLER(sampler_MountainDepth);
       float _Near; float _Far; float _SeamThickness; float _SeamFeather;
       struct VIn{ float4 pos:POSITION; float2 uv:TEXCOORD0; };
       struct VOut{ float4 pos:SV_Position; float2 uv:TEXCOORD0; };
       VOut VertDefault(VIn i){ VOut o; o.pos = TransformObjectToHClip(i.pos.xyz); o.uv = i.uv; return o; }
       float LinearizeDepth(float d){ // 0..1 -> view Z
         float z = d * 2.0 - 1.0;
         return (2.0 * _Near * _Far) / (_Far + _Near - z * (_Far - _Near));
       }
       float smoothstep1(float a, float b, float x){ float t = saturate((x - a)/max(b-a,1e-6)); return t*t*(3-2*t); }
       float4 Frag(VOut i):SV_Target{
         float2 uv = i.uv;
         float4 tc = SAMPLE_TEXTURE2D(_TerrainColor, sampler_TerrainColor, uv);
         float4 mc = SAMPLE_TEXTURE2D(_MountainColor, sampler_MountainColor, uv);
         float td = SAMPLE_TEXTURE2D(_TerrainDepth, sampler_TerrainDepth, uv).r;
         float md = SAMPLE_TEXTURE2D(_MountainDepth, sampler_MountainDepth, uv).r;
         bool tValid = td < 0.9999; // assume cleared to 1.0
         bool mValid = md < 0.9999;
         float tZ = tValid ? LinearizeDepth(td) : 1e9;
         float mZ = mValid ? LinearizeDepth(md) : 1e9;
         bool mFront = mValid && (!tValid || mZ <= tZ);
         bool tFront = tValid && (!mValid || tZ <  mZ);
         float4 baseCol = (mFront? mc : tc);
         if(!tValid && !mValid) return float4(0,0,0,1);
         bool both = tValid && mValid;
         if(!both) return baseCol;
         float delta = abs(tZ - mZ);
         float w = 1.0 - smoothstep1(_SeamThickness, _SeamFeather, delta);
         if(w <= 0.0) return baseCol;
         float4 front = mFront ? mc : tc;
         float4 back  = mFront ? tc : mc;
         return lerp(front, back, w);
       }
       ENDHLSL
     }
   }
 }

6) Composite pass setup:
   - Create a Blit/FullScreenDraw feature after transparent rendering; feed TerrainColor/TerrainDepth and MountainColor/MountainDepth into the material above; set _Near/_Far from Camera, _SeamThickness≈0.1–0.2, _SeamFeather≈0.3–0.5.
   - Output to camera color. This guarantees each object was shaded independently; only final colors are mixed at the seam.

Unity — HDRP
1) Create Custom Pass Volume in your scene, set Injection Point = Before Post Process.
2) Add two Custom Passes:
   - Pass A (Terrain): Set Render Targets = TerrainColor/TerrainDepth; Renderers = Layer "Terrain"; Clear Color+Depth.
   - Pass B (Mountain): Set Render Targets = MountainColor/MountainDepth; Renderers = Layer "Mountain"; Clear Color+Depth.
3) Add a Fullscreen Custom Pass (HLSL) using the same fragment logic as the URP composite. In HDRP, sample depth as RFloat or use your own depth RTs; linearize with camera near/far.
4) Bind the four RTs and camera near/far to the fullscreen pass material; draw to CameraColor.

Unreal Engine 5 (UE5)
Option A — Separate Scene Capture 2D actors (simple to wire up):
1) Place two SceneCapture2D actors:
   - CaptureTerrain: ShowOnly List contains Terrain actors; set Render Target = RT_TerrainColor; also set a Depth RT via CustomDepth or create a second capture.
   - CaptureMountain: ShowOnly List contains Mountain actors; Render Target = RT_MountainColor; depth similarly.
   Notes:
   - For linear depth, use a material on the capture that writes view-space depth to a separate RT (Material Domain: Post Process or Surface with CustomDepth pass). Alternatively, use SceneDepth in a post process to output to a depth RT.
2) Make two render targets for depth (R32f): RT_TerrainDepth, RT_MountainDepth.
3) In a Post Process Material (Domain: Post Process, Blendable Location: After Tonemapping or Before, as needed):
   - Sample the four RTs via TextureObject parameters.
   - Convert SceneDepth-style values to linear if needed (use View.WorldToMetersScale and View.NearFar in material functions or pass constants from a Material Parameter Collection).
   - Implement contact-band blend and write to EmissiveColor; set Material to Replace tonemapper as appropriate.

Minimal UE5 HLSL (Custom node) inside a Post Process Material:
 Inputs: UV, TerrainColorTex, TerrainDepthTex, MountainColorTex, MountainDepthTex, Near, Far, SeamThickness, SeamFeather.
 Code:
 float LinearizeDepth(float d, float n, float f){
   float z = d * 2.0 - 1.0;
   return (2.0 * n * f) / (f + n - z * (f - n));
 }
 float4 tc = Texture2DSample(TerrainColorTex, TerrainColorTexSampler, UV);
 float4 mc = Texture2DSample(MountainColorTex, MountainColorTexSampler, UV);
 float td = Texture2DSample(TerrainDepthTex, TerrainDepthTexSampler, UV).r;
 float md = Texture2DSample(MountainDepthTex, MountainDepthTexSampler, UV).r;
 bool tValid = td < 0.9999;
 bool mValid = md < 0.9999;
 float tZ = tValid ? LinearizeDepth(td, Near, Far) : 1e9;
 float mZ = mValid ? LinearizeDepth(md, Near, Far) : 1e9;
 bool mFront = mValid && (!tValid || mZ <= tZ);
 float4 baseCol = mFront ? mc : tc;
 if(!(tValid && mValid)) return baseCol;
 float delta = abs(tZ - mZ);
 float w = 1.0 - smoothstep(SeamThickness, SeamFeather, delta);
 float4 front = mFront ? mc : tc;
 float4 back  = mFront ? tc : mc;
 return lerp(front, back, w);

Option B — Single scene with Custom Depth/Stencil masks:
1) Enable Render CustomDepth Pass in Project Settings.
2) Assign CustomDepth Stencil values: Terrain=1, Mountain=2.
3) Create two SceneCapture2D or two Render Layers using Composure (recommended) to output color and a linear depth pass per group.
4) Composite with a Post Process Material as above.

Notes and guardrails
- Depth formats: prefer R32F for linear depth RTs; if you only have non-linear device depth, use the provided linearization.
- Clear values: clear depth RTs to 1.0 (far) so "invalid" pixels are easily tested.
- Do not sample the other object’s textures in its material; all mixing happens in the composite pass only near the seam.
- Tuning: start with SeamThickness=0.1, SeamFeather=0.35 in world-space depth units consistent with your linearization.

This pipeline preserves strict separation of diffuse during shading and blends only final colors in a narrow contact band to avoid seams without color bleed.

Below are concrete, copy-pastable compositing snippets and URP renderer feature updates to: (1) render terrain-only and mountain-only into separate color+linear-depth RTs, (2) run a full-screen composite that picks the front/back per pixel from those two depth textures, linearizes if needed, and (3) applies a contact-band blend to avoid color bleed. Includes URP/HDRP HLSL and a UE5 material setup.

A) Contact-band logic (reference)
- Given linear depths zT, zM (in the same space), define:
  - front = min-depth set, back = other set
  - band weight w = 1 - smoothstep(thickness, feather, abs(zT - zM))
  - color = lerp(frontColor, backColor, w)
- Outside the band (large depth gap), the front-most wins; within the band, colors feather smoothly. Because each set is shaded to its own color RT, no diffuse leaks across.

B) Unity URP — complete RendererFeature with two offscreen passes (color + linear depth) and final composite pass
Files:
- Assets/Scripts/ContactBandFeature.cs
- Assets/Shaders/ContactBandWriteDepth.hlsl (small include for linear depth)
- Assets/Shaders/ContactBandComposite.hlsl (full-screen composite shader)

1) ContactBandComposite.hlsl (URP full-screen pass)
Shader "Hidden/ContactBand/Composite"
{
    Properties {}
    SubShader
    {
        Tags { "RenderType"="Opaque" "Queue"="Overlay" }
        ZTest Always Cull Off ZWrite Off Blend One Zero
        Pass
        {
            HLSLPROGRAM
            #pragma vertex Vert
            #pragma fragment Frag
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            TEXTURE2D_X(_TerrainColor);
            SAMPLER(sampler_TerrainColor);
            TEXTURE2D_X(_MountainColor);
            SAMPLER(sampler_MountainColor);
            TEXTURE2D_X(_TerrainDepthLin);
            SAMPLER(sampler_TerrainDepthLin);
            TEXTURE2D_X(_MountainDepthLin);
            SAMPLER(sampler_MountainDepthLin);

            float _SeamThickness;   // e.g., 0.15 (same units as linear depth)
            float _SeamFeather;     // e.g., 0.30 (> thickness)

            struct VSIn { float3 posOS : POSITION; float2 uv : TEXCOORD0; };
            struct VSOut { float4 posCS : SV_POSITION; float2 uv : TEXCOORD0; };

            VSOut Vert(VSIn v)
            {
                VSOut o;
                o.posCS = TransformObjectToHClip(v.posOS);
                o.uv = v.uv;
                return o;
            }

            float smoothstep01(float e0, float e1, float x)
            {
                float t = saturate((x - e0) / max(e1 - e0, 1e-6));
                return t * t * (3.0 - 2.0 * t);
            }

            float4 Frag(VSOut i) : SV_Target
            {
                float2 uv = i.uv;
                float3 cT = SAMPLE_TEXTURE2D_X(_TerrainColor, sampler_TerrainColor, uv).rgb;
                float3 cM = SAMPLE_TEXTURE2D_X(_MountainColor, sampler_MountainColor, uv).rgb;

                float zT = SAMPLE_TEXTURE2D_X(_TerrainDepthLin, sampler_TerrainDepthLin, uv).r; // linear depth (smaller = closer)
                float zM = SAMPLE_TEXTURE2D_X(_MountainDepthLin, sampler_MountainDepthLin, uv).r;

                bool tFront = (zT > 0 && (zT <= zM || zM <= 0)); // treat 0 as empty
                float3 cFront = tFront ? cT : cM;
                float3 cBack  = tFront ? cM : cT;
                float  zFront = tFront ? zT : zM;
                float  zBack  = tFront ? zM : zT;

                float valid = (zFront > 0) ? 1.0 : 0.0;
                if (valid < 0.5)
                {
                    // Only back is valid
                    return float4(cBack, 1);
                }

                float dz = (zBack > 0) ? abs(zFront - zBack) : 1e6;
                float w = 1.0 - smoothstep01(_SeamThickness, _SeamFeather, dz);
                float3 c = lerp(cFront, cBack, w);
                return float4(c, 1);
            }
            ENDHLSL
        }
    }
}

