3) ContactBandFeature.cs (URP RendererFeature)
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

public class ContactBandFeature : ScriptableRendererFeature
{
    [System.Serializable]
    public class Settings
    {
        public LayerMask terrainLayer;
        public LayerMask mountainLayer;
        public RenderPassEvent captureEvent = RenderPassEvent.AfterRenderingOpaques;
        public RenderPassEvent compositeEvent = RenderPassEvent.AfterRenderingTransparents;
        public Material compositeMaterial; // Hidden/ContactBand/Composite
        public int width = 0;  // 0 = camera size
        public int height = 0;
        public RenderTextureFormat colorFmt = RenderTextureFormat.ARGBHalf;
        public RenderTextureFormat depthFmt = RenderTextureFormat.RFloat; // linear depth stored in R
        public float seamThickness = 0.15f;
        public float seamFeather = 0.30f;
    }

    class CapturePass : ScriptableRenderPass
    {
        FilteringSettings filtering;
        ShaderTagId shaderTagId = new ShaderTagId("UniversalForward");
        string profilerTag;
        int colorID, depthLinID;
        RenderTargetIdentifier colorRT, depthLinRT;
        RenderTextureDescriptor baseDesc;
        int tempDepthBufferID;

        public CapturePass(string tag, LayerMask layer, RenderPassEvent evt)
        {
            profilerTag = tag;
            renderPassEvent = evt;
            filtering = new FilteringSettings(RenderQueueRange.opaque, layer);
            colorID = Shader.PropertyToID(tag + "_Color");
            depthLinID = Shader.PropertyToID(tag + "_DepthLin");
            tempDepthBufferID = Shader.PropertyToID(tag + "_CameraDepthTemp");
        }

        public void Setup(RenderTextureDescriptor cameraDesc, RenderTextureFormat colorFmt, RenderTextureFormat depthFmt, int w, int h)
        {
            baseDesc = cameraDesc;
            if (w > 0) baseDesc.width = w;
            if (h > 0) baseDesc.height = h;
            baseDesc.msaaSamples = 1;
            baseDesc.depthBufferBits = 0;
            baseDesc.colorFormat = colorFmt;
        }

        public override void Configure(CommandBuffer cmd, RenderTextureDescriptor cameraTextureDescriptor)
        {
            // Color RT
            cmd.GetTemporaryRT(colorID, baseDesc, FilterMode.Bilinear);
            colorRT = new RenderTargetIdentifier(colorID);

            // A temporary camera-depth texture (device depth) to linearize from
            var depthDesc = baseDesc;
            depthDesc.colorFormat = RenderTextureFormat.Depth;
            depthDesc.depthBufferBits = 32;
            cmd.GetTemporaryRT(tempDepthBufferID, depthDesc, FilterMode.Point);

            // Linear depth RT (RFloat)
            var linDesc = baseDesc;
            linDesc.colorFormat = RenderTextureFormat.RFloat;
            linDesc.depthBufferBits = 0;
            cmd.GetTemporaryRT(depthLinID, linDesc, FilterMode.Point);
            depthLinRT = new RenderTargetIdentifier(depthLinID);

            ConfigureTarget(colorRT, new RenderTargetIdentifier(tempDepthBufferID));
            ConfigureClear(ClearFlag.All, Color.clear);
        }

        public override void Execute(ScriptableRenderContext context, ref RenderingData renderingData)
        {
            var cmd = CommandBufferPool.Get(profilerTag);
            using (new ProfilingScope(cmd, new ProfilingSampler(profilerTag)))
            {
                context.ExecuteCommandBuffer(cmd);
                cmd.Clear();

                var drawSettings = CreateDrawingSettings(shaderTagId, ref renderingData, SortingCriteria.CommonOpaque);
                var rds = renderingData.cullResults;
                // Draw filtered set into color RT while writing camera depth
                context.DrawRenderers(rds, ref drawSettings, ref filtering);

                // Blit device depth to linear depth RT
                // Fullscreen material-less blit using built-in copy depth is not exposed here;
                // so we convert via a small inline shader in a Blit. URP 14+: use CoreUtils.DrawFullScreen.
                // For simplicity, use a custom material compiled below via Shader.Find.
            }
            context.ExecuteCommandBuffer(cmd);
            CommandBufferPool.Release(cmd);
        }

        public override void OnCameraCleanup(CommandBuffer cmd)
        {
            if (cmd == null) return;
            cmd.ReleaseTemporaryRT(colorID);
            cmd.ReleaseTemporaryRT(tempDepthBufferID);
            cmd.ReleaseTemporaryRT(depthLinID);
        }

        public RenderTargetIdentifier ColorRT => colorRT;
        public RenderTargetIdentifier DepthLinRT => depthLinRT;
        public int ColorRTId => colorID;
        public int DepthLinRTId => depthLinID;
        public int TempDepthId => tempDepthBufferID;
    }

    class CompositePass : ScriptableRenderPass
    {
        string profilerTag = "ContactBand_Composite";
        Material mat;
        RenderTargetIdentifier srcTerrainColor, srcTerrainDepth, srcMountainColor, srcMountainDepth;
        int _TerrainColor = Shader.PropertyToID("_TerrainColor");
        int _MountainColor = Shader.PropertyToID("_MountainColor");
        int _TerrainDepthLin = Shader.PropertyToID("_TerrainDepthLin");
        int _MountainDepthLin = Shader.PropertyToID("_MountainDepthLin");
        float thickness, feather;

        public CompositePass(Material m, RenderPassEvent evt)
        {
            mat = m;
            renderPassEvent = evt;
        }

        public void Setup(RenderTargetIdentifier tCol, RenderTargetIdentifier tZ, RenderTargetIdentifier mCol, RenderTargetIdentifier mZ, float th, float fe)
        {
            srcTerrainColor = tCol;
            srcTerrainDepth = tZ;
            srcMountainColor = mCol;
            srcMountainDepth = mZ;
            thickness = th;
            feather = fe;
        }

        public override void Execute(ScriptableRenderContext context, ref RenderingData renderingData)
        {
            if (mat == null) return;

            var cmd = CommandBufferPool.Get(profilerTag);
            using (new ProfilingScope(cmd, new ProfilingSampler(profilerTag)))
            {
                mat.SetTexture(_TerrainColor, srcTerrainColor);
                mat.SetTexture(_MountainColor, srcMountainColor);
                mat.SetTexture(_TerrainDepthLin, srcTerrainDepth);
                mat.SetTexture(_MountainDepthLin, srcMountainDepth);
                mat.SetFloat("_SeamThickness", thickness);
                mat.SetFloat("_SeamFeather", feather);

                Blit(cmd, BuiltinRenderTextureType.None, BuiltinRenderTextureType.CameraTarget, mat);
            }
            context.ExecuteCommandBuffer(cmd);
            CommandBufferPool.Release(cmd);
        }
    }

    public Settings settings = new Settings();

    CapturePass terrainPass;
    CapturePass mountainPass;
    CompositePass compositePass;

    // Material to linearize depth (device -> linear eye depth)
    Material depthLinMat;

    public override void Create()
    {
        terrainPass = new CapturePass("Terrain", settings.terrainLayer, settings.captureEvent);
        mountainPass = new CapturePass("Mountain", settings.mountainLayer, settings.captureEvent);
        compositePass = new CompositePass(settings.compositeMaterial, settings.compositeEvent);

        depthLinMat = CoreUtils.CreateEngineMaterial(@"Shader \"Hidden/ContactBand/DepthToLinear\"{
SubShader{ Tags{ \"RenderType\"=\"Opaque\" } ZTest Always ZWrite Off Cull Off }
Pass{ HLSLPROGRAM
#pragma vertex Vert
#pragma fragment Frag
#include \"Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl\"
struct VSOut{ float4 pos:SV_POSITION; float2 uv:TEXCOORD0; };
VSOut Vert(uint id:SV_VertexID){ VSOut o; float2 uv=float2((id<<1)&2, id&2); o.pos=float4(uv*2-1,0,1); o.uv=uv; return o; }
TEXTURE2D_X_FLOAT(_CameraDepthTexture);
SAMPLER(sampler_CameraDepthTexture);
float4 Frag(VSOut i):SV_Target{ float d = SAMPLE_TEXTURE2D_X(_CameraDepthTexture, sampler_CameraDepthTexture, i.uv).r; float lin = LinearEyeDepth(d, _ZBufferParams); return float4(lin,0,0,1); }
ENDHLSL }
}
}");
    }

    public override void AddRenderPasses(ScriptableRenderer renderer, ref RenderingData renderingData)
    {
        var camDesc = renderingData.cameraData.cameraTargetDescriptor;
        terrainPass.Setup(camDesc, settings.colorFmt, settings.depthFmt, settings.width, settings.height);
        mountainPass.Setup(camDesc, settings.colorFmt, settings.depthFmt, settings.width, settings.height);

        renderer.EnqueuePass(terrainPass);
        renderer.EnqueuePass(mountainPass);

        // After both captures, linearize each pass's depth into its dedicated RFloat RTs
        var cmd = CommandBufferPool.Get("ContactBand_LinearizeDepth");
        using (new ProfilingScope(cmd, new ProfilingSampler("ContactBand_LinearizeDepth")))
        {
            // Blit the per-pass camera depth into each linear depth RT
            // First terrain
            cmd.SetGlobalTexture("_CameraDepthTexture", terrainPass.TempDepthId);
            Blit(cmd, terrainPass.TempDepthId, terrainPass.DepthLinRT, depthLinMat);
            // Then mountain
            cmd.SetGlobalTexture("_CameraDepthTexture", mountainPass.TempDepthId);
            Blit(cmd, mountainPass.TempDepthId, mountainPass.DepthLinRT, depthLinMat);
        }
        renderer.EnqueuePass(new ImmediateCmdPass(cmd));

        // Composite to camera target
        compositePass.Setup(terrainPass.ColorRT, terrainPass.DepthLinRT, mountainPass.ColorRT, mountainPass.DepthLinRT, settings.seamThickness, settings.seamFeather);
        renderer.EnqueuePass(compositePass);
    }

    class ImmediateCmdPass : ScriptableRenderPass
    {
        CommandBuffer _cmd;
        public ImmediateCmdPass(CommandBuffer cmd){ _cmd = cmd; renderPassEvent = RenderPassEvent.AfterRenderingOpaques; }
        public override void Execute(ScriptableRenderContext context, ref RenderingData renderingData)
        { context.ExecuteCommandBuffer(_cmd); _cmd.Clear(); }
        public override void OnCameraCleanup(CommandBuffer cmd){ CommandBufferPool.Release(_cmd); }
    }
}

Usage (URP):
- Create a Material from Hidden/ContactBand/Composite and assign to settings.compositeMaterial.
- Assign terrain/mountain layers in the feature.
- Add the feature to your URP Renderer Data.

C) Unity HDRP — FullScreen Custom Pass HLSL
- Use two DrawRenderers Custom Passes to fill TerrainColor/DepthLin and MountainColor/DepthLin (as set up earlier).
- Then a FullScreen Custom Pass with the same HLSL as ContactBandComposite.hlsl above (reuse the same shader). Bind your RTs to the material slots _TerrainColor, _MountainColor, _TerrainDepthLin, _MountainDepthLin and set _SeamThickness/_SeamFeather.
- In HDRP, linear eye depth is available via LoadCameraDepth/LinearEyeDepth helpers; ensure your two depth RTs are already linear or convert similarly before composite.

D) Unreal Engine 5 — Material setup for compositing
Goal: Given TerrainColorRT, TerrainDepthRT, MountainColorRT, MountainDepthRT (both depths linear and in the same space), build a Post-Process Material (Unlit, Post-Process domain) that picks front/back and applies the contact-band blend.

Nodes (UE5 Material Editor):
- TextureObjectParameter TerrainColor (Texture2D) -> TextureSample (Sampler: Linear Clamp) -> cT (RGB)
- TextureObjectParameter MountainColor -> TextureSample -> cM (RGB)
- TextureObjectParameter TerrainDepth (PF_R32_FLOAT) -> TextureSample -> zT (R)
- TextureObjectParameter MountainDepth -> TextureSample -> zM (R)
- Valid masks: vT = Step(0.0, zT) and vM = Step(0.0, zM); treat 0 as empty. In Material: compare GreaterThan(z, 0.0) using If node or > operator.
- Front test: tFront = (vT && (!vM || zT <= zM)). Build with If/Lerp: If(vT, If(1 - vM, 1, If(zT <= zM, 1, 0)), 0).
- cFront = Lerp(cM, cT, tFront); cBack = Lerp(cT, cM, tFront)  // swap via tFront
- zFront = Lerp(zM, zT, tFront); zBack = Lerp(zT, zM, tFront)
- dz = Abs(zFront - zBack); when back invalid (vBack = Lerp(vT, vM, 1 - tFront)), set dzHuge = 1e6: dz = Lerp(1e6, dz, vBack)
- Smooth band: s = saturate((dz - thickness) / max(feather - thickness, 1e-6)); w = 1 - (s*s*(3 - 2*s))
- color = Lerp(cFront, cBack, w)
- EmissiveColor = color; Opacity = 1 (or ignore in Post-Process)

Material parameters:
- thickness (Scalar), feather (Scalar) exposed to tweak.

Wiring hints:
- Use Texture Coordinates node (UV0) to sample all 4 RTs in screen space. If using SceneCapture2D RTs the UVs are normalized, so regular UV0 is fine when drawing to a full-screen quad. If sampling via Material Functions in Post-Process, use Customized UVs or ScreenAligned coords.
- Ensure Depth RTs are linear. If they are device depths, convert: Lin = ProjectionMatrix.M22 / (deviceDepth - ProjectionMatrix.M32) etc., or simpler, write linear depths directly in the capture materials.

E) Why this prevents color bleed
- Terrain and mountain are shaded in isolation into TerrainColor/MountainColor. The composite never reads the other set’s materials or lighting—only the final colors and their linear depths. Outside the contact band, only the nearest set is shown. Within the band, a shallow, controlled blend occurs, eliminating diffuse cross-contamination.

ASCII contact-band diagram
               Camera
                 \
Terrain surface -----====================----- Mountain surface
                  ^   contact band (blend)   ^
                  |                          |
             front-most wins           front-most wins

That’s it: plug the URP feature into your renderer, assign the two layers, and in UE5 bind the four RTs into the post-process material and place it in a global PostProcessVolume.

Concise explanation
The contact-band blend avoids color bleed by confining cross-object mixing to a thin depth gap where the terrain and mountain surfaces approach each other but do not intersect. We compute per-pixel front/back samples and a signed separation along view depth; only when that separation is within a small band do we interpolate between the two albedos. Outside the band, each object shows its own color exclusively, so the terrain never inherits the mountain’s diffuse (and vice versa) except in that narrow, controlled transition.

Unity URP/HDRP: full-screen HLSL composite (copy-paste)
// Expected textures (bound via material/global):
// _TerrainColor, _MountainColor : RGB albedo buffers (sRGB content)
// _TerrainDepth, _MountainDepth : linear eye-depth in meters (float)
// _BandCenter (x), _BandWidth (y), _Feather (z)
// If using URP/HDRP, ensure these are set as global textures and params.

CBUFFER_START(CompositeParams)
float3 _BandParams; // x=BandCenter, y=BandWidth, z=Feather
CBUFFER_END

TEXTURE2D(_TerrainColor);  SAMPLER(sampler_TerrainColor);
TEXTURE2D(_MountainColor); SAMPLER(sampler_MountainColor);
TEXTURE2D(_TerrainDepth);  SAMPLER(sampler_TerrainDepth);
TEXTURE2D(_MountainDepth); SAMPLER(sampler_MountainDepth);

struct VSIn  { float3 posOS:POSITION; float2 uv:TEXCOORD0; };
struct VSOut { float4 posCS:SV_Position; float2 uv:TEXCOORD0; };

VSOut VSFull(VSIn v){ VSOut o; o.posCS=float4(v.posOS.xy,0,1); o.uv=v.uv; return o; }

float SmoothBandWeight(float d, float center, float width, float feather)
{
    // Map separation d around center into [0,1] across width, feathered at edges
    float halfW = max(1e-6, width*0.5);
    float t = saturate(0.5 + (d - center)/(2.0*halfW));
    // Feather with smoothstep for softer transition
    float f = max(1e-6, feather);
    return smoothstep(0.0, f, t) * (1.0 - smoothstep(1.0 - f, 1.0, t));
}

float3 LinearFromSRGB(float3 c)
{
    // Approximate sRGB->linear
    return pow(max(c, 0.0.xxx), 2.2.xxx);
}

float3 SRGBFromLinear(float3 c)
{
    // Approximate linear->sRGB
    return pow(max(c, 0.0.xxx), 1.0/2.2.xxx);
}

float4 PSFull(VSOut i):SV_Target
{
    float2 uv = i.uv;

    // Sample inputs
    float3 terrSRGB = _TerrainColor.Sample(sampler_TerrainColor,   uv).rgb;
    float3 mounSRGB = _MountainColor.Sample(sampler_MountainColor, uv).rgb;
    float  dTerr    = _TerrainDepth.Sample(sampler_TerrainDepth,   uv).r; // linear eye depth
    float  dMoun    = _MountainDepth.Sample(sampler_MountainDepth, uv).r; // linear eye depth

    // Choose front/back by smaller positive depth
    bool  hasTerr = (dTerr > 0.0);
    bool  hasMoun = (dMoun > 0.0);
    float dFront = 0.0, dBack = 0.0;
    float3 colFrontSRGB = 0.0.xxx, colBackSRGB = 0.0.xxx;

    if (hasTerr && hasMoun)
    {
        bool terrFront = (dTerr <= dMoun);
        dFront = terrFront ? dTerr : dMoun;
        dBack  = terrFront ? dMoun : dTerr;
        colFrontSRGB = terrFront ? terrSRGB : mounSRGB;
        colBackSRGB  = terrFront ? mounSRGB : terrSRGB;
    }
    else if (hasTerr)
    {
        dFront = dTerr; dBack = 1e9; colFrontSRGB = terrSRGB; colBackSRGB = terrSRGB;
    }
    else if (hasMoun)
    {
        dFront = dMoun; dBack = 1e9; colFrontSRGB = mounSRGB; colBackSRGB = mounSRGB;
    }
    else
    {
        return float4(0,0,0,1);
    }

    // Separation and band weight
    float sep = dBack - dFront; // positive if two layers present
    float wBand = SmoothBandWeight(sep, _BandParams.x, _BandParams.y, _BandParams.z);

    // Convert to linear for correct blending
    float3 frontLin = LinearFromSRGB(colFrontSRGB);
    float3 backLin  = LinearFromSRGB(colBackSRGB);

    // Only blend within the narrow band; otherwise show the true front
    float useBlend = (sep < 1e8) ? wBand : 0.0; // if no back, no blend
    float3 outLin = lerp(frontLin, backLin, useBlend);

    return float4(SRGBFromLinear(outLin), 1);
}

// Minimal pass/technique stubs (URP/HDRP will bind via ScriptableRenderPass/CustomPass)
