UE5 material graph (copy-paste as node recipe)
Goal: Linearize scene depths for Terrain and Mountain, pick front/back per pixel, and apply contact-band blend.

Nodes and wiring:
- TextureObject (TerrainColor, sRGB), TextureObject (MountainColor, sRGB)
- TextureObject (TerrainDepth), TextureObject (MountainDepth)  // store linear eye depth in meters
- TextureSample TerrainColorSample (TerrainColor, sRGB on), UVs: ScreenAlignedUVs
- TextureSample MountainColorSample (MountainColor, sRGB on), UVs: ScreenAlignedUVs
- TextureSample TerrainDepthSample (TerrainDepth), Sampler: Point/Clamp, UVs: ScreenAlignedUVs
- TextureSample MountainDepthSample (MountainDepth), Sampler: Point/Clamp, UVs: ScreenAlignedUVs
- Linearize colors for blending:
  • ToLinearColor(TerrainColorSample.RGB) -> TerrLin
  • ToLinearColor(MountainColorSample.RGB) -> MounLin
- Determine availability:
  • HasTerr = > (TerrainDepthSample.R, 0)
  • HasMoun = > (MountainDepthSample.R, 0)
- Front/back selection:
  • TerrFront = <= (TerrainDepthSample.R, MountainDepthSample.R)
  • FrontLin = If(HasTerr & (TerrFront | !HasMoun), TerrLin, MounLin)
  • FrontD   = If(HasTerr & (TerrFront | !HasMoun), TerrainDepthSample.R, MountainDepthSample.R)
  • BackLin  = If(HasTerr & HasMoun, If(TerrFront, MounLin, TerrLin), FrontLin)
  • BackD    = If(HasTerr & HasMoun, If(TerrFront, MountainDepthSample.R, TerrainDepthSample.R), 1e9)
- Separation and band weight:
  • Sep = BackD - FrontD
  • Parameters: BandCenter (Scalar), BandWidth (Scalar>0), Feather (Scalar in [0,1])
  • HalfW = Max(BandWidth*0.5, 1e-6)
  • t = saturate(0.5 + (Sep - BandCenter) / (2*HalfW))
  • w0 = SmoothStep(0, Feather, t)
  • w1 = 1 - SmoothStep(1-Feather, 1, t)
  • wBand = w0 * w1
- Blended linear color:
  • UseBlend = If(Sep < 1e8, wBand, 0)
  • OutLin = Lerp(FrontLin, BackLin, UseBlend)
- Output:
  • BaseColor = ToSRGB(OutLin) or feed OutLin to BaseColor with Material set to Use Linear Color Space in project settings.
  • Opacity = 1

Notes:
- Ensure TerrainDepth and MountainDepth are linear eye-depth textures. If you only have device depth, first convert to linear depth using your projection parameters in a pre-pass.
- Band tuning: start with BandCenter=0, BandWidth=0.2m, Feather=0.2, then adjust.

URP renderer feature/pass to output linear depth RTs and invoke composite (copy-paste C#)
// Place in an Editor/Runtime assembly. Create two features: one to write depths, one to composite.
// Assumes you have two layers: Terrain layer and Mountain layer. Attach DepthTag component to those renderers or filter by layer masks.

using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

public class ContactBandCompositeFeature : ScriptableRendererFeature
{
    [System.Serializable]
    public class Settings
    {
        public LayerMask terrainMask;
        public LayerMask mountainMask;
        public Material depthWriteMat;   // simple shader that writes linear eye depth to color
        public Material compositeMat;    // material using the HLSL composite above
        public float bandCenter = 0f;
        public float bandWidth = 0.2f;
        public float feather = 0.2f;
    }

    class DepthPass : ScriptableRenderPass
    {
        readonly string m_ProfilerTag;
        FilteringSettings m_Filtering;
        ShaderTagId m_ShaderTag = new ShaderTagId("DepthOnly");
        RenderTargetHandle m_Target;
        Material m_Mat;
        RenderStateBlock m_State;

        public DepthPass(string tag, LayerMask mask, Material mat, RenderTargetHandle target)
        {
            m_ProfilerTag = tag;
            renderPassEvent = RenderPassEvent.AfterRenderingPrePasses;
            m_Filtering = new FilteringSettings(RenderQueueRange.opaque, mask);
            m_Mat = mat;
            m_Target = target;
            m_State = new RenderStateBlock(RenderStateMask.Depth)
            {
                depthState = new DepthState(true, CompareFunction.LessEqual)
            };
        }

        public override void OnCameraSetup(CommandBuffer cmd, ref RenderingData renderingData)
        {
            var desc = renderingData.cameraData.cameraTargetDescriptor;
            desc.colorFormat = RenderTextureFormat.RFloat;
            desc.depthBufferBits = 0;
            cmd.GetTemporaryRT(m_Target.id, desc, FilterMode.Point);
            ConfigureTarget(m_Target.Identifier());
            ConfigureClear(ClearFlag.All, Color.clear);
        }

        public override void Execute(ScriptableRenderContext context, ref RenderingData renderingData)
        {
            var cmd = CommandBufferPool.Get(m_ProfilerTag);
            using (new ProfilingScope(cmd, new ProfilingSampler(m_ProfilerTag)))
            {
                var draw = CreateDrawingSettings(m_ShaderTag, ref renderingData, SortingCriteria.CommonOpaque);
                draw.overrideMaterial = m_Mat; // writes linear depth to color.R
                context.ExecuteCommandBuffer(cmd); cmd.Clear();
                context.DrawRenderers(renderingData.cullResults, ref draw, ref m_Filtering, ref m_State);
            }
            context.ExecuteCommandBuffer(cmd);
            CommandBufferPool.Release(cmd);
        }

        public override void OnCameraCleanup(CommandBuffer cmd)
        {
            if (cmd == null) return;
            cmd.ReleaseTemporaryRT(m_Target.id);
        }
    }

    class CompositePass : ScriptableRenderPass
    {
        readonly string m_ProfilerTag = "ContactBandComposite";
        Material m_Mat;
        RenderTargetHandle m_TerrainDepth;
        RenderTargetHandle m_MountainDepth;
        int _TerrainDepthID = Shader.PropertyToID("_TerrainDepth");
        int _MountainDepthID = Shader.PropertyToID("_MountainDepth");
        int _BandParamsID = Shader.PropertyToID("_BandParams");

        public CompositePass(Material mat, RenderTargetHandle terr, RenderTargetHandle moun)
        {
            renderPassEvent = RenderPassEvent.AfterRenderingTransparents;
            m_Mat = mat;
            m_TerrainDepth = terr;
            m_MountainDepth = moun;
        }

        public override void Execute(ScriptableRenderContext context, ref RenderingData renderingData)
        {
            var cmd = CommandBufferPool.Get(m_ProfilerTag);
            using (new ProfilingScope(cmd, new ProfilingSampler(m_ProfilerTag)))
            {
                // Bind depth RTs for the shader
                cmd.SetGlobalTexture(_TerrainDepthID, m_TerrainDepth.Identifier());
                cmd.SetGlobalTexture(_MountainDepthID, m_MountainDepth.Identifier());

                // Terrain/Mountain color inputs are assumed rendered to camera color already, or bind custom if needed
                var camDesc = renderingData.cameraData.cameraTargetDescriptor;
                Blit(cmd, source: BuiltinRenderTextureType.CameraTarget, destination: BuiltinRenderTextureType.CameraTarget, m_Mat);
            }
            context.ExecuteCommandBuffer(cmd);
            CommandBufferPool.Release(cmd);
        }
    }

    public Settings settings = new Settings();
    RenderTargetHandle m_TerrainDepth;
    RenderTargetHandle m_MountainDepth;
    DepthPass m_TerrainPass;
    DepthPass m_MountainPass;
    CompositePass m_CompositePass;

    public override void Create()
    {
        m_TerrainDepth.Init("_TerrainDepthRT");
        m_MountainDepth.Init("_MountainDepthRT");

        m_TerrainPass = new DepthPass("TerrainDepthPass", settings.terrainMask, settings.depthWriteMat, m_TerrainDepth);
        m_MountainPass = new DepthPass("MountainDepthPass", settings.mountainMask, settings.depthWriteMat, m_MountainDepth);
        m_CompositePass = new CompositePass(settings.compositeMat, m_TerrainDepth, m_MountainDepth);
    }

    public override void AddRenderPasses(ScriptableRenderer renderer, ref RenderingData renderingData)
    {
        // Push band params
        Shader.SetGlobalVector("_BandParams", new Vector4(settings.bandCenter, settings.bandWidth, settings.feather, 0));

        renderer.EnqueuePass(m_TerrainPass);
        renderer.EnqueuePass(m_MountainPass);
        renderer.EnqueuePass(m_CompositePass);
    }
}

Depth writer shader (copy-paste minimal)
// Tagged with "DepthOnly" pass name so the DepthPass can drive it; writes linear eye depth to R.
Shader "Hidden/WriteLinearDepth"
{
    SubShader
    {
        Tags { "RenderType"="Opaque" }
        Pass
        {
            Name "DepthOnly"
            ZWrite On ZTest LEqual Cull Back
            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            struct Attributes { float4 positionOS:POSITION; };
            struct Varyings  { float4 positionCS:SV_Position; float  eyeZ:TEXCOORD0; };

            Varyings vert(Attributes v)
            {
                Varyings o;
                o.positionCS = TransformObjectToHClip(v.positionOS.xyz);
                float3 ws = TransformObjectToWorld(v.positionOS.xyz);
                float3 vs = TransformWorldToView(ws);
                o.eyeZ = -vs.z; // meters
                return o;
            }

            half4 frag(Varyings i):SV_Target { return half4(i.eyeZ,0,0,1); }
            ENDHLSL
        }
    }
}

Usage notes
- Render terrain and mountain normally into the camera color buffer (or separate color RTs if preferred), while the two depth passes write linear depth into _TerrainDepth and _MountainDepth.
- The composite pass samples both colors and depths, selects the front surface per pixel, and blends only when the depth separation lies within the contact band, eliminating unwanted color diffusion.
- Tune _BandParams = (center, width, feather) for a tight, artifact-free seam.

