// Utility: Log last error text
string LastErr()
{
   int e = GetLastError();
   ResetLastError();
   return(IntegerToString(e) + ": " + ErrorDescription(e));
}

// Utility: split hours list
bool IsHourSkipped(int utchour)
{
   if(StringLen(InpSkipHoursUTC)==0) return(false);
   string parts[];
   int n = StringSplit(InpSkipHoursUTC, ',', parts);
   for(int i=0;i<n;i++)
   {
      int h = (int)StringToInteger(StringTrim(parts[i]));
      if(h==utchour) return(true);
   }
   return(false);
}

// Utility: round volume to step and bounds
double NormalizeVolume(double vol)
{
   if(vol<gMinVolume) vol = gMinVolume;
   if(vol>gMaxVolume) vol = gMaxVolume;
   if(gVolStep>0)
   {
      double steps = MathFloor((vol - gMinVolume + 1e-12)/gVolStep);
      vol = gMinVolume + steps*gVolStep;
      // fallback if rounding pushed below min
      if(vol < gMinVolume) vol = gMinVolume;
   }
   return(NormalizeDouble(vol, 2));
}

// Check one-position-per-symbol for our magic number
bool HasOpenPosition()
{
   for(int i=PositionsTotal()-1;i>=0;i--)
   {
      ulong ticket = PositionGetTicket(i);
      if(ticket==0) continue;
      if(!PositionSelectByTicket(ticket)) continue;
      if(PositionGetString(POSITION_SYMBOL)==gSymbol && PositionGetInteger(POSITION_MAGIC)==(long)InpMagicNumber)
         return(true);
   }
   return(false);
}

// Calculate signal on last closed bar
int GetSignal()
{
   // 1 = buy, -1 = sell, 0 = none
   if(ArraySize(rates)<3) return(0);
   int idx = 1; // last closed bar index in iTimeframe series buffers

   double f_prev = fastEMA[idx+1];
   double s_prev = slowEMA[idx+1];
   double f_now  = fastEMA[idx];
   double s_now  = slowEMA[idx];
   double r_now  = rsi[idx];
   double atr_now= atr[idx];

   if(InpATR_MinFilter>0.0 && atr_now < InpATR_MinFilter)
      return(0);

   bool bullCross = (f_prev <= s_prev) && (f_now > s_now) && (r_now >= InpRSI_Buy);
   bool bearCross = (f_prev >= s_prev) && (f_now < s_now) && (r_now <= InpRSI_Sell);

   if(bullCross) return(1);
   if(bearCross) return(-1);
   return(0);
}

// Compute position size by equity risk and per-trade margin caps
bool ComputeVolume(int direction, double entryPrice, double slPrice, double &outVol)
{
   outVol = 0.0;
   double equity      = AccountInfoDouble(ACCOUNT_EQUITY);
   double freeMargin  = AccountInfoDouble(ACCOUNT_FREEMARGIN);
   double marginLevel = AccountInfoDouble(ACCOUNT_MARGIN_LEVEL); // percent

   if(InpMinMarginLevelPct>0.0 && marginLevel>0.0 && marginLevel < InpMinMarginLevelPct)
   {
      Print("[Risk] Margin level too low ", DoubleToString(marginLevel,2), "% < ", DoubleToString(InpMinMarginLevelPct,2), "%");
      return(false);
   }

   double riskMoney = equity * (InpRiskPerTradePct/100.0);
   if(riskMoney <= 0.0)
   {
      Print("[Risk] riskMoney computed <= 0");
      return(false);
   }

   double stopDistance = MathAbs(entryPrice - slPrice);
   if(stopDistance <= gPoint*0.5)
   {
      Print("[Risk] Stop distance too small: ", DoubleToString(stopDistance, gDigits));
      return(false);
   }

   // Pip/point value per 1 lot
   double contractSize = SymbolInfoDouble(gSymbol, SYMBOL_TRADE_CONTRACT_SIZE);
   if(contractSize<=0) contractSize = 100000.0;

   // Approximate tick value per lot
   double tv = 0.0; SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_VALUE, tv);
   double ts = 0.0; SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_SIZE, ts);
   if(tv<=0 || ts<=0) { tv = gTickValue; ts = gTickSize; }
   if(tv<=0 || ts<=0)
   {
      Print("[Risk] Invalid tick value/size");
      return(false);
   }

   double valuePerPointPerLot = tv * (gPoint/ts); // monetary value per point for 1 lot
   if(valuePerPointPerLot<=0)
   {
      Print("[Risk] valuePerPointPerLot invalid");
      return(false);
   }

   double stopPoints = stopDistance / gPoint;
   double moneyPerLotAtSL = stopPoints * valuePerPointPerLot;
   if(moneyPerLotAtSL<=0)
   {
      Print("[Risk] moneyPerLotAtSL invalid");
      return(false);
   }

   double volByRisk = riskMoney / moneyPerLotAtSL;

   // Enforce free margin usage cap via OrderCalcMargin iterative reduction
   double maxMarginUse = freeMargin * (InpMaxFreeMarginUsagePct/100.0);
   double testVol = MathMin(volByRisk, gMaxVolume);
   testVol = MathMax(testVol, gMinVolume);
   testVol = NormalizeVolume(testVol);

   double needMargin=0.0;
   for(int i=0;i<20;i++) // try reduce to fit cap
   {
      if(testVol < gMinVolume-1e-9) break;
      if(!OrderCalcMargin((direction>0)?ORDER_TYPE_BUY:ORDER_TYPE_SELL, gSymbol, testVol, entryPrice, needMargin))
      {
         Print("[Risk] OrderCalcMargin failed: ", LastErr());
         return(false);
      }
      if(needMargin <= maxMarginUse) break;
      testVol = NormalizeVolume(testVol - gVolStep);
   }

   if(testVol < gMinVolume-1e-9)
   {
      Print("[Risk] Volume too small after margin cap. needMargin=", DoubleToString(needMargin,2), " cap=", DoubleToString(maxMarginUse,2));
      return(false);
   }

   // Ensure free margin after reserving required margin remains positive
   if(needMargin > freeMargin)
   {
      Print("[Risk] Not enough free margin. need=", DoubleToString(needMargin,2), " free=", DoubleToString(freeMargin,2));
      return(false);
   }

   outVol = NormalizeVolume(testVol);
   return(outVol>=gMinVolume);
}

// Place order with SL/TP
bool PlaceEntry(int direction, double entry, double sl, double tp, double volume)
{
   trade.SetExpertMagicNumber((long)InpMagicNumber);
   trade.SetDeviationInPoints(InpSlippagePoints);

   bool ok=false;
   if(direction>0)
      ok = trade.Buy(volume, gSymbol, entry, sl, tp);
   else
      ok = trade.Sell(volume, gSymbol, entry, sl, tp);

   if(!ok)
   {
      Print("[Trade] Order send failed: ", trade.ResultRetcode(), " ", trade.ResultRetcodeDescription());
      return(false);
   }
   Print("[Trade] Opened ", (direction>0?"BUY":"SELL"), " vol=", DoubleToString(volume,2), " entry=", DoubleToString(entry,gDigits),
         " SL=", DoubleToString(sl,gDigits), " TP=", DoubleToString(tp,gDigits), " ticket=", (long)trade.ResultOrder());
   return(true);
}

// Manage existing position: breakeven + trailing SL
void ManagePosition()
{
   if(!HasOpenPosition()) return;
   if(!PositionSelect(gSymbol)) return;

   long   type   = PositionGetInteger(POSITION_TYPE);
   double vol    = PositionGetDouble(POSITION_VOLUME);
   double price  = PositionGetDouble(POSITION_PRICE_OPEN);
   double sl     = PositionGetDouble(POSITION_SL);
   double tp     = PositionGetDouble(POSITION_TP);
   double curBid = SymbolInfoDouble(gSymbol, SYMBOL_BID);
   double curAsk = SymbolInfoDouble(gSymbol, SYMBOL_ASK);

   // Recompute ATR for trailing
   double atr_now = atr[1];
   double trailDist = InpATR_TrailMult * atr_now;
   if(trailDist < gPoint*2) trailDist = gPoint*2;

   // Breakeven logic
   double rr_now=0.0;
   if(type==POSITION_TYPE_BUY)
   {
      double risk = price - sl; if(risk<=0) risk = InpATR_SL_Mult*atr_now;
      rr_now = (curBid - price) / risk;
      if(InpBreakevenRR>0 && rr_now >= InpBreakevenRR)
      {
         double beSL = price + gPoint* (gStopsLevelPoints+1);
         if(sl < beSL)
         {
            trade.PositionModify(gSymbol, beSL, tp);
         }
      }
      if(InpAllowTrailing)
      {
         double newSL = curBid - trailDist;
         double minAllowed = price + gPoint*(gStopsLevelPoints+1);
         if(newSL > sl && newSL > minAllowed)
            trade.PositionModify(gSymbol, newSL, tp);
      }
   }
   else if(type==POSITION_TYPE_SELL)
   {
      double risk = sl - price; if(risk<=0) risk = InpATR_SL_Mult*atr_now;
      rr_now = (price - curAsk) / risk;
      if(InpBreakevenRR>0 && rr_now >= InpBreakevenRR)
      {
         double beSL = price - gPoint*(gStopsLevelPoints+1);
         if(sl == 0 || sl > beSL)
         {
            trade.PositionModify(gSymbol, beSL, tp);
         }
      }
      if(InpAllowTrailing)
      {
         double newSL = curAsk + trailDist;
         double maxAllowed = price - gPoint*(gStopsLevelPoints+1);
         if((sl==0 || newSL < sl) && newSL < maxAllowed)
            trade.PositionModify(gSymbol, newSL, tp);
      }
   }
}

//========================
// OnInit: create indicators, cache symbol info
//========================
int OnInit()
{
   gSymbol = _Symbol;

   if(!SymbolSelect(gSymbol, true))
   {
      Print("[Init] Failed to select symbol: ", gSymbol, " ", LastErr());
      return(INIT_FAILED);
   }

   gPoint  = SymbolInfoDouble(gSymbol, SYMBOL_POINT);
   gDigits = (int)SymbolInfoInteger(gSymbol, SYMBOL_DIGITS);
   gTickSize  = SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_SIZE);
   gTickValue = SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_VALUE);
   gMinVolume = SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_MIN);
   gMaxVolume = SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_MAX);
   gVolStep   = SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_STEP);
   gStopsLevelPoints = (int)SymbolInfoInteger(gSymbol, SYMBOL_TRADE_STOPS_LEVEL);

   if(gPoint<=0 || gMinVolume<=0 || gVolStep<=0)
   {
      Print("[Init] Invalid symbol parameters. point=", gPoint, " minVol=", gMinVolume, " volStep=", gVolStep);
      return(INIT_FAILED);
   }

   // Create indicators
   hFastEMA = iMA(gSymbol, InpTimeframe, InpFastEMA, 0, MODE_EMA, PRICE_CLOSE);
   hSlowEMA = iMA(gSymbol, InpTimeframe, InpSlowEMA, 0, MODE_EMA, PRICE_CLOSE);
   hRSI     = iRSI(gSymbol, InpTimeframe, InpRSIPeriod, PRICE_CLOSE);
   hATR     = iATR(gSymbol, InpTimeframe, InpATRPeriod);

   if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
   {
      Print("[Init] Indicator handle creation failed: ", LastErr());
      return(INIT_FAILED);
   }

   // Preload buffers
   ArraySetAsSeries(rates, true);
   ArraySetAsSeries(fastEMA, true);
   ArraySetAsSeries(slowEMA, true);
   ArraySetAsSeries(rsi, true);
   ArraySetAsSeries(atr, true);

   if(!RefreshRates())
      Print("[Init] RefreshRates failed");

   Print("[Init] EA initialized on ", gSymbol, " TF=", EnumToString(InpTimeframe));
   return(INIT_SUCCEEDED);
}

//========================
// OnDeinit: release indicators
//========================
void OnDeinit(const int reason)
{
   if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
   if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
   if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
   if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);
}

//========================
// OnTick: filters, signals, orders, management
//========================
void OnTick()
{
   if(_StopFlag) return;

   // Spread filter
   double ask = SymbolInfoDouble(gSymbol, SYMBOL_ASK);
   double bid = SymbolInfoDouble(gSymbol, SYMBOL_BID);
   if(ask<=0 || bid<=0) return;
   int spreadPoints = (int)((ask - bid)/gPoint + 0.5);
   if(spreadPoints > InpMaxSpreadPoints)
   {
      // too wide
      return;
   }

   // Session/hour filter (UTC)
   datetime now = TimeCurrent();
   MqlDateTime t; TimeToStruct(now, t);
   if(IsHourSkipped(t.hour))
      return;

   // Load market data for signal timeframe
   if(CopyRates(gSymbol, InpTimeframe, 0, 100, rates) < 50) return;

   // Update indicator buffers
   if(CopyBuffer(hFastEMA, 0, 0, 100, fastEMA) < 50) return;
   if(CopyBuffer(hSlowEMA, 0, 0, 100, slowEMA) < 50) return;
   if(CopyBuffer(hRSI,     0, 0, 100, rsi)     < 50) return;
   if(CopyBuffer(hATR,     0, 0, 100, atr)     < 50) return;

   // Trade only on a new closed bar
   datetime barTime = rates[1].time;
   if(barTime == lastClosedBarTime)
   {
      // Still manage existing position every tick
      ManagePosition();
      return;
   }

   lastClosedBarTime = barTime;

   // Manage any open position on new bar as well
   ManagePosition();

   // One-position-per-symbol
   if(HasOpenPosition()) return;

   // Generate signal
   int sig = GetSignal();
   if(sig==0) return;

   // Compute SL/TP based on ATR
   double atr_now = atr[1];
   double slDist  = InpATR_SL_Mult * atr_now;
   if(slDist < gPoint * (gStopsLevelPoints+1))
      slDist = gPoint * (gStopsLevelPoints+1);

   double entry = (sig>0) ? ask : bid;
   double sl    = 0.0;
   double tp    = 0.0;

   if(sig>0)
   {
      sl = entry - slDist;
      tp = entry + InpRR * slDist;
   }
   else
   {
      sl = entry + slDist;
      tp = entry - InpRR * slDist;
   }

   // Price normalization
   sl = NormalizeDouble(sl, gDigits);
   tp = NormalizeDouble(tp, gDigits);
   entry = NormalizeDouble(entry, gDigits);

   // Risk sizing and margin checks
   double volume=0.0;
   if(!ComputeVolume(sig, entry, sl, volume))
   {
      Print("[Risk] Volume computation failed; skipping trade");
      return;
   }

   // Final sanity: ensure stops respect stops level
   if(gStopsLevelPoints>0)
   {
      if(sig>0)
      {
         if((entry - sl) < (gStopsLevelPoints+1)*gPoint) sl = entry - (gStopsLevelPoints+1)*gPoint;
         if((tp - entry) < (gStopsLevelPoints+1)*gPoint) tp = entry + (gStopsLevelPoints+1)*gPoint;
      }
      else
      {
         if((sl - entry) < (gStopsLevelPoints+1)*gPoint) sl = entry + (gStopsLevelPoints+1)*gPoint;
         if((entry - tp) < (gStopsLevelPoints+1)*gPoint) tp = entry - (gStopsLevelPoints+1)*gPoint;
      }
      sl = NormalizeDouble(sl, gDigits);
      tp = NormalizeDouble(tp, gDigits);
   }

   // Place order
   PlaceEntry(sig, entry, sl, tp, volume);
}

