bool GetIndicatorValues(const string sym, double &emaFastPrev, double &emaSlowPrev, double &emaFastCurr, double &emaSlowCurr, double &rsiCurr, double &atrCurr)
{
  double b1[3], b2[3], r[3], a[3];
  ArraySetAsSeries(b1,true); ArraySetAsSeries(b2,true); ArraySetAsSeries(r,true); ArraySetAsSeries(a,true);
  if(CopyBuffer(hFastEMA,0,0,3,b1)<3) return false;
  if(CopyBuffer(hSlowEMA,0,0,3,b2)<3) return false;
  if(CopyBuffer(hRSI,   0,0,2,r)<2)   return false;
  if(CopyBuffer(hATR,   0,0,2,a)<2)   return false;

  emaFastCurr = b1[0];
  emaSlowCurr = b2[0];
  emaFastPrev = b1[1];
  emaSlowPrev = b2[1];
  rsiCurr     = r[0];
  atrCurr     = a[0];
  return true;
}

//========================
// Risk/Margin: compute volume from equity risk and cap by margin usage
//========================
bool ComputeTradeParameters(const string sym, const bool isBuy, const double atr, double &volumeOut, double &slPriceOut, double &tpPriceOut)
{
  MqlTick tick; if(!SymbolInfoTick(sym,tick)) { Print("[RISK] No tick"); return false; }

  // Stop distance based on ATR
  double stopDist = MathMax(atr * InpATR_SL_Mult, gStopsLevelPoints * gPoint);
  if(stopDist <= 0.0)
  {
    Print("[RISK] Invalid stop distance.");
    return false;
  }

  double entry = isBuy ? tick.ask : tick.bid;
  double sl    = isBuy ? entry - stopDist : entry + stopDist;
  double tp    = isBuy ? entry + (stopDist * InpRR) : entry - (stopDist * InpRR);

  // Respect freeze/stops levels
  double minStop = gStopsLevelPoints * gPoint;
  if(isBuy)
  {
    if((entry - sl) < minStop) sl = entry - minStop;
    if((tp - entry) < minStop) tp = entry + minStop;
  }
  else
  {
    if((sl - entry) < minStop) sl = entry + minStop;
    if((entry - tp) < minStop) tp = entry - minStop;
  }

  sl = NormalizePrice(sl);
  tp = NormalizePrice(tp);

  // Equity-based risk sizing: risk = InpRiskPerTradePct% of equity
  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  double riskCash = equity * (InpRiskPerTradePct/100.0);
  if(riskCash <= 0)
  {
    Print("[RISK] Equity or risk % invalid.");
    return false;
  }

  double stopInPrice = MathAbs(entry - sl);
  if(stopInPrice <= 0)
  {
    Print("[RISK] Stop distance is zero.");
    return false;
  }

  // value per point per lot
  double pointValuePerLot = (gTickValue / gTickSize) * gPoint; // money per point for 1 lot
  if(pointValuePerLot <= 0)
  {
    Print("[RISK] Invalid point value per lot.");
    return false;
  }

  double stopPoints = stopInPrice / gPoint;
  double moneyPerLotAtStop = stopPoints * pointValuePerLot;
  if(moneyPerLotAtStop <= 0)
  {
    Print("[RISK] Invalid money per lot at stop.");
    return false;
  }

  double volFromRisk = riskCash / moneyPerLotAtStop;
  double vol = NormalizeVolume(volFromRisk);
  if(vol <= 0)
  {
    PrintFormat("[RISK] Computed volume too small. volFromRisk=%.6f", volFromRisk);
    return false;
  }

  // Margin usage cap: require margin for vol not to exceed % of free margin
  double freeMargin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  double maxUse = freeMargin * (InpMaxFreeMarginUsagePct/100.0);
  double needMargin=0.0;
  if(!OrderCalcMargin(isBuy?ORDER_TYPE_BUY:ORDER_TYPE_SELL, sym, vol, entry, needMargin))
  {
    Print("[RISK] OrderCalcMargin failed. Err=",GetLastError());
    return false;
  }

  if(needMargin > maxUse)
  {
    // scale down proportionally
    double scale = (maxUse/needMargin);
    double volCapped = NormalizeVolume(vol * scale);
    if(volCapped < gMinVolume)
    {
      PrintFormat("[RISK] Margin cap reduces volume below min. needMargin=%.2f maxUse=%.2f scale=%.4f", needMargin, maxUse, scale);
      return false;
    }
    // Recalc margin for new vol to ensure feasible
    double needMargin2=0.0;
    if(!OrderCalcMargin(isBuy?ORDER_TYPE_BUY:ORDER_TYPE_SELL, sym, volCapped, entry, needMargin2))
    {
      Print("[RISK] OrderCalcMargin (capped) failed. Err=",GetLastError());
      return false;
    }
    if(needMargin2 > freeMargin)
    {
      PrintFormat("[RISK] Not enough free margin even after cap. need=%.2f free=%.2f", needMargin2, freeMargin);
      return false;
    }
    vol = volCapped;
  }

  // Margin level validation (if available)
  double ml = GetMarginLevelPct();
  if(InpMinMarginLevelPct>0.0 && ml>0.0 && ml < InpMinMarginLevelPct)
  {
    PrintFormat("[RISK] Margin level %.2f%% below minimum %.2f%%. Skip.", ml, InpMinMarginLevelPct);
    return false;
  }

  volumeOut   = vol;
  slPriceOut  = sl;
  tpPriceOut  = tp;
  return true;
}

//========================
// Signal generation (EMA cross with RSI and ATR filter)
//========================
int GetSignal(const string sym, const double emaFastPrev, const double emaSlowPrev, const double emaFastCurr, const double emaSlowCurr, const double rsi, const double atr)
{
  if(InpATR_MinFilter>0.0 && atr < InpATR_MinFilter) return 0; // too quiet
  bool crossUp   = (emaFastPrev <= emaSlowPrev) && (emaFastCurr > emaSlowCurr);
  bool crossDown = (emaFastPrev >= emaSlowPrev) && (emaFastCurr < emaSlowCurr);

  if(crossUp && rsi >= InpRSI_Buy)  return 1;  // buy
  if(crossDown && rsi <= InpRSI_Sell) return -1; // sell
  return 0;
}

//========================
// Entry conditions: spread and session filters
//========================
bool CanTradeNow(const string sym)
{
  // Market availability
  if(!SymbolInfoInteger(sym, SYMBOL_TRADING_ALLOWED)) { Print("[FILTER] Trading not allowed for symbol."); return false; }

  // Spread filter
  double spreadPts = CurrentSpreadPoints(sym);
  if(spreadPts==DBL_MAX) { Print("[FILTER] No tick for spread."); return false; }
  if(InpMaxSpreadPoints>0 && spreadPts > InpMaxSpreadPoints)
  {
    PrintFormat("[FILTER] Spread %.1f pts exceeds max %d pts.", spreadPts, InpMaxSpreadPoints);
    return false;
  }

  // Session filter by UTC hour
  datetime now = TimeCurrent();
  MqlDateTime dt; TimeToStruct(now, dt);
  int hourUTC = dt.hour; // TimeCurrent is server time; assume server=UTC for safety, or adapt externally
  if(hourUTC>=0 && hourUTC<24 && gSkipHour[hourUTC])
  {
    PrintFormat("[FILTER] Hour %d is blocked by session filter.", hourUTC);
    return false;
  }

  return true;
}

//========================
// Place order with full error handling
//========================
bool PlaceTrade(const string sym, const bool isBuy, const double volume, const double sl, const double tp)
{
  MqlTick tick; if(!SymbolInfoTick(sym,tick)) { Print("[TRADE] No tick."); return false; }
  double price = isBuy ? tick.ask : tick.bid;

  trade.SetExpertMagicNumber(InpMagicNumber);
  trade.SetDeviationInPoints(InpSlippagePoints);

  bool ok = isBuy ? trade.Buy(volume, sym, price, sl, tp, "EMA_RSI_ATR buy")
                  : trade.Sell(volume, sym, price, sl, tp, "EMA_RSI_ATR sell");
  if(!ok)
  {
    PrintFormat("[TRADE] Order send failed. ret=%d err=%d desc=%s", (int)ok, GetLastError(), trade.ResultRetcodeDescription());
    return false;
  }
  PrintFormat("[TRADE] %s placed: vol=%.2f price=%.5f SL=%.5f TP=%.5f ticket=%I64u",
              isBuy?"BUY":"SELL", volume, price, sl, tp, trade.ResultOrder());
  return true;
}

//========================
// Manage open position: breakeven and trailing stop by ATR
//========================
void ManagePosition(const string sym, const long type, const double entry, double &sl, double &tp)
{
  if(!InpAllowTrailing) return;

  double atr[2]; ArraySetAsSeries(atr,true);
  if(CopyBuffer(hATR,0,0,2,atr)<2) return;
  double atrVal = atr[0];
  if(atrVal<=0) return;

  double trailDist = MathMax(atrVal*InpATR_TrailMult, gStopsLevelPoints*gPoint);

  MqlTick tick; if(!SymbolInfoTick(sym,tick)) return;
  double bid=tick.bid, ask=tick.ask;

  // Breakeven move
  if(InpBreakevenRR>0.0)
  {
    double bePriceBuy  = entry + (atrVal*InpATR_SL_Mult*InpBreakevenRR);
    double bePriceSell = entry - (atrVal*InpATR_SL_Mult*InpBreakevenRR);
    if(type==POSITION_TYPE_BUY && bid>bePriceBuy)
    {
      double newSL = MathMax(sl, entry);
      newSL = NormalizePrice(newSL);
      if(newSL>sl) { trade.PositionModify(sym, newSL, tp); sl=newSL; }
    }
    else if(type==POSITION_TYPE_SELL && ask<bePriceSell)
    {
      double newSL = MathMin(sl, entry);
      newSL = NormalizePrice(newSL);
      if(newSL<sl || sl==0.0) { trade.PositionModify(sym, newSL, tp); sl=newSL; }
    }
  }

  // ATR trailing
  if(type==POSITION_TYPE_BUY)
  {
    double desiredSL = NormalizePrice(bid - trailDist);
    if(desiredSL>sl && (bid - desiredSL) >= gStopsLevelPoints*gPoint)
    {
      if(trade.PositionModify(sym, desiredSL, tp)) sl = desiredSL;
    }
  }
  else if(type==POSITION_TYPE_SELL)
  {
    double desiredSL = NormalizePrice(ask + trailDist);
    if((sl==0.0 || desiredSL<sl) && (desiredSL - ask) >= gStopsLevelPoints*gPoint)
    {
      if(trade.PositionModify(sym, desiredSL, tp)) sl = desiredSL;
    }
  }
}

//========================
// Lifecycle
//========================
int OnInit()
{
  const string sym = _Symbol;
  if(!RefreshSymbolInfo(sym)) return(INIT_FAILED);
  if(!IndicatorsCreate(sym))  return(INIT_FAILED);
  ParseSkipHours(InpSkipHoursUTC);
  Print("[INIT] Ready on ", sym, " TF=", (int)InpTimeframe);
  return(INIT_SUCCEEDED);
}

void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);
}

void OnTick()
{
  const string sym = _Symbol;
  if(!RefreshSymbolInfo(sym)) return;

  // Ensure indicators exist
  if(!IndicatorsCreate(sym)) return;

  // Work on bar close to avoid noise
  datetime barTime = iTime(sym, InpTimeframe, 0);
  if(barTime==0) return;
  if(gLastClosedBarTime == 0) gLastClosedBarTime = barTime;

  // Manage existing position every tick
  ulong tk; long ptype; double popen, psl, ptp, pvol;
  if(GetOurPosition(sym, tk, ptype, popen, psl, ptp, pvol))
  {
    ManagePosition(sym, ptype, popen, psl, ptp);
  }

  // Only evaluate new entries on a new closed bar
  if(barTime == gLastClosedBarTime) return;
  gLastClosedBarTime = barTime;

  // One-position-per-symbol (any magic)
  if(HasAnyPositionOnSymbol(sym))
  {
    Print("[FILTER] Position already open on symbol. Skipping new entry.");
    return;
  }

  if(!CanTradeNow(sym)) return;

  // Read indicators
  double emaFPrev, emaSPrev, emaFCurr, emaSCurr, rsi, atr;
  if(!GetIndicatorValues(sym, emaFPrev, emaSPrev, emaFCurr, emaSCurr, rsi, atr))
  {
    Print("[SIG] Failed to get indicator values.");
    return;
  }

  int sig = GetSignal(sym, emaFPrev, emaSPrev, emaFCurr, emaSCurr, rsi, atr);
  if(sig==0) return;

  // Compute volume and protective levels with full margin checks
  bool isBuy = (sig>0);
  double vol=0, sl=0, tp=0;
  if(!ComputeTradeParameters(sym, isBuy, atr, vol, sl, tp))
  {
    // Detailed reason already printed in ComputeTradeParameters
    return;
  }

  // Final free-margin and margin-level validations before send
  double freeMargin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  double needMargin=0.0; MqlTick t; SymbolInfoTick(sym,t);
  if(!OrderCalcMargin(isBuy?ORDER_TYPE_BUY:ORDER_TYPE_SELL, sym, vol, isBuy?t.ask:t.bid, needMargin))
  {
    Print("[CHECK] OrderCalcMargin before send failed. Err=", GetLastError());
    return;
  }
  if(needMargin > freeMargin)
  {
    PrintFormat("[CHECK] Not enough free margin. need=%.2f free=%.2f", needMargin, freeMargin);
    return;
  }
  double ml = GetMarginLevelPct();
  if(InpMinMarginLevelPct>0.0 && ml>0.0 && ml < InpMinMarginLevelPct)
  {
    PrintFormat("[CHECK] Margin level %.2f%% below minimum %.2f%%. Abort.", ml, InpMinMarginLevelPct);
    return;
  }

  // Place order
  if(!PlaceTrade(sym, isBuy, vol, sl, tp))
    return;
}

//+------------------------------------------------------------------+
//|                                         EMA_RSI_ATR_Manager.mq5  |
//|  EMA Cross + RSI + ATR with robust risk & margin controls        |
//|  One-position-per-symbol, spread/session filters, trailing stop  |
//+------------------------------------------------------------------+
#property strict
#property version   "1.50"
#property description "EMA Cross + RSI + ATR strategy with full trade management and robust margin/risk logic."

#include <Trade/Trade.mqh>

CTrade trade;

//========================
// Inputs: Strategy & Risk
//========================
input ENUM_TIMEFRAMES InpTimeframe      = PERIOD_M5;      // Signal timeframe
input int             InpFastEMA        = 21;             // Fast EMA period
input int             InpSlowEMA        = 55;             // Slow EMA period
input int             InpRSIPeriod      = 14;             // RSI period
input double          InpRSI_Buy        = 55.0;           // RSI threshold for buys
input double          InpRSI_Sell       = 45.0;           // RSI threshold for sells
input int             InpATRPeriod      = 14;             // ATR period
input double          InpATR_SL_Mult    = 1.5;            // SL = ATR * this multiplier
input double          InpATR_TrailMult  = 1.0;            // Trailing distance = ATR * this multiplier
input double          InpRR             = 2.0;            // Reward:Risk ratio
input double          InpATR_MinFilter  = 0.0;            // Minimum ATR filter (price units); set 0 to disable

//========================
// Inputs: Risk Management
//========================
input double          InpRiskPerTradePct          = 0.5;   // Percent of equity risk per trade (e.g., 0.5 = 0.5%)
input double          InpMaxFreeMarginUsagePct    = 10.0;  // Cap: single trade margin <= this % of free margin
input double          InpMinMarginLevelPct        = 500.0; // Do not open if projected margin level < this (%); ignored if <=0
input ulong           InpMagicNumber              = 987654321; // Magic number to tag positions

//========================
// Inputs: Execution & Filters
//========================
input int             InpSlippagePoints           = 20;    // Max deviation (points)
input int             InpMaxSpreadPoints          = 30;    // Max spread (points) allowed for entries
input string          InpSkipHoursUTC             = "21,22"; // Skip trading on these UTC hours (comma-separated)
input bool            InpAllowTrailing            = true;  // Enable trailing SL
input double          InpBreakevenRR              = 1.0;   // Move SL to BE after reaching this RR (0 to disable)

//========================
// Internal state & handles
//========================
int     hFastEMA = INVALID_HANDLE;
int     hSlowEMA = INVALID_HANDLE;
int     hRSI     = INVALID_HANDLE;
int     hATR     = INVALID_HANDLE;

datetime gLastSignalBarTime = 0;

// Symbol parameters cache
string  gSymbol;
double  gPoint      = 0.0;
int     gDigits     = 0;
double  gTickSize   = 0.0;
double  gTickValue  = 0.0;
double  gMinVolume  = 0.0;
double  gMaxVolume  = 0.0;
double  gVolStep    = 0.0;
int     gStopsLevelPoints = 0;
int     gFreezeLevelPoints = 0;

// Session skip hours (UTC) map
bool    gSkipHour[24];

//==================================================================
// Helpers
//==================================================================
void LogLastError(const string context)
{
  int err = GetLastError();
  PrintFormat("%s | Error %d: %s", context, err, ErrorDescription(err));
  ResetLastError();
}

void ParseSkipHours(const string hours_csv)
{
  ArrayInitialize(gSkipHour,false);
  string trimmed = hours_csv;
  StringTrimLeft(trimmed);
  StringTrimRight(trimmed);
  if(trimmed=="") return;
  string parts[];
  int n = StringSplit(trimmed, ',', parts);
  for(int i=0;i<n;i++)
  {
    string p = parts[i];
    StringTrimLeft(p);
    StringTrimRight(p);
    if(p=="") continue;
    int h = (int)StringToInteger(p);
    if(h>=0 && h<24) gSkipHour[h]=true;
  }
}

bool RefreshSymbolInfo(const string sym)
{
  gSymbol = sym;
  if(!SymbolSelect(gSymbol, true))
  {
    LogLastError("SymbolSelect failed");
    return false;
  }

  gPoint  = SymbolInfoDouble(gSymbol, SYMBOL_POINT);
  gDigits = (int)SymbolInfoInteger(gSymbol, SYMBOL_DIGITS);
  gTickSize = SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_SIZE);
  gTickValue= SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_VALUE);
  gMinVolume= SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_MIN);
  gMaxVolume= SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_MAX);
  gVolStep  = SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_STEP);
  gStopsLevelPoints  = (int)SymbolInfoInteger(gSymbol, SYMBOL_TRADE_STOPS_LEVEL);
  gFreezeLevelPoints = (int)SymbolInfoInteger(gSymbol, SYMBOL_TRADE_FREEZE_LEVEL);

  long trade_mode = SymbolInfoInteger(gSymbol, SYMBOL_TRADE_MODE);
  if(trade_mode == SYMBOL_TRADE_MODE_DISABLED || trade_mode == SYMBOL_TRADE_MODE_CLOSEONLY)
  {
    PrintFormat("Trading not allowed for symbol %s (mode=%d)", gSymbol, (int)trade_mode);
    return false;
  }

  if(gPoint<=0.0 || gTickSize<=0.0 || gMinVolume<=0.0 || gVolStep<=0.0)
  {
    Print("Invalid symbol trading parameters detected.");
    return false;
  }
  return true;
}

bool OnePositionPerSymbol()
{
  for(int i=0;i<PositionsTotal();i++)
  {
    ulong ticket = PositionGetTicket(i);
    if(ticket==0) continue;
    if(PositionSelectByTicket(ticket))
    {
      string sym = PositionGetString(POSITION_SYMBOL);
      ulong  mgc = (ulong)PositionGetInteger(POSITION_MAGIC);
      if(sym==gSymbol && mgc==InpMagicNumber)
        return true;
    }
  }
  return false;
}

bool IsTradingHourUTC()
{
  datetime now = TimeTradeServer();
  MqlDateTime dt; TimeToStruct(now, dt);
  int h = dt.hour; // server time assumed close to UTC; adjust if needed
  if(h>=0 && h<24 && gSkipHour[h])
    return false;
  return true;
}

bool SpreadOK()
{
  double spread_points = (SymbolInfoDouble(gSymbol, SYMBOL_ASK) - SymbolInfoDouble(gSymbol, SYMBOL_BID)) / gPoint;
  return (spread_points <= InpMaxSpreadPoints);
}

// Read buffer value helper
bool ReadBuffer(const int handle, const int shift, double &val)
{
  if(handle==INVALID_HANDLE) return false;
  if(!CopyBuffer(handle, 0, shift, 1, val))
    return false;
  return (val!=EMPTY_VALUE && val!=0.0) || true; // accept zero
}

// Round volume to step and bounds
double NormalizeVolume(const double vol)
{
  double v = MathMax(gMinVolume, MathMin(gMaxVolume, vol));
  int steps = (int)MathRound((v - gMinVolume)/gVolStep);
  double norm = gMinVolume + steps*gVolStep;
  // guard against precision artifacts
  norm = NormalizeDouble(norm, 8);
  if(norm < gMinVolume) norm = gMinVolume;
  if(norm > gMaxVolume) norm = gMaxVolume;
  return norm;
}

// Calculate stop-loss and take-profit prices based on ATR
bool CalcSLTP(const bool isBuy, const double atr, double &sl, double &tp, double &entry)
{
  MqlTick tick; if(!SymbolInfoTick(gSymbol, tick)) { LogLastError("SymbolInfoTick failed"); return false; }
  entry = isBuy ? tick.ask : tick.bid;

  double sl_dist = InpATR_SL_Mult * atr;
  if(sl_dist <= 0.0) return false;

  if(isBuy)
  {
    sl = entry - sl_dist;
    tp = entry + (InpRR * sl_dist);
  }
  else
  {
    sl = entry + sl_dist;
    tp = entry - (InpRR * sl_dist);
  }

  // Respect stop levels and freeze levels
  int min_dist_points = MathMax(gStopsLevelPoints, gFreezeLevelPoints);
  double min_dist_price = min_dist_points * gPoint;

  if(isBuy)
  {
    if((entry - sl) < min_dist_price) sl = entry - min_dist_price;
    if((tp - entry) < min_dist_price) tp = entry + min_dist_price;
  }
  else
  {
    if((sl - entry) < min_dist_price) sl = entry + min_dist_price;
    if((entry - tp) < min_dist_price) tp = entry - min_dist_price;
  }

  sl = NormalizeDouble(sl, gDigits);
  tp = NormalizeDouble(tp, gDigits);
  return true;
}

// Equity-based position sizing with OrderCalcMargin, margin caps and safety checks
bool ComputeVolume(const bool isBuy, const double entry, const double sl, double &volume_out)
{
  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  double free_margin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  double balance = AccountInfoDouble(ACCOUNT_BALANCE);
  double stop_dist = MathAbs(entry - sl);
  if(stop_dist <= 0.0) { Print("Stop distance is zero; sizing aborted."); return false; }

  // Risk per trade in account currency
  double risk_amount = equity * (InpRiskPerTradePct/100.0);
  if(risk_amount <= 0.0) { Print("Risk amount <= 0"); return false; }

  // Value per point per 1 lot
  double contract_size = SymbolInfoDouble(gSymbol, SYMBOL_TRADE_CONTRACT_SIZE);
  if(contract_size <= 0.0) contract_size = 100000.0; // fallback common FX size
  // Approximate pip value per 1 lot = (tick value / tick size); then per point value
  double value_per_point_per_lot = 0.0;
  if(gTickSize>0.0)
    value_per_point_per_lot = (gTickValue / gTickSize) * gPoint; // convert to point increment
  if(value_per_point_per_lot<=0.0)
    value_per_point_per_lot = (gTickValue>0.0? gTickValue : (contract_size*0.0001)) * (gPoint/0.0001);

  double stop_points = stop_dist / gPoint;
  if(stop_points <= 0.0) return false;

  double vol_by_risk = risk_amount / (stop_points * value_per_point_per_lot);

  // Now enforce margin cap using OrderCalcMargin
  double test_volume = NormalizeVolume(vol_by_risk);
  if(test_volume < gMinVolume) test_volume = gMinVolume;

  // Ensure margin per trade <= InpMaxFreeMarginUsagePct of current free margin
  double margin_needed = 0.0;
  if(!OrderCalcMargin(isBuy?ORDER_TYPE_BUY:ORDER_TYPE_SELL, gSymbol, test_volume, entry, margin_needed))
  {
    LogLastError("OrderCalcMargin failed in sizing");
    return false;
  }

  double max_margin_allowed = free_margin * (InpMaxFreeMarginUsagePct/100.0);
  if(max_margin_allowed <= 0.0)
  {
    Print("Max margin allowed computed <= 0; sizing aborted.");
    return false;
  }

  if(margin_needed > max_margin_allowed && margin_needed>0.0)
  {
    double scale = max_margin_allowed / margin_needed;
    test_volume = NormalizeVolume(test_volume * scale);
    if(test_volume < gMinVolume)
    {
      Print("Volume after margin cap < min volume; sizing aborted.");
      return false;
    }
    if(!OrderCalcMargin(isBuy?ORDER_TYPE_BUY:ORDER_TYPE_SELL, gSymbol, test_volume, entry, margin_needed))
    {
      LogLastError("OrderCalcMargin failed after rescale");
      return false;
    }
  }

  // Projected margin-level check
  if(InpMinMarginLevelPct > 0.0)
  {
    double used_margin_now = AccountInfoDouble(ACCOUNT_MARGIN);
    double proj_used_margin = used_margin_now + margin_needed;
    double proj_margin_level = (proj_used_margin>0.0)? (equity / proj_used_margin * 100.0) : 1000000.0;
    if(proj_margin_level < InpMinMarginLevelPct)
    {
      PrintFormat("Projected margin level %.2f%% < minimum %.2f%%; aborting.", proj_margin_level, InpMinMarginLevelPct);
      return false;
    }
  }

  // Ensure free margin after order remains positive by a buffer
  double fm_buffer = 0.1; // 10% of margin_needed buffer
  if((free_margin - margin_needed) < margin_needed*fm_buffer)
  {
    Print("Insufficient free margin after projected order; aborting.");
    return false;
  }

  volume_out = NormalizeVolume(test_volume);
  return (volume_out >= gMinVolume);
}

void SetTradeParams()
{
  trade.SetExpertMagicNumber((long)InpMagicNumber);
  trade.SetDeviationInPoints(InpSlippagePoints);
}

// Apply trailing stop and optional breakeven
void ManageOpenPosition()
{
  if(!PositionSelect(gSymbol)) return;
  if((ulong)PositionGetInteger(POSITION_MAGIC) != InpMagicNumber) return;

  bool   isBuy = (PositionGetInteger(POSITION_TYPE)==POSITION_TYPE_BUY);
  double entry = PositionGetDouble(POSITION_PRICE_OPEN);
  double sl    = PositionGetDouble(POSITION_SL);
  double tp    = PositionGetDouble(POSITION_TP);
  double price = 0.0;
  MqlTick tick; if(!SymbolInfoTick(gSymbol, tick)) { LogLastError("SymbolInfoTick in ManageOpenPosition"); return; }
  price = isBuy ? tick.bid : tick.ask;

  double atr=0.0; if(!ReadBuffer(hATR, 0, atr) || atr<=0.0) return;
  double trail_dist = InpATR_TrailMult * atr;
  if(trail_dist<=0.0) return;

  double min_dist_price = MathMax(gStopsLevelPoints, gFreezeLevelPoints) * gPoint;

  double new_sl = sl;

  if(InpAllowTrailing)
  {
    if(isBuy)
    {
      double candidate = price - trail_dist;
      if(sl==0.0 || candidate - sl > gPoint) // tighten only forward
        new_sl = MathMax(sl, candidate);
      if((price - new_sl) < min_dist_price) new_sl = price - min_dist_price;
    }
    else
    {
      double candidate = price + trail_dist;
      if(sl==0.0 || sl - candidate > gPoint)
        new_sl = MathMin(sl==0.0?candidate:sl, candidate);
      if((new_sl - price) < min_dist_price) new_sl = price + min_dist_price;
    }
  }

  // Breakeven move
  if(InpBreakevenRR > 0.0)
  {
    double risk = MathAbs(entry - (PositionGetDouble(POSITION_TYPE)==POSITION_TYPE_BUY ? (sl>0.0?sl:entry - trail_dist) : (sl>0.0?sl:entry + trail_dist)));
    if(risk>0.0)
    {
      double rr_reached = MathAbs(price - entry) / risk;
      if(rr_reached >= InpBreakevenRR)
      {
        if(isBuy) new_sl = MathMax(new_sl, entry);
        else      new_sl = MathMin(new_sl, entry);
      }
    }
  }

  new_sl = NormalizeDouble(new_sl, gDigits);
  if(new_sl!=sl && new_sl>0.0)
  {
    if(!trade.PositionModify(gSymbol, new_sl, tp))
      LogLastError("PositionModify (trailing/breakeven) failed");
  }
}

// Generate trading signal from EMA cross + RSI filter
int GetSignal()
{
  // return 1 for buy, -1 for sell, 0 for none
  double ema_fast_0, ema_fast_1, ema_slow_0, ema_slow_1, rsi_0;
  if(!ReadBuffer(hFastEMA, 0, ema_fast_0)) return 0;
  if(!ReadBuffer(hFastEMA, 1, ema_fast_1)) return 0;
  if(!ReadBuffer(hSlowEMA, 0, ema_slow_0)) return 0;
  if(!ReadBuffer(hSlowEMA, 1, ema_slow_1)) return 0;
  if(!ReadBuffer(hRSI, 0, rsi_0)) return 0;

  bool bullCross = (ema_fast_1 <= ema_slow_1) && (ema_fast_0 > ema_slow_0);
  bool bearCross = (ema_fast_1 >= ema_slow_1) && (ema_fast_0 < ema_slow_0);

  if(bullCross && rsi_0 >= InpRSI_Buy) return 1;
  if(bearCross && rsi_0 <= InpRSI_Sell) return -1;
  return 0;
}

//==================================================================
// Standard EA functions
//==================================================================
int OnInit()
{
  if(!RefreshSymbolInfo(_Symbol))
  {
    Print("Failed to refresh symbol info.");
    return INIT_FAILED;
  }

  ParseSkipHours(InpSkipHoursUTC);
  SetTradeParams();

  // Indicators
  hFastEMA = iMA(gSymbol, InpTimeframe, InpFastEMA, 0, MODE_EMA, PRICE_CLOSE);
  if(hFastEMA==INVALID_HANDLE) { LogLastError("iMA fast invalid"); return INIT_FAILED; }

  hSlowEMA = iMA(gSymbol, InpTimeframe, InpSlowEMA, 0, MODE_EMA, PRICE_CLOSE);
  if(hSlowEMA==INVALID_HANDLE) { LogLastError("iMA slow invalid"); return INIT_FAILED; }

  hRSI = iRSI(gSymbol, InpTimeframe, InpRSIPeriod, PRICE_CLOSE);
  if(hRSI==INVALID_HANDLE) { LogLastError("iRSI invalid"); return INIT_FAILED; }

  hATR = iATR(gSymbol, InpTimeframe, InpATRPeriod);
  if(hATR==INVALID_HANDLE) { LogLastError("iATR invalid"); return INIT_FAILED; }

  // Warm up buffers
  double tmp;
  if(!ReadBuffer(hFastEMA,0,tmp) || !ReadBuffer(hSlowEMA,0,tmp) || !ReadBuffer(hRSI,0,tmp) || !ReadBuffer(hATR,0,tmp))
  {
    Print("Indicator warm-up failed");
    return INIT_FAILED;
  }

  Print("EA initialized successfully on ", gSymbol);
  return INIT_SUCCEEDED;
}

void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)    IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)    IndicatorRelease(hATR);
}

void OnTick()
{
  if(_Symbol!=gSymbol) if(!RefreshSymbolInfo(_Symbol)) return;

  // Filters: session and spread
  if(!IsTradingHourUTC()) return;
  if(!SpreadOK()) return;

  // Maintain trailing for existing position
  ManageOpenPosition();

  // One-position-per-symbol rule
  if(OnePositionPerSymbol()) return;

  // Signal generation on closed bar to avoid intra-bar noise
  static datetime last_bar_time = 0;
  datetime cur_bar_time = iTime(gSymbol, InpTimeframe, 0);
  if(cur_bar_time == 0) return;
  if(cur_bar_time == last_bar_time) return; // only once per bar
  last_bar_time = cur_bar_time;

  // Ensure ATR filter if required
  double atr=0.0; if(!ReadBuffer(hATR, 0, atr) || atr<=0.0) return;
  if(InpATR_MinFilter>0.0 && atr < InpATR_MinFilter) return;

  int signal = GetSignal();
  if(signal==0) return;

  bool isBuy = (signal>0);

  double sl=0.0, tp=0.0, entry=0.0;
  if(!CalcSLTP(isBuy, atr, sl, tp, entry)) { Print("CalcSLTP failed"); return; }

  double volume=0.0;
  if(!ComputeVolume(isBuy, entry, sl, volume)) { Print("ComputeVolume aborted"); return; }

  // Final pre-trade margin check with exact volume
  double final_margin=0.0;
  if(!OrderCalcMargin(isBuy?ORDER_TYPE_BUY:ORDER_TYPE_SELL, gSymbol, volume, entry, final_margin))
  { LogLastError("OrderCalcMargin pre-trade failed"); return; }

  double free_margin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  double max_margin_allowed = free_margin * (InpMaxFreeMarginUsagePct/100.0);
  if(final_margin > max_margin_allowed)
  {
    PrintFormat("Final margin %.2f > cap %.2f; abort.", final_margin, max_margin_allowed);
    return;
  }

  // Send order
  MqlTick tick; if(!SymbolInfoTick(gSymbol, tick)) { LogLastError("SymbolInfoTick before order"); return; }
  trade.SetExpertMagicNumber((long)InpMagicNumber);
  trade.SetDeviationInPoints(InpSlippagePoints);

  bool sent=false;
  if(isBuy)
    sent = trade.Buy(volume, gSymbol, tick.ask, sl, tp, "EMA_RSI_BUY");
  else
    sent = trade.Sell(volume, gSymbol, tick.bid, sl, tp, "EMA_RSI_SELL");

  if(!sent)
  {
    LogLastError("Order send failed");
    return;
  }
  else
  {
    PrintFormat("Order sent: %s vol=%.2f SL=%.5f TP=%.5f", isBuy?"BUY":"SELL", volume, sl, tp);
  }
}
